export const DEMO_BIRTH_DETAILS_JSON = "{\"1-1\":{\"photo\":{\"src\":\"/birth/seunodeurop.jpg\",\"thumbSrc\":\"/birth/thumbs/seunodeurop.jpg\",\"author\":\"Flocci Nivis\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20260307_Galanthus_nivalis.jpg\",\"familyLine\":\"수선화과의 작은 알뿌리 식물이에요 — 눈이 채 녹기 전에 고개 숙인 흰 꽃을 가장 먼저 피웁니다.\"},\"stories\":[{\"id\":\"bstory-snowdrop-paskov-nivalin\",\"title\":\"발칸 농민의 민간요법이 치매약이 됐습니다\",\"hook\":\"발칸 산골 사람들이 신경통에 쓰던 알뿌리에서, 지금도 처방되는 치매약이 나왔습니다.\",\"body\":\"발칸과 캅카스 산골에서는 오래전부터 스노드롭 알뿌리를 신경 계통 병에 써 왔어요. 1950년대에 불가리아 화학자 디미타르 파스코프가 그 민간요법에 눈을 돌렸어요. 그는 스노드롭 알뿌리에서 갈란타민이라는 물질을 뽑아내 니발린이라는 이름으로 세상에 내놨어요. 갈란타민은 아세틸콜린을 분해하는 효소를 막아요. 알츠하이머병에서 모자라는 게 바로 그 아세틸콜린이라, 이 물질은 지금도 알츠하이머 증상 치료제로 쓰이고 있어요. 눈 녹기도 전에 고개를 내미는 이 작은 꽃이, 기억을 붙잡아 두는 약의 원료였던 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"불가리아\"},{\"key\":\"era\",\"text\":\"1950년대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7933568/\"},{\"id\":\"bstory-snowdrop-moly-odysseus\",\"title\":\"오디세우스가 받은 약초라는 설\",\"hook\":\"마녀의 마법을 막아 준 호메로스의 약초가 스노드롭이었다는 주장이 있습니다.\",\"body\":\"오디세이아에는 헤르메스가 오디세우스에게 약초 하나를 건네는 장면이 나와요. 그걸 지니고 있으면 마녀 키르케의 약이 듣지 않는다고요. 호메로스는 그 풀을 몰리라고 불렀어요. 20세기 신경학자들이 재미있는 가설을 냈어요. 키르케가 쓴 약이 기억과 정신을 흐리는 항콜린성 독이라면, 그걸 막을 해독제는 콜린 쪽을 붙드는 물질이어야 한다는 거예요. 스노드롭의 갈란타민이 바로 그런 물질이거든요. 물론 몰리가 정말 스노드롭이었는지는 아무도 확인할 수 없어요. 다만 '홀리 몰리'라는 감탄사가 여기서 왔을지도 모른다는 이야기까지 붙어 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"mcgill.ca\",\"sourceUrl\":\"https://www.mcgill.ca/oss/article/medical-history/odysseus-snowdrop-odyssey\"},{\"id\":\"bstory-snowdrop-golden-tears-ebay\",\"title\":\"알뿌리 하나가 1,850파운드에 팔렸습니다\",\"hook\":\"2022년 이베이에서 스노드롭 알뿌리 한 알이 1,850파운드에 낙찰됐습니다. 배송비는 5파운드였습니다.\",\"body\":\"스노드롭에 미친 사람들을 영어로 갈란토파일이라고 불러요. 이들이 모이는 곳이 봄마다 열리는 알뿌리 경매예요. 2022년 2월, 갈란투스 플리카투스 '골든 티어스' 알뿌리 한 알이 이베이에서 1,850파운드에 팔렸어요. 배송비는 5파운드였고요. 이 품종을 만든 사람은 몽크실버 너서리의 조 샤먼이에요. 스노드롭의 왕이라고 불리는 사람인데, 2015년에도 자기가 만든 '골든 플리스'로 1,390파운드라는 기록을 세운 적이 있어요. 손톱만 한 흰 꽃 한 송이의 값이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"gardensillustrated.com\",\"sourceUrl\":\"https://www.gardensillustrated.com/news/snowdrop-bulb-sells-for-a-record-busting-1850\"}]},\"1-2\":{\"stories\":[]},\"1-3\":{\"stories\":[{\"id\":\"bstory-autumn-crocus-byzantine-gout\",\"title\":\"독초를 통풍약으로 바꾼 5세기 의사들\",\"hook\":\"황제의 주치의는 이 독초로 고약을 개어 부어오른 관절에 붙이라고 했어요.\",\"body\":\"콜키쿰은 처음에 약이 아니라 독으로 기록됐어요. 1세기 디오스코리데스가 이 식물을 언급하기는 했지만 강한 독성을 강조했거든요. 그런데 5세기 비잔티움에서 판이 바뀌어요. 의철학자 세베루스 이아트로소피스타가 헤르모닥틸, 곧 콜키쿰을 통풍 치료에 처음 끌어들였고, 같은 시기 학자 테오도시우스도 같은 식물을 통풍 약초로 제안했어요. 레오 1세 황제의 주치의였던 야코부스 프시크레스토스는 이 풀로 끈적한 고약을 만들어 부어오른 관절에 붙이라고 권했어요. 흔히 콜키쿰을 통풍 치료에 도입한 사람으로 알려진 알렉산드로스 트랄레스는 사실 헤르모닥틸이 든 처방 여섯 가지를 남기면서 그 공을 앞의 세 사람에게 돌렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"비잔티움\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC7046033/\"},{\"id\":\"bstory-autumn-crocus-wild-garlic-poisoning\",\"title\":\"뿌리 하나와 잎 셋으로 끓인 차\",\"hook\":\"산마늘로 착각해 끓인 차 500밀리리터에 콜히친이 최소 10밀리그램 들어 있었어요.\",\"body\":\"2026년 학술지 톡식스에 실린 증례 보고는 이 식물이 왜 무서운지 보여 줘요. 한 환자가 콜키쿰을 산마늘로 착각해, 뿌리 하나와 잎 세 장으로 차 500밀리리터를 끓여 마셨어요. 연구진이 추정한 콜히친 섭취량은 최소 10밀리그램, 많으면 40밀리그램이 넘어요. 6시간 뒤 복통과 구토와 심한 설사가 시작됐고, 24시간째에는 착란과 어눌한 말이 겹쳤으며, 사흘째에는 급성 심장 기능 저하로 호흡 보조를 받았어요. 이 환자는 7일 만에 회복해 퇴원했지만, 논문이 인용한 이전 사례 열아홉 건 가운데 열 건은 사망이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13120402/\"}]},\"1-4\":{\"stories\":[]},\"1-5\":{\"photo\":{\"src\":\"/birth/norugwi.jpg\",\"thumbSrc\":\"/birth/thumbs/norugwi.jpg\",\"author\":\"阿橋 HQ\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:%E5%B0%96%E7%93%A3%E7%8D%90%E8%80%B3%E7%B4%B0%E8%BE%9B_Hepatica_asiatica_f_acutiloba_-%E9%A6%96%E7%88%BE%E5%88%87%E9%A0%AD%E5%B1%B1%E5%85%AC%E5%9C%92_Seoul,_South_Korea-_(33142022393).jpg\",\"familyLine\":\"미나리아재비과의 이른 봄 야생화예요 — 잎이 펼쳐지기 전에 솜털 돋은 꽃대부터 올립니다.\"},\"stories\":[{\"id\":\"bstory-hepatica-liverwort-1883\",\"title\":\"간을 닮았다는 이유로 45만 파운드가 팔렸습니다\",\"hook\":\"잎이 간을 닮았다는 이유 하나로, 1883년 한 해에만 45만 파운드어치가 팔려 나갔습니다.\",\"body\":\"노루귀 잎은 세 갈래로 갈라지고 자줏빛이 돌아요. 옛사람들은 그 모양이 간을 닮았다고 봤어요. 닮은 것이 닮은 것을 고친다는 믿음이 있었거든요. 그래서 노루귀는 간약이 됐어요. 1800년대 후반 미국 남부 산지에서는 사람들이 산을 훑으며 노루귀 잎을 땄어요. 특허약 회사들이 사 갔거든요. 1883년 한 해에만 약재상들이 사들인 노루귀 잎이 45만 파운드, 그러니까 이백 톤이 넘었어요. 결말은 싱거워요. 아무도 효과를 못 봤고, 약은 시장에서 사라졌고, 노루귀는 다시 흔한 봄꽃으로 돌아왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"northernwoodlands.org\",\"sourceUrl\":\"https://northernwoodlands.org/articles/article/doctrine-signatures\"}]},\"1-6\":{\"stories\":[]},\"1-7\":{\"stories\":[]},\"1-8\":{\"stories\":[]},\"1-9\":{\"stories\":[]},\"1-10\":{\"photo\":{\"src\":\"/birth/hoeyangmok.jpg\",\"thumbSrc\":\"/birth/thumbs/hoeyangmok.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Buxus_koreana%27s_flowers.JPG\",\"familyLine\":\"회양목과의 늘푸른 관목이에요 — 봄에 연노랑 꽃이 잎겨드랑이에 모여 핍니다.\"},\"stories\":[]},\"1-11\":{\"photo\":{\"src\":\"/birth/cheukbaeknamu.jpg\",\"thumbSrc\":\"/birth/thumbs/cheukbaeknamu.jpg\",\"author\":\"Josef Grunig at Flickr\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Platycladus_orientalis_cones.jpg\",\"familyLine\":\"측백나무과의 늘푸른 침엽수예요 — 납작한 부챗살 잎에 분을 바른 듯한 청록색 열매가 달립니다.\"},\"stories\":[{\"id\":\"bstory-thuja-cartier-tree-of-life\",\"title\":\"괴혈병을 멈춘 나무가 생명의 나무가 됐습니다\",\"hook\":\"1536년 겨울, 이로쿼이 사람들이 끓여 준 나뭇잎 물 한 사발이 프랑스 선원들을 살렸습니다.\",\"body\":\"1536년 겨울, 자크 카르티에의 배는 세인트로렌스강에 갇혀 있었어요. 신선한 것을 못 먹은 선원들이 괴혈병으로 쓰러졌고요. 이로쿼이 사람들이 상록수 껍질과 잎을 물에 끓여 마시게 했어요. 사람들이 살아났어요. 그들은 그 나무를 아네다라고 불렀어요. 프랑스인들은 아르브르 드 비, 생명의 나무라고 옮겨 적었고요. 이 이름이 그대로 학명 옆에 붙어 오늘날의 아르보르비타이가 됐어요. 비타민 C가 병을 고쳤다는 건 사백 년 뒤에야 밝혀졌어요. 어느 침엽수였는지는 아직도 학자들 사이에서 갈려요.\",\"notes\":[{\"key\":\"region\",\"text\":\"캐나다·프랑스\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2647905/\"},{\"id\":\"bstory-thuja-daegu-dodong-grove\",\"title\":\"천연기념물 목록의 맨 앞자리\",\"hook\":\"우리나라에서 천연기념물 지정이 처음 무더기로 이뤄진 날, 목록의 맨 앞에 이 숲이 있었습니다.\",\"body\":\"대구 동구 도동 산비탈에는 측백나무만 빽빽하게 들어찬 숲이 있어요. 넓이가 삼만 오천 제곱미터가 넘어요. 이 숲이 천연기념물로 지정된 날짜는 1962년 12월 7일이에요. 우리나라 천연기념물 지정이 처음으로 무더기로 이뤄진 날이고, 도동 측백나무 숲은 그 목록의 맨 앞자리에 올랐어요. 측백나무는 원래 중국 북부와 우리나라 일부에만 자라는 나무예요. 그런 나무가 이렇게 한 비탈을 통째로 차지하고 있는 곳은 드물어요. 관리 주체는 대구시이고, 지금도 개인 소유자가 따로 있는 숲이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"heritage.go.kr\",\"sourceUrl\":\"https://www.heritage.go.kr/heri/cul/culSelectDetail.do?ccbaCpno=1362200010000\"}]},\"1-12\":{\"photo\":{\"src\":\"/birth/hyanggi-alriseom.jpg\",\"thumbSrc\":\"/birth/thumbs/hyanggi-alriseom.jpg\",\"author\":\"Christian Ferrer\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lobularia_maritima,_S%C3%A8te_01.jpg\",\"familyLine\":\"십자화과의 낮게 퍼지는 풀이에요 — 자잘한 흰 꽃이 방석처럼 덮이며 꿀 향을 냅니다.\"},\"stories\":[{\"id\":\"bstory-sweet-alyssum-name-moved\",\"title\":\"알리섬이라 부르지만 알리섬이 아닙니다\",\"hook\":\"이 꽃을 알리섬이라 부르는 사람은 많지만, 학명에서 알리섬이라는 이름은 이미 빠져나갔습니다.\",\"body\":\"향기 알리섬은 이름이 한 번 이사를 갔어요. 예전 학명은 알리숨 마리티뭄이었어요. 그래서 지금도 화원에서는 그냥 알리섬이라고 불러요. 그런데 분류가 정리되면서 이 꽃은 로불라리아속으로 옮겨졌어요. 로불라리아는 라틴어로 작은 꼬투리라는 뜻이에요. 열매가 자잘한 꼬투리로 맺히거든요. 종소명 마리티마는 바닷가라는 뜻이고요. 지중해 해안이 고향이에요. 여름이 서늘한 곳에서는 봄부터 첫서리까지 흰 꽃을 끊이지 않고 피워요. 부르는 이름과 적히는 이름이 다른 꽃이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/lobularia-maritima/\"}]},\"1-13\":{\"stories\":[]},\"1-14\":{\"stories\":[]},\"1-15\":{\"photo\":{\"src\":\"/birth/gasi.jpg\",\"thumbSrc\":\"/birth/thumbs/gasi.jpg\",\"author\":\"DidierFy\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Prunus_spinosa_04.2025_(9).jpg\",\"familyLine\":\"잎보다 먼저 흰 꽃을 피우는 장미과의 가시나무예요 — 굳은 가지 끝이 그대로 가시가 됩니다.\"},\"stories\":[{\"id\":\"bstory-thorn-glastonbury-christmas\",\"title\":\"크리스마스에 꽃을 피우는 가시나무\",\"hook\":\"영국에는 한겨울에 꽃을 피우는 가시나무가 있고, 그 가지는 해마다 왕실 식탁으로 갑니다.\",\"body\":\"글래스턴베리에는 이상한 산사나무가 한 그루 있어요. 봄에 한 번, 겨울에 또 한 번 꽃을 피우거든요. 크라타이구스 모노기나 비플로라라는 변종이에요. 비플로라가 두 번 핀다는 뜻이에요. 전설은 이래요. 아리마태아 요셉이 이 언덕에 지팡이를 꽂았더니 뿌리가 내려 나무가 됐다고요. 그 겨울 꽃가지는 수백 년 동안 해마다 영국 군주의 크리스마스 식탁에 올랐어요. 그런데 2010년 12월, 누군가 이 나무의 가지를 톱으로 잘라 버렸어요. 범인은 끝내 밝혀지지 않았어요. 재미있는 건 이 나무가 영국 자생종이 아니라는 점이에요. 중동 쪽에서 온 나무예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"중세~오늘날\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"blogs.reading.ac.uk\",\"sourceUrl\":\"https://blogs.reading.ac.uk/crg/glastonbury-thorn/\"}]},\"1-16\":{\"stories\":[]},\"1-17\":{\"photo\":{\"src\":\"/birth/suyeong-0117.jpg\",\"thumbSrc\":\"/birth/thumbs/suyeong-0117.jpg\",\"author\":\"Stefan.lefnaer\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rumex_acetosa_(subsp._acetosa)_sl18.jpg\",\"familyLine\":\"마디풀과의 여러해살이풀이에요 — 신맛 나는 잎을 먹고, 초여름엔 붉게 물든 꽃차례가 곧게 섭니다.\"},\"stories\":[{\"id\":\"bstory-sorrel-acetaria\",\"title\":\"1699년 샐러드 책의 필수 재료\",\"hook\":\"존 이블린은 수영을 샐러드에서 결코 빼서는 안 될 재료라고 못 박았어요.\",\"body\":\"1699년 영국의 존 이블린은 샐러드만 다룬 책 아세타리아를 펴냈어요. 그 목록의 예순한 번째 항목이 수영이에요. 잎이 둥근 프랑스 종과 잎이 넓은 독일 종을 나누어 적고, 그린란드 수영이 가장 낫다고 했죠. 성질은 차고, 씻어 내리며, 시고, 식욕을 돋우고, 열을 가라앉히고, 간을 식히고, 심장을 튼튼하게 한다고 썼어요. 무엇보다 그는 수영을 괴혈병을 막고 부패를 막는 재료로 보았어요. 나머지 재료에 상큼한 날을 세워 주어서 오렌지와 레몬 같은 신맛 재료가 없을 때 그 자리를 대신하니, 결코 빼서는 안 된다고 못 박았고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/15517/15517-h/15517-h.htm\"},{\"id\":\"bstory-sorrel-salts-of-lemon\",\"title\":\"잉크 얼룩을 지운 레몬염\",\"hook\":\"수영에서 나온 옥살산은 '레몬염'이라는 이름으로 팔려 얼룩을 지우는 데 쓰였어요.\",\"body\":\"수영의 신맛은 옥살산에서 나와요. 그런데 이 성분은 먹는 것 말고도 쓸모가 있었어요. 수영에서 나온 옥살산염은 레몬염이라는 이름으로 상품이 되어, 밀짚을 표백하거나 리넨에 앉은 녹 자국을 빼거나 잉크 얼룩을 지우는 데 쓰였어요. 약으로도 오래 썼어요. 1세기의 그리스 의사 디오스코리데스와 로마의 대 플리니우스 시절부터 등장하는데, 몸을 식혀 주는 풀로 여겨 열병과 피부 종양, 황달, 몸속 궤양에 썼고 헌데와 멍, 종기, 수두에도 발랐어요. 화살촉 모양 잎은 1700년대까지 유럽 중세 채마밭에서 익숙한 풍경이었어요. 값이 싸고 어디서나 구할 수 있어 가난한 사람의 풀이라는 별명도 붙었고, 도싯의 아이들은 잎을 간식처럼 뜯어 먹었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"eatweeds.co.uk\",\"sourceUrl\":\"https://www.eatweeds.co.uk/sorrel-rumex-acetosa\"}]},\"1-18\":{\"photo\":{\"src\":\"/birth/eojeogwi.jpg\",\"thumbSrc\":\"/birth/thumbs/eojeogwi.jpg\",\"author\":\"Robert Flogaus-Faust\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Abutilon_theophrasti_RF.jpg\",\"familyLine\":\"아욱과의 한해살이풀이에요 — 벨벳처럼 부드러운 넓은 잎 사이로 노란 꽃이 하나씩 핍니다.\"},\"stories\":[]},\"1-19\":{\"photo\":{\"src\":\"/birth/sonamu-0119.jpg\",\"thumbSrc\":\"/birth/thumbs/sonamu-0119.jpg\",\"author\":\"Shuvaev\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Pinus_densiflora,_Morris_Arboretum_03.jpg\",\"familyLine\":\"소나무과의 늘푸른 큰키나무예요 — 붉은 껍질과 두 개씩 모여나는 바늘잎이 우리 산을 지킵니다.\"},\"stories\":[{\"id\":\"bstory-pine-jeongipumsong\",\"title\":\"벼슬 받은 소나무 한 그루\",\"hook\":\"임금의 가마가 걸리자 스스로 가지를 들어 올렸다는 나무가 있어요.\",\"body\":\"충청북도 보은군 속리산 어귀에는 정이품송이라 불리는 소나무가 서 있어요. 1464년, 세조 10년에 임금이 법주사로 행차하다 이 나무 아래를 지나게 되는데, 처진 가지에 가마가 걸릴 참이었대요. 연이 걸린다는 말이 떨어지자 나무가 스스로 가지를 위로 들어 올려 임금을 지나가게 했다는 이야기가 전해져요. 세조는 그 공을 기려 정이품 벼슬을 내렸고, 그래서 이름이 정이품송이 됐어요. 실제 나무는 높이 약 15미터, 가슴높이 줄기둘레 약 4.7미터에 가지가 동서로 19.9미터, 남북으로 19미터 뻗어 있고, 수령은 500년에서 600년으로 추정돼요. 1962년 12월 7일 천연기념물로 지정됐지만 1970년대 이후 솔잎혹파리 피해를 입어 1982년에는 보호구역과 철책이 설치됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0030407\"},{\"id\":\"bstory-pine-sehando\",\"title\":\"유배지에서 그린 송백\",\"hook\":\"벼슬을 잃은 사람 곁에 남은 제자에게, 김정희는 소나무 그림을 보내요.\",\"body\":\"1844년, 김정희는 제주도 유배지에 있었어요. 지위도 권력도 사라진 자리였죠. 그때 역관 이상적은 두 번이나 북경에서 귀한 책을 구해 스승에게 보냈어요. 김정희는 그 마음에 답해 종이에 먹만으로 그림 한 장을 그려 건넵니다. 세로 23센티미터, 가로 69.2센티미터의 작은 화면에 허름한 집 한 채가 놓이고, 그 좌우로 소나무와 잣나무가 두 그루씩 마주 서 있어요. 겨울에도 잎을 떨구지 않는 나무를 지조의 상징으로 세운 구도예요. 이 그림이 세한도예요. 1974년 국보로 지정됐고 지금은 서울 국립중앙박물관에 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0038956\"},{\"id\":\"bstory-pine-prometheus\",\"title\":\"4862개의 나이테\",\"hook\":\"1964년, 세상에서 가장 오래 산 나무가 나이를 재려던 사람의 손에 잘려 나갔어요.\",\"body\":\"1964년 여름, 지리학자 도널드 커리는 네바다주 휠러피크에서 브리슬콘 소나무를 조사하고 있었어요. WPN-114라는 번호를 붙인 나무에서 온전한 시료를 얻지 못하자 그는 산림청 허가를 받아 나무를 베고 단면을 통째로 살폈죠. 세어 보니 나이테가 4,862개였어요. 혹독한 해에는 테가 아예 생기지 않는 점을 감안하면 실제 나이는 약 4,900살로 추정됐고요. 당시까지 확인된 가장 오래된 나무였고, 2위였던 캘리포니아의 브리슬콘 소나무는 4,847살이었어요. 2012년에는 같은 지역에서 5,065살 된 나무가 발견됐죠. 프로메테우스라 불린 그 나무의 단면 조각은 지금 그레이트베이슨 방문자센터에 전시돼 있고, 브리슬콘 소나무는 연방 토지에서 보호받고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nps.gov\",\"sourceUrl\":\"https://www.nps.gov/grba/learn/historyculture/the-prometheus-story.htm\"}]},\"1-20\":{\"photo\":{\"src\":\"/birth/minariajaebi-0120.jpg\",\"thumbSrc\":\"/birth/thumbs/minariajaebi-0120.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ranunculus_japonicus_3.JPG\",\"familyLine\":\"미나리아재비과의 여러해살이풀이에요 — 기름을 바른 듯 반짝이는 노란 꽃잎이 특징입니다.\"},\"stories\":[{\"id\":\"bstory-buttercup-chin-glow\",\"title\":\"턱이 노랗게 물드는 이유\",\"hook\":\"미나리아재비를 턱에 대면 노란빛이 도는 데는 이유가 있어요.\",\"body\":\"미나리아재비를 턱 아래 대고 노란빛이 비치면 버터를 좋아하는 거라는 놀이가 유럽에 오래 있었어요. 2011년 케임브리지대 연구진이 그 광학을 실제로 재 봤어요. 꽃잎 표피 세포의 윗면이 유리에 가까울 만큼 매끈한 데다, 표피 아래에 공기층이 얇게 떠 있어 반사면이 하나가 아니라 둘이었어요. 두 면이 겹쳐 반사를 두 배로 만들기 때문에 다른 꽃보다 유독 잘 비친다는 결론이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"cam.ac.uk\",\"sourceUrl\":\"https://www.cam.ac.uk/research/news/why-buttercups-reflect-yellow-on-chins\"},{\"id\":\"bstory-buttercup-little-frog\",\"title\":\"작은 개구리라는 이름 그리고 일부러 낸 물집\",\"hook\":\"라눙쿨루스는 라틴어로 '작은 개구리'예요.\",\"body\":\"미나리아재비속의 학명 Ranunculus는 라틴어 rana, 곧 개구리에 축소형 어미가 붙은 말이에요. '작은 개구리'라는 뜻이고, 물가와 축축한 자리에 잘 자라 개구리와 이웃이 되기 때문이라고 봐요. 이 풀에는 라눈쿨린이 들어 있는데, 잎이 으깨지면 프로토아네모닌으로 바뀌어 살갗에 물집을 만들어요. 유럽에서는 동정을 사려고 일부러 이 즙으로 물집을 냈다는 이야기가 전해질 만큼 잘 알려진 성질이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"home.howstuffworks.com\",\"sourceUrl\":\"https://home.howstuffworks.com/ranunculus.htm\"}]},\"1-21\":{\"photo\":{\"src\":\"/birth/damjaengideonggul.jpg\",\"thumbSrc\":\"/birth/thumbs/damjaengideonggul.jpg\",\"author\":\"Johann Jaritz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Poertschach_Hauptstrasse_Parthenocissus_tricuspidata_Blattwerk_04062015_4423.jpg\",\"familyLine\":\"포도과의 낙엽 덩굴식물이에요 — 흡반 달린 덩굴손으로 담벼락을 타고 오릅니다.\"},\"stories\":[{\"id\":\"bstory-ivy-last-leaf-behrman\",\"title\":\"벽에 그려진 잎 하나\",\"hook\":\"폐렴에 걸린 화가는 담쟁이 잎이 다 떨어지면 자기도 죽는다고 했습니다. 마지막 잎은 끝내 떨어지지 않았습니다.\",\"body\":\"오 헨리의 단편 「마지막 잎새」에서 존시는 폐렴으로 누워 창밖 벽돌담의 담쟁이덩굴을 세요. 잎이 다 떨어지면 자기도 간다고요. 아래층에는 사십 년 동안 붓을 들고도 걸작 하나 못 그린 늙은 화가 베어먼이 살아요. 늘 걸작을 그리겠다고 말만 하던 사람이에요. 비바람이 몰아친 밤이 지나고, 담쟁이에는 잎 하나가 남아 있었어요. 존시는 살아났고요. 그 잎은 베어먼이 그날 밤 벽에 그려 놓은 그림이었어요. 그리고 베어먼은 그 밤에 걸린 폐렴으로 세상을 떠났어요. 그게 그의 걸작이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"1900년대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/3707/pg3707-images.html\"},{\"id\":\"bstory-ivy-league-1935-newspaper\",\"title\":\"아이비리그라는 말은 기자들이 만들었습니다\",\"hook\":\"아이비리그는 대학들이 스스로 붙인 이름이 아니라 스포츠 기자들이 굴리던 말이었습니다.\",\"body\":\"아이비리그라는 말이 활자로 처음 확인되는 건 1935년 2월 7일 크리스천 사이언스 모니터예요. 이미 1933년에 뉴욕 트리뷴의 스탠리 우드워드가 비슷하게 쓴 기록도 있고요. 대학들이 모여 스스로 붙인 이름이 아니라 스포츠 기자들이 굴리던 말이었던 거예요. 정작 아이비리그가 정식 운동 연맹이 된 건 한참 뒤예요. 이름의 뿌리는 오래된 교사 벽을 덮은 덩굴이에요. 다만 그 벽을 실제로 덮고 있는 건 우리가 담쟁이덩굴이라 부르는 파르테노키수스인 경우가 많아요. 영어 아이비는 원래 헤데라를 가리키는 말이라, 같은 이름 아래 서로 다른 덩굴이 섞여 있는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"1930년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Ivy_League\"}]},\"1-22\":{\"photo\":{\"src\":\"/birth/ikki-0122.jpg\",\"thumbSrc\":\"/birth/thumbs/ikki-0122.jpg\",\"author\":\"Hans Hillewaert\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Polytrichum_commune_.jpg\",\"familyLine\":\"꽃 대신 포자로 번지는 선태식물이에요 — 그늘지고 축축한 땅을 초록 융단처럼 덮습니다.\"},\"stories\":[{\"id\":\"bstory-moss-sphagnum-field-dressing\",\"title\":\"늪에서 걷어 온 붕대\",\"hook\":\"1차 세계대전의 표준 지혈대는 공장이 아니라 늪에서 왔습니다. 그걸 걷은 사람은 여자와 아이들이었습니다.\",\"body\":\"1차 세계대전 초기에는 상처보다 패혈증으로 죽는 병사가 더 많았어요. 1915년에 군의관 찰스 캐스카트가 옛 기록을 떠올렸어요. 예전에는 물이끼로 상처를 싸맸다는 거예요. 시험해 보니 통했어요. 물이끼는 솜보다 두 배 넘는 피와 진물을 빨아들이고, 산성이라 세균이 잘 못 자라거든요. 그래서 전국 규모의 이끼 채집 사업이 시작됐어요. 보드민 무어에서 셰틀랜드까지, 여자들과 아이들이 차고 젖은 늪에 들어가 이끼를 걷었어요. 말리고 골라 무명 주머니에 채운 그 이끼가 영국과 자치령 군대의 표준 지혈대가 됐어요. 군복 안쪽에 꿰매 넣고 다니는 그 주머니예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"1910년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theconversation.com\",\"sourceUrl\":\"https://theconversation.com/war-and-peat-how-bog-moss-helped-save-thousands-of-lives-in-world-war-i-106630\"},{\"id\":\"bstory-moss-who-picked-it\",\"title\":\"그 이끼를 캔 사람들\",\"hook\":\"붕대가 될 이끼를 캔 것은 각지의 여자들과 아이들이었어요.\",\"body\":\"물이끼 붕대의 재료는 공장이 아니라 늪지에서 나왔어요. 그것을 캐고 말리고 자루에 채운 것은 온갖 나이의 여성과 아이들이었어요. 캐나다 적십자 온타리오 지부만 해도 1916년 한 해에 100만 장이 넘는 붕대를 만들어 보냈고, 1918년에는 영국에서 한 달에 100만 장이 병원으로 나갔어요. 전선 반대편도 사정은 같아서 독일에서는 민간인은 물론 연합군 포로까지 이 일에 동원됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-absorbency\",\"title\":\"제 무게 22배를 머금는 이끼\",\"hook\":\"세포의 90퍼센트가 죽은 세포라, 물이끼는 제 무게의 22배까지 물을 빨아들여요.\",\"body\":\"물이끼는 제 무게의 22배까지 물을 머금어요. 탈지면의 두 배죠. 세포의 90퍼센트가 죽은 세포라 애초에 물을 빨아들이게 생긴 구조예요. 게다가 세포벽이 음전하를 띠어 상처 둘레를 산성으로 만들고, 그 산성이 세균 번식을 막아요. 식물학자 아이작 베일리 밸푸어와 군의관 찰스 워커 캐스카트가 쓸 만한 두 종을 골라냈어요. 1916년 캐나다 적십자는 드레싱 100만 장 넘게, 압박포 200만 장 가까이, 패드 100만 장을 보냈고, 1918년에는 영국에서 매달 100만 장이 유럽과 이집트, 메소포타미아의 병원으로 나갔어요. 채집 안내문은 자루를 4분의 3만 채워 마른 땅으로 끌어낸 다음 그 위에서 춤을 춰 물을 빼라고 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-saihoji\",\"title\":\"설계되지 않은 이끼 정원\",\"hook\":\"교토 사이호지의 이끼 120종은 정원사가 심은 게 아니라 홍수와 방치가 만든 거예요.\",\"body\":\"교토 사이호지 정원을 덮은 이끼는 120종이에요. 그런데 처음부터 이끼 정원으로 설계된 게 아니에요. 무소 소세키가 이 절을 되살렸을 때만 해도 황금 연못에 뜬 섬들의 꼭대기는 수면과 거의 같은 높이였어요. 그 뒤 이 일대는 몇 번이나 홍수를 겪었고, 그때마다 연못 바닥을 쳐내 물 높이를 낮추면서 퍼낸 진흙을 섬 위에 쌓았어요. 이끼는 그 진흙에서 자라기 시작했어요. 특히 에도 시대, 절을 손볼 사람이 없어 허물어져 가는 동안 이끼가 두껍게 앉았고, 지금 사람들이 보러 오는 풍경은 그 방치의 결과예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mlit.go.jp\",\"sourceUrl\":\"https://www.mlit.go.jp/tagengo-db/en/R1-00439.html\"}]},\"1-23\":{\"photo\":{\"src\":\"/birth/budeul.jpg\",\"thumbSrc\":\"/birth/thumbs/budeul.jpg\",\"author\":\"Peter O'Connor aka anemoneprojectors from Stevenage, United Kingdom\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Bulrush_(Typha_latifolia)_(8139113636).jpg\",\"familyLine\":\"물가에 서는 부들과의 여러해살이풀이에요 — 여름이면 소시지 모양의 갈색 암꽃차례가 곧게 올라옵니다.\"},\"stories\":[]},\"1-24\":{\"photo\":{\"src\":\"/birth/gaeule-pineun-sapeuran.jpg\",\"thumbSrc\":\"/birth/thumbs/gaeule-pineun-sapeuran.jpg\",\"author\":\"Koshur\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Macro_photograph_of_saffron_flower_(Crocus_sativus).jpg\",\"familyLine\":\"붓꽃과의 알뿌리 식물이에요 — 가을에 보랏빛 꽃을 피우고, 붉은 암술을 말려 사프란 향신료로 씁니다.\"},\"stories\":[]},\"1-25\":{\"photo\":{\"src\":\"/birth/jeomnadonamul.jpg\",\"thumbSrc\":\"/birth/thumbs/jeomnadonamul.jpg\",\"author\":\"Peter O'Connor aka anemoneprojectors from Stevenage, United Kingdom\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Common_Mouse-ear_(Cerastium_fontanum)_(9163760223).jpg\",\"familyLine\":\"석죽과의 작은 들풀이에요 — 잔털 덮인 줄기 끝에 끝이 갈라진 흰 꽃잎을 답니다.\"},\"stories\":[{\"id\":\"bstory-cerastium-cow-horn-capsule\",\"title\":\"이름은 소뿔에서 왔습니다\",\"hook\":\"속명 케라스티움은 뿔이라는 뜻입니다. 꽃이 아니라 열매를 보고 붙인 이름입니다.\",\"body\":\"점나도나물속의 속명 케라스티움은 그리스어 케라스에서 왔어요. 뿔이라는 뜻이에요. 꽃 이야기가 아니에요. 열매 이야기예요. 이 무리 가운데 어떤 종은 씨앗이 든 꼬투리가 소뿔처럼 살짝 휘어 있거든요. 그 굽은 모양 하나 때문에 속 전체가 뿔이라는 이름을 갖게 된 거예요. 흰 꽃이 무더기로 피는 원예종 케라스티움 토멘토숨은 여름에 내리는 눈이라는 별명으로 불려요. 이탈리아가 고향인데, 흰 꽃이 하도 빽빽하게 피어서 바닥이 하얗게 덮이거든요. 종소명 토멘토숨은 잎과 줄기에 흰 솜털이 덮여 있다는 뜻이고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/cerastium-tomentosum/\"}]},\"1-26\":{\"photo\":{\"src\":\"/birth/mimosa.jpg\",\"thumbSrc\":\"/birth/thumbs/mimosa.jpg\",\"author\":\"Ranjithsiji\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Mimosa_pudica_flower_DSC_4267.jpg\",\"familyLine\":\"콩과의 열대성 풀이에요 — 잎을 건드리면 곧바로 접히고, 분홍 솜방울 같은 꽃이 핍니다.\"},\"stories\":[{\"id\":\"bstory-mimosa-de-mairan-cupboard\",\"title\":\"찬장 속에서도 잎을 여닫았습니다\",\"hook\":\"1729년, 한 천문학자가 미모사를 찬장에 가두었습니다. 빛이 없는데도 잎은 때를 맞춰 열리고 닫혔습니다.\",\"body\":\"1729년 프랑스의 장 자크 도르투 드 메랑이 미모사 화분 하나를 어두운 찬장에 넣었어요. 미모사 잎은 낮에 펴지고 밤에 접히잖아요. 빛이 없으면 그 리듬도 멈출 거라고 생각하기 쉬운데, 아니었어요. 캄캄한 찬장 안에서도 잎은 때를 맞춰 열리고 닫혔어요. 식물 안에 시계가 들어 있다는 첫 증거였어요. 메랑은 조심스러운 사람이었어요. 온도 변화나 새어 든 빛 같은 다른 요인을 지울 수 없다고 스스로 적었고, 이건 다른 학자들이 이어서 해야 할 일이라고 미뤄 두었어요. 그 뒤 백 년이 지나 드 캉돌이 이 리듬의 주기를 재 보니 스물두 시간 반이었어요. 하루보다 짧았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"srbr.org\",\"sourceUrl\":\"https://srbr.org/the-birth-of-chronobiology-a-botanical-observation/\"},{\"id\":\"bstory-mimosa-gagliano-drop-training\",\"title\":\"떨어뜨려도 더는 잎을 접지 않았습니다\",\"hook\":\"화분을 계속 떨어뜨렸더니 미모사가 잎 접기를 그만뒀습니다. 한 달 뒤에도 기억하고 있었습니다.\",\"body\":\"서호주대학교의 모니카 갈리아노 연구진은 미모사를 동물처럼 다뤄 봤어요. 장치를 만들어 화분을 같은 높이에서 반복해서 떨어뜨린 거예요. 처음에는 미모사가 잎을 착착 접었어요. 그런데 이 충격이 실제로 해롭지 않다는 걸 알아차리자 잎 접기를 그만뒀어요. 더 놀라운 건 그다음이에요. 한 달 동안 아무 방해 없이 놔둔 뒤에 다시 떨어뜨렸는데도 미모사는 잎을 접지 않았어요. 배운 걸 잊지 않은 거예요. 연구진은 이 지속 기간이 동물의 습관화와 맞먹는다고 적었어요. 다만 이 결과를 두고는 단순한 운동 피로일 뿐이라는 반박 논문도 나와 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"오스트레일리아\"},{\"key\":\"era\",\"text\":\"2010년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"sci.news\",\"sourceUrl\":\"https://www.sci.news/biology/science-mimosa-plants-memory-01695.html\"}]},\"1-27\":{\"photo\":{\"src\":\"/birth/magamok.jpg\",\"thumbSrc\":\"/birth/thumbs/magamok.jpg\",\"author\":\"Carlquist, Sherwin John, 1930-2021\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:(Sorbus_commixta_in_Mount_Nishi-Hotaka,_Japan)_-_DPLA_-_89bc6c038fe5f982c1bc4cbd61845136.jpg\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 초여름엔 흰 꽃이 우산처럼 모여 피고 가을엔 붉은 열매가 달립니다.\"},\"stories\":[{\"id\":\"bstory-rowan-red-thread-rhyme\",\"title\":\"마가목과 붉은 실\",\"hook\":\"마녀를 막는 방법은 간단했습니다. 마가목 가지 두 개를 붉은 실로 묶는 것입니다.\",\"body\":\"스코틀랜드에는 이런 가락이 전해져요. 마가목과 붉은 실은 마녀의 발을 늦춘다고요. 마가목 잔가지 두 개를 십자로 엇대고 붉은 실로 묶어요. 칼은 쓰지 않아요. 그걸 문설주 위에 걸거나, 외투 안감에 꿰매 넣거나, 주머니에 넣고 다녔어요. 맨섬에서는 오월 전야마다 소한테도 매달아 줬고요. 왜 하필 마가목이었을까요. 열매를 뒤집어 보면 꼭지 자리에 다섯 갈래 별 모양이 새겨져 있어요. 오래된 보호의 표식이거든요. 게다가 붉은색은 마법을 막는 색으로 여겨졌는데, 가을 마가목은 그 붉은 열매를 무더기로 달아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"treesforlife.org.uk\",\"sourceUrl\":\"https://treesforlife.org.uk/into-the-forest/trees-plants-animals/trees/rowan/rowan-mythology-and-folklore/\"},{\"id\":\"bstory-rowan-thor-river-grip\",\"title\":\"토르를 건져 올린 나무\",\"hook\":\"북유럽 신화에서 급류에 휩쓸리던 토르가 붙잡은 것이 마가목이었습니다.\",\"body\":\"북유럽 전승에 이런 이야기가 있어요. 토르가 저승의 거센 강물에 휩쓸려 떠내려가고 있었어요. 그때 마가목 한 그루가 강 쪽으로 몸을 굽혀 주었고, 토르는 그 가지를 붙잡고 뭍으로 올라왔어요. 스칸디나비아에서는 절벽이나 다른 나무의 갈라진 틈에 뿌리를 내린 마가목을 특별히 여겼어요. 땅에 닿지 않고 자란 나무라고 해서 나는 마가목이라 불렀고, 그런 나무에는 더 센 힘이 깃들었다고 봤어요. 룬 문자를 새겨 점을 칠 때 쓰는 나무도 마가목이었고요. 스코틀랜드 고지대에는 열매 말고는 이 나무의 어느 부분도 함부로 쓰지 말라는 강한 금기가 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"노르드\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"treesforlife.org.uk\",\"sourceUrl\":\"https://treesforlife.org.uk/into-the-forest/trees-plants-animals/trees/rowan/rowan-mythology-and-folklore/\"}]},\"1-28\":{\"photo\":{\"src\":\"/birth/geomeun-popeulra.jpg\",\"thumbSrc\":\"/birth/thumbs/geomeun-popeulra.jpg\",\"author\":\"Christian Fischer\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:PopulusNigra2a.jpg\",\"familyLine\":\"버드나무과의 낙엽 큰키나무예요 — 물가에서 곧게 자라며 봄에 늘어진 꽃차례를 답니다.\"},\"stories\":[{\"id\":\"bstory-black-poplar-heliades-amber\",\"title\":\"울다가 나무가 된 자매들\",\"hook\":\"해의 아들이 떨어져 죽자 누이들은 강가에서 울다 포플러가 됐습니다. 눈물은 굳어 호박이 됐습니다.\",\"body\":\"파에톤은 태양신 헬리오스의 아들이에요. 아버지의 태양 마차를 몰겠다고 고집을 부리다가 제우스의 벼락을 맞고 에리다노스강으로 떨어졌어요. 누이인 헬리아데스 자매들이 강가에 모여 울었어요. 울음이 그치지 않았어요. 그러다 발목이 굳고 뿌리가 잡히기 시작했어요. 오비디우스는 그 장면을 이렇게 적었어요. 맏이가 땅에 몸을 던지려는데 발목이 이미 굳어 있었고, 다른 누이는 머리카락을 쥐어뜯으려다 잎 달린 가지를 뜯었다고요. 자매들은 포플러가 됐어요. 그리고 흘러내린 눈물은 햇볕에 굳어 호박이 됐어요. 강물을 타고 흘러간 그 호박을 사람들이 주워 갔고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스·로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theoi.com\",\"sourceUrl\":\"https://www.theoi.com/Nymphe/NymphaiHeliades.html\"},{\"id\":\"bstory-black-poplar-600-females\",\"title\":\"영국에 남은 암나무는 육백 그루입니다\",\"hook\":\"영국의 야생 검은포플러는 칠천 그루쯤 남았습니다. 그중 암나무는 육백 그루입니다.\",\"body\":\"검은포플러는 한때 영국 풍경의 기본값이었어요. 지금은 아니에요. 야생 상태로 남은 검은포플러가 칠천 그루쯤인데, 그중 암나무는 육백 그루밖에 안 돼요. 문제는 여기예요. 나무가 씨로 이어지려면 암수가 서로 닿을 만한 거리에 있어야 하는데, 남은 나무들이 도랑가와 범람원에 뿔뿔이 흩어져 자라거든요. 슈롭셔, 체셔, 서머싯, 이스트앵글리아 쪽에 그나마 몰려 있어요. 다 자라면 삼십 미터까지 크고, 껍질이 짙은 갈색을 넘어 거의 검게 보여서 이런 이름이 붙었어요. 나방 애벌레들에게는 아주 중요한 먹이나무이기도 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"woodlandtrust.org.uk\",\"sourceUrl\":\"https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/british-trees/a-z-of-british-trees/black-poplar/\"}]},\"1-29\":{\"photo\":{\"src\":\"/birth/ikki-0122.jpg\",\"thumbSrc\":\"/birth/thumbs/ikki-0122.jpg\",\"author\":\"Hans Hillewaert\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Polytrichum_commune_.jpg\",\"familyLine\":\"꽃 대신 포자로 번지는 선태식물이에요 — 그늘지고 축축한 땅을 초록 융단처럼 덮습니다.\"},\"stories\":[{\"id\":\"bstory-moss-sphagnum-field-dressing\",\"title\":\"늪에서 걷어 온 붕대\",\"hook\":\"1차 세계대전의 표준 지혈대는 공장이 아니라 늪에서 왔습니다. 그걸 걷은 사람은 여자와 아이들이었습니다.\",\"body\":\"1차 세계대전 초기에는 상처보다 패혈증으로 죽는 병사가 더 많았어요. 1915년에 군의관 찰스 캐스카트가 옛 기록을 떠올렸어요. 예전에는 물이끼로 상처를 싸맸다는 거예요. 시험해 보니 통했어요. 물이끼는 솜보다 두 배 넘는 피와 진물을 빨아들이고, 산성이라 세균이 잘 못 자라거든요. 그래서 전국 규모의 이끼 채집 사업이 시작됐어요. 보드민 무어에서 셰틀랜드까지, 여자들과 아이들이 차고 젖은 늪에 들어가 이끼를 걷었어요. 말리고 골라 무명 주머니에 채운 그 이끼가 영국과 자치령 군대의 표준 지혈대가 됐어요. 군복 안쪽에 꿰매 넣고 다니는 그 주머니예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"1910년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theconversation.com\",\"sourceUrl\":\"https://theconversation.com/war-and-peat-how-bog-moss-helped-save-thousands-of-lives-in-world-war-i-106630\"},{\"id\":\"bstory-moss-who-picked-it\",\"title\":\"그 이끼를 캔 사람들\",\"hook\":\"붕대가 될 이끼를 캔 것은 각지의 여자들과 아이들이었어요.\",\"body\":\"물이끼 붕대의 재료는 공장이 아니라 늪지에서 나왔어요. 그것을 캐고 말리고 자루에 채운 것은 온갖 나이의 여성과 아이들이었어요. 캐나다 적십자 온타리오 지부만 해도 1916년 한 해에 100만 장이 넘는 붕대를 만들어 보냈고, 1918년에는 영국에서 한 달에 100만 장이 병원으로 나갔어요. 전선 반대편도 사정은 같아서 독일에서는 민간인은 물론 연합군 포로까지 이 일에 동원됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-absorbency\",\"title\":\"제 무게 22배를 머금는 이끼\",\"hook\":\"세포의 90퍼센트가 죽은 세포라, 물이끼는 제 무게의 22배까지 물을 빨아들여요.\",\"body\":\"물이끼는 제 무게의 22배까지 물을 머금어요. 탈지면의 두 배죠. 세포의 90퍼센트가 죽은 세포라 애초에 물을 빨아들이게 생긴 구조예요. 게다가 세포벽이 음전하를 띠어 상처 둘레를 산성으로 만들고, 그 산성이 세균 번식을 막아요. 식물학자 아이작 베일리 밸푸어와 군의관 찰스 워커 캐스카트가 쓸 만한 두 종을 골라냈어요. 1916년 캐나다 적십자는 드레싱 100만 장 넘게, 압박포 200만 장 가까이, 패드 100만 장을 보냈고, 1918년에는 영국에서 매달 100만 장이 유럽과 이집트, 메소포타미아의 병원으로 나갔어요. 채집 안내문은 자루를 4분의 3만 채워 마른 땅으로 끌어낸 다음 그 위에서 춤을 춰 물을 빼라고 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-saihoji\",\"title\":\"설계되지 않은 이끼 정원\",\"hook\":\"교토 사이호지의 이끼 120종은 정원사가 심은 게 아니라 홍수와 방치가 만든 거예요.\",\"body\":\"교토 사이호지 정원을 덮은 이끼는 120종이에요. 그런데 처음부터 이끼 정원으로 설계된 게 아니에요. 무소 소세키가 이 절을 되살렸을 때만 해도 황금 연못에 뜬 섬들의 꼭대기는 수면과 거의 같은 높이였어요. 그 뒤 이 일대는 몇 번이나 홍수를 겪었고, 그때마다 연못 바닥을 쳐내 물 높이를 낮추면서 퍼낸 진흙을 섬 위에 쌓았어요. 이끼는 그 진흙에서 자라기 시작했어요. 특히 에도 시대, 절을 손볼 사람이 없어 허물어져 가는 동안 이끼가 두껍게 앉았고, 지금 사람들이 보러 오는 풍경은 그 방치의 결과예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mlit.go.jp\",\"sourceUrl\":\"https://www.mlit.go.jp/tagengo-db/en/R1-00439.html\"}]},\"1-30\":{\"photo\":{\"src\":\"/birth/maeswi-merigoldeu.jpg\",\"thumbSrc\":\"/birth/thumbs/maeswi-merigoldeu.jpg\",\"author\":\"Krzysztof Golik\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Caltha_palustris_in_Avoriaz_(3).jpg\",\"familyLine\":\"미나리아재비과의 습지 식물이에요 — 이른 봄 물가에서 윤나는 노란 꽃을 피웁니다.\"},\"stories\":[{\"id\":\"bstory-marsh-marigold-not-a-marigold\",\"title\":\"메리골드가 아닌 메리골드\",\"hook\":\"이름에 메리골드가 들어 있지만 이 꽃은 메리골드와 아무 관계가 없습니다.\",\"body\":\"매쉬 메리골드는 이름이 잘못 붙은 대표적인 꽃이에요. 출처 자료도 대놓고 이 이름이 오해를 부른다고 적어 놓았어요. 생김새도 메리골드를 안 닮았고, 집안도 달라요. 메리골드는 국화과인데 매쉬 메리골드는 미나리아재비과예요. 학명은 칼타 팔루스트리스, 팔루스트리스는 늪에 산다는 뜻이에요. 뉴펀들랜드부터 알래스카까지, 남으로는 네브래스카와 노스캐롤라이나까지 물가를 따라 자라는 여러해살이풀이에요. 이름표만 보고 화단의 메리골드를 떠올리면 완전히 다른 꽃을 만나게 돼요. 물에 발을 담근 채 노란 꽃을 피우는 풀이거든요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/caltha-palustris/\"}]},\"1-31\":{\"stories\":[]},\"2-1\":{\"stories\":[]},\"2-2\":{\"photo\":{\"src\":\"/birth/mogwa.jpg\",\"thumbSrc\":\"/birth/thumbs/mogwa.jpg\",\"author\":\"Rorolinus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Pseudocydonia_sinensis_flower.JPG\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 봄에 연분홍 꽃이 피고 가을엔 향이 진한 노란 열매가 열립니다.\"},\"stories\":[]},\"2-3\":{\"photo\":{\"src\":\"/birth/hwangsaenaengi.jpg\",\"thumbSrc\":\"/birth/thumbs/hwangsaenaengi.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cardamine_flexuosa_kz06.jpg\",\"familyLine\":\"십자화과의 작은 봄나물이에요 — 논둑과 밭가에서 흰 꽃잎 네 장을 십자로 펼칩니다.\"},\"stories\":[]},\"2-4\":{\"stories\":[]},\"2-5\":{\"photo\":{\"src\":\"/birth/yangchi-0205.jpg\",\"thumbSrc\":\"/birth/thumbs/yangchi-0205.jpg\",\"author\":\"MPF\",\"license\":\"CC BY 2.5\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Athyrium_filix-femina0.jpg\",\"familyLine\":\"꽃 대신 포자로 번지는 양치식물이에요 — 돌돌 말린 새순이 펴지며 깃털 같은 잎이 됩니다.\"},\"stories\":[{\"id\":\"bstory-fern-seed-walk-invisible\",\"title\":\"고사리 씨앗을 쥐면 투명해집니다\",\"hook\":\"셰익스피어의 등장인물은 이렇게 말합니다. 우리에겐 고사리 씨앗 처방이 있으니 보이지 않게 다닌다고요.\",\"body\":\"헨리 4세 1부에 이런 대사가 나와요. 우리에겐 고사리 씨앗 처방이 있으니 보이지 않게 다닌다고요. 관객이 웃으려면 그 말을 알아들어야 하잖아요. 그러니까 그 시절 영국 사람들은 고사리 씨앗이 사람을 투명하게 만든다고 믿었던 거예요. 채집법도 정해져 있었어요. 한여름 밤 자정, 고사리 잎 아래에 백랍 접시 열두 장을 겹쳐 놓아요. 자정에 푸른 꽃이 열리며 금빛 씨앗 한 알이 떨어지는데, 그게 접시 열한 장을 뚫고 열두 번째 접시에 내려앉는다는 거예요. 사실 고사리는 꽃도 씨앗도 없어요. 잎 뒷면의 갈색 점, 그건 포자예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기~19세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"britishfairies.wordpress.com\",\"sourceUrl\":\"https://britishfairies.wordpress.com/2018/02/18/fern-seed-and-invisibility/\"},{\"id\":\"bstory-fern-boyi-shuqi-wei\",\"title\":\"주나라 곡식을 안 먹겠다며 캐 먹은 것\",\"hook\":\"두 형제는 주나라 곡식을 먹지 않겠다며 산에 들어가 풀을 캐 먹었습니다. 그러다 굶어 죽었습니다.\",\"body\":\"사기 백이열전에 나오는 이야기예요. 백이와 숙제는 고죽군의 두 아들이었어요. 무왕이 은나라를 치는 것을 두고 신하가 임금을 죽이는 일이라며 말렸지만 소용없었어요. 천하가 주나라를 섬기게 되자 두 사람은 그것을 부끄럽게 여겼어요. 의롭게 주나라 곡식을 먹지 않겠다며 수양산에 숨어 미를 캐 먹었어요. 굶어 죽기 직전에 노래 하나를 지었고, 그러고는 수양산에서 굶어 죽었어요. 여기 나오는 미를 우리말로는 오래도록 고사리라고 옮겨 왔어요. 다만 그 풀이 실제로 어떤 식물이었는지는 갈려요. 고사리로 보는 쪽도, 살갈퀴 종류로 보는 쪽도 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"ctext.org\",\"sourceUrl\":\"https://ctext.org/shiji/bo-yi-lie-zhuan\"},{\"id\":\"bstory-fern-fernseed-invisible\",\"title\":\"고사리 씨앗을 가진 도둑\",\"hook\":\"셰익스피어의 강도는 고사리 씨앗 처방으로 투명해진다고 자랑해요.\",\"body\":\"양치식물은 꽃도 씨앗도 맺지 않아요. 포자로 번지죠. 그런데 눈에 보이지 않는 씨앗이 있다면 그걸 지닌 사람도 보이지 않게 되지 않을까. 이 논리가 유럽에 오래 떠돌았어요. 셰익스피어는 헨리 4세 1부 2막 1장에서 그 믿음을 그대로 무대에 올려요. 강도 개즈힐이 이렇게 말해요. 우리는 성 안에 있는 것처럼 마음 놓고 훔친다, 우리에게는 고사리 씨앗 처방이 있어서 보이지 않게 다니거든. 그러자 여관 지배인이 곧바로 받아쳐요. 글쎄, 네가 보이지 않게 다니는 건 고사리 씨앗보다 밤 덕이 더 클 것 같은데.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"shakespeare.mit.edu\",\"sourceUrl\":\"https://shakespeare.mit.edu/1henryiv/1henryiv.2.1.html\"},{\"id\":\"bstory-fern-pteridomania-1855\",\"title\":\"1855년 영국을 덮친 고사리 열병\",\"hook\":\"킹즐리는 딸들이 걸린 유행에 '프테리도마니아'라는 병명을 붙였어요.\",\"body\":\"1855년 5월, 찰스 킹즐리는 글라우코스, 혹은 바닷가의 경이라는 책을 냅니다. 그 안에 이런 문장이 있어요. 당신의 딸들도 아마 요즘 유행하는 프테리도마니아에 걸려서, 고사리를 모으고 사들이고, 그것을 기를 워드 상자까지 장만하고, 발음도 안 되는 학명을 두고 다투고 있을 거라고요. 그 상자 값은 아버지가 치른다는 말도 괄호로 덧붙여요. 프테리도마니아는 킹즐리가 만든 말이에요. 양치식물을 뜻하는 그리스어 어근에 광기를 뜻하는 마니아를 붙였죠. 그러면서도 그는 이 유행이 소설이나 자수보다 딸들을 더 활기차고 밝게 만든다고 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"빅토리아 시대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/695/pg695.txt\"}]},\"2-6\":{\"photo\":{\"src\":\"/birth/bawisol.jpg\",\"thumbSrc\":\"/birth/thumbs/bawisol.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Orostachys_japonica_(flower).jpg\",\"familyLine\":\"돌나물과의 다육식물이에요 — 바위와 기와 위에 붙어 살다 가을에 흰 꽃대를 탑처럼 올립니다.\"},\"stories\":[]},\"2-7\":{\"stories\":[]},\"2-8\":{\"photo\":{\"src\":\"/birth/beomuigwi-0208.jpg\",\"thumbSrc\":\"/birth/thumbs/beomuigwi-0208.jpg\",\"author\":\"Averater\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Saxifraga_fortunei_GotBot_2015_001.jpg\",\"familyLine\":\"바위틈에 뿌리내리는 범의귀과의 여러해살이풀이에요 — 가는 꽃대 끝에 흰 꽃이 흩날리듯 달립니다.\"},\"stories\":[{\"id\":\"bstory-saxifraga-rock-breaker\",\"title\":\"바위를 깨는 풀이라는 이름\",\"hook\":\"속명 자체가 바위를 깬다는 뜻입니다. 실제로 이 풀은 바위 틈에 뿌리를 박고 시간을 들여 돌을 벌립니다.\",\"body\":\"범의귀속의 속명 삭시프라가는 라틴어 두 낱말을 붙인 이름이에요. 삭숨은 바위, 프란게레는 깨뜨린다는 뜻이에요. 합치면 바위를 깨는 풀이 돼요. 허풍이 아니에요. 이 무리는 그늘진 벼랑이나 이끼 낀 바위 틈에 자리를 잡고, 그 틈에 뿌리를 밀어 넣어 시간을 들여 돌을 조금씩 벌려 놓거든요. 사람 눈에는 그저 작고 여린 풀인데, 하는 일은 바위 쪼개기예요. 무거운 점토질 흙도 견뎌서 지피식물로 곧잘 쓰이고요. 도감에서는 무릎 높이도 안 되는 풀 옆에 이 사나운 이름이 나란히 붙어 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/saxifraga-stolonifera/\"},{\"id\":\"bstory-aarons-beard-wheler1676\",\"title\":\"1676년 한 그루에서\",\"hook\":\"영국과 아일랜드 야생 개체가 전부 1676년 들여온 정원 계통 하나에서 갈라졌대요.\",\"body\":\"아론의 수염이라 불리는 히페리쿰 칼리키눔은 불가리아와 튀르키예 북서부가 고향이에요. 영국 제도에는 1676년에 조지 휠러 경이 이스탄불 근처에서 가져와 심었죠. 놀라운 건 그다음이에요. 영국과 아일랜드에서 야생으로 자라는 개체가 전부 그때 들어온 정원 계통 하나에서 갈라져 나온 것으로 보인다는 거예요. 비결은 번식 방식에 있어요. 이 아관목은 영국과 아일랜드에서 꽃이 대체로 자가불화합성이라 씨를 잘 맺지 못하는데, 대신 땅속줄기가 흙 속을 빠르게 달리며 한자리에 오래 남는 복제 군락을 만들거든요. 350년 가까이 같은 개체가 몸을 늘려 온 셈이죠. 다만 새 원예 품종이 들어오면 그 벽이 깨져 침입성이 커질 수 있다는 경고도 함께 붙어 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"bsbi.org\",\"sourceUrl\":\"https://bsbi.org/in-your-area/local-botany/co-fermanagh/fermanagh-species-accounts/hypericum-calycinum-l\"},{\"id\":\"bstory-aarons-beard-londonpride\",\"title\":\"폭격 자리에 핀 런던 프라이드\",\"hook\":\"대공습 폭격 터를 뒤덮은 범의귀속 풀이 1941년 봄 노래의 제목이 됐어요.\",\"body\":\"런던 프라이드는 범의귀속의 교잡종 삭시프라가 우르비움을 가리키는 이름이에요. 스페인 피레네산맥의 종과 아일랜드 서부의 종이 만나 생긴 잡종으로, 적어도 17세기부터 알려져 있었죠. 숟가락 모양 잎이 방석처럼 깔리고 초여름에 분홍빛이 도는 흰 꽃이 작게 올라와요. 2차 세계대전 공습으로 런던 곳곳이 폐허가 되자 이 작은 풀이 폭격 자리를 빠르게 덮었어요. 노엘 카워드는 1941년 봄 대공습 한복판에서 시민들의 사기를 북돋우려 같은 이름의 노래 런던 프라이드를 썼고요. 이 식물은 1993년 영국왕립원예협회의 가든 메리트상을 받았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"gardenofeaden.blogspot.com\",\"sourceUrl\":\"https://gardenofeaden.blogspot.com/2017/02/which-plant-is-london-pride.html\"}]},\"2-9\":{\"photo\":{\"src\":\"/birth/eunmaehwa.jpg\",\"thumbSrc\":\"/birth/thumbs/eunmaehwa.jpg\",\"author\":\"Giancarlo Dessì\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Myrtus_communis11.jpg\",\"familyLine\":\"지중해가 고향인 도금양과의 늘푸른 관목이에요 — 수술이 부챗살처럼 퍼진 흰 꽃에서 맑은 향이 납니다.\"},\"stories\":[{\"id\":\"bstory-myrtle-gotha-nosegay-1845\",\"title\":\"1845년 꽃다발에서 잘라 낸 가지 하나\",\"hook\":\"빅토리아 여왕이 받은 꽃다발에서 가지 하나를 잘라 심었습니다. 그 덤불은 지금도 살아 있습니다.\",\"body\":\"1845년 9월 3일, 빅토리아 여왕은 독일 고타를 떠나면서 꽃다발 하나를 받았어요. 앨버트 공의 할머니가 건넨 거였어요. 여왕은 그 다발에서 은매화 가지 하나를 잘라 새로 산 별장 오스본 하우스의 담장 아래에 심게 했어요. 그 덤불이 지금도 살아 있어요. 1858년 큰딸 빅토리아가 프로이센 왕자와 결혼할 때, 그 덤불에서 자른 가지가 부케에 들어갔어요. 신부의 순결을 뜻하는 독일식 관습이었대요. 그 뒤로 엘리자베스 2세, 다이애나, 캐서린, 메건까지 왕실 신부들의 부케에는 이 담장에서 자른 가지가 계속 들어갔어요. 백칠십 년 넘게 한 덤불에서 나온 가지예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"english-heritage.org.uk\",\"sourceUrl\":\"https://www.english-heritage.org.uk/visit/inspire-me/blog/blog-posts/osborne-myrtle-and-royal-weddings/\"},{\"id\":\"bstory-myrtle-aphrodite-sacred\",\"title\":\"사랑의 여신에게 바쳐진 나무\",\"hook\":\"은매화가 결혼식 꽃이 된 데에는 이천 년 넘은 사연이 있습니다.\",\"body\":\"고전 자료들은 아프로디테에게 바쳐진 식물을 나열할 때 은매화를 맨 앞에 놓아요. 장미, 사과, 양귀비와 함께요. 오비디우스의 축제력, 비온의 목가, 파우사니아스의 기행문 같은 여러 원전이 같은 목록을 전해요. 사랑과 아름다움의 여신에게 딸린 나무였던 거예요. 그러니 신부가 은매화를 드는 관습은 어제오늘 일이 아니에요. 지중해에서 이 나무는 아주 오래전부터 혼례의 상징이었고, 그 자리가 유럽 곳곳으로 퍼졌어요. 영국 왕실이 독일식 관습이라 부른 그 풍습도, 거슬러 올라가면 이 목록에 닿아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"theoi.com\",\"sourceUrl\":\"https://www.theoi.com/Olympios/Aphrodite.html\"}]},\"2-10\":{\"photo\":{\"src\":\"/birth/seohyang-0210.jpg\",\"thumbSrc\":\"/birth/thumbs/seohyang-0210.jpg\",\"author\":\"chisloup\",\"license\":\"CC BY 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Daphn%C3%A9_odora_en_fleurs_-_panoramio.jpg\",\"familyLine\":\"팥꽃나무과의 늘푸른 관목이에요 — 이른 봄, 잎보다 먼저 뭉친 꽃송이에서 멀리까지 향이 퍼집니다.\"},\"stories\":[{\"id\":\"bstory-daphne-odora-not-a-laurel\",\"title\":\"월계수의 이름을 쓰는 월계수 아닌 나무\",\"hook\":\"학명은 다프네, 흔한 별명은 스퍼지 로렐. 그런데 이 나무는 월계수가 아닙니다.\",\"body\":\"서향의 학명은 다프네 오도라예요. 다프네는 그리스 말로 월계수를 뜻해요. 아폴론에게 쫓기다 월계수가 된 님프의 이름이기도 하고요. 영어권에서 이 나무에 붙은 별명 가운데는 스퍼지 로렐, 드워프 베이 같은 것도 있어요. 로렐도 베이도 월계수를 가리키는 말이에요. 그런데 서향은 월계수와 아무 관계가 없어요. 팥꽃나무과 나무거든요. 향기 하나만큼은 대단해서 겨울 끝자락에 담장 하나를 통째로 채워요. 대신 온몸에 독이 있어요. 자료는 이 나무의 독성을 최고 등급으로 매겨 놓았어요. 이름은 월계수, 집안은 팥꽃나무, 성질은 독초예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/daphne-odora/\"},{\"id\":\"bstory-daphne-sleeping-scent\",\"title\":\"여산에서 잠을 깬 향기\",\"hook\":\"벼랑 밑에서 낮잠을 자다 향기에 깬 승려가 이 나무에 이름을 붙였대요.\",\"body\":\"서향은 중국이 원산이고 송나라 때부터, 그러니까 천 년 넘게 길러 온 나무예요. 중국 본초 기록에는 이름의 유래로 이런 이야기가 전해요. 여산 벼랑 아래에서 낮잠을 자던 승려가 잊을 수 없는 향기에 잠을 깼고, 그 향의 근원을 찾아 벼랑을 올라가 꽃이 핀 이 나무를 발견하고는 잠결의 향이라 이름 붙였다는 거예요. 늦겨울에 밀랍처럼 도톰한 분홍 꽃이 뭉쳐 피고 향은 꽤 멀리까지 퍼져요. 유럽 정원사들이 이 나무를 만난 것은 1771년, 일본을 거쳐 영국에 들어오면서였어요. 잎이든 열매든 뿌리든 먹으면 중독되고 수액은 피부를 상하게 해요. 물이 고이는 흙에서는 뿌리가 썩어 그대로 죽어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"woodlanders.net\",\"sourceUrl\":\"https://woodlanders.net/products/daphne-odora\"},{\"id\":\"bstory-daphne-not-laurel\",\"title\":\"린네가 남긴 말장난\",\"hook\":\"그리스어 다프네는 월계수라는 뜻인데, 정작 서향은 월계수와 과부터 달라요.\",\"body\":\"서향속의 학명 다프네는 그리스어로 월계수라는 뜻이에요. 아폴론에게 쫓기던 물의 님프 다프네가 강의 신인 아버지에게 빌어 월계수로 변했다는 신화에서 온 말이죠. 그런데 정원의 서향은 월계수와 아무 관계가 없어요. 월계수는 녹나무과이고 서향은 팥꽃나무과라 과부터 다릅니다. 1750년대에 이명법을 세운 린네는 이 사실을 알면서도 유럽의 한 종에 다프네 라우레올라라는 이름을 붙였어요. 풀어 쓰면 월계수 월계수인 셈이라, 일종의 말장난이었어요. 서향은 중국 송나라 때부터 재배됐고 일본 기록에는 1309년에 나타나요. 중국에서는 목이 아플 때와 천연두에 씻는 약으로 썼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"khkeeler.blogspot.com\",\"sourceUrl\":\"http://khkeeler.blogspot.com/2015/05/plant-story-daphne-attractive-and.html\"}]},\"2-11\":{\"photo\":{\"src\":\"/birth/melrisa.jpg\",\"thumbSrc\":\"/birth/thumbs/melrisa.jpg\",\"author\":\"Jamain\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Melissa_officinalis_J1.jpg\",\"familyLine\":\"꿀풀과의 여러해살이 허브예요 — 잎을 문지르면 레몬 향이 나서 차로 즐겨 마십니다.\"},\"stories\":[{\"id\":\"bstory-melissa-carmelite-water-1611\",\"title\":\"1611년 파리 수도원이 만든 물\",\"hook\":\"1611년 파리의 맨발 카르멜회 수도원이 향초를 증류해 만든 물이, 지금도 같은 이름으로 팔립니다.\",\"body\":\"1611년, 맨발 카르멜회 수도사들이 파리 보지라르 거리 70번지에 수도원을 세웠어요. 후원자는 프랑스 왕비 마리 드 메디시스였고요. 이들은 그곳에 증류소를 차리고 약초와 향신료를 섞어 물 하나를 만들었어요. 멜리사, 그러니까 레몬밤이 중심이었어요. 오 드 멜리스 데 카름이라는 이름으로 팔린 이 물은 만병통치에 가깝게 대접받았어요. 처방은 비밀이었고요. 지금은 부아예 가문이 그 처방을 물려받아 일곱 대째 손으로 만들고 있어요. 사백 년 넘게 이름도, 만드는 사람도 크게 바뀌지 않은 물이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"17세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"eaudemelisse.com\",\"sourceUrl\":\"https://eaudemelisse.com/en/our-history/origins/\"},{\"id\":\"bstory-melissa-pliny-keep-the-swarm\",\"title\":\"벌을 붙잡아 두는 풀\",\"hook\":\"플리니우스는 벌이 달아나지 않게 하려면 이 풀을 심으라고 적었습니다.\",\"body\":\"플리니우스의 박물지 21권에는 벌을 위해 심어야 할 풀을 다룬 장이 따로 있어요. 거기 멜리소필론이라는 풀이 나와요. 꿀잎이라는 뜻이에요. 후대 주석자들은 이 풀을 린네가 말한 멜리사 오피키날리스, 그러니까 레몬밤으로 봤어요. 플리니우스가 적어 둔 쓸모는 이래요. 이 풀이 있으면 벌떼가 처음 날아오를 때 잘 모여들고, 멀리까지 흩어져 달아나는 것을 막아 준다고요. 벌을 붙잡아 두는 풀이었던 거예요. 멜리사라는 이름 자체가 그리스 말로 꿀벌이에요. 이름과 쓸모가 같은 자리를 가리키는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"1세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"perseus.tufts.edu\",\"sourceUrl\":\"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.02.0137%3Abook%3D21%3Achapter%3D41\"}]},\"2-12\":{\"photo\":{\"src\":\"/birth/jwikkorimangcho.jpg\",\"thumbSrc\":\"/birth/thumbs/jwikkorimangcho.jpg\",\"author\":\"Jeevan Jose, Kerala, India\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rostellularia_procumbens_by_kadavoor.jpg\",\"familyLine\":\"쥐꼬리망초과의 한해살이풀이에요 — 길가에서 이삭 모양 꽃차례에 연분홍 꽃을 차례로 답니다.\"},\"stories\":[]},\"2-13\":{\"photo\":{\"src\":\"/birth/galpul.jpg\",\"thumbSrc\":\"/birth/thumbs/galpul.jpg\",\"author\":\"Rasbak\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Phalaris_arundinacea_flowers,_rietgras_bloempjes_(1).jpg\",\"familyLine\":\"물가에 무리 짓는 벼과의 여러해살이풀이에요 — 초여름에 이삭이 촘촘히 뭉친 꽃차례를 세웁니다.\"},\"stories\":[{\"id\":\"bstory-canary-grass-invader\",\"title\":\"정원에서 나가 늪을 덮었습니다\",\"hook\":\"정원사의 대님이라 불릴 만큼 얌전한 무늬풀이, 습지에서는 다른 풀을 밀어냅니다.\",\"body\":\"갈풀의 학명은 팔라리스 아룬디나케아예요. 영어권에서는 리드 카나리그래스라고 불러요. 잎에 흰 줄무늬가 든 원예 품종은 정원사의 대님, 리본 그래스라는 예쁜 별명으로 팔리고요. 그런데 이 풀이 습지로 나가면 이야기가 달라져요. 서늘한 철에 먼저 올라와 자리를 선점하고 빽빽하게 덮어 버리거든요. 북미에서는 숲과 습지를 위협하는 침입종으로 관리 대상이에요. 헷갈리는 건 여기예요. 북미에도 자생하는 갈풀 계열이 따로 있어서, 같은 종 안에서 자생 계통과 침입 계통이 섞여 있어요. 그래서 눈으로 보고 어느 쪽인지 가려내기가 아주 어려워요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/phalaris-arundinacea/\"}]},\"2-14\":{\"photo\":{\"src\":\"/birth/kamomilre.jpg\",\"thumbSrc\":\"/birth/thumbs/kamomilre.jpg\",\"author\":\"Sarbast.T.Hameed\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Matricaria_Chamomilla_Flowers.jpg\",\"familyLine\":\"국화과의 한해살이 허브예요 — 사과 향이 나는 흰 꽃을 말려 차로 우려 마십니다.\"},\"stories\":[{\"id\":\"bstory-chamomile-peter-rabbit-tea\",\"title\":\"말썽 부린 밤에 먹인 차\",\"hook\":\"동화 속에서 가장 유명한 처벌은 매가 아니라 캐모마일 차 한 숟갈이었습니다.\",\"body\":\"베아트릭스 포터의 「피터 래빗 이야기」 마지막 장면이에요. 피터는 맥그리거 씨네 밭에 몰래 들어갔다가 재킷과 신발을 잃고 겨우 도망쳐 나와요. 두 주 사이에 두 번째로 잃어버린 옷이었어요. 그날 저녁 피터는 몸이 좋지 않았어요. 엄마는 피터를 침대에 눕히고 캐모마일 차를 끓였어요. 그리고 한 숟갈을 먹였어요. 잠들기 전에 한 큰술이라고 적혀 있어요. 같은 시각 말썽을 안 부린 플롭시와 몹시와 코튼테일은 빵과 우유와 블랙베리를 먹었고요. 아이들 책에서 캐모마일 차는 그렇게 약이자 벌이자 위로가 됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"1900년대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/14838/pg14838-images.html\"},{\"id\":\"bstory-chamomile-falstaff-trodden\",\"title\":\"밟힐수록 잘 자란다는 말\",\"hook\":\"폴스타프는 이렇게 말합니다. 캐모마일은 밟힐수록 빨리 자라지만 젊음은 쓸수록 빨리 닳는다고요.\",\"body\":\"헨리 4세 1부 2막 4장에서 폴스타프가 왕 흉내를 내며 왕자에게 훈계를 늘어놔요. 그 대사에 캐모마일이 나와요. 캐모마일은 밟힐수록 더 빨리 자라지만 젊음은 헛되이 쓸수록 더 빨리 닳는다고요. 술집에서 사기꾼이 늘어놓는 헛소리 한가운데, 정확한 원예 지식 하나가 박혀 있는 거예요. 실제로 캐모마일은 밟히는 데 강해요. 그래서 유럽에서는 잔디 대신 캐모마일을 깔아 밟고 다니는 정원을 만들기도 했어요. 밟으면 향이 올라오거든요. 셰익스피어의 관객은 그 냄새를 알고 있었을 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"opensourceshakespeare.org\",\"sourceUrl\":\"https://www.opensourceshakespeare.org/views/plays/play_view.php?WorkID=henry4p1&Act=2&Scene=4&Scope=scene\"}]},\"2-15\":{\"photo\":{\"src\":\"/birth/samnamu-0215.jpg\",\"thumbSrc\":\"/birth/thumbs/samnamu-0215.jpg\",\"author\":\"Σ64\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Kanagawa-birin50-daiyuuzan.JPG\",\"familyLine\":\"측백나무과의 늘푸른 침엽수예요 — 곧게 뻗은 붉은 줄기와 송곳 같은 잎이 숲을 이룹니다.\"},\"stories\":[{\"id\":\"bstory-sugi-yakushima-thousand-years\",\"title\":\"천 년이 기준선인 숲\",\"hook\":\"야쿠시마에서는 천 년을 넘긴 삼나무만 야쿠스기라고 부릅니다. 그 아래는 아직 어린나무입니다.\",\"body\":\"가고시마 남쪽 바다에 야쿠섬이 있어요. 작은 섬인데 산이 높고 비가 억수같이 내려요. 그 습한 산속에 삼나무 원시림이 있어요. 여기서는 나무를 부르는 기준이 남달라요. 천 년을 넘긴 삼나무만 야쿠스기라고 부르거든요. 천 년이 안 된 나무는 그냥 어린 삼나무예요. 이 숲은 1993년에 유네스코 세계자연유산이 됐어요. 등재 사유에는 천 년을 넘긴 삼나무 원시림이 이 섬의 핵심이라고 적혀 있어요. 작은 섬 하나에 식물만 천구백 종이 살고 있고요. 같은 삼나무인데 어느 산에서는 꽃가루 골칫거리이고, 이 섬에서는 세계유산이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"whc.unesco.org\",\"sourceUrl\":\"https://whc.unesco.org/en/list/662\"},{\"id\":\"bstory-cedar-nikko-avenue\",\"title\":\"세계에서 가장 긴 삼나무길\",\"hook\":\"1628년부터 스무 해에 걸쳐 삼나무 20만 그루를 심어 만든 35.41킬로미터짜리 가로수길이에요.\",\"body\":\"일본 도치기현 이마이치를 중심으로 세 갈래 길이 모이는 닛코의 삼나무 가로수길은 기네스 세계기록이 인정한 세계에서 가장 긴 가로수길이에요. 총 길이가 35.41킬로미터, 그러니까 약 22마일이에요. 1628년부터 1648년까지 스무 해에 걸쳐 삼나무 20만 그루를 심어 만들었고, 그중 1만 3500그루 넘게 아직 살아 있어요. 남은 나무들의 평균 키는 27미터고요. 심은 나무의 대부분은 지난 400년 사이에 사라졌지만, 남은 것만으로도 이 길은 여전히 세계 최장 기록을 지키고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"guinnessworldrecords.com\",\"sourceUrl\":\"https://www.guinnessworldrecords.com/world-records/longest-avenue-of-trees\"},{\"id\":\"bstory-cedar-pollen-policy\",\"title\":\"40억 그루가 만든 꽃가루\",\"hook\":\"전후 일본이 심은 삼나무 40억 그루가 지금은 국민 다섯 중 한 명을 괴롭혀요.\",\"body\":\"일본은 2차 대전이 끝난 뒤 헐벗은 산을 되살리고 건설 목재를 대려고 삼나무를 대대적으로 심었어요. 1950년부터 1970년까지 산에 꽂힌 삼나무만 40억 그루가 넘어요. 그런데 값싼 수입 목재가 들어오면서 국내 목재 수요가 사라졌고, 베어 내지 못한 나무들은 그대로 자라 꽃가루를 뿜기 시작했지요. 지금 일본에서 가훈쇼라 부르는 꽃가루 알레르기는 국민 다섯 명 중 한 명에게 나타나요. 30년 사이 꽃가루 농도는 다섯 배, 환자 수는 세 배로 늘었고요. 2007년 도야마현 임업연구소가 꽃가루를 만들지 않는 품종을 개발하는 등 대안이 나왔지만, 무화분·저화분 품종은 아직 해마다 심는 묘목의 10퍼센트를 조금 넘는 수준이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nippon.com\",\"sourceUrl\":\"https://www.nippon.com/en/nipponblog/m00081/\"},{\"id\":\"bstory-cedar-jomon-sugi\",\"title\":\"1966년에야 발견된 조몬스기\",\"hook\":\"둘레 16.4미터의 이 삼나무는 1966년에야 세상에 알려졌어요.\",\"body\":\"규슈 남쪽 야쿠시마섬 깊은 산속에 조몬스기라는 삼나무가 서 있어요. 키는 25.3미터로 압도적이진 않은데, 줄기 둘레가 16.4미터나 돼요. 나이는 2000년에서 7200년 사이로 추정되고, 연륜 측정으로는 최소 2000년이라는 값이 나왔어요. 놀라운 건 이 나무가 1966년에야 공식적으로 알려졌다는 점이에요. 근처에는 1580년대에 잘려 나간 거대한 삼나무의 그루터기, 이른바 윌슨 그루터기가 남아 있어요. 지금은 뿌리가 상할까 봐 밑동에서 15미터 떨어진 전망대에서만 볼 수 있고, 왕복 열 시간쯤 걸어야 닿아요. 야쿠시마는 1993년 세계자연유산이 되었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"japan.travel\",\"sourceUrl\":\"https://www.japan.travel/en/spot/596/\"}]},\"2-16\":{\"photo\":{\"src\":\"/birth/wolgyesu.jpg\",\"thumbSrc\":\"/birth/thumbs/wolgyesu.jpg\",\"author\":\"Cillas\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Laurus_nobilis_HRM1.jpg\",\"familyLine\":\"지중해에서 온 녹나무과의 늘푸른 나무예요 — 봄에 노란 꽃이 잎겨드랑이에 모여 피고, 잎은 향신료로 씁니다.\"},\"stories\":[{\"id\":\"bstory-laurel-daphne-transformed\",\"title\":\"붙잡히기 직전에 나무가 됐습니다\",\"hook\":\"아폴론에게 쫓기던 님프는 대지에 도움을 청했고, 그 자리에서 월계수가 됐습니다.\",\"body\":\"다프네는 강의 님프였어요. 아폴론이 그를 쫓았어요. 다프네는 지칠 때까지 달아나다가 마지막에 대지의 여신에게 도움을 청했어요. 그 순간 몸이 나무가 됐어요. 월계수였어요. 아폴론은 그 나무를 자기 신성한 나무로 삼았어요. 그래서 델포이의 아폴론 신전에는 월계수가 따라다녀요. 다프네라는 이름 자체가 그리스 말로 월계수예요. 이야기가 이름을 낳은 게 아니라 이름이 이야기를 낳았다고 보는 학자들도 있어요. 어느 쪽이든, 승리의 관을 쓴다는 말의 뿌리에는 붙잡히지 않으려고 나무가 된 님프가 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theoi.com\",\"sourceUrl\":\"https://www.theoi.com/Nymphe/NympheDaphne.html\"},{\"id\":\"bstory-laurel-laureate-word\",\"title\":\"노벨상 수상자라는 말에 들어 있는 잎\",\"hook\":\"로리엇이라는 단어를 뜯어 보면 월계수가 나옵니다. 학사 학위 이름에도 들어 있습니다.\",\"body\":\"영어로 노벨상 수상자를 노벨 로리엇이라고 해요. 계관시인은 포이트 로리엇이고요. 이 로리엇이라는 말의 뿌리가 월계수예요. 고대 그리스에서 승자에게 씌운 관이 월계수 가지였거든요. 로마가 그 관습을 이어받으면서 라틴어 라우루스가 유럽 언어 곳곳에 박혔어요. 바칼로레아, 배칠러 같은 학위 이름에도 이 잎이 들어 있어요. 월계수는 승리만 상징한 게 아니에요. 의술과 예술, 그리고 전쟁의 끝을 뜻하기도 했어요. 상장 가장자리에 그려진 잎사귀 무늬를 오늘도 볼 수 있는데, 그게 이천 년 넘게 이어진 그 잎이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스·로마\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theconversation.com\",\"sourceUrl\":\"https://theconversation.com/whats-a-laureate-a-classicist-explains-the-words-roots-in-ancient-greek-victors-winning-crowns-of-laurel-leaves-191407\"}]},\"2-17\":{\"photo\":{\"src\":\"/birth/yasaenghwa.jpg\",\"thumbSrc\":\"/birth/thumbs/yasaenghwa.jpg\",\"author\":\"Mount Rainier National Park from Ashford, WA, United States\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Wildflower_Meadow_(6997737191).jpg\",\"familyLine\":\"누가 심지 않아도 제 자리에서 피는 들꽃들이에요 — 계절마다 다른 얼굴로 초원을 물들입니다.\"},\"stories\":[]},\"2-18\":{\"photo\":{\"src\":\"/birth/minariajaebi-0120.jpg\",\"thumbSrc\":\"/birth/thumbs/minariajaebi-0120.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ranunculus_japonicus_3.JPG\",\"familyLine\":\"미나리아재비과의 여러해살이풀이에요 — 기름을 바른 듯 반짝이는 노란 꽃잎이 특징입니다.\"},\"stories\":[{\"id\":\"bstory-buttercup-chin-glow\",\"title\":\"턱이 노랗게 물드는 이유\",\"hook\":\"미나리아재비를 턱에 대면 노란빛이 도는 데는 이유가 있어요.\",\"body\":\"미나리아재비를 턱 아래 대고 노란빛이 비치면 버터를 좋아하는 거라는 놀이가 유럽에 오래 있었어요. 2011년 케임브리지대 연구진이 그 광학을 실제로 재 봤어요. 꽃잎 표피 세포의 윗면이 유리에 가까울 만큼 매끈한 데다, 표피 아래에 공기층이 얇게 떠 있어 반사면이 하나가 아니라 둘이었어요. 두 면이 겹쳐 반사를 두 배로 만들기 때문에 다른 꽃보다 유독 잘 비친다는 결론이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"cam.ac.uk\",\"sourceUrl\":\"https://www.cam.ac.uk/research/news/why-buttercups-reflect-yellow-on-chins\"},{\"id\":\"bstory-buttercup-little-frog\",\"title\":\"작은 개구리라는 이름 그리고 일부러 낸 물집\",\"hook\":\"라눙쿨루스는 라틴어로 '작은 개구리'예요.\",\"body\":\"미나리아재비속의 학명 Ranunculus는 라틴어 rana, 곧 개구리에 축소형 어미가 붙은 말이에요. '작은 개구리'라는 뜻이고, 물가와 축축한 자리에 잘 자라 개구리와 이웃이 되기 때문이라고 봐요. 이 풀에는 라눈쿨린이 들어 있는데, 잎이 으깨지면 프로토아네모닌으로 바뀌어 살갗에 물집을 만들어요. 유럽에서는 동정을 사려고 일부러 이 즙으로 물집을 냈다는 이야기가 전해질 만큼 잘 알려진 성질이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"home.howstuffworks.com\",\"sourceUrl\":\"https://home.howstuffworks.com/ranunculus.htm\"}]},\"2-19\":{\"photo\":{\"src\":\"/birth/tteokgalnamu-0219.jpg\",\"thumbSrc\":\"/birth/thumbs/tteokgalnamu-0219.jpg\",\"author\":\"あおもりくま(Aomorikuma)\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Daimyo_Oak_20170513_IMG_8412.jpg\",\"familyLine\":\"참나무과의 낙엽 큰키나무예요 — 봄에 늘어진 수꽃차례를 달고, 두툼한 잎으로 떡을 싸기도 했습니다.\"},\"stories\":[{\"id\":\"bstory-oak-boscobel-all-day\",\"title\":\"왕이 하루를 보낸 나무\",\"hook\":\"군인들이 숲을 뒤지는 동안, 왕은 참나무 위에 앉아 그들을 내려다보고 있었습니다.\",\"body\":\"1651년 9월, 우스터 전투에서 진 스물한 살의 찰스는 쫓기는 몸이 됐어요. 보스코벨 하우스에 숨어들었는데, 같이 도망 중이던 윌리엄 케어리스가 집도 숲도 위험하다고 했어요. 대신 한 가지 방법을 알고 있다고요. 삼사 년 전에 가지를 쳐서 잎이 빽빽하게 자란 참나무 한 그루였어요. 두 사람은 그 나무에 올라가 하루를 통째로 보냈어요. 찰스는 삼십 년 뒤 새뮤얼 피프스에게 그날을 이렇게 구술했어요. 나무 위에서 보니 군인들이 숲 여기저기를 뒤지며 오가는 게 보였다고요. 왕정복고 뒤 그의 생일 5월 29일은 오크 애플 데이가 됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"english-heritage.org.uk\",\"sourceUrl\":\"https://www.english-heritage.org.uk/visit/places/boscobel-house-and-the-royal-oak/history/charles-ii-and-the-royal-oak/\"},{\"id\":\"bstory-oak-dodona-oracle\",\"title\":\"잎 소리를 듣고 신탁을 읽었습니다\",\"hook\":\"그리스에서 가장 오래된 신탁소는 건물이 아니라 참나무 한 그루였습니다.\",\"body\":\"그리스 북서부 에페이로스의 골짜기에 도도나가 있어요. 제우스의 신탁소로 고대 그리스 세계 전체에 이름이 알려진 곳이에요. 이곳의 중심에는 신전 건물이 아니라 참나무 한 그루가 있었어요. 사제들이 그 잎이 스치는 소리를 듣고 신의 뜻을 읽었다고 해요. 이 신탁소는 헬레니즘 시대에 크게 확장돼서 그리스에서 손꼽히는 규모의 극장까지 들어섰어요. 끝은 급작스러웠어요. 4세기에 테오도시우스 황제가 이교 성소를 금지하면서 그 참나무가 뽑혔어요. 이후 이 자리에는 기독교 바실리카가 들어섰고, 6세기 중엽에 완전히 버려졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"worldhistory.org\",\"sourceUrl\":\"https://www.worldhistory.org/Dodona/\"},{\"id\":\"bstory-oak-iron-gall-ink\",\"title\":\"참나무 혹으로 만든 잉크\",\"hook\":\"중세부터 19세기까지 유럽의 글씨는 대부분 참나무 벌레혹으로 만든 잉크였어요.\",\"body\":\"참나무 가지에 벌레가 알을 낳으면 나무가 방어 반응으로 둥근 혹을 만들어요. 이 혹을 황산철, 물, 아라비아검과 섞으면 철몰식자잉크가 돼요. 예일대 도서관의 필사 재료 프로젝트는 이 잉크를 중세부터 19세기까지 필사본에서 가장 자주 발견되는 잉크라고 설명해요. 렘브란트와 반 고흐, 빅토르 위고도 이 잉크로 그림을 그렸고요. 문제는 시간이에요. 이 잉크의 산도는 보통 pH 1에서 3 사이라, 산이 종이를 타고 번지면서 섬유를 끊고 글자를 파랑검정에서 갈색으로 바꿔 놔요. 옛 문서를 위협하는 가장 큰 원인 가운데 하나예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세~19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"travelingscriptorium.com\",\"sourceUrl\":\"https://travelingscriptorium.com/2013/03/21/iron-gall-ink/\"}]},\"2-20\":{\"photo\":{\"src\":\"/birth/kalmia.jpg\",\"thumbSrc\":\"/birth/thumbs/kalmia.jpg\",\"author\":\"Katja Schulz from Washington, D. C., USA\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Mountain_Laurel_in_Bloom_(33956585443).jpg\",\"familyLine\":\"북아메리카가 고향인 진달래과의 늘푸른 관목이에요 — 접시 모양 꽃이 공처럼 모여 핍니다.\"},\"stories\":[{\"id\":\"bstory-kalmia-anther-catapult\",\"title\":\"벌이 방아쇠를 당기면 꽃가루가 튑니다\",\"hook\":\"칼미아 꽃은 열 개의 투석기를 장전해 놓고 벌을 기다립니다.\",\"body\":\"칼미아 꽃을 들여다보면 꽃잎 안쪽에 작은 홈이 열 개 파여 있어요. 그 홈마다 수술의 꽃밥이 하나씩 꽂혀 있고요. 꽃이 벌어질 때 수술대가 활처럼 휘면서 팽팽하게 당겨져요. 장전이 끝난 상태예요. 벌이 꽃 안으로 들어와 수술대를 건드리면 꽃밥이 홈에서 튕겨 나오면서 벌의 몸에 꽃가루를 뿌려요. 열 개의 작은 투석기가 동시에 작동하는 셈이에요. 그런데 이 예쁜 관목은 온몸에 독이 있어요. 영어 별명 가운데 시프킬, 양을 죽이는 나무라는 것도 있을 정도예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/kalmia-latifolia/\"}]},\"2-21\":{\"photo\":{\"src\":\"/birth/nemopilra.jpg\",\"thumbSrc\":\"/birth/thumbs/nemopilra.jpg\",\"author\":\"Walter Siegmund\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Nemophila_menziesii_7794.JPG\",\"familyLine\":\"지치과의 한해살이풀이에요 — 하늘빛 다섯 장 꽃잎이 낮게 깔리며 봄 들판을 물들입니다.\"},\"stories\":[{\"id\":\"bstory-nemophila-hitachi-53-million\",\"title\":\"언덕 하나가 통째로 파랗습니다\",\"hook\":\"이바라키의 한 언덕에서는 봄마다 오백삼십만 송이가 한꺼번에 핍니다.\",\"body\":\"이바라키현 히타치 해변공원의 미하라시 언덕은 봄마다 색이 바뀌어요. 4월 중순부터 5월 초까지 네모필라가 피거든요. 송이 수가 오백삼십만이에요. 삼점오 헥타르짜리 언덕이 거의 빈틈없이 파랗게 덮여요. 영어 이름은 베이비 블루 아이즈, 아기의 파란 눈이에요. 재미있는 건 이 꽃이 일본 자생종이 아니라는 점이에요. 북미 캘리포니아 쪽에서 온 한해살이풀이에요. 언덕 위로 올라가면 파란 꽃밭 너머로 바다가 이어져서 어디까지가 꽃이고 어디부터가 바다인지 잘 구분이 안 돼요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"timeout.com\",\"sourceUrl\":\"https://www.timeout.com/tokyo/things-to-do/nemophila-harmony\"}]},\"2-22\":{\"photo\":{\"src\":\"/birth/mugunghwa-0222.jpg\",\"thumbSrc\":\"/birth/thumbs/mugunghwa-0222.jpg\",\"author\":\"そらみみ (Soramimi)\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Flower_of_hibiscus_syriacus_in_Hakozaki_Campus,_Kyushu_University.jpg\",\"familyLine\":\"아욱과의 낙엽 관목이자 우리나라 나라꽃이에요 — 여름 내내 아침마다 새 꽃을 피웁니다.\"},\"stories\":[{\"id\":\"bstory-mugunghwa-80000-seedlings-burned\",\"title\":\"묘목 팔만 주를 불태운 사건\",\"hook\":\"학교 실습지에서 기른 무궁화 묘목이 전국으로 나갔습니다. 1933년 일제는 그 묘목 팔만 주를 태웠습니다.\",\"body\":\"남궁억은 민족교육자였어요. 강원도 홍천에 모곡학교를 세우고, 학생 실습지에서 무궁화 묘목을 길렀어요. 그 묘목을 전국 각지로 보냈고요. 나라꽃을 심는 일 자체가 운동이었던 거예요. 1933년, 일제는 이 일이 불온사상을 고취하고 치안을 어지럽힌다고 했어요. 모곡학교 교직원과 교회 목사, 남궁억의 친척까지 모두 잡아갔어요. 그리고 무궁화 묘목 팔만 주를 불태웠어요. 이 사건을 취조하던 중에 기독교인들의 비밀결사 십자당이 드러나면서 일이 더 커졌고, 수많은 사람이 함께 붙잡혔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"1930년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0018951\"},{\"id\":\"bstory-mugunghwa-shanhaijing-junzi\",\"title\":\"아침에 피고 저녁에 지는 풀\",\"hook\":\"이천 년도 더 된 중국 지리서에 군자의 나라와 그 나라의 풀 한 포기가 적혀 있습니다.\",\"body\":\"산해경 해외동경에 이런 대목이 있어요. 그 북쪽에 군자국이 있는데, 사람들이 의관을 갖추고 칼을 차며, 짐승을 먹이고 큰 호랑이 두 마리를 곁에 두고, 서로 사양하며 다투지 않는다고요. 그리고 한 문장이 더 붙어요. 훈화초가 있는데 아침에 피고 저녁에 진다고요. 후대 사람들은 이 훈화초를 무궁화로 읽었어요. 무궁화가 하루 만에 지는 꽃이거든요. 다투지 않는 나라에 하루짜리 꽃이 핀다는 그림이 오래 남았어요. 다만 훈화초가 정말 무궁화였는지, 군자국이 어디였는지는 원문이 말해 주지 않아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국·한국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"ctext.org\",\"sourceUrl\":\"https://ctext.org/shan-hai-jing/hai-wai-dong-jing\"},{\"id\":\"bstory-rose-of-sharon-no-law\",\"title\":\"법으로 정한 적 없는 나라꽃\",\"hook\":\"무궁화를 국화로 삼는다고 못 박은 법 조항은 없어요.\",\"body\":\"무궁화는 법으로 국화라고 정해진 적이 없어요. 관습으로 그렇게 여겨 온 꽃이에요. 그 대신 기록이 아주 오래됐어요. 기원전 8세기에서 3세기 사이에 엮인 산해경은 우리 땅의 꽃을 훈화초라 적으며 아침에 피었다가 저녁에 진다고 했고, 신라 효공왕이 당나라에 보낸 국서는 우리나라를 무궁화의 땅이라는 뜻의 근역이라 불렀어요. 강희안의 양화소록에는 단군이 나라를 열 때 무궁화가 비로소 나왔다는 전승이 실려 있고요. 결정적인 계기는 개화기였어요. 애국가 후렴에 무궁화 삼천리 화려강산이라는 구절이 들어가면서 무궁화는 조선의 국화가 되어 오늘에 이르렀어요. 꽃이 7월부터 10월까지 백 일 넘게 이어 피어서 붙은 이름이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0018949\"},{\"id\":\"bstory-rose-of-sharon-namgung-eok\",\"title\":\"1933년, 불태워진 묘목 10만 주\",\"hook\":\"일제 경찰은 학생들을 시켜 무궁화 묘포를 뽑게 하고 그 자리에 벚나무를 심었어요.\",\"body\":\"강원도 홍천 보리울에 모곡학교를 세운 남궁억은 무궁화 묘목을 길러 전국에 보급했어요. 무궁화를 심는 일이 민족의식을 지키는 일이라고 보았기 때문이에요. 1933년, 모곡학교 교사 김복동의 일기장을 압수한 경찰이 수사를 시작했어요. 남궁억과 유자훈, 김복동, 남궁모 등 관련자들은 한 달 넘게 혹독한 취조와 고문을 받은 뒤 서울로 넘겨졌죠. 강원도 경찰국은 모곡학교 학생들을 동원해 묘포의 무궁화를 뽑게 했고, 10만 주에 가까운 묘목이 모두 불에 탔어요. 일제는 뽑아낸 자리에 일본 국화인 사쿠라를 심었고, 모곡학교는 폐교되어 공립학교로 편입됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"christiantoday.co.kr\",\"sourceUrl\":\"https://www.christiantoday.co.kr/news/326782\"},{\"id\":\"bstory-rose-of-sharon-bible-mistranslation\",\"title\":\"샤론의 장미는 무궁화가 아니다\",\"hook\":\"성경의 '샤론의 장미'는 무궁화가 아니라 사프란이나 백합류였을 가능성이 커요.\",\"body\":\"영어권에서 무궁화를 부르는 이름 로즈 오브 샤론은 1611년 킹제임스 성경의 아가에서 처음 쓰였어요. 그런데 학자들은 이 번역이 히브리어 하바첼렛 하샤론을 잘못 옮긴 것으로 봐요. 이스라엘 샤론 평야에서 자라던 사프란이나 바다수선화, 튤립, 마돈나백합 쪽이었을 가능성이 크다는 거예요. 지금 우리가 로즈 오브 샤론이라 부르는 식물은 학명이 히비스쿠스 시리아쿠스, 곧 시리아의 히비스커스인데 실제로는 아시아가 원산이에요. 이름이 두 번 어긋난 셈이에요. 게다가 장미도 아니에요. 아욱과에 속해서 접시꽃, 목화, 오크라, 마시멜로와 친척이고, 아시아에서는 영원히 지지 않는 꽃이라 불렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중동\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"vineyardgazette.com\",\"sourceUrl\":\"https://vineyardgazette.com/news/2011/08/25/rose-without-thorn\"}]},\"2-23\":{\"photo\":{\"src\":\"/birth/salgukkot.jpg\",\"thumbSrc\":\"/birth/thumbs/salgukkot.jpg\",\"author\":\"ElenaLitera\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:%D0%90%D0%BB%D0%BC%D0%B0%D1%82%D1%8B,_%D1%80%D0%BE%D1%89%D0%B0_%D0%91%D0%B0%D1%83%D0%BC%D0%B0,_%D1%86%D0%B2%D0%B5%D1%82%D0%B5%D0%BD%D0%B8%D0%B5_%D0%B0%D0%B1%D1%80%D0%B8%D0%BA%D0%BE%D1%81%D0%B0_(5).jpg\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 잎이 나기 전 연분홍 꽃이 가지를 가득 덮습니다.\"},\"stories\":[{\"id\":\"bstory-apricot-dong-feng-xinglin\",\"title\":\"진료비 대신 살구나무를 심게 했습니다\",\"hook\":\"이 의원은 돈을 받지 않았습니다. 대신 나은 사람에게 살구나무를 심으라고 했습니다.\",\"body\":\"삼국시대 오나라 사람 동봉은 어려서부터 의술을 배운 명의였어요. 그는 병을 고쳐 주고 돈을 받지 않았어요. 대신 조건을 하나 걸었어요. 가벼운 병이 나은 사람은 살구나무 한 그루, 중한 병이 나은 사람은 다섯 그루를 심으라고요. 몇 해가 지나자 그 자리에 살구나무 십만 그루가 우거진 숲이 생겼어요. 사람들은 그를 동선행림, 살구숲의 신선이라 불렀어요. 그때부터 중국과 우리나라에서 행림, 곧 살구숲은 의료계를 가리키는 말이 됐어요. 한의원 간판에서 행림이라는 두 글자를 보면 이 숲 이야기예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"3세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"fuzhou.gov.cn\",\"sourceUrl\":\"https://www.fuzhou.gov.cn/zgfzzt/zjrc/mdfc/mdrj/202111/t20211115_4242647.htm\"}]},\"2-24\":{\"photo\":{\"src\":\"/birth/bingka.jpg\",\"thumbSrc\":\"/birth/thumbs/bingka.jpg\",\"author\":\"Naturformidleren\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:A_flower_of_lesser_periwinkle_(Vinca_minor)_close_up.jpg\",\"familyLine\":\"협죽도과의 늘푸른 덩굴성 풀이에요 — 그늘진 땅을 덮으며 보랏빛 바람개비 같은 꽃을 피웁니다.\"},\"stories\":[{\"id\":\"bstory-periwinkle-rousseau-thirty-years\",\"title\":\"삼십 년 만에 알아본 꽃\",\"hook\":\"산길에서 파란 것을 본 사람은 소리를 질렀습니다. 삼십 년 전 그 사람이 가르쳐 준 꽃이었습니다.\",\"body\":\"루소의 고백록에 이런 장면이 있어요. 바랑 부인과 함께 길을 가던 어느 날, 부인이 울타리에서 파란 것을 보고 말했어요. 아직 빙카가 피어 있네요. 그때 루소는 식물을 몰랐고 발밑의 풀을 알아볼 만큼 눈도 좋지 않아서 지나치면서 흘끗 봤을 뿐이었어요. 그러고 삼십 년 가까이 흘렀어요. 스위스 산길을 오르던 루소가 갑자기 소리를 질렀어요. 아, 빙카가 있다고요. 그사이 그는 식물학자가 돼 있었고, 바랑 부인은 곁에 없었어요. 프랑스에서 이 꽃이 기억과 우정의 상징이 된 건 이 한 장면 때문이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스·스위스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/3913/3913-h/3913-h.htm\"}]},\"2-25\":{\"photo\":{\"src\":\"/birth/sahyangjangmi.jpg\",\"thumbSrc\":\"/birth/thumbs/sahyangjangmi.jpg\",\"author\":\"Wilrooij\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rosa_moschata_-_Rosengarten_am_Schlo%C3%9Fberg.jpg\",\"familyLine\":\"장미과의 덩굴성 장미예요 — 홑겹 흰 꽃에서 사향을 닮은 진한 향이 납니다.\"},\"stories\":[{\"id\":\"bstory-musk-rose-rediscovered-1963\",\"title\":\"사라진 줄 알았던 장미를 남의 정원에서 찾았습니다\",\"hook\":\"엘리자베스 시대에 들어와 자취를 감춘 장미가, 1963년 어느 노정원사의 뜰에 살아 있었습니다.\",\"body\":\"사향장미는 엘리자베스 시대에 영국 정원에 들어왔다고 해요. 그런데 어느 순간 재배 목록에서 사라졌어요. 장미 도감에 이름은 남았는데 그 이름표를 달고 팔리는 것들이 진짜 사향장미가 아니었어요. 1963년, 장미 연구자 그레이엄 스튜어트 토머스가 진짜를 찾아냈어요. 원예가 E. A. 보울스가 살던 미들턴 하우스의 정원이었어요. 학명 모스카타는 라틴어로 사향이라는 뜻이에요. 향으로 이름을 얻은 장미가 향을 아는 사람의 뜰에서 몇백 년을 버티고 있었던 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanic.cam.ac.uk\",\"sourceUrl\":\"https://www.botanic.cam.ac.uk/the-garden/plant-list/rosa-moschata/\"}]},\"2-26\":{\"photo\":{\"src\":\"/birth/adoniseu.jpg\",\"thumbSrc\":\"/birth/thumbs/adoniseu.jpg\",\"author\":\"阿橋 HQ\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:%E5%81%B4%E9%87%91%E7%9B%9E%E8%8A%B1_Adonis_amurensis_-%E9%A6%96%E7%88%BE%E5%88%87%E9%A0%AD%E5%B1%B1%E5%85%AC%E5%9C%92_Seoul,_South_Korea-_(33823991311).jpg\",\"familyLine\":\"미나리아재비과의 여러해살이풀이에요 — 눈이 덜 녹은 이른 봄에 황금빛 꽃을 가장 먼저 엽니다.\"},\"stories\":[]},\"2-27\":{\"photo\":{\"src\":\"/birth/arabiaui-byeol.jpg\",\"thumbSrc\":\"/birth/thumbs/arabiaui-byeol.jpg\",\"author\":\"Smailtn\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ornithogalum_arabicum.jpg\",\"familyLine\":\"지중해에서 온 알뿌리 식물이에요 — 흰 꽃 한가운데 검은 씨방이 별처럼 박혀 있습니다.\"},\"stories\":[]},\"2-28\":{\"photo\":{\"src\":\"/birth/bori.jpg\",\"thumbSrc\":\"/birth/thumbs/bori.jpg\",\"author\":\"JackyM59\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Champ_d%27Orge_carr%C3%A9e_(Hordeum_vulgare).jpg\",\"familyLine\":\"벼과의 한해살이 곡물이에요 — 초여름이면 까끄라기 달린 이삭이 들판을 금빛으로 물들입니다.\"},\"stories\":[{\"id\":\"bstory-barley-shoe-size-barleycorn\",\"title\":\"신발 치수는 보리 낟알에서 왔습니다\",\"hook\":\"영국식 신발 치수가 한 칸 오르면 발이 8.5밀리미터 길어집니다. 그 단위의 정체는 보리 낟알 하나입니다.\",\"body\":\"중세 잉글랜드에서는 길이를 재는 기준이 제각각이었어요. 잉글랜드의 한 자는 보리 낟알 서른아홉 개인데, 국경 너머 웨일스에서는 스물일곱 개였어요. 거래에서 다툼이 생길 수밖에 없었죠. 1324년, 상인들의 압박을 받은 에드워드 2세가 칙령을 냈어요. 마르고 둥근 보리 낟알 세 개를 나란히 놓은 길이를 1인치로 한다고요. 그 아래 단위인 보리 낟알 하나는 배럴리콘이라 불렸어요. 신발 장인들이 이 단위를 그대로 가져다 썼어요. 그래서 지금도 영국식 신발 치수는 한 칸에 배럴리콘 하나, 약 8.5밀리미터씩 올라가요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"14세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"satra.com\",\"sourceUrl\":\"https://www.satra.com/bulletin/article.php?id=3230\"}]},\"2-29\":{\"photo\":{\"src\":\"/birth/areumeria.jpg\",\"thumbSrc\":\"/birth/thumbs/areumeria.jpg\",\"author\":\"Matthias Bethke\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20230519_Gew%C3%B6hnliche_Grasnelke_(Armeria_maritima).jpg\",\"familyLine\":\"바닷가 바위에 붙어 사는 갯질경과의 여러해살이풀이에요 — 방석 같은 잎 위로 분홍 꽃방울을 올립니다.\"},\"stories\":[{\"id\":\"bstory-armeria-thrift-threepence\",\"title\":\"동전에 새겨진 말장난\",\"hook\":\"1937년 영국 3펜스 동전 뒷면에 이 꽃이 새겨졌습니다. 꽃 이름이 곧 절약이라는 뜻이었기 때문입니다.\",\"body\":\"아르메리아의 영어 이름은 스리프트예요. 절약이라는 뜻과 같은 낱말이에요. 1937년부터 1952년까지 영국의 3펜스 동전 뒷면에는 이 꽃이 새겨져 있었어요. 가장 값이 작은 동전에 절약이라는 이름의 꽃을 올린 거예요. 하필 그 시기는 전쟁 전후로 영국인들에게 아껴 쓰라고 다그치던 때였고요. 지갑을 열 때마다 동전이 잔소리를 하는 셈이었어요. 요즘도 영국의 나이 든 사람들은 이 꽃을 보면 스리페니 빗이라 부르던 그 동전을 떠올린다고 해요. 서쪽 바닷가 바위 위에서 초여름에 분홍 방울처럼 피는 꽃이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"1930년대~1950년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botsocscot.wordpress.com\",\"sourceUrl\":\"https://botsocscot.wordpress.com/2022/07/10/plant-of-the-week-11th-july-2022-thrift-armeria-maritima-mill-willd/\"},{\"id\":\"bstory-armeria-mine-spoil-metal\",\"title\":\"광산 폐석 더미에 피는 꽃\",\"hook\":\"납과 구리를 캐던 자리에 남은 독한 흙더미에서, 이 꽃은 태연히 자랍니다.\",\"body\":\"아르메리아는 바닷가 바위에서 사는 꽃이에요. 소금기를 견디려고 잎 표면에 세포 여덟 개로 된 아주 작은 배출샘을 달고 있어요. 그 샘으로 소금을 밖으로 내보내요. 그런데 이 능력이 엉뚱한 데서 쓸모를 발휘해요. 아르메리아는 납, 아연, 니켈, 카드뮴, 구리, 크롬, 비소 같은 중금속에도 놀랄 만큼 강해요. 그래서 버려진 납광산과 구리광산의 폐석 더미를 이 꽃이 뒤덮곤 해요. 다른 식물은 뿌리도 못 내리는 흙이거든요. 바닷물의 나트륨과 염소를 처리하던 방식이, 광산의 독한 금속에도 통했던 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botsocscot.wordpress.com\",\"sourceUrl\":\"https://botsocscot.wordpress.com/2022/07/10/plant-of-the-week-11th-july-2022-thrift-armeria-maritima-mill-willd/\"}]},\"3-1\":{\"stories\":[]},\"3-2\":{\"photo\":{\"src\":\"/birth/minariajaebi-0120.jpg\",\"thumbSrc\":\"/birth/thumbs/minariajaebi-0120.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ranunculus_japonicus_3.JPG\",\"familyLine\":\"미나리아재비과의 여러해살이풀이에요 — 기름을 바른 듯 반짝이는 노란 꽃잎이 특징입니다.\"},\"stories\":[{\"id\":\"bstory-buttercup-chin-glow\",\"title\":\"턱이 노랗게 물드는 이유\",\"hook\":\"미나리아재비를 턱에 대면 노란빛이 도는 데는 이유가 있어요.\",\"body\":\"미나리아재비를 턱 아래 대고 노란빛이 비치면 버터를 좋아하는 거라는 놀이가 유럽에 오래 있었어요. 2011년 케임브리지대 연구진이 그 광학을 실제로 재 봤어요. 꽃잎 표피 세포의 윗면이 유리에 가까울 만큼 매끈한 데다, 표피 아래에 공기층이 얇게 떠 있어 반사면이 하나가 아니라 둘이었어요. 두 면이 겹쳐 반사를 두 배로 만들기 때문에 다른 꽃보다 유독 잘 비친다는 결론이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"cam.ac.uk\",\"sourceUrl\":\"https://www.cam.ac.uk/research/news/why-buttercups-reflect-yellow-on-chins\"},{\"id\":\"bstory-buttercup-little-frog\",\"title\":\"작은 개구리라는 이름 그리고 일부러 낸 물집\",\"hook\":\"라눙쿨루스는 라틴어로 '작은 개구리'예요.\",\"body\":\"미나리아재비속의 학명 Ranunculus는 라틴어 rana, 곧 개구리에 축소형 어미가 붙은 말이에요. '작은 개구리'라는 뜻이고, 물가와 축축한 자리에 잘 자라 개구리와 이웃이 되기 때문이라고 봐요. 이 풀에는 라눈쿨린이 들어 있는데, 잎이 으깨지면 프로토아네모닌으로 바뀌어 살갗에 물집을 만들어요. 유럽에서는 동정을 사려고 일부러 이 즙으로 물집을 냈다는 이야기가 전해질 만큼 잘 알려진 성질이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"home.howstuffworks.com\",\"sourceUrl\":\"https://home.howstuffworks.com/ranunculus.htm\"}]},\"3-3\":{\"photo\":{\"src\":\"/birth/jaunyeong.jpg\",\"thumbSrc\":\"/birth/thumbs/jaunyeong.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Astragalus_sinicus_3.JPG\",\"familyLine\":\"콩과의 두해살이풀이에요 — 논에 거름으로 심어, 봄이면 분홍 꽃이 논바닥을 덮습니다.\"},\"stories\":[]},\"3-4\":{\"photo\":{\"src\":\"/birth/namuttalgi.jpg\",\"thumbSrc\":\"/birth/thumbs/namuttalgi.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rubus_idaeus_kz05.jpg\",\"familyLine\":\"장미과의 낙엽 떨기나무예요 — 흰 꽃이 진 자리에 붉은 산딸기가 익습니다.\"},\"stories\":[]},\"3-5\":{\"stories\":[]},\"3-6\":{\"stories\":[]},\"3-7\":{\"photo\":{\"src\":\"/birth/hwangsaenaengi.jpg\",\"thumbSrc\":\"/birth/thumbs/hwangsaenaengi.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cardamine_flexuosa_kz06.jpg\",\"familyLine\":\"십자화과의 작은 봄나물이에요 — 논둑과 밭가에서 흰 꽃잎 네 장을 십자로 펼칩니다.\"},\"stories\":[]},\"3-8\":{\"photo\":{\"src\":\"/birth/bamkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/bamkkot.jpg\",\"author\":\"Apple2000\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanese_Chestnut02.jpg\",\"familyLine\":\"참나무과의 낙엽 큰키나무예요 — 초여름이면 크림빛 수꽃차례가 늘어지며 짙은 향을 퍼뜨립니다.\"},\"stories\":[{\"id\":\"bstory-chestnut-town-name-castania\",\"title\":\"마을 이름이 그대로 나무 이름이 됐습니다\",\"hook\":\"밤나무의 속명은 사람 이름도 신 이름도 아닙니다. 그리스의 한 마을 이름입니다.\",\"body\":\"밤나무의 속명 카스타네아는 사람 이름이 아니에요. 테살리아에 있던 카스타니아라는 마을 이름에서 왔어요. 그 마을 근처에 밤나무가 유난히 많았다고 해요. 마을 하나가 통째로 한 속의 이름이 된 거예요. 종소명 사티바는 사람이 심어 기른다는 뜻이고요. 야생에서 저절로 난 게 아니라 사람 손을 탄 나무라는 표시예요. 이름 두 마디에 사람과 마을이 다 들어 있는 셈이에요. 유럽밤나무는 산지 숲에서 잘 자라고 열매도 먹을 수 있지만, 미국에서는 밤나무줄기마름병에 약해서 상업적으로 재배하지 않아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/castanea-sativa/\"}]},\"3-9\":{\"photo\":{\"src\":\"/birth/nakyeopsong.jpg\",\"thumbSrc\":\"/birth/thumbs/nakyeopsong.jpg\",\"author\":\"Σ64\",\"license\":\"CC BY 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Larix_kaempferi_01.jpg\",\"familyLine\":\"잎을 떨구는 보기 드문 침엽수예요 — 봄엔 연둣빛 새잎, 가을엔 황금빛으로 산을 물들입니다.\"},\"stories\":[{\"id\":\"bstory-larch-conifer-that-undresses\",\"title\":\"겨울마다 옷을 다 벗는 침엽수\",\"hook\":\"침엽수는 겨울에도 푸르다는 말은 이 나무 앞에서 틀립니다.\",\"body\":\"낙엽송은 소나무과 나무예요. 잎도 바늘 모양이고 솔방울도 달려요. 그런데 가을이 되면 잎을 노랗게 물들였다가 전부 떨어뜨려요. 침엽수는 늘 푸르다는 상식이 이 나무 앞에서 무너지는 거예요. 이름부터가 그래요. 학명 라릭스 데키두아에서 데키두아는 낙엽성이라는 뜻이에요. 자라면 삼십 미터를 훌쩍 넘고 유럽에는 오백 살 된 나무도 있어요. 봄에 새로 돋는 연한 초록 바늘잎은 침엽수 중에서도 유난히 부드러워요. 일 년에 한 번씩 완전히 새 옷으로 갈아입는 나무예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/larix-decidua/\"}]},\"3-10\":{\"photo\":{\"src\":\"/birth/neureupnamu-0310.jpg\",\"thumbSrc\":\"/birth/thumbs/neureupnamu-0310.jpg\",\"author\":\"Ptelea\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:SHHG_Ulmus_davidiana.jpg\",\"familyLine\":\"느릅나무과의 낙엽 큰키나무예요 — 잎보다 먼저 자잘한 꽃이 피고 날개 달린 열매가 바람에 날립니다.\"},\"stories\":[{\"id\":\"bstory-elm-dutch-disease-women\",\"title\":\"네덜란드 병이라는 이름의 진짜 주인\",\"hook\":\"네덜란드 느릅나무병은 네덜란드 느릅나무의 병이 아닙니다. 그 병을 밝혀낸 네덜란드 여성들의 이름입니다.\",\"body\":\"느릅나무를 세계에서 지워 가는 병의 이름은 네덜란드 느릅나무병이에요. 네덜란드 느릅나무가 걸리는 병이라는 뜻으로 오해하기 쉬운데 아니에요. 1921년부터 네덜란드에서 이 병의 정체를 밝혀낸 연구자들 때문에 붙은 이름이에요. 베아트리체 스홀 슈바르츠가 박사학위 논문에서 병든 목재에서 나온 새 곰팡이를 정밀하게 기술하고 이름을 붙였어요. 그리고 그 곰팡이를 건강한 나무에 접종해 병을 재현했고요. 크리스티네 바위스만이 뒤를 이었어요. 두 사람 모두 요한나 베스테르데이크 밑에서 일했어요. 병의 고향은 아시아라는 게 지금의 정설이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"1920년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"auf.isa-arbor.com\",\"sourceUrl\":\"https://auf.isa-arbor.com/content/1/6/107\"},{\"id\":\"bstory-elm-okc-survivor-tree\",\"title\":\"주차장에 그늘을 드리우던 나무\",\"hook\":\"폭탄이 터지기 전, 그 느릅나무의 쓸모는 주차장에 그늘을 만드는 것이었습니다.\",\"body\":\"오클라호마시티 도심 주차장에 미국느릅나무 한 그루가 있었어요. 그 주차장에서 그늘이 있는 자리는 그 나무 아래뿐이었어요. 그래서 사람들은 나무 밑에 차를 대려고 일부러 일찍 출근했다고 해요. 1995년 4월 19일, 몇 미터 떨어진 곳에서 이천 킬로그램에 가까운 폭탄이 터졌어요. 백육십팔 명이 죽고 수백 명이 다쳤어요. 나무는 서 있었어요. 그런데 가지에 증거물이 걸려 있어서 수사를 위해 베어 낼 뻔했어요. 지금 그 나무는 서바이버 트리라고 불려요. 주차장 그늘나무였던 나무가요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"1990년대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"memorialmuseum.com\",\"sourceUrl\":\"https://memorialmuseum.com/experience/the-survivor-tree/\"},{\"id\":\"bstory-elm-married-vine\",\"title\":\"포도를 느릅나무에 시집보내다\",\"hook\":\"로마 농부들은 포도나무를 느릅나무에 올리는 일을 '혼인'이라 불렀어요.\",\"body\":\"로마 농부들은 포도나무를 느릅나무에 올리는 일을 두고 포도를 느릅나무에게 시집보낸다고 말했어요. 서기 50년 무렵 콜루멜라는 농서 '농업론'에 그 방법을 꼼꼼히 적었는데, 버팀목으로는 씨가 맺히지 않아 꺾꽂이로만 늘리는 아티니아 느릅나무를 권했고 소들도 들판 느릅나무보다 이 잎을 더 좋아한다고 덧붙였어요. 베르길리우스와 카툴루스는 이 농사 용어를 사람의 혼인으로 옮겨 왔어요. 튼튼하지만 열매를 맺지 못하는 남편이 느릅나무, 약하지만 열매를 맺는 아내가 포도나무라는 구도였죠. 1600년 무렵 셰익스피어의 아드리아나도 같은 말을 해요. 당신은 느릅나무예요, 나는 포도나무고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대~16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"iforest.sisef.org\",\"sourceUrl\":\"https://iforest.sisef.org/contents/?id=ifor1244-007\"},{\"id\":\"bstory-elm-dutch-women\",\"title\":\"병 이름에 남은 여성들\",\"hook\":\"네덜란드느릅나무병은 병이 시작된 곳이 아니라, 밝혀낸 사람들의 나라 이름이에요.\",\"body\":\"네덜란드느릅나무병이라는 이름은 병이 네덜란드에서 시작돼서가 아니라, 네덜란드 연구자들이 그 정체를 밝혀냈기 때문에 붙었어요. 1918년 가을부터 느릅나무가 죽는다는 보고가 이어지자 빌리 코멜린 스홀턴 연구소가 나섰고, 소장 요한나 베스테르데이크는 1921년까지 56명을 이 문제에 붙였는데 그중 절반 가까이가 여성이었어요. 마리 베아트리스 슈바르츠가 원인을 새로운 곰팡이로 지목해 이름 붙였고, 크리스티너 바위스만은 1927년 이 곰팡이의 또 다른 생활사 단계를 찾아냈어요. 바위스만은 1930년 미국 최초의 발병 사례를 확인했고, 1936년 초 갑자기 세상을 떠났어요. 1935년에 나온 저항성 계통에는 그의 이름이 붙었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"arboretum.harvard.edu\",\"sourceUrl\":\"https://arboretum.harvard.edu/arnoldia-stories/ulmus-x-hollandica-christine-buisman/\"}]},\"3-11\":{\"photo\":{\"src\":\"/birth/sseumbagwi.jpg\",\"thumbSrc\":\"/birth/thumbs/sseumbagwi.jpg\",\"author\":\"bastus917\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ixeridium_dentatum_1.jpg\",\"familyLine\":\"국화과의 여러해살이풀이에요 — 쓴맛 나는 잎을 나물로 먹고, 봄에 노란 혀꽃이 핍니다.\"},\"stories\":[]},\"3-12\":{\"photo\":{\"src\":\"/birth/suyangbeodeul.jpg\",\"thumbSrc\":\"/birth/thumbs/suyangbeodeul.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cornjum,_Martenastate,_(tuin)_03.jpg\",\"familyLine\":\"버드나무과의 낙엽 큰키나무예요 — 물가로 길게 늘어진 가지에 봄이면 연둣빛 꽃차례가 달립니다.\"},\"stories\":[{\"id\":\"bstory-willow-wanggeon-leaf-in-water\",\"title\":\"물 위에 띄운 버들잎 한 장\",\"hook\":\"목마른 장군이 물을 청했습니다. 처녀는 바가지에 버들잎을 띄워 건넸습니다.\",\"body\":\"전라남도 나주시청 앞에 완사천이라는 샘이 있어요. 아무리 가물어도 마르지 않는다고 해요. 여기에 전설이 내려와요. 왕건이 이 근처를 지나다가 물을 청했어요. 샘가에서 빨래하던 처녀가 바가지에 물을 뜨고, 곁의 버들잎을 따서 물 위에 띄워 건넸어요. 왕건이 왜 잎을 띄웠느냐고 묻자 처녀가 답했어요. 말을 달려오시느라 목이 몹시 마르실 텐데 급히 드시면 체하실 것 같아 천천히 불어 가며 드시라고 띄웠다고요. 이 처녀가 고려 2대 임금 혜종의 어머니, 나주 오씨 장화왕후예요. 나주시의 상징인 버들아가씨가 여기서 나왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"10세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"atlasnews.co.kr\",\"sourceUrl\":\"http://www.atlasnews.co.kr/news/articleView.html?idxno=10738\"},{\"id\":\"bstory-willow-napoleon-cuttings\",\"title\":\"무덤 곁 버드나무의 후손들\",\"hook\":\"황제는 자기가 묻힐 자리를 직접 골랐습니다. 그 곁의 버드나무는 가지째 세계로 흩어졌습니다.\",\"body\":\"나폴레옹은 세인트헬레나섬에서 자기가 묻힐 자리를 직접 골랐어요. 버드나무 골짜기라 불리던 곳이에요. 1821년 5월에 죽어 그 자리에 묻혔고, 무덤 머리맡에는 수양버들 한 그루가 서 있었어요. 외딴섬까지 찾아온 방문객들이 그 나무의 가지를 잘라 갔어요. 그리고 세계 곳곳에 심었어요. 1840년에 유해는 프랑스로 옮겨졌지만 나무의 후손들은 그대로 남았어요. 남아프리카의 한 농장에도 그 가지에서 자란 나무가 있어요. 저수지 둑 위에 홀로 서 있는데, 섬에 갇혔던 황제와 닮았다고 적혀 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"세인트헬레나\"},{\"key\":\"era\",\"text\":\"19세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"babylonstoren.com\",\"sourceUrl\":\"https://babylonstoren.com/blog/post/napoleons-willow\"}]},\"3-13\":{\"photo\":{\"src\":\"/birth/sanokjamhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/sanokjamhwa.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hosta_sieboldiana_(flower).jpg\",\"familyLine\":\"그늘을 좋아하는 비비추속의 여러해살이풀이에요 — 넓은 잎 사이로 긴 꽃대를 올려 나팔 모양 꽃을 답니다.\"},\"stories\":[{\"id\":\"bstory-hosta-host-not-a-lily\",\"title\":\"백합도 원추리도 아닌 이름\",\"hook\":\"표에는 데이 릴리라 적혀 있지만, 이 풀은 백합속도 원추리속도 아닙니다.\",\"body\":\"옥잠화속의 속명 호스타는 오스트리아 식물학자 니콜라우스 호스트를 기린 이름이에요. 종소명 플란타기네아는 잎이 질경이를 닮았다는 뜻이고요. 이름 어디에도 백합은 없어요. 그런데 영어 통용명은 플랜테인 릴리, 오거스트 릴리처럼 자꾸 릴리가 붙어요. 분류상으로는 비짜루과, 그러니까 아스파라거스와 한집안이에요. 백합속도 아니고 원추리속도 아니에요. 중국 원산이고, 그늘지고 축축한 자리에서 크고 흰 향기로운 꽃을 피워요. 이름표만 믿고 백합을 기대하면 전혀 다른 풀을 만나게 돼요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/hosta-plantaginea/\"}]},\"3-14\":{\"photo\":{\"src\":\"/birth/amondeu.jpg\",\"thumbSrc\":\"/birth/thumbs/amondeu.jpg\",\"author\":\"Krzysztof Golik\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Prunus_dulcis_in_Jardins_de_la_Fontaine_in_Nimes_13.jpg\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 이른 봄 연분홍 꽃이 먼저 피고, 씨앗 속 알맹이를 먹습니다.\"},\"stories\":[{\"id\":\"bstory-almond-van-gogh-nephew\",\"title\":\"조카가 태어난 소식을 듣고 그린 가지\",\"hook\":\"동생이 아들을 낳고 형의 이름을 붙였습니다. 형은 곧바로 꽃 핀 아몬드 가지를 그리기 시작했습니다.\",\"body\":\"1890년 초, 생레미의 요양원에 있던 반 고흐에게 편지가 왔어요. 동생 테오와 제수 요에게 아들이 태어났고, 이름을 형의 이름을 따서 빈센트 빌럼으로 짓겠다는 편지였어요. 테오는 이렇게 썼어요. 이 아이가 형처럼 굳세고 용감했으면 좋겠다고요. 반 고흐는 곧바로 그리기 시작했어요. 아몬드였어요. 아몬드는 2월이면 벌써 꽃을 피워서 봄이 온다는 신호로 통하거든요. 새 생명에 딱 맞는 나무였어요. 이 그림은 반 고흐 집안이 가장 아꼈던 작품이 됐고, 그 아기는 자라서 반 고흐 미술관을 세웠어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스·네덜란드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"vangoghmuseum.nl\",\"sourceUrl\":\"https://www.vangoghmuseum.nl/en/collection/s0176v1962\"}]},\"3-15\":{\"photo\":{\"src\":\"/birth/dokdanggeun.jpg\",\"thumbSrc\":\"/birth/thumbs/dokdanggeun.jpg\",\"author\":\"Marie Portas\",\"license\":\"CC BY-SA 2.0 fr\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Conium_maculatum_inflorescence_(02).jpg\",\"familyLine\":\"산형과의 두해살이풀이에요 — 흰 꽃이 우산처럼 퍼지지만 온몸에 강한 독을 품고 있습니다.\"},\"stories\":[{\"id\":\"bstory-hemlock-coniine-killer\",\"title\":\"소크라테스를 죽인 분자\",\"hook\":\"독당근에는 여러 알칼로이드가 들어 있지만, 사람을 죽이는 것은 그중 하나입니다.\",\"body\":\"독당근에는 피페리딘 계열 알칼로이드가 여러 가지 들어 있어요. 그중 가장 치명적인 게 코니인이에요. 소크라테스가 기원전 399년에 마신 잔에 들어 있던 물질이죠. 재미있는 건 이 물질이 유기화학사에서 갖는 자리예요. 코니인은 사람이 실험실에서 인공으로 합성해 낸 최초의 알칼로이드 가운데 하나예요. 사람을 죽인 분자가 사람 손으로 다시 만들어진 셈이에요. 헴록이라는 영어 이름은 고대 영어 힘리케에서 왔고, 문학에서 처음 이 철자로 등장하는 건 셰익스피어의 헨리 5세예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6150177/\"},{\"id\":\"bstory-hemlock-poison-parsley-names\",\"title\":\"이름부터가 경고문입니다\",\"hook\":\"독당근의 영어 별명 목록은 그대로 오인 사고의 목록입니다. 독파슬리, 당근고사리, 얼룩미나리.\",\"body\":\"독당근의 영어 별명들을 늘어놓으면 이 식물이 왜 위험한지 바로 보여요. 포이즌 파슬리, 캐럿 펀, 스포티드 헴록, 스포티드 카우베인, 캐럿 위드, 캘리포니아 펀. 파슬리, 당근, 고사리, 미나리. 전부 사람들이 캐서 먹는 것들이에요. 별명이 곧 헷갈리는 대상의 목록인 거예요. 실제로 독당근 중독 사고는 대개 야생 파슬리나 야생 당근으로 착각해 캔 데서 생겨요. 줄기의 자줏빛 얼룩이 구분점 가운데 하나라 스포티드라는 말이 여러 별명에 붙어 있고요. 이름 하나하나가 경고문인데도 사고는 지금도 일어나요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6150177/\"}]},\"3-16\":{\"photo\":{\"src\":\"/birth/bakha-0316.jpg\",\"thumbSrc\":\"/birth/thumbs/bakha-0316.jpg\",\"author\":\"Mjhuft\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Mentha_canadensis.jpg\",\"familyLine\":\"꿀풀과의 여러해살이 허브예요 — 잎에서 시원한 향이 나고 잎겨드랑이마다 연보라 꽃이 뭉쳐 핍니다.\"},\"stories\":[{\"id\":\"bstory-mint-minthe-trampled\",\"title\":\"밟혀서 향이 된 님프\",\"hook\":\"저승의 왕이 사랑한 님프는 여왕의 발에 짓밟혔습니다. 그 자리에서 박하가 돋았습니다.\",\"body\":\"민테는 엘리스 지방의 물의 님프였어요. 하데스가 그를 사랑했고요. 그런데 민테가 자기가 페르세포네보다 아름답다고, 하데스가 곧 자기에게 돌아올 거라고 떠벌렸어요. 그 말이 화를 불렀어요. 스트라본의 지리지는 민테가 페르세포네의 발에 짓밟혀 정원의 박하로 변했다고 적어요. 오피아노스는 데메테르가 노해서 짓밟았다고 하고, 오비디우스는 페르세포네가 직접 변신시켰다고 해요. 누가 밟았는지는 갈리는데 결말은 같아요. 짓밟힌 자리에서 향기로운 풀이 돋았다는 것. 필로스 근처에는 지금도 민테의 이름을 딴 산이 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"theoi.com\",\"sourceUrl\":\"https://www.theoi.com/Nymphe/NympheMinthe.html\"},{\"id\":\"bstory-mint-peppermint-hybrid\",\"title\":\"페퍼민트는 야생에서 우연히 생긴 잡종이에요\",\"hook\":\"페퍼민트에는 조상이 둘 있어요.\",\"body\":\"페퍼민트는 워터민트와 스피어민트가 자연에서 교배해 생긴 잡종이에요. 1696년 영국 박물학자 존 레이가 들판에서 후추 맛이 나는 민트를 발견해 처음 기록했고, 1721년에는 런던 약전에 올랐어요. 상업 재배는 18세기 중반 서리주 미첨 일대에서 시작됐는데, 그곳 이름을 딴 미첨 민트는 지금도 가장 널리 퍼진 계통이에요. 향은 오래됐지만 종 자체는 꽤 젊은 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Peppermint\"},{\"id\":\"bstory-mint-mitcham-500acres\",\"title\":\"미첨의 박하밭 500에이커\",\"hook\":\"1750년 무렵 시작된 미첨의 페퍼민트 재배는 1850년에 약 500에이커에 이르렀어요.\",\"body\":\"페퍼민트는 오랫동안 박하의 한 갈래로만 취급되다가 1696년 식물학자 존 레이가 별개의 종으로 갈라냈어요. 1721년에는 런던 약전에 정식으로 올랐지요. 상업 재배는 1750년 무렵 런던 남쪽 미첨에서 시작됐고, 1850년에는 재배 면적이 약 500에이커에 이르렀어요. 박하 자체는 훨씬 오래되어서 중세 유럽의 식물 목록에는 빠짐없이 올랐고 9세기 수녀원 정원에서도 길렀으며, 페퍼민트는 13세기 아이슬란드 약전에도 이름이 보여요. 초서는 민트가 가득하고 회향이 푸른 작은 길을 노래했고, 1568년 터너의 약초서는 정원 박하를 스피어민트로 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"http://botanical.com/botanical/mgmh/m/mints-39.html\"}]},\"3-17\":{\"photo\":{\"src\":\"/birth/kongkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/kongkkot.jpg\",\"author\":\"Juan Carlos Fonseca Mata\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Flor_de_frijol_(Phaseolus_vulgaris)_I.jpg\",\"familyLine\":\"콩과의 한해살이 덩굴풀이에요 — 나비 모양 꽃이 지고 나면 그 자리에 꼬투리가 맺힙니다.\"},\"stories\":[{\"id\":\"bstory-bean-pythagoras-forbade\",\"title\":\"콩을 금지한 철학자\",\"hook\":\"피타고라스가 남긴 금기 가운데 가장 유명한 것은 콩을 먹지 말라는 것이었습니다.\",\"body\":\"피타고라스에 관해 확실하게 말할 수 있는 게 많지 않아요. 그런데 아리스토텔레스가 남긴 기록에는 분명한 게 하나 있어요. 피타고라스가 삶의 방식을 세운 사람이고, 콩 먹는 것을 금했다는 거예요. 아리스토텔레스는 그 이유를 여러 가지로 추측했는데 그중 하나가 흥미로워요. 콩을 저승과 연결 짓는 설명이에요. 영혼이 몸을 옮겨 다닌다는 그의 윤회설과 이어지는 대목이거든요. 후대에는 별별 해석이 다 붙었어요. 콩이 사람 모양을 닮아서라는 설도 있고요. 정작 피타고라스 본인이 남긴 글은 한 줄도 전해지지 않아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"기원전 6세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plato.stanford.edu\",\"sourceUrl\":\"https://plato.stanford.edu/entries/pythagoras/\"},{\"id\":\"bstory-bean-diogenes-forbidden-list\",\"title\":\"금지 목록에 함께 오른 것들\",\"hook\":\"콩과 함께 금지된 것은 붉은숭어와 검은꼬리, 그리고 짐승의 심장이었습니다.\",\"body\":\"디오게네스 라에르티오스가 정리한 피타고라스의 금기 목록을 보면 조합이 재미있어요. 무엇보다 붉은숭어와 검은꼬리를 먹지 말라고 했고, 짐승의 심장을 멀리하라고 했고, 그리고 콩을 금했어요. 아리스토텔레스에 따르면 때로는 위와 성대까지 금했다고 해요. 물고기 두 종류, 심장, 콩. 무슨 기준인지 지금 눈으로는 잘 안 잡혀요. 어떤 기록은 그가 꿀이나 벌집, 빵 정도로 끼니를 때웠고 낮에는 술을 입에 대지 않았다고 전해요. 이천오백 년 전 어느 학파의 식탁 규칙이, 목록으로만 남아 있는 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"3세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"en.wikisource.org\",\"sourceUrl\":\"https://en.wikisource.org/wiki/Lives_of_the_Eminent_Philosophers/Book_VIII\"}]},\"3-18\":{\"photo\":{\"src\":\"/birth/aseuparageoseu.jpg\",\"thumbSrc\":\"/birth/thumbs/aseuparageoseu.jpg\",\"author\":\"Ayotte, Gilles, 1948-\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Asparagus_officinalis_15-p.bot-lilia.aspar-04.jpg\",\"familyLine\":\"비짜루과의 여러해살이풀이에요 — 봄에 올라온 어린 순을 먹고, 여름엔 실 같은 잎에 종 모양 꽃이 달립니다.\"},\"stories\":[{\"id\":\"bstory-asparagus-pee-anosmia\",\"title\":\"냄새를 못 맡는 사람이 더 많았습니다\",\"hook\":\"아스파라거스를 먹은 뒤 소변 냄새를 못 맡는 사람이 절반을 넘습니다. 유전자 때문입니다.\",\"body\":\"2016년 크리스마스 특집호에 실린 논문이에요. 하버드 연구진이 미국 간호사 건강연구와 보건전문가 추적연구에 참여한 육천구백여 명의 유전 정보를 뒤졌어요. 질문은 하나였어요. 아스파라거스를 먹은 뒤 소변에서 특유의 냄새를 느끼느냐. 결과가 뜻밖이에요. 남성의 58퍼센트, 여성의 61.5퍼센트가 냄새를 못 맡는 쪽이었어요. 못 맡는 사람이 더 많았던 거예요. 유전체를 훑어보니 후각 수용체 유전자들이 몰려 있는 1번 염색체 구간에서 신호가 나왔어요. 냄새가 안 나는 게 아니라 못 맡는 거였어요. 논문 제목에도 말장난이 들어가 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"2010년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bmj.com\",\"sourceUrl\":\"https://www.bmj.com/content/355/bmj.i6071\"}]},\"3-19\":{\"photo\":{\"src\":\"/birth/chijanamu.jpg\",\"thumbSrc\":\"/birth/thumbs/chijanamu.jpg\",\"author\":\"Adriel anv00\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Gardenia_jasminoides_flower_Argentina.jpg\",\"familyLine\":\"꼭두서니과의 늘푸른 관목이에요 — 두꺼운 흰 꽃이 짙은 향을 내고, 열매는 노란 물감으로 씁니다.\"},\"stories\":[{\"id\":\"bstory-gardenia-billie-holiday-burn\",\"title\":\"머리를 태운 밤에 꽂은 꽃\",\"hook\":\"고데기에 머리가 탔습니다. 그 자리를 가리려고 꽂은 꽃이 평생의 상징이 됐습니다.\",\"body\":\"공연 직전이었어요. 빌리 홀리데이가 머리를 매만지다가 고데기에 왼쪽 귀 뒤쪽 머리를 태워 버렸어요. 잘려 나간 자리가 훤히 보였고요. 같이 있던 동료 가수가 급히 옷 보관소로 달려갔어요. 마침 거기서 꽃을 팔고 있었고, 큰 흰 치자꽃을 하나 사 왔어요. 홀리데이는 그날 밤 그 꽃으로 탄 자리를 가리고 무대에 올랐어요. 그러고는 그 모습이 마음에 들어서 이후 모든 공연 전에 머리에 치자꽃을 꽂았어요. 응급 처치 하나가 한 시대의 상징이 된 거예요. 지금 남아 있는 사진 속 그 흰 꽃은 원래 사고를 덮으려던 것이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"1930년대~1940년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"graziamagazine.com\",\"sourceUrl\":\"https://graziamagazine.com/articles/billie-holiday-hair/\"},{\"id\":\"bstory-gardenia-alexander-garden-name\",\"title\":\"재스민이 아닌데 재스민이라 불립니다\",\"hook\":\"케이프 재스민이라는 별명을 달고 있지만 이 나무는 재스민이 아닙니다. 커피 집안입니다.\",\"body\":\"치자나무의 영어 별명은 케이프 재스민이에요. 케이프 제서민이라고도 하고요. 그런데 재스민과는 아무 관계가 없어요. 치자나무는 꼭두서니과, 그러니까 커피나무와 한집안이에요. 재스민은 물푸레나무과고요. 향이 진하다는 이유 하나로 재스민이라는 이름을 얻어 버린 거예요. 학명 가르데니아는 스코틀랜드 출신 박물학자 알렉산더 가든을 기린 이름이에요. 원산지는 중국 남부와 일본의 물가고요. 이름표에는 아프리카 남단의 지명과 인도 계열 꽃 이름과 스코틀랜드 사람 이름이 붙어 있는데, 정작 고향은 동아시아 개울가예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국·중국\"},{\"key\":\"era\",\"text\":\"18세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/gardenia-jasminoides/\"}]},\"3-20\":{\"stories\":[]},\"3-21\":{\"photo\":{\"src\":\"/birth/beotkkotnan.jpg\",\"thumbSrc\":\"/birth/thumbs/beotkkotnan.jpg\",\"author\":\"Franz van Duns\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hoya_carnosa_-_umbel_with_nectar_droplets.jpg\",\"familyLine\":\"협죽도과의 늘푸른 덩굴식물이에요 — 밀랍을 빚은 듯한 별 모양 꽃이 공처럼 모여 달립니다.\"},\"stories\":[{\"id\":\"bstory-hoya-not-cherry-not-orchid\",\"title\":\"벚꽃도 아니고 난초도 아닙니다\",\"hook\":\"이름에 벚꽃과 난이 다 들어 있는데, 둘 다 아닙니다.\",\"body\":\"벚꽃난의 학명은 호야 카르노사예요. 영어 별명은 왁스 플랜트, 포슬린 플라워, 허니 플랜트예요. 밀랍 식물, 도자기 꽃, 꿀 식물이라는 뜻이에요. 이름들이 하나같이 촉감과 질감을 가리켜요. 꽃잎이 정말 밀랍이나 도자기처럼 단단하고 반들거리거든요. 그런데 우리말 이름에는 벚꽃과 난이 들어 있어요. 둘 다 아니에요. 벚나무와도 난초과와도 무관한, 협죽도과의 상록 덩굴식물이에요. 나무나 바위에 붙어 사는 착생식물이고요. birth_flowers 표에 붙은 영문명 허니 플랜트는 정확한데, 우리말 이름은 두 겹으로 헷갈리게 돼 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/hoya-carnosa/\"},{\"id\":\"bstory-hoya-1782-naming\",\"title\":\"1782년의 첫 이름\",\"hook\":\"벚꽃난은 처음 학계에 등장할 때 호야가 아니라 아스클레피아스라는 이름이었어요.\",\"body\":\"지금 호야 카르노사라 부르는 이 덩굴은 처음부터 호야가 아니었어요. 1782년 린네의 아들 카를 폰 린네가 아버지 저작의 보유편인 수플레멘툼 플란타룸 170쪽에서 이 식물을 아스클레피아스 카르노사로 기재했어요. 종소명 카르노사는 살집이 있다는 뜻으로, 두툼하게 살이 오른 잎을 가리켜요. 그로부터 스물여덟 해 뒤인 1810년, 스코틀랜드 식물학자 로버트 브라운이 박주가리 무리를 정리한 논문에서 이 종을 새 속인 호야로 옮겼어요. 속명은 노섬벌랜드 공작의 시온하우스에서 40년을 일한 정원사 토머스 호이의 성에서 왔고요. 그래서 학명 뒤에는 두 사람의 흔적이 괄호 친 형태로 나란히 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ipni.org\",\"sourceUrl\":\"https://www.ipni.org/n/107308-3\"},{\"id\":\"bstory-hoya-peduncle\",\"title\":\"시든 꽃대를 자르지 마세요\",\"hook\":\"꽃이 진 자리를 잘라내면 다음 해에 필 꽃까지 함께 잘려 나가요.\",\"body\":\"벚꽃난은 꽃이 지고 남은 짧은 꽃대를 그대로 두어야 해요. 이 꽃대는 페덩클, 흔히 스퍼라고 부르는 여러 해 남는 구조인데, 많은 종이 해마다 같은 꽃대에서 다시 꽃을 피워요. 아이오와주립대 확장교육 자료는 시든 꽃은 저절로 떨어지게 두고 절대 잘라내지 말라고 못 박아요. 잘라 버리면 앞으로 꽃이 달릴 자리를 없애는 셈이라 개화가 오래 늦어지거든요. 꽃은 밀랍을 입힌 듯한 별 모양으로 무리 지어 피고 대개 여름에 나오며, 저녁이나 밤에 향이 특히 진해져요. 이 속에는 아시아와 오스트레일리아, 그 주변 섬의 열대·아열대에 자생하는 수백 종이 들어 있고 대개 나뭇가지에 붙어 사는 착생식물이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"yardandgarden.extension.iastate.edu\",\"sourceUrl\":\"https://yardandgarden.extension.iastate.edu/how-to/all-about-hoyas\"}]},\"3-22\":{\"photo\":{\"src\":\"/birth/dangauk.jpg\",\"thumbSrc\":\"/birth/thumbs/dangauk.jpg\",\"author\":\"Alvesgaspar\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Mallow_January_2008-1.jpg\",\"familyLine\":\"아욱과의 여러해살이풀이에요 — 자줏빛 줄무늬가 그어진 꽃잎 다섯 장이 활짝 펼쳐집니다.\"},\"stories\":[{\"id\":\"bstory-mallow-marshmallow-root\",\"title\":\"마시멜로는 원래 뿌리였습니다\",\"hook\":\"모닥불에 굽는 그 하얀 것의 이름은, 늪에 사는 아욱이라는 뜻입니다.\",\"body\":\"마시멜로라는 이름을 뜯어 보면 마시와 멜로예요. 늪과 아욱이에요. 실제로 알타이아 오피키날리스라는 아욱과 풀에서 왔어요. 물기 많은 땅에서 이 미터까지 자라요. 기원전 이천 년쯤 이집트 사람들은 이 뿌리에서 끈적한 즙을 뽑아 꿀과 견과를 섞어 과자를 만들었어요. 왕과 신에게만 올리는 것이었대요. 19세기 프랑스 제과사들이 이 뿌리를 설탕, 물, 달걀흰자와 함께 휘저어 파트 드 기모브라는 폭신한 과자를 만들었어요. 건강 간식으로 팔려서 크게 인기를 끌었고요. 문제는 뿌리를 말리고 다듬는 일이 너무 고됐다는 거예요. 그래서 1880년대부터 뿌리 대신 젤라틴이 들어갔어요. 지금 마시멜로에는 아욱이 없어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이집트·프랑스\"},{\"key\":\"era\",\"text\":\"고대~19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mentalfloss.com\",\"sourceUrl\":\"https://www.mentalfloss.com/food/candy/long-sweet-history-marshmallows\"}]},\"3-23\":{\"stories\":[]},\"3-24\":{\"photo\":{\"src\":\"/birth/geumyeonghwa.jpg\",\"thumbSrc\":\"/birth/thumbs/geumyeonghwa.jpg\",\"author\":\"Kaldari\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Kaldari_Eschscholzia_californica_01.jpg\",\"familyLine\":\"양귀비과의 한해살이풀이에요 — 햇빛이 들면 주황빛 꽃잔을 열고 흐리면 다시 오므립니다.\"},\"stories\":[{\"id\":\"bstory-california-poppy-two-friends\",\"title\":\"서로의 이름을 꽃에 붙인 두 사람\",\"hook\":\"한 사람은 친구의 이름을 양귀비에 붙였고, 친구는 그 사람의 이름을 루피너스에 붙였습니다.\",\"body\":\"1816년 10월 2일, 러시아 제국 해군기를 단 두 돛대 범선 루릭호가 샌프란시스코만에 들어왔어요. 케이프 혼을 돌아 남태평양 섬들을 훑고 열다섯 달을 항해한 배였어요. 배에는 과학자 네 명이 타고 있었고, 그중에 아델베르트 폰 샤미소가 있었어요. 샤미소는 그 한 달 동안 만 일대의 동식물을 기록했어요. 그가 프레시디오에서 채집한 표본에 붙인 이름이 에스콜지아 칼리포르니카예요. 배의 젊은 군의관이자 박물학자였던 친구 요한 프리드리히 에슈숄츠의 이름을 딴 거예요. 에슈숄츠도 답례를 했어요. 그곳의 루피너스 하나에 루피누스 카미소니스라는 이름을 붙였거든요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국·독일\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nps.gov\",\"sourceUrl\":\"https://www.nps.gov/articles/adelbert-von-chamisso.htm\"}]},\"3-25\":{\"photo\":{\"src\":\"/birth/deonggulseong-sikmul.jpg\",\"thumbSrc\":\"/birth/thumbs/deonggulseong-sikmul.jpg\",\"author\":\"JLPC\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cl%C3%A9matite_montagnes_FR_2013.jpg\",\"familyLine\":\"스스로 서는 대신 다른 것을 붙잡고 오르는 식물들이에요 — 덩굴손과 흡반으로 빛을 향해 올라갑니다.\"},\"stories\":[]},\"3-26\":{\"stories\":[]},\"3-27\":{\"photo\":{\"src\":\"/birth/kalseolraria.jpg\",\"thumbSrc\":\"/birth/thumbs/kalseolraria.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Calceolaria_biflora_kz01.jpg\",\"familyLine\":\"남아메리카가 고향인 여러해살이풀이에요 — 주머니처럼 부푼 아랫입술 꽃잎이 신발을 닮았습니다.\"},\"stories\":[]},\"3-28\":{\"photo\":{\"src\":\"/birth/kkotakasianamu.jpg\",\"thumbSrc\":\"/birth/thumbs/kkotakasianamu.jpg\",\"author\":\"peganum from Small Dole, England\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Robinia_hispida_-_Flickr_-_peganum.jpg\",\"familyLine\":\"콩과의 낙엽 관목이에요 — 붉은 센털이 덮인 가지에 분홍 나비 모양 꽃이 늘어집니다.\"},\"stories\":[{\"id\":\"bstory-robinia-oldest-tree-in-paris\",\"title\":\"파리에서 가장 늙은 나무\",\"hook\":\"1601년에 심긴 나무가 지금도 파리 한복판에 서 있습니다. 콘크리트 버팀목에 기대서요.\",\"body\":\"파리 5구 르네 비비아니 광장에 나무 한 그루가 있어요. 1601년에 심겼어요. 파리에서 가장 오래된 나무예요. 심은 사람은 앙리 4세의 왕실 정원사였던 식물학자 장 로뱅이에요. 그는 프랑스령 아메리카 식민지에서 낯선 식물을 잔뜩 들여왔고, 천삼백 종이 넘게 기록했어요. 이 나무는 지금 높이 십오 미터, 둘레 삼점오 미터예요. 원래 이 종은 십 미터를 잘 넘기지 않는데 유난히 크게 자란 거예요. 지금은 콘크리트 구조물이 몸을 받치고 있어요. 이름 이야기가 재미있어요. 오랫동안 아카시아의 한 종류로 여겨졌는데, 백 년도 더 지나 린네가 아카시아가 아니라고 정리하면서 로비니아 프세우도아카키아, 곧 가짜 아카시아라는 이름이 붙었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"17세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"thetreeographer.com\",\"sourceUrl\":\"https://thetreeographer.com/2018/04/06/oldest-tree-in-paris-robinia-of-square-rene-viviani/\"}]},\"3-29\":{\"photo\":{\"src\":\"/birth/ueong.jpg\",\"thumbSrc\":\"/birth/thumbs/ueong.jpg\",\"author\":\"Bartosz Cuber\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Arctium_lappa_-_flowers.jpg\",\"familyLine\":\"국화과의 두해살이풀이에요 — 갈고리 달린 총포에 둘러싸인 자주색 꽃이 피고, 뿌리를 먹습니다.\"},\"stories\":[{\"id\":\"bstory-burdock-velcro-dog-walk\",\"title\":\"개털에 붙은 씨앗을 현미경으로 봤습니다\",\"hook\":\"개를 데리고 숲을 걷다가 바지에 붙은 우엉 씨앗을 떼어 왔습니다. 현미경 아래에 갈고리 수천 개가 있었습니다.\",\"body\":\"1941년, 스위스 로잔 근처에 살던 조르주 드 메스트랄이 아이리시 포인터를 데리고 숲을 걸었어요. 돌아와 보니 바지와 개털에 우엉 씨앗이 잔뜩 붙어 있었어요. 보통은 짜증을 내며 떼어 버리는데, 그는 하나를 집으로 가져와 현미경 아래에 놓았어요. 씨앗 표면에 아주 작은 갈고리 수천 개가 돋아 있었어요. 그 갈고리가 옷감의 실 고리와 개털에 걸려 있었던 거예요. 그는 나일론으로 갈고리와 고리를 만들어 붙였다 떼었다 하는 잠금장치를 만들었어요. 이름은 벨루어와 크로셰, 벨벳과 갈고리를 붙여 벨크로라고 지었고요. 특허는 1955년에 나왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스위스\"},{\"key\":\"era\",\"text\":\"1940년대~1950년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"invent.org\",\"sourceUrl\":\"https://www.invent.org/blog/inventors/walk-in-the-woods-velcro\"},{\"id\":\"bstory-burdock-weed-and-vegetable\",\"title\":\"누구에겐 잡초, 누구에겐 반찬\",\"hook\":\"서양에서는 뽑아내기 어려운 잡초입니다. 동아시아에서는 채소입니다.\",\"body\":\"우엉의 영어 별명 목록에는 이런 게 섞여 있어요. 그레이터 버독, 소니 버, 스네이크스 루바브, 베거스 버튼스. 그리고 고보. 앞의 것들은 잡초 이름이고 고보는 일본어로 우엉이에요. 실제로 북미에서 우엉은 빈터와 길가와 목초지를 차지하는 골칫거리로 다뤄져요. 뽑아도 소용이 없어요. 뿌리가 곧고 깊게 박히는 데다, 씨앗이 엄청나게 많이 떨어지고 그 씨앗이 오래도록 살아남거든요. 첫해에는 낮게 잎만 펼치고 이듬해에 훌쩍 솟아 꽃을 피워요. 같은 뿌리를 두고 한쪽에서는 제초 대상 목록에, 한쪽에서는 식용이라 적어 놓았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/arctium-lappa/\"}]},\"3-30\":{\"photo\":{\"src\":\"/birth/geumjakhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/geumjakhwa.jpg\",\"author\":\"DidierFy\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cytisus_scoparius_04.2026_(1).jpg\",\"familyLine\":\"콩과의 낙엽 관목이에요 — 빗자루처럼 곧은 가지마다 노란 나비 모양 꽃이 빼곡히 핍니다.\"},\"stories\":[{\"id\":\"bstory-broom-plantagenet-sprig\",\"title\":\"왕조 이름이 된 나뭇가지\",\"hook\":\"삼백 년 넘게 잉글랜드를 다스린 왕조의 이름은 라틴어로 금작화 가지라는 뜻입니다.\",\"body\":\"플랜태저넷은 1154년 헨리 2세부터 1485년 리처드 3세까지 잉글랜드 왕좌를 지킨 가문의 이름이에요. 이 말은 라틴어 플란타 게니스타에서 왔어요. 금작화 가지라는 뜻이에요. 헨리 2세의 아버지인 앙주 백작 조프루아의 별명이었다고 해요. 투구에 금작화 가지를 꽂고 다녔다는 설명이 흔하지만, 사냥터를 넓히려고 금작화를 심고 다녔기 때문이라는 설명이 더 그럴듯하다고 보는 자료도 있어요. 재미있는 건 이 이름이 세습 성씨가 아니었다는 점이에요. 조프루아의 후손들은 이백오십 년 넘게 성씨 없이 지냈고, 1450년쯤 요크 공작 리처드가 스스로 그렇게 부르면서 비로소 왕조의 이름이 됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드·프랑스\"},{\"key\":\"era\",\"text\":\"12세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"encyclopedia.com\",\"sourceUrl\":\"https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/plantagenet\"}]},\"3-31\":{\"photo\":{\"src\":\"/birth/heukjongcho.jpg\",\"thumbSrc\":\"/birth/thumbs/heukjongcho.jpg\",\"author\":\"Stefan.lefnaer\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Nigella_damascena_sl3.jpg\",\"familyLine\":\"미나리아재비과의 한해살이풀이에요 — 실처럼 가는 잎이 안개처럼 꽃을 감싸 안습니다.\"},\"stories\":[{\"id\":\"bstory-nigella-love-and-devil\",\"title\":\"안개 속의 사랑, 덤불 속의 악마\",\"hook\":\"같은 꽃에 붙은 두 별명이 정반대입니다. 하나는 안개 속의 사랑, 하나는 덤불 속의 악마입니다.\",\"body\":\"흑종초의 영어 별명은 두 가지가 나란히 쓰여요. 러브 인 어 미스트, 그리고 데블 인 어 부시예요. 안개 속의 사랑과 덤불 속의 악마예요. 같은 꽃인데 이름이 이렇게 갈려요. 이유는 생김새예요. 꽃 둘레를 실처럼 가늘게 갈라진 잎이 빙 둘러싸고 있어서 꽃이 안개에 싸인 것처럼 보이거든요. 그런데 꽃이 지고 열매가 부풀면 그 실 같은 것들이 뿔처럼 삐죽삐죽 솟은 형상이 돼요. 그래서 악마가 튀어나온 것 같다고 본 거예요. 미나리아재비과의 서늘한 철 한해살이풀이고, 부푼 씨꼬투리는 말려서 장식으로 많이 써요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/nigella-damascena/\"}]},\"4-1\":{\"photo\":{\"src\":\"/birth/amondeu.jpg\",\"thumbSrc\":\"/birth/thumbs/amondeu.jpg\",\"author\":\"Krzysztof Golik\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Prunus_dulcis_in_Jardins_de_la_Fontaine_in_Nimes_13.jpg\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 이른 봄 연분홍 꽃이 먼저 피고, 씨앗 속 알맹이를 먹습니다.\"},\"stories\":[{\"id\":\"bstory-almond-van-gogh-nephew\",\"title\":\"조카가 태어난 소식을 듣고 그린 가지\",\"hook\":\"동생이 아들을 낳고 형의 이름을 붙였습니다. 형은 곧바로 꽃 핀 아몬드 가지를 그리기 시작했습니다.\",\"body\":\"1890년 초, 생레미의 요양원에 있던 반 고흐에게 편지가 왔어요. 동생 테오와 제수 요에게 아들이 태어났고, 이름을 형의 이름을 따서 빈센트 빌럼으로 짓겠다는 편지였어요. 테오는 이렇게 썼어요. 이 아이가 형처럼 굳세고 용감했으면 좋겠다고요. 반 고흐는 곧바로 그리기 시작했어요. 아몬드였어요. 아몬드는 2월이면 벌써 꽃을 피워서 봄이 온다는 신호로 통하거든요. 새 생명에 딱 맞는 나무였어요. 이 그림은 반 고흐 집안이 가장 아꼈던 작품이 됐고, 그 아기는 자라서 반 고흐 미술관을 세웠어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스·네덜란드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"vangoghmuseum.nl\",\"sourceUrl\":\"https://www.vangoghmuseum.nl/en/collection/s0176v1962\"}]},\"4-2\":{\"stories\":[]},\"4-3\":{\"stories\":[]},\"4-4\":{\"stories\":[]},\"4-5\":{\"photo\":{\"src\":\"/birth/muhwagwa.jpg\",\"thumbSrc\":\"/birth/thumbs/muhwagwa.jpg\",\"author\":\"Rudolphous\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20210731_Hortus_botanicus_Leiden_-_Ficus_carica.jpg\",\"familyLine\":\"뽕나무과의 낙엽 나무예요 — 꽃이 열매 속에 숨어 피어서 '꽃 없는 열매'라 불립니다.\"},\"stories\":[{\"id\":\"bstory-fig-ficus-ruminalis-she-wolf\",\"title\":\"늑대가 젖을 먹인 자리의 무화과\",\"hook\":\"로마 건국 신화에는 무화과나무 한 그루가 서 있습니다. 쌍둥이가 떠내려와 닿은 자리입니다.\",\"body\":\"로마의 팔라티노 언덕 기슭, 루페르칼 동굴 가까이에 무화과나무 한 그루가 서 있었어요. 이름은 피쿠스 루미날리스. 전승에 따르면 로물루스와 레무스가 강물에 떠내려와 닿은 자리, 늑대가 젖을 먹인 자리가 바로 이 나무 아래였어요. 바로, 세르비우스, 페스투스, 플리니우스, 플루타르코스까지 여러 고대 저자가 이 나무를 적어 두었어요. 나라의 기원을 나무 한 그루에 못 박아 둔 셈이에요. 그래서 이 나무의 상태는 나라의 상태로 읽혔어요. 리비우스 시대까지도 서 있었다는 기록이 있고, 오비디우스 무렵에는 흔적만 남았다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"penelope.uchicago.edu\",\"sourceUrl\":\"https://penelope.uchicago.edu/Thayer/E/Gazetteer/Places/Europe/Italy/Lazio/Roma/Rome/_Texts/PLATOP*/Ficus_Ruminalis.html\"},{\"id\":\"bstory-fig-flowers-inside\",\"title\":\"꽃은 열매 안쪽에 핍니다\",\"hook\":\"무화과의 꽃을 본 사람이 드문 이유는 간단합니다. 꽃이 열매 안쪽에 피기 때문입니다.\",\"body\":\"무화과는 이름부터가 꽃 없는 열매라는 뜻이에요. 그런데 꽃이 없는 게 아니에요. 안쪽에 피어요. 우리가 열매라고 부르는 그 주머니가 사실은 씨방이 아니라 부풀어 오른 꽃받침이에요. 식물학에서는 시코니움이라고 불러요. 그 안쪽 벽에 자잘한 꽃이 빼곡히 피어 있는 거예요. 그래서 무화과를 먹는다는 건 꽃송이를 통째로 먹는 일이에요. 그러면 수분은 어떻게 할까요. 원래는 아주 작은 벌이 그 좁은 구멍으로 기어들어 가서 해결해요. 다만 북미에서 재배되는 무화과는 수분 없이도 열매가 맺혀요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/ficus-carica/\"}]},\"4-6\":{\"photo\":{\"src\":\"/birth/adoniseu.jpg\",\"thumbSrc\":\"/birth/thumbs/adoniseu.jpg\",\"author\":\"阿橋 HQ\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:%E5%81%B4%E9%87%91%E7%9B%9E%E8%8A%B1_Adonis_amurensis_-%E9%A6%96%E7%88%BE%E5%88%87%E9%A0%AD%E5%B1%B1%E5%85%AC%E5%9C%92_Seoul,_South_Korea-_(33823991311).jpg\",\"familyLine\":\"미나리아재비과의 여러해살이풀이에요 — 눈이 덜 녹은 이른 봄에 황금빛 꽃을 가장 먼저 엽니다.\"},\"stories\":[]},\"4-7\":{\"photo\":{\"src\":\"/birth/gongjakgosari.jpg\",\"thumbSrc\":\"/birth/thumbs/gongjakgosari.jpg\",\"author\":\"Doug McGrady from Warwick, RI, USA\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Adiantum_pedatum_(northern_maidenhair_fern),_Willsboro,_NY_(32127843596).jpg\",\"familyLine\":\"포자로 번지는 양치식물이에요 — 검은 잎자루에서 잎이 공작 꼬리처럼 둥글게 펼쳐집니다.\"},\"stories\":[{\"id\":\"bstory-adiantum-unwetted\",\"title\":\"젖지 않는다는 뜻의 이름\",\"hook\":\"속명 아디안툼은 젖지 않는다는 뜻입니다. 물을 끼얹어도 잎에 맺히지 않기 때문입니다.\",\"body\":\"공작고사리의 속명 아디안툼은 그리스어 아디안토스에서 왔어요. 젖지 않는다는 뜻이에요. 잎이 물을 튕겨 내거든요. 물을 부어도 잎 위에 맺히지 않고 굴러떨어져요. 이름이 곧 관찰 기록인 셈이에요. 종소명 페다툼은 새의 발 같다는 뜻이고요. 잎자루가 갈라져 부챗살처럼 퍼지는 모양을 가리켜요. 북아메리카 동부와 동아시아에 걸쳐 자라는데, 두 대륙에 같은 계열이 흩어져 있는 전형적인 사례이기도 해요. 아주 가는 검은 잎자루 위에 얇은 잎이 얹혀 있어서, 물이 안 묻는다는 말이 더 그럴듯하게 들려요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/adiantum-pedatum/\"}]},\"4-8\":{\"photo\":{\"src\":\"/birth/geumjakhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/geumjakhwa.jpg\",\"author\":\"DidierFy\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cytisus_scoparius_04.2026_(1).jpg\",\"familyLine\":\"콩과의 낙엽 관목이에요 — 빗자루처럼 곧은 가지마다 노란 나비 모양 꽃이 빼곡히 핍니다.\"},\"stories\":[{\"id\":\"bstory-broom-plantagenet-sprig\",\"title\":\"왕조 이름이 된 나뭇가지\",\"hook\":\"삼백 년 넘게 잉글랜드를 다스린 왕조의 이름은 라틴어로 금작화 가지라는 뜻입니다.\",\"body\":\"플랜태저넷은 1154년 헨리 2세부터 1485년 리처드 3세까지 잉글랜드 왕좌를 지킨 가문의 이름이에요. 이 말은 라틴어 플란타 게니스타에서 왔어요. 금작화 가지라는 뜻이에요. 헨리 2세의 아버지인 앙주 백작 조프루아의 별명이었다고 해요. 투구에 금작화 가지를 꽂고 다녔다는 설명이 흔하지만, 사냥터를 넓히려고 금작화를 심고 다녔기 때문이라는 설명이 더 그럴듯하다고 보는 자료도 있어요. 재미있는 건 이 이름이 세습 성씨가 아니었다는 점이에요. 조프루아의 후손들은 이백오십 년 넘게 성씨 없이 지냈고, 1450년쯤 요크 공작 리처드가 스스로 그렇게 부르면서 비로소 왕조의 이름이 됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드·프랑스\"},{\"key\":\"era\",\"text\":\"12세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"encyclopedia.com\",\"sourceUrl\":\"https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/plantagenet\"}]},\"4-9\":{\"stories\":[]},\"4-10\":{\"photo\":{\"src\":\"/birth/bingka.jpg\",\"thumbSrc\":\"/birth/thumbs/bingka.jpg\",\"author\":\"Naturformidleren\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:A_flower_of_lesser_periwinkle_(Vinca_minor)_close_up.jpg\",\"familyLine\":\"협죽도과의 늘푸른 덩굴성 풀이에요 — 그늘진 땅을 덮으며 보랏빛 바람개비 같은 꽃을 피웁니다.\"},\"stories\":[{\"id\":\"bstory-periwinkle-rousseau-thirty-years\",\"title\":\"삼십 년 만에 알아본 꽃\",\"hook\":\"산길에서 파란 것을 본 사람은 소리를 질렀습니다. 삼십 년 전 그 사람이 가르쳐 준 꽃이었습니다.\",\"body\":\"루소의 고백록에 이런 장면이 있어요. 바랑 부인과 함께 길을 가던 어느 날, 부인이 울타리에서 파란 것을 보고 말했어요. 아직 빙카가 피어 있네요. 그때 루소는 식물을 몰랐고 발밑의 풀을 알아볼 만큼 눈도 좋지 않아서 지나치면서 흘끗 봤을 뿐이었어요. 그러고 삼십 년 가까이 흘렀어요. 스위스 산길을 오르던 루소가 갑자기 소리를 질렀어요. 아, 빙카가 있다고요. 그사이 그는 식물학자가 돼 있었고, 바랑 부인은 곁에 없었어요. 프랑스에서 이 꽃이 기억과 우정의 상징이 된 건 이 한 장면 때문이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스·스위스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/3913/3913-h/3913-h.htm\"}]},\"4-11\":{\"photo\":{\"src\":\"/birth/kkotgobi.jpg\",\"thumbSrc\":\"/birth/thumbs/kkotgobi.jpg\",\"author\":\"Robert Flogaus-Faust\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Polemonium_caeruleum_RF.jpg\",\"familyLine\":\"꽃고비과의 여러해살이풀이에요 — 사다리처럼 마주 붙은 잎 위로 푸른 종 모양 꽃이 모여 핍니다.\"},\"stories\":[{\"id\":\"bstory-polemonium-two-names\",\"title\":\"야곱의 사다리라 불리는 풀\",\"hook\":\"한 풀에 그리스 쥐오줌풀과 야곱의 사다리라는 두 이름이 나란히 붙어 있습니다.\",\"body\":\"꽃고비속 식물의 영어 통용명은 두 갈래로 갈려요. 하나는 그리스 발레리안, 그리스 쥐오줌풀이에요. 다른 하나는 야곱의 사다리예요. 야곱의 사다리라는 이름은 잎을 보면 이해가 돼요. 작은 잎이 잎줄기 양쪽으로 사다리 가로대처럼 가지런히 마주 붙어 있거든요. 창세기에서 야곱이 꿈에 본 그 사다리를 떠올린 거예요. 서로 다른 두 이름이 하나는 약효를, 하나는 잎 모양을 가리키는 셈이에요. 참고로 한국의 꽃고비는 폴레모니움 카이룰레움 계열이라 이 자료가 다루는 북미종과는 다른 종이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/polemonium-reptans/\"}]},\"4-12\":{\"photo\":{\"src\":\"/birth/boksakkot.jpg\",\"thumbSrc\":\"/birth/thumbs/boksakkot.jpg\",\"author\":\"lumoplank\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Alishan,_Part_II_-_Alishan5306.jpg\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 잎이 나기 전 분홍 꽃이 가지를 감싸듯 피어납니다.\"},\"stories\":[{\"id\":\"bstory-peach-taoyuan-oath\",\"title\":\"복숭아밭에서 맺은 의형제\",\"hook\":\"삼국지연의의 첫 장면은 전투가 아니라 꽃밭입니다. 세 사람이 복숭아밭에서 형제가 됩니다.\",\"body\":\"삼국지연의의 첫 회 제목이 이래요. 복숭아밭에서 잔치를 열어 세 호걸이 의형제를 맺고, 황건적을 베어 영웅들이 처음 공을 세우다. 소설이 시작하자마자 나오는 무대가 전장이 아니라 꽃밭인 거예요. 유비, 관우, 장비가 복숭아꽃이 만발한 뜰에서 형제의 의를 맺는 장면이죠. 첫 회 머리에 붙은 사에는 이런 구절이 있어요. 도도한 장강은 동으로 흘러가고 물결이 영웅을 씻어 가며, 옳고 그름과 이기고 지는 것도 고개를 돌리면 헛되다고요. 그 허무한 노래 바로 뒤에 꽃밭의 맹세가 오는 배치예요. 도원결의라는 말이 여기서 나왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"14세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ctext.org\",\"sourceUrl\":\"https://ctext.org/sanguo-yanyi/ch1\"}]},\"4-13\":{\"photo\":{\"src\":\"/birth/pereusia-gukhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/pereusia-gukhwa.jpg\",\"author\":\"Rl\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:2007_coreopsis_tinctoria.jpg\",\"familyLine\":\"국화과의 한해살이풀이에요 — 노란 꽃잎 안쪽에 붉은 고리가 둘러진 것이 특징입니다.\"},\"stories\":[{\"id\":\"bstory-coreopsis-not-persian\",\"title\":\"페르시아에서 오지 않았습니다\",\"hook\":\"페르시아 국화라 부르지만 이 꽃의 고향은 북아메리카 대평원입니다.\",\"body\":\"페르시아 국화라는 이름은 일본을 거쳐 들어온 한자 이름이에요. 그런데 이 꽃은 페르시아와 아무 상관이 없어요. 학명은 코레옵시스 팅크토리아, 영어로는 플레인스 코레옵시스, 대평원의 코레옵시스예요. 북아메리카가 고향이에요. 종소명 팅크토리아는 물을 들인다는 뜻이고요. 실제로 오래전부터 염료 식물로 쓰였어요. 노란 꽃잎 안쪽에 붉은 갈색 무늬가 도장처럼 찍혀 있는 게 특징이에요. 나비와 벌이 좋아하고 척박한 흙에서도 잘 자라요. 이름은 서아시아를 가리키는데 실물은 아메리카 초원에서 온 꽃이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/coreopsis-tinctoria/\"}]},\"4-14\":{\"photo\":{\"src\":\"/birth/huinnapalkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/huinnapalkkot.jpg\",\"author\":\"Jebulon\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ipomoea_alba_Alhambra_Spain.jpg\",\"familyLine\":\"메꽃과의 덩굴성 풀이에요 — 나팔처럼 벌어진 흰 꽃이 딱 하루만 피고 집니다.\"},\"stories\":[{\"id\":\"bstory-morning-glory-edo-henka-asagao\",\"title\":\"에도를 뒤흔든 변화 나팔꽃\",\"hook\":\"꽃 같지도 않은 나팔꽃을 만들려고 에도 사람들이 살림을 기울였습니다.\",\"body\":\"나팔꽃은 일본 자생종이 아닌데, 원예화가 유독 일본에서만 깊게 진행됐어요. 1차 붐은 에도시대 분카분세이 연간이었어요. 계기가 뜻밖이에요. 1806년 에도 대화재로 시타야 일대에 빈 땅이 크게 생겼고, 거기서 화훼업자들이 나팔꽃을 골라 기르기 시작한 거예요. 2차 붐은 가에이안세이 연간에 왔고, 이때는 원종과 닮은 구석이 거의 없는 꽃들이 쏟아졌어요. 유전학 쪽에서 보면 이 붐의 정체는 트랜스포존이에요. 움직이는 유전자가 활발하게 옮겨 다니며 색과 모양을 지배하는 유전자에 끼어들었고, 나팔꽃이 자가수분을 잘하는 성질 덕에 그 변이가 금방 겉으로 드러났어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mg.biology.kyushu-u.ac.jp\",\"sourceUrl\":\"http://mg.biology.kyushu-u.ac.jp/hort-history.php\"},{\"id\":\"bstory-morning-glory-kengoshi-seed\",\"title\":\"소를 끌고 와 바꾸던 씨앗\",\"hook\":\"나팔꽃은 처음에 꽃으로 들어오지 않았습니다. 약으로 들어왔습니다.\",\"body\":\"나팔꽃이 일본에 건너온 건 지금부터 천이백 년쯤 전, 나라시대에 중국을 통해서였어요. 그때는 꽃을 보려고 들여온 게 아니었어요. 약이었어요. 그것도 아주 센 설사약이었고요. 그래서 처음에는 아사가오라고 부르지도 않았어요. 약으로 쓰는 씨앗은 견우자, 식물체는 견우라고 불렀어요. 소를 끌고 온다는 뜻의 이름이에요. 씨앗이 소와 바꿀 만큼 귀했다는 데서 왔다고 전해져요. 지금은 여름 아침에 잠깐 피었다 지는 꽃으로만 알려져 있지만, 이름 안에는 아직 소 한 마리가 들어 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"8세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"mg.biology.kyushu-u.ac.jp\",\"sourceUrl\":\"http://mg.biology.kyushu-u.ac.jp/hort-history.php\"}]},\"4-15\":{\"photo\":{\"src\":\"/birth/pen-okideu.jpg\",\"thumbSrc\":\"/birth/thumbs/pen-okideu.jpg\",\"author\":\"Bouke ten Cate\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Groenknolorchis_-_fen_orchid_-_Liparis_loeselii_2.jpg\",\"familyLine\":\"습지에 사는 난초과의 여러해살이풀이에요 — 두 장의 반들거리는 잎 사이로 연둣빛 작은 꽃을 올립니다.\"},\"stories\":[]},\"4-16\":{\"stories\":[]},\"4-17\":{\"stories\":[]},\"4-18\":{\"photo\":{\"src\":\"/birth/jaunyeong.jpg\",\"thumbSrc\":\"/birth/thumbs/jaunyeong.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Astragalus_sinicus_3.JPG\",\"familyLine\":\"콩과의 두해살이풀이에요 — 논에 거름으로 심어, 봄이면 분홍 꽃이 논바닥을 덮습니다.\"},\"stories\":[]},\"4-19\":{\"stories\":[]},\"4-20\":{\"photo\":{\"src\":\"/birth/baenamu.jpg\",\"thumbSrc\":\"/birth/thumbs/baenamu.jpg\",\"author\":\"PumpkinSky\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Pyrus_pyrifolia_(Shinko)_inflorescence2.JPG\",\"familyLine\":\"장미과의 낙엽 큰키나무예요 — 봄에 흰 꽃잎 다섯 장이 모여 피고, 가을에 배가 익습니다.\"},\"stories\":[]},\"4-21\":{\"photo\":{\"src\":\"/birth/suyangbeodeul.jpg\",\"thumbSrc\":\"/birth/thumbs/suyangbeodeul.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cornjum,_Martenastate,_(tuin)_03.jpg\",\"familyLine\":\"버드나무과의 낙엽 큰키나무예요 — 물가로 길게 늘어진 가지에 봄이면 연둣빛 꽃차례가 달립니다.\"},\"stories\":[{\"id\":\"bstory-willow-wanggeon-leaf-in-water\",\"title\":\"물 위에 띄운 버들잎 한 장\",\"hook\":\"목마른 장군이 물을 청했습니다. 처녀는 바가지에 버들잎을 띄워 건넸습니다.\",\"body\":\"전라남도 나주시청 앞에 완사천이라는 샘이 있어요. 아무리 가물어도 마르지 않는다고 해요. 여기에 전설이 내려와요. 왕건이 이 근처를 지나다가 물을 청했어요. 샘가에서 빨래하던 처녀가 바가지에 물을 뜨고, 곁의 버들잎을 따서 물 위에 띄워 건넸어요. 왕건이 왜 잎을 띄웠느냐고 묻자 처녀가 답했어요. 말을 달려오시느라 목이 몹시 마르실 텐데 급히 드시면 체하실 것 같아 천천히 불어 가며 드시라고 띄웠다고요. 이 처녀가 고려 2대 임금 혜종의 어머니, 나주 오씨 장화왕후예요. 나주시의 상징인 버들아가씨가 여기서 나왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"10세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"atlasnews.co.kr\",\"sourceUrl\":\"http://www.atlasnews.co.kr/news/articleView.html?idxno=10738\"},{\"id\":\"bstory-willow-napoleon-cuttings\",\"title\":\"무덤 곁 버드나무의 후손들\",\"hook\":\"황제는 자기가 묻힐 자리를 직접 골랐습니다. 그 곁의 버드나무는 가지째 세계로 흩어졌습니다.\",\"body\":\"나폴레옹은 세인트헬레나섬에서 자기가 묻힐 자리를 직접 골랐어요. 버드나무 골짜기라 불리던 곳이에요. 1821년 5월에 죽어 그 자리에 묻혔고, 무덤 머리맡에는 수양버들 한 그루가 서 있었어요. 외딴섬까지 찾아온 방문객들이 그 나무의 가지를 잘라 갔어요. 그리고 세계 곳곳에 심었어요. 1840년에 유해는 프랑스로 옮겨졌지만 나무의 후손들은 그대로 남았어요. 남아프리카의 한 농장에도 그 가지에서 자란 나무가 있어요. 저수지 둑 위에 홀로 서 있는데, 섬에 갇혔던 황제와 닮았다고 적혀 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"세인트헬레나\"},{\"key\":\"era\",\"text\":\"19세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"babylonstoren.com\",\"sourceUrl\":\"https://babylonstoren.com/blog/post/napoleons-willow\"}]},\"4-22\":{\"stories\":[]},\"4-23\":{\"photo\":{\"src\":\"/birth/doraji.jpg\",\"thumbSrc\":\"/birth/thumbs/doraji.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Platycodon_grandiflorus_(flower_s2).jpg\",\"familyLine\":\"초롱꽃과의 여러해살이풀이에요 — 풍선처럼 부푼 꽃봉오리가 별 모양으로 터지듯 열립니다.\"},\"stories\":[{\"id\":\"bstory-balloon-flower-akechi-kikyo\",\"title\":\"배신자의 문장이 된 꽃\",\"hook\":\"혼노지를 둘러싼 깃발에 그려진 연푸른 도라지꽃을 보고, 사람들은 배신자가 누구인지 알았습니다.\",\"body\":\"일본 전국시대 무장들의 가문 문장은 대개 검은색 한 가지였어요. 그런데 아케치 미쓰히데는 연푸른색으로 물들인 도라지 문장을 썼어요. 미즈이로 기쿄예요. 얼마나 눈에 띄었는지, 오다 노부나가가 그 문장을 부러워했다는 이야기까지 전해져요. 1582년 혼노지의 변 때, 노부나가를 에워싼 병사들의 깃발에 바로 그 연푸른 도라지가 그려져 있었어요. 배신자가 누구인지 그 자리에서 드러난 거예요. 그 뒤로 도라지 문장은 배신의 상징처럼 취급됐어요. 노부나가의 후손들은 지금도 도라지꽃을 장식하지 않는다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"touken-world.jp\",\"sourceUrl\":\"https://www.touken-world.jp/tips/91006/\"},{\"id\":\"bstory-balloon-flower-balloon-bud\",\"title\":\"터지기 직전의 풍선\",\"hook\":\"이 꽃의 이름은 핀 모습이 아니라 피기 직전 모습에서 왔습니다.\",\"body\":\"도라지의 영어 이름은 벌룬 플라워, 풍선꽃이에요. 꽃이 풍선처럼 생겨서가 아니에요. 아직 피지 않은 봉오리에서 온 이름이에요. 도라지 봉오리는 다섯 갈래 꽃잎이 가장자리끼리 딱 붙은 채로 안쪽에 공기를 품고 부풀어요. 그래서 피기 직전에는 정말 작은 종이 풍선처럼 빵빵해져요. 손으로 누르면 톡 소리가 날 것 같은 상태죠. 그러다 붙어 있던 자리가 갈라지면서 별 모양으로 벌어져요. 학명 플라티코돈은 넓은 종이라는 뜻이고요. 부풀었다가 종이 되는, 두 단계짜리 이름을 가진 꽃이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/platycodon-grandiflorus/\"}]},\"4-24\":{\"stories\":[]},\"4-25\":{\"photo\":{\"src\":\"/birth/jungguk-paemo.jpg\",\"thumbSrc\":\"/birth/thumbs/jungguk-paemo.jpg\",\"author\":\"James Steakley\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fritillaria_thunbergii.jpg\",\"familyLine\":\"백합과의 알뿌리 식물이에요 — 고개 숙인 연둣빛 종 모양 꽃이 줄기를 따라 달립니다.\"},\"stories\":[]},\"4-26\":{\"photo\":{\"src\":\"/birth/nonnaengi.jpg\",\"thumbSrc\":\"/birth/thumbs/nonnaengi.jpg\",\"author\":\"batra3x\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cardamine_lyrata.jpg\",\"familyLine\":\"물가와 논에 자라는 십자화과의 여러해살이풀이에요 — 둥근 잎이 줄기를 따라 달리고 흰 꽃잎 네 장이 십자로 핍니다.\"},\"stories\":[]},\"4-27\":{\"stories\":[]},\"4-28\":{\"stories\":[]},\"4-29\":{\"stories\":[]},\"4-30\":{\"photo\":{\"src\":\"/birth/geumsaseulnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/geumsaseulnamu.jpg\",\"author\":\"Jebulon\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Laburnum_anagyroides_Medik._Cytise_-_Aubour_JdP.jpg\",\"familyLine\":\"콩과의 낙엽 큰키나무예요 — 초여름이면 노란 꽃송이가 사슬처럼 길게 늘어집니다.\"},\"stories\":[{\"id\":\"bstory-laburnum-bodnant-55m\",\"title\":\"오십오 미터짜리 금빛 터널\",\"hook\":\"빅토리아 시대 사람이 1880년에 만든 터널이, 지금도 오월마다 노랗게 켜집니다.\",\"body\":\"웨일스 보드난트 정원에는 오십오 미터짜리 아치 통로가 있어요. 1880년에 이 정원을 만든 헨리 포친이 세웠어요. 설계를 맡긴 사람은 에드워드 밀너인데, 수정궁을 만든 조지프 팩스턴의 제자였어요. 16세기와 17세기 유럽 정원의 퍼걸러 산책로를 본떠 만든 구조예요. 여기에 금사슬나무를 올렸어요. 오월 말에서 유월 초, 삼 주 남짓 되는 기간에 이 통로 천장이 통째로 노란 꽃송이로 뒤덮여요. 영국에서 가장 길고 가장 오래된 금사슬 아치로 여겨지고, 이 삼 주 동안에만 오만 명이 찾아와요.\",\"notes\":[{\"key\":\"region\",\"text\":\"웨일스\"},{\"key\":\"era\",\"text\":\"19세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nationaltrust.org.uk\",\"sourceUrl\":\"https://www.nationaltrust.org.uk/visit/wales/bodnant-garden/laburnum-arch-at-bodnant-garden\"}]},\"5-1\":{\"photo\":{\"src\":\"/birth/kauseulrip-aengcho.jpg\",\"thumbSrc\":\"/birth/thumbs/kauseulrip-aengcho.jpg\",\"author\":\"Bff\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Primula_veris20170513_7568.jpg\",\"familyLine\":\"이른 봄 풀밭에서 노란 종 여러 개를 한 대에 매달고 고개를 숙여요.\"},\"stories\":[{\"id\":\"bstory-cowslip-ariel-bell\",\"title\":\"요정이 잠드는 종\",\"hook\":\"템페스트의 요정 에어리얼은 카우슬립 종 속에 눕는다고 노래해요.\",\"body\":\"셰익스피어의 템페스트 5막에서 요정 에어리얼은 이렇게 노래해요. 벌이 꿀을 빠는 곳에서 나도 빨고, 카우슬립 종 속에 나는 눕는다고요. 카우슬립의 꽃은 노란 종이 여러 개 모여 고개를 숙인 모양이라, 요정 하나가 들어가 눕는 침대로 그려 놓기에 알맞았어요. 영국에서는 이 꽃을 '요정의 잔'이라 부르던 지방도 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bardgarden.blogspot.com\",\"sourceUrl\":\"https://bardgarden.blogspot.com/2014/10/primroses-cowslips-oxlips.html\"},{\"id\":\"bstory-cowslip-queens-pensioners\",\"title\":\"여왕의 근위병이 된 꽃\",\"hook\":\"요정은 카우슬립의 귀에 진주를 걸어 준다고 말해요.\",\"body\":\"한여름 밤의 꿈 2막에서 요정은 티타니아를 모시는 일을 이렇게 설명해요. 키 큰 카우슬립이 여왕의 근위병이고, 금빛 옷에 점이 박혀 있으며, 자기는 그 꽃 귀마다 진주를 하나씩 걸어 준다고요. 여기서 근위병은 엘리자베스 1세를 호위하던 신사 근위대를 가리켜요. 금실 자수 옷에 진주를 달고 여왕 곁에 늘어선 쉰 명의 귀족을 카우슬립 무리에 겹쳐 놓은 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"shakespeare.org.uk\",\"sourceUrl\":\"https://www.shakespeare.org.uk/explore-shakespeare/blogs/pearl-every-cowslips-ear/\"}]},\"5-2\":{\"photo\":{\"src\":\"/birth/minariajaebi-0502.jpg\",\"thumbSrc\":\"/birth/thumbs/minariajaebi-0502.jpg\",\"author\":\"K1ng8766\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ranunculus_japonicus_Keelung.jpg\",\"familyLine\":\"들판에 흔한 노란 다섯 잎 꽃인데, 꽃잎이 기름칠한 듯 반짝여요.\"},\"stories\":[{\"id\":\"bstory-buttercup-chin-glow\",\"title\":\"턱이 노랗게 물드는 이유\",\"hook\":\"미나리아재비를 턱에 대면 노란빛이 도는 데는 이유가 있어요.\",\"body\":\"미나리아재비를 턱 아래 대고 노란빛이 비치면 버터를 좋아하는 거라는 놀이가 유럽에 오래 있었어요. 2011년 케임브리지대 연구진이 그 광학을 실제로 재 봤어요. 꽃잎 표피 세포의 윗면이 유리에 가까울 만큼 매끈한 데다, 표피 아래에 공기층이 얇게 떠 있어 반사면이 하나가 아니라 둘이었어요. 두 면이 겹쳐 반사를 두 배로 만들기 때문에 다른 꽃보다 유독 잘 비친다는 결론이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"cam.ac.uk\",\"sourceUrl\":\"https://www.cam.ac.uk/research/news/why-buttercups-reflect-yellow-on-chins\"},{\"id\":\"bstory-buttercup-little-frog\",\"title\":\"작은 개구리라는 이름 그리고 일부러 낸 물집\",\"hook\":\"라눙쿨루스는 라틴어로 '작은 개구리'예요.\",\"body\":\"미나리아재비속의 학명 Ranunculus는 라틴어 rana, 곧 개구리에 축소형 어미가 붙은 말이에요. '작은 개구리'라는 뜻이고, 물가와 축축한 자리에 잘 자라 개구리와 이웃이 되기 때문이라고 봐요. 이 풀에는 라눈쿨린이 들어 있는데, 잎이 으깨지면 프로토아네모닌으로 바뀌어 살갗에 물집을 만들어요. 유럽에서는 동정을 사려고 일부러 이 즙으로 물집을 냈다는 이야기가 전해질 만큼 잘 알려진 성질이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"home.howstuffworks.com\",\"sourceUrl\":\"https://home.howstuffworks.com/ranunculus.htm\"}]},\"5-3\":{\"photo\":{\"src\":\"/birth/mindeulre.jpg\",\"thumbSrc\":\"/birth/thumbs/mindeulre.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Paardenbloem_%28Taraxacum_officinale%29_06.JPG\",\"familyLine\":\"밟혀도 다시 서고, 씨앗이 되고 나면 바람만 기다려요.\"},\"stories\":[{\"id\":\"bstory-dandelion-dent-de-lion\",\"title\":\"사자의 이빨이라는 이름\",\"hook\":\"민들레의 영어 이름은 '사자의 이빨'이라는 뜻이에요.\",\"body\":\"영어 dandelion은 14세기 초에 dent-de-lioun으로 적혔어요. 프랑스어 dent de lion, 곧 '사자의 이빨'을 그대로 옮긴 말이고, 톱니처럼 갈라진 잎 가장자리를 사자 송곳니에 빗댄 이름으로 봐요. 학명 Taraxacum의 뿌리는 더 멀리 있어요. 9~11세기 페르시아 의학서에서 라지와 이븐 시나가 이 풀을 타라샤쿠크라 불렀고, 중세 유럽이 그 말을 옮겨 적으면서 굳었다는 설이 유력해요. 잎 하나에 두 문화권의 이름이 겹쳐 있는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"jhiblog.org\",\"sourceUrl\":\"https://www.jhiblog.org/2020/05/20/a-dandelion-story-from-medieval-herbals-to-wholefoods/\"},{\"id\":\"bstory-dandelion-vortex-ring\",\"title\":\"홀씨가 나는 방식은 2018년에야 밝혀졌어요\",\"hook\":\"민들레 홀씨 위에는 공기로 된 고리가 떠 있어요.\",\"body\":\"민들레 홀씨의 갓털은 빈 곳이 90퍼센트가 넘는데도 같은 크기의 원판보다 네 배 넘는 공기 저항을 만들어요. 2018년 에든버러대 연구진이 풍동과 고속 촬영으로 그 이유를 찾아 네이처에 실었어요. 갓털 사이로 공기가 빠져나가면서 씨앗 위쪽에 떨어져 있는 소용돌이 고리가 생기고, 그 고리가 홀씨를 오래 떠 있게 붙잡아 준다는 거예요. 자연에서 이런 분리형 소용돌이 고리가 관찰된 것은 그때가 처음이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"nature.com\",\"sourceUrl\":\"https://www.nature.com/articles/s41586-018-0604-2\"}]},\"5-4\":{\"photo\":{\"src\":\"/birth/ttalgi.jpg\",\"thumbSrc\":\"/birth/thumbs/ttalgi.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fragaria_vesca_-_metsmaasikas.jpg\",\"familyLine\":\"흰 다섯 잎 꽃이 지고 나면 그 자리에 붉은 열매가 앉아요.\"},\"stories\":[{\"id\":\"bstory-strawberry-frezier-spy\",\"title\":\"요새를 그리러 간 사람이 딸기를 가져왔어요\",\"hook\":\"칠레 해안 요새를 몰래 측량하던 프랑스 공병이 딸기 몇 포기를 챙겼어요.\",\"body\":\"1712년 프랑스 공병 장교 아메데 프랑수아 프레지에는 상선 선장 행세를 하며 칠레와 페루 해안의 스페인 요새를 몰래 측량했어요. 그가 그곳에서 본 것이 알이 굵은 칠레딸기였고, 1714년 마르세유로 돌아올 때 몇 포기를 배에 싣고 왔어요. 긴 항해를 견딘 것은 다섯 포기뿐이었다고 전해져요. 그는 이 딸기를 브레스트의 식물원과 왕립정원에 넘겼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"atlasobscura.com\",\"sourceUrl\":\"https://www.atlasobscura.com/articles/big-strawberries-spy-chile-france\"},{\"id\":\"bstory-strawberry-accidental-hybrid\",\"title\":\"우연히 섞여 지금의 딸기가 되었어요\",\"hook\":\"오늘 먹는 딸기는 남북 아메리카의 두 딸기가 우연히 만난 결과예요.\",\"body\":\"프레지에가 가져온 칠레딸기는 잘 자랐지만 열매를 거의 맺지 못했어요. 그가 고른 포기가 대부분 암그루였기 때문이에요. 그런데 브르타뉴의 밭에서 북아메리카산 버지니아딸기와 나란히 심기면서 꽃가루가 오갔고, 두 부모 어느 쪽보다 크고 향이 좋은 열매가 나왔어요. 파인애플 향이 난다고 해서 붙은 이름이 지금의 학명 Fragaria × ananassa예요. 세계가 먹는 딸기는 이 우연한 잡종의 후손이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"herbaria.plants.ox.ac.uk\",\"sourceUrl\":\"https://herbaria.plants.ox.ac.uk/bol/plants400/Profiles/ef/Fragaria\"}]},\"5-5\":{\"stories\":[]},\"5-6\":{\"stories\":[]},\"5-7\":{\"photo\":{\"src\":\"/birth/ttalgi.jpg\",\"thumbSrc\":\"/birth/thumbs/ttalgi.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fragaria_vesca_-_metsmaasikas.jpg\",\"familyLine\":\"흰 다섯 잎 꽃이 지고 나면 그 자리에 붉은 열매가 앉아요.\"},\"stories\":[{\"id\":\"bstory-strawberry-frezier-spy\",\"title\":\"요새를 그리러 간 사람이 딸기를 가져왔어요\",\"hook\":\"칠레 해안 요새를 몰래 측량하던 프랑스 공병이 딸기 몇 포기를 챙겼어요.\",\"body\":\"1712년 프랑스 공병 장교 아메데 프랑수아 프레지에는 상선 선장 행세를 하며 칠레와 페루 해안의 스페인 요새를 몰래 측량했어요. 그가 그곳에서 본 것이 알이 굵은 칠레딸기였고, 1714년 마르세유로 돌아올 때 몇 포기를 배에 싣고 왔어요. 긴 항해를 견딘 것은 다섯 포기뿐이었다고 전해져요. 그는 이 딸기를 브레스트의 식물원과 왕립정원에 넘겼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"atlasobscura.com\",\"sourceUrl\":\"https://www.atlasobscura.com/articles/big-strawberries-spy-chile-france\"},{\"id\":\"bstory-strawberry-accidental-hybrid\",\"title\":\"우연히 섞여 지금의 딸기가 되었어요\",\"hook\":\"오늘 먹는 딸기는 남북 아메리카의 두 딸기가 우연히 만난 결과예요.\",\"body\":\"프레지에가 가져온 칠레딸기는 잘 자랐지만 열매를 거의 맺지 못했어요. 그가 고른 포기가 대부분 암그루였기 때문이에요. 그런데 브르타뉴의 밭에서 북아메리카산 버지니아딸기와 나란히 심기면서 꽃가루가 오갔고, 두 부모 어느 쪽보다 크고 향이 좋은 열매가 나왔어요. 파인애플 향이 난다고 해서 붙은 이름이 지금의 학명 Fragaria × ananassa예요. 세계가 먹는 딸기는 이 우연한 잡종의 후손이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"herbaria.plants.ox.ac.uk\",\"sourceUrl\":\"https://herbaria.plants.ox.ac.uk/bol/plants400/Profiles/ef/Fragaria\"}]},\"5-8\":{\"stories\":[]},\"5-9\":{\"stories\":[]},\"5-10\":{\"stories\":[]},\"5-11\":{\"photo\":{\"src\":\"/birth/sagwa-0511.jpg\",\"thumbSrc\":\"/birth/thumbs/sagwa-0511.jpg\",\"author\":\"Johann Jaritz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:P%C3%B6rtschach_Winklern_10.-Oktober-Stra%C3%9Fe_67_Jonagold_Apfelbl%C3%BCte_23042015_2568.jpg\",\"familyLine\":\"가지마다 분홍 봉오리가 열리면서 흰 꽃으로 벌어져요.\"},\"stories\":[{\"id\":\"bstory-apple-almaty\",\"title\":\"사과의 아버지라는 이름의 도시\",\"hook\":\"카자흐스탄 알마티의 옛 이름은 '사과의 아버지'예요.\",\"body\":\"재배 사과의 조상은 카자흐스탄 톈산산맥에 자생하는 말루스 시에베르시예요. 20세기 초 러시아 식물학자 니콜라이 바빌로프가 알마티 근교에서 사과나무가 야생으로 빽빽하게 얽혀 자라는 숲을 보고 이곳을 사과의 고향으로 지목했고, 훗날 유전체 분석이 그 짐작을 뒷받침했어요. 알마티의 옛 이름 알마아타는 '사과의 아버지'라는 뜻이에요. 다만 소련 시절 개발로 야생 사과 숲의 상당 부분이 사라졌고, 지금은 남은 숲을 지키는 일이 과제로 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"카자흐스탄\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/travel/saving-the-apples-ancient-ancestor-in-the-forests-of-kazakhstan-180983493/\"},{\"id\":\"bstory-apple-graft-and-cider\",\"title\":\"씨앗으로 심으면 부모를 닮지 않아요\",\"hook\":\"사과 씨를 심으면 그 사과가 나오지 않아요.\",\"body\":\"사과는 씨앗으로 번식하면 부모와 전혀 다른 나무가 나와요. 그래서 과수원은 원하는 품종의 가지를 대목에 붙이는 접붙이기로 나무를 복제해요. 미국의 존 채프먼, 이른바 조니 애플시드는 반대로 씨앗만 뿌리고 다녔어요. 접붙이기를 창조에 손대는 일로 여겼다고 전해져요. 그렇게 나온 사과는 대개 그냥 먹기엔 떫어서 대부분 사과술로 짜였어요. 미국 개척지의 사과나무는 먹을거리라기보다 마실 거리에 가까웠던 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"wildabundance.net\",\"sourceUrl\":\"https://www.wildabundance.net/blog/johnny-appleseed/\"},{\"id\":\"bstory-apple-newton-tree\",\"title\":\"뉴턴의 사과나무는 아직 산다\",\"hook\":\"1816년 폭풍에 쓰러진 나무가 그 자리에서 다시 뿌리를 내려 지금도 서 있어요.\",\"body\":\"뉴턴이 사과 떨어지는 걸 본 건 1666년 늦여름이었대요. 품종은 플라워 오브 켄트로, 15세기 기록까지 거슬러 올라가는 요리용 사과예요. 이 이야기는 뉴턴 본인이 볼테르와 존 콘듀잇, 윌리엄 스터클리 같은 사람들에게 직접 들려준 것이고, 글로 남은 첫 기록은 뉴턴이 세상을 떠난 1726년 콘듀잇의 메모예요. 1806년 에드먼드 터너의 책은 울스소프 정원의 특정 나무를 그 나무로 지목하면서 그 나무는 아직 남아 있고 방문객에게 보여진다고 적었어요. 1816년 폭풍이 나무를 쓰러뜨렸지만 남은 부분이 다시 뿌리를 내렸고, 그 나무가 지금도 울스소프에 서 있어요. 수령은 350년이 넘어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"york.ac.uk\",\"sourceUrl\":\"https://www.york.ac.uk/physics-engineering-technology/about/newtons-apple-tree/\"},{\"id\":\"bstory-apple-chapman-cider\",\"title\":\"자니 애플시드는 술나무를 심었다\",\"hook\":\"그가 심은 사과는 먹으려는 게 아니라, 발효시켜 사이다를 담그기 위한 것이었어요.\",\"body\":\"1774년 매사추세츠에서 태어난 존 채프먼은 1790년대부터 펜실베이니아에서 일리노이까지 옮겨 다니며 정착민보다 먼저 과수원을 만들고 되팔았어요. 그런데 그가 심은 사과는 그대로 먹기엔 너무 시었어요. 그는 스베덴보리교 신자였고, 그 교리가 접붙이기를 금했거든요. 접을 붙이면 식물이 아파한다고 봤대요. 그래서 오직 씨앗으로만 심었고, 씨에서 난 사과는 거의 다 발효용, 곧 하드 사이다용이었어요. 당시 오하이오 컴퍼니는 100에이커를 얻으려면 3년 안에 사과나무 쉰 그루와 복숭아나무 스무 그루를 심으라고 요구했으니, 그의 묘목은 정착 증서나 다름없었어요. 금주법 시대에는 그 신 사과나무들이 단속에 베여 나갔다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"18세기~19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/arts-culture/real-johnny-appleseed-brought-applesand-booze-american-frontier-180953263/\"},{\"id\":\"bstory-apple-eris-discord\",\"title\":\"초대받지 못한 여신의 사과\",\"hook\":\"결혼식에 부르지 않았다는 이유로 던진 황금 사과 하나가 트로이 전쟁을 불렀어요.\",\"body\":\"불화의 여신 에리스는 헤시오도스의 신통기에서 밤의 여신 닉스가 마지막으로 낳은 자식으로 나와요. 펠레우스와 테티스의 결혼식에 초대받지 못한 에리스는 가장 아름다운 이에게라고 새긴 황금 사과를 던져 넣었어요. 아테나와 헤라, 아프로디테가 서로 자기 것이라 다투자 제우스는 판정을 트로이 왕자 파리스에게 떠넘겼지요. 아프로디테는 세상에서 가장 아름다운 여인 헬레네를 주겠다고 약속해 사과를 차지했고요. 파리스가 헬레네를 데려가면서 그리스 연합군이 트로이로 향했고, 십 년 전쟁이 시작됐어요. 불화의 사과라는 말은 여기서 나왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"worldhistory.org\",\"sourceUrl\":\"https://www.worldhistory.org/Eris/\"}]},\"5-12\":{\"photo\":{\"src\":\"/birth/railrak.jpg\",\"thumbSrc\":\"/birth/thumbs/railrak.jpg\",\"author\":\"Ayotte, Gilles, 1948-\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Syringa_vulgaris_15-p.bot-syrin.vulga-18.jpg\",\"familyLine\":\"작은 통꽃이 원뿔로 모여 피고, 향이 늘 먼저 도착해요.\"},\"stories\":[{\"id\":\"bstory-lilac-syringa-pan\",\"title\":\"갈대가 된 님프와 피리\",\"hook\":\"라일락의 속명 Syringa는 '피리'라는 뜻이에요.\",\"body\":\"그리스 신화에서 목신 판이 님프 시링가를 쫓자 시링가는 강가에서 속이 빈 갈대로 변했다고 전해져요. 판은 그 갈대를 잘라 첫 팬파이프를 만들었고, 그 악기의 이름이 시링크스예요. 라일락의 속명 Syringa는 이 그리스어 '관, 피리'에서 왔어요. 라일락 가지는 속이 무른 심으로 차 있어 파내면 대롱이 되는데, 유럽에서는 실제로 이 가지로 피리를 만들었다고 해요. 이름이 신화와 생김새 양쪽을 함께 가리키는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"thegardenhistory.blog\",\"sourceUrl\":\"https://thegardenhistory.blog/2017/04/15/lilac-time/\"},{\"id\":\"bstory-lilac-busbecq\",\"title\":\"오스만 정원에서 유럽으로 건너온 향기\",\"hook\":\"라일락은 콘스탄티노플의 정원을 거쳐 유럽에 들어왔어요.\",\"body\":\"라일락의 고향은 발칸반도예요. 그런데 서유럽 정원에 들어온 길은 오스만 제국을 거쳤어요. 16세기 중반 합스부르크 황제 페르디난트 1세의 대사로 콘스탄티노플에 머물던 오지에 기슬랭 드 부스베크가 오스만 관리들의 정원에서 이 꽃을 보고 반해 유럽으로 보냈고, 1563년 무렵 중부 유럽에 자리 잡았다고 전해져요. 부스베크는 튤립을 유럽에 알린 인물로도 이름이 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"튀르키예\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"baldhiker.com\",\"sourceUrl\":\"https://www.baldhiker.com/the-sweet-aroma-of-lilacs/\"}]},\"5-13\":{\"photo\":{\"src\":\"/birth/sansanamu.jpg\",\"thumbSrc\":\"/birth/thumbs/sansanamu.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Crataegus_pinnatifida%27s_flower.JPG\",\"familyLine\":\"흰 꽃이 우산처럼 모여 피고, 가을엔 붉은 열매가 그 자리에 달려요.\"},\"stories\":[{\"id\":\"bstory-hawthorn-glastonbury-thorn\",\"title\":\"크리스마스에 한 번 더 피는 가시나무\",\"hook\":\"글래스턴베리의 산사나무는 겨울에도 꽃을 피워요.\",\"body\":\"잉글랜드 서머싯의 글래스턴베리에는 아리마태아 요셉이 짚고 온 지팡이를 땅에 꽂자 그 자리에서 뿌리를 내리고 싹을 틔워 꽃이 피었다는 산사나무 전설이 전해져요. 사람들이 이 나무를 특별하게 여긴 것은 봄에 한 번 피고 한겨울, 대개 동지 무렵에 다시 꽃을 다는 성질 때문이었어요. 품종 이름에 붙은 '비플로라'가 바로 한 해에 두 번 핀다는 뜻이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"allhallowsguild.org\",\"sourceUrl\":\"https://allhallowsguild.org/visit-us/cathedral-gardens-virtual-tour/the-main-cathedral-gardens/glastonbury-thorn/\"},{\"id\":\"bstory-hawthorn-cut-down\",\"title\":\"베이고 잘리고 그래도 이어진 나무\",\"hook\":\"이 나무는 17세기에 한 번 2010년에 또 한 번 잘렸어요.\",\"body\":\"글래스턴베리의 성스러운 산사나무는 17세기 내전기에 청교도 병사가 미신의 물건이라며 베어 냈다고 전해져요. 그래도 마을 사람들이 미리 잘라 둔 가지를 접붙여 뒤를 이었고, 지금 수도원 터에 선 나무도 그 후손으로 여겨져요. 크리스마스에 꽃봉오리가 달린 가지를 왕실에 보내는 관습도 오래 이어지고 있어요. 2010년에는 위어리얼 언덕의 나무가 밤사이 가지를 모두 잘리는 일이 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bbc.com\",\"sourceUrl\":\"https://www.bbc.com/news/uk-england-somerset-11957440\"}]},\"5-14\":{\"photo\":{\"src\":\"/birth/maebaltopkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/maebaltopkkot.jpg\",\"author\":\"Uoaei1\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Aquilegia_vulgaris_Gemeindealpe_01.JPG\",\"familyLine\":\"꽃잎 뒤로 매 발톱처럼 굽은 꿀주머니가 다섯 개 뻗어 있어요.\"},\"stories\":[{\"id\":\"bstory-columbine-eagle-and-dove\",\"title\":\"독수리 발톱이자 비둘기 떼\",\"hook\":\"같은 꽃을 보고 누구는 독수리를 누구는 비둘기를 떠올렸어요.\",\"body\":\"매발톱꽃의 속명 Aquilegia는 라틴어 aquila, 곧 독수리에서 왔다고 봐요. 뒤로 굽은 다섯 개의 꿀주머니가 맹금의 굽은 발톱을 닮았다는 거예요. 반면 영어 이름 columbine은 라틴어 columba, 곧 비둘기에서 왔어요. 꽃을 거꾸로 놓고 보면 다섯 마리 비둘기가 머리를 맞대고 둘러앉은 모습으로 보였기 때문이에요. 한국어 이름 매발톱꽃은 앞쪽 계보를 따라간 이름이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"thehistoryjar.com\",\"sourceUrl\":\"https://thehistoryjar.com/2023/07/22/columbines-grannys-bonnet-aquilegia-call-it-what-you-will/\"},{\"id\":\"bstory-columbine-holy-spirit\",\"title\":\"중세 그림에 숨어 있는 다섯 마리 비둘기\",\"hook\":\"중세 화가들은 매발톱꽃을 성령의 표시로 그려 넣었어요.\",\"body\":\"비둘기를 닮았다는 인상은 중세 유럽에서 종교적 의미로 굳었어요. 꽃 뒤로 뻗은 다섯 개의 꿀주머니가 비둘기 다섯 마리가 모여 앉은 모습으로 읽혔고, 비둘기는 성령의 상징이었어요. 여기에 매발톱꽃 일곱 송이를 성령의 일곱 은사, 곧 지혜와 지성, 조언과 용기, 지식과 공경과 경외로 읽는 해석까지 겹쳤어요. 중세와 르네상스 그림에 이유 없이 놓인 듯한 매발톱꽃이 자주 등장하는 이유예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"academic.oup.com\",\"sourceUrl\":\"https://academic.oup.com/jxb/article/60/6/1535/519453\"}]},\"5-15\":{\"stories\":[]},\"5-16\":{\"photo\":{\"src\":\"/birth/jobapnamul.jpg\",\"thumbSrc\":\"/birth/thumbs/jobapnamul.jpg\",\"author\":\"Kızıl\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hieracium_umbellatum%E2%80%93IMG_5860.jpg\",\"familyLine\":\"가늘게 선 줄기 끝에서 노란 혀꽃이 사방으로 퍼져요.\"},\"stories\":[{\"id\":\"bstory-hieracium-mendel-failure\",\"title\":\"멘델을 막아선 풀\",\"hook\":\"완두로 유전 법칙을 찾은 멘델은 조팝나물 앞에서 멈췄어요.\",\"body\":\"완두 실험을 끝낸 멘델은 조팝나물속 연구자였던 식물학자 카를 폰 네겔리와 편지를 주고받으며 이 속으로 실험을 옮겼어요. 그런데 자손 세대가 갈라지지 않고 대부분 부모를 똑 닮은 모습으로 나왔어요. 멘델은 몇 해를 쏟고도 답을 얻지 못한 채 1868년 수도원장이 되면서 연구를 접었어요. 이유는 그가 알 수 없던 것이었어요. 조팝나물속의 많은 종은 수정 없이 씨를 맺는 무수정생식을 해요. 이 현상은 그가 죽고 한참 뒤인 1904년에야 밝혀졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"오스트리아\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"academic.oup.com\",\"sourceUrl\":\"https://academic.oup.com/jxb/article/62/5/1699/493601\"},{\"id\":\"bstory-hieracium-hawk-eyes\",\"title\":\"매가 눈을 씻는 풀이라는 오해\",\"hook\":\"속명 Hieracium은 '매'라는 뜻이에요.\",\"body\":\"조팝나물속의 학명 Hieracium은 그리스어 히에락스, 곧 매에서 왔어요. 로마의 플리니우스는 박물지에 매가 이 풀을 찢어 즙을 눈에 뿌려 흐려진 시력을 되돌린다고 적었어요. 영어 이름 hawkweed도 여기서 나왔어요. 물론 매가 이 풀에 관심을 두거나 이 풀에 시력을 좋게 하는 성분이 들어 있다는 근거는 없어요. 근거 없는 관찰 하나가 학명으로 굳어 2000년을 버틴 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"friendsofeloisebutler.org\",\"sourceUrl\":\"https://www.friendsofeloisebutler.org/pages/plants/orangehawkweed.html\"}]},\"5-17\":{\"stories\":[]},\"5-18\":{\"photo\":{\"src\":\"/birth/okseulrip-aengcho.jpg\",\"thumbSrc\":\"/birth/thumbs/okseulrip-aengcho.jpg\",\"author\":\"Silar\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:02022_0057_Primula_elatior.jpg\",\"familyLine\":\"카우슬립보다 꽃이 크고, 한쪽만 바라보며 몰려 피어요.\"},\"stories\":[{\"id\":\"bstory-oxlip-oberon-bank\",\"title\":\"오베론이 아는 둑\",\"hook\":\"티타니아가 잠드는 그 둑에는 옥슬립이 피어 있어요.\",\"body\":\"한여름 밤의 꿈 2막에서 오베론은 이렇게 말해요. 나는 야생 백리향이 피는 둑을 하나 알고 있다고, 옥슬립과 고개 숙인 제비꽃이 자라는 곳이라고요. 이어 인동과 들장미가 지붕을 이룬 그곳에서 티타니아가 밤마다 잠든다고 하고, 그 잠든 눈에 꽃즙을 떨어뜨리는 것이 극 전체를 굴리는 장치가 돼요. 옥슬립은 그 짧은 꽃 목록에서 첫 자리를 차지해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"folger.edu\",\"sourceUrl\":\"https://www.folger.edu/explore/shakespeares-works/a-midsummer-nights-dream/read/\"},{\"id\":\"bstory-oxlip-between-two\",\"title\":\"프림로즈와 카우슬립 사이\",\"hook\":\"옥슬립은 두 앵초 사이에서 나온 것으로 알려져 있어요.\",\"body\":\"옥슬립은 프림로즈와 카우슬립 사이에서 나온 것으로 널리 설명돼요. 셰익스피어 정원을 다루는 글들은 세 앵초를 늘 한 묶음으로 놓고, 옥슬립을 카우슬립의 큰 사촌쯤으로 소개해요. 셰익스피어도 겨울 이야기 4막에서 페르디타가 꽃을 늘어놓는 대목에 '대담한 옥슬립'을 끼워 넣었어요. 세 꽃을 나란히 놓는 이 습관은 400년이 지나도록 잘 바뀌지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"bardgarden.blogspot.com\",\"sourceUrl\":\"https://bardgarden.blogspot.com/2014/10/primroses-cowslips-oxlips.html\"}]},\"5-19\":{\"stories\":[]},\"5-20\":{\"photo\":{\"src\":\"/birth/gwaengibap.jpg\",\"thumbSrc\":\"/birth/thumbs/gwaengibap.jpg\",\"author\":\"André Karwath aka Aka\",\"license\":\"CC BY-SA 2.5\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Oxalis_corniculata_-_blossom_top_%28aka%29.jpg\",\"familyLine\":\"하트 세 장이 모인 잎 사이에서 노란 별 같은 꽃이 올라와요.\"},\"stories\":[{\"id\":\"bstory-woodsorrel-shamrock-mixup\",\"title\":\"아일랜드 사람들이 먹었다는 그 풀\",\"hook\":\"1571년 영국인이 적은 '샴록'은 토끼풀이 아니었을 수 있어요.\",\"body\":\"샴록이라는 말이 영어에 처음 나타난 것은 1571년 에드먼드 캠피언의 아일랜드 역사서예요. 그는 아일랜드 사람들이 샴록과 물냉이, 뿌리와 풀을 먹는다고 적었어요. 그런데 아일랜드 쪽 기록 어디에도 토끼풀을 먹었다는 자료는 없고, 괭이밥을 먹었다는 자료는 있어요. 게일어로 괭이밥을 셤소그라 부르는데, 샴록의 어원인 셤로그와 소리가 비슷해요. 이 닮은 이름 때문에 두 풀이 오래 뒤섞였다고 봐요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"irishtimes.com\",\"sourceUrl\":\"https://www.irishtimes.com/culture/heritage/eating-and-drinking-the-shamrock-1.1728268\"},{\"id\":\"bstory-woodsorrel-alleluia\",\"title\":\"알렐루야라고 불린 꽃\",\"hook\":\"유럽에서는 괭이밥을 '알렐루야'라고 불렀어요.\",\"body\":\"유럽에서 괭이밥에는 '알렐루야'라는 별명이 붙어 있어요. 부활절 전후, 교회에서 알렐루야를 다시 부르기 시작하는 시기에 숲 바닥에서 꽃이 피기 때문이에요. 잎을 씹으면 나는 신맛은 옥살산 때문인데, 이 성분이 속명 Oxalis의 뿌리이기도 해요. 신맛 나는 잎과 봄에 맞춰 피는 흰 꽃, 세 갈래 잎이 겹치면서 괭이밥은 오래 성스러운 풀 쪽으로 읽혀 왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pacifichorticulture.org\",\"sourceUrl\":\"https://pacifichorticulture.org/articles/sun-shamrocks-and-alleluia-flowers/\"}]},\"5-21\":{\"stories\":[]},\"5-22\":{\"photo\":{\"src\":\"/birth/gwigorikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/gwigorikkot.jpg\",\"author\":\"Diego Delso\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fuchsia_magellanica_%27Pumile%27%2C_Jard%C3%ADn_Bot%C3%A1nico_de_M%C3%BAnich%2C_Alemania%2C_2013-05-04%2C_DD_01.jpg\",\"familyLine\":\"붉은 꽃받침 아래로 자줏빛 치마가 매달려 귀고리처럼 흔들려요.\"},\"stories\":[{\"id\":\"bstory-fuchsia-plumier\",\"title\":\"카리브해에서 찾아 독일 학자에게 바친 이름\",\"hook\":\"푹시아는 발견자가 아니라 200년 앞선 학자의 이름을 달고 있어요.\",\"body\":\"1695년 프랑스 수사이자 식물학자였던 샤를 플뤼미에는 루이 14세의 명으로 기나나무를 찾아 카리브해로 세 번째 항해를 떠났어요. 그는 히스파니올라섬 기슭에서 처음 보는 식물을 발견해 스케치하고 기록했어요. 1703년 그는 이 식물의 이름을 공식으로 발표하면서 자기 이름이 아니라 독일 의사이자 식물학자였던 레온하르트 푹스의 이름을 붙였어요. 푹스는 그보다 130년 전에 세상을 떠난 사람이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"blog.thompson-morgan.com\",\"sourceUrl\":\"https://blog.thompson-morgan.com/history-of-fuchsias/\"}]},\"5-23\":{\"photo\":{\"src\":\"/birth/pului-ssak.jpg\",\"thumbSrc\":\"/birth/thumbs/pului-ssak.jpg\",\"author\":\"USGS Bee Inventory and Monitoring Lab from Beltsville, Maryland, USA\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Boxelder%2C_twig_upper_marlboro_2015-04-10-20.29.25_ZS_PMax_%2816916113178%29.jpg\",\"familyLine\":\"잎이 되기 직전, 아직 접혀 있는 상태를 그대로 보여줘요.\"},\"stories\":[]},\"5-24\":{\"photo\":{\"src\":\"/birth/helriotoropeu.jpg\",\"thumbSrc\":\"/birth/thumbs/helriotoropeu.jpg\",\"author\":\"Jules Verne Times Two\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Close-up_of_heliotrope_flower_%28Heliotropium_arborescens%29%2C_Jardim_da_Funda%C3%A7%C3%A3o_Calouste_Gulbenkian%2C_Lisbon%2C_Portugal_julesvernex2.jpg\",\"familyLine\":\"작은 보랏빛 꽃이 뭉쳐 피고, 바닐라를 닮은 향이 나요.\"},\"stories\":[{\"id\":\"bstory-heliotrope-clytie\",\"title\":\"아흐레를 해만 바라본 님프\",\"hook\":\"클리티에는 먹지도 마시지도 않고 아흐레 동안 해를 좇았어요.\",\"body\":\"오비디우스의 변신 이야기 4권에 클리티에 이야기가 있어요. 태양신 헬리오스의 마음이 레우코토에에게 옮겨 가자 클리티에는 바깥에 나앉아 아흐레 밤낮을 먹지도 마시지도 않고 하늘을 건너가는 해만 좇아 고개를 돌렸어요. 그 자리에서 몸이 땅에 뿌리내렸고 해를 따라 도는 풀이 되었다고 해요. 헬리오트로프라는 이름 자체가 그리스어로 '해를 향해 돈다'는 뜻이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"eclecticlight.co\",\"sourceUrl\":\"https://eclecticlight.co/2017/04/19/changing-stories-ovids-metamorphoses-on-canvas-16-venus-and-mars-leucothoe-and-clytie/\"},{\"id\":\"bstory-heliotrope-not-sunflower\",\"title\":\"그 꽃은 해바라기일 수 없어요\",\"hook\":\"클리티에가 해바라기가 되었다는 그림은 사실 시대가 맞지 않아요.\",\"body\":\"후대 그림과 번역은 클리티에를 해바라기로 바꿔 놓는 일이 많아요. 그런데 해바라기는 북아메리카 원산이라 오비디우스가 살던 로마에는 없던 꽃이에요. 그가 떠올린 것은 지중해에 자생하는 헬리오트로피움 쪽이었을 거예요. 게다가 영어에서 heliotrope는 지치과에 속해 국화과인 해바라기와 계통도 달라요. 그림 속의 큰 노란 꽃은 신화가 아니라 신대륙 이후의 상상이 덧붙은 자리예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"eclecticlight.co\",\"sourceUrl\":\"https://eclecticlight.co/2017/04/19/changing-stories-ovids-metamorphoses-on-canvas-16-venus-and-mars-leucothoe-and-clytie/\"}]},\"5-25\":{\"stories\":[]},\"5-26\":{\"photo\":{\"src\":\"/birth/olribeunamu.jpg\",\"thumbSrc\":\"/birth/thumbs/olribeunamu.jpg\",\"author\":\"Javier martin\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Olea_europaea_FlowersCloseup_SolanadelPino.jpg\",\"familyLine\":\"열매로만 알던 나무가 여름 앞에서 아주 작은 흰 꽃을 무더기로 달아요.\"},\"stories\":[{\"id\":\"bstory-olive-acropolis-sprout\",\"title\":\"불탄 다음 날 두 뼘이 자랐다는 나무\",\"hook\":\"페르시아군이 태운 올리브나무가 이튿날 싹을 냈다고 헤로도토스는 적었어요.\",\"body\":\"아테네의 수호신 자리를 두고 아테나와 포세이돈이 겨뤘을 때, 포세이돈은 삼지창으로 바위를 쳐 짠물 샘을 냈고 아테나는 올리브나무를 심었다고 전해져요. 아크로폴리스는 그 올리브를 신성한 나무로 모셨어요. 헤로도토스는 기원전 480년 페르시아군이 아테네를 불태운 뒤의 일을 이렇게 적었어요. 사람들이 이튿날 올라가 보니 타 버린 그루터기에서 두 규빗쯤 되는 새 가지가 올라와 있었다고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"greekcitytimes.com\",\"sourceUrl\":\"https://greekcitytimes.com/2021/06/27/olive-tree-acropolis/\"},{\"id\":\"bstory-olive-kotinos\",\"title\":\"고대 올림픽의 상은 올리브 가지 하나였어요\",\"hook\":\"우승자가 받은 것은 야생 올리브로 엮은 관 하나뿐이었어요.\",\"body\":\"고대 올림피아에서 우승자에게 준 상은 코티노스, 곧 야생 올리브 가지로 엮은 관이었어요. 제우스 신전 옆에 선 신성한 야생 올리브에서 부모가 모두 살아 있는 소년이 황금 가위로 가지를 잘라 헤라 신전의 상 위에 올려 두면, 심판들이 그것으로 관을 엮어 씌웠어요. 파우사니아스는 이 나무를 헤라클레스가 먼 북쪽 땅에서 가져와 아버지 제우스의 신전 곁에 심은 것이라고 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"olympia-museum.gr\",\"sourceUrl\":\"https://olympia-museum.gr/olive-wreaths-of-olympia-ancient-symbols-of-victory/\"}]},\"5-27\":{\"stories\":[]},\"5-28\":{\"photo\":{\"src\":\"/birth/bakha-0528.jpg\",\"thumbSrc\":\"/birth/thumbs/bakha-0528.jpg\",\"author\":\"Superior National Forest\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Mentha_arvensis_2_%285097344051%29.jpg\",\"familyLine\":\"잎겨드랑이마다 연보랏빛 꽃이 둥글게 뭉쳐 층층이 올라가요.\"},\"stories\":[{\"id\":\"bstory-mint-minthe-trampled\",\"title\":\"밟혀서 향이 된 님프\",\"hook\":\"저승의 왕이 사랑한 님프는 여왕의 발에 짓밟혔습니다. 그 자리에서 박하가 돋았습니다.\",\"body\":\"민테는 엘리스 지방의 물의 님프였어요. 하데스가 그를 사랑했고요. 그런데 민테가 자기가 페르세포네보다 아름답다고, 하데스가 곧 자기에게 돌아올 거라고 떠벌렸어요. 그 말이 화를 불렀어요. 스트라본의 지리지는 민테가 페르세포네의 발에 짓밟혀 정원의 박하로 변했다고 적어요. 오피아노스는 데메테르가 노해서 짓밟았다고 하고, 오비디우스는 페르세포네가 직접 변신시켰다고 해요. 누가 밟았는지는 갈리는데 결말은 같아요. 짓밟힌 자리에서 향기로운 풀이 돋았다는 것. 필로스 근처에는 지금도 민테의 이름을 딴 산이 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"theoi.com\",\"sourceUrl\":\"https://www.theoi.com/Nymphe/NympheMinthe.html\"},{\"id\":\"bstory-mint-peppermint-hybrid\",\"title\":\"페퍼민트는 야생에서 우연히 생긴 잡종이에요\",\"hook\":\"페퍼민트에는 조상이 둘 있어요.\",\"body\":\"페퍼민트는 워터민트와 스피어민트가 자연에서 교배해 생긴 잡종이에요. 1696년 영국 박물학자 존 레이가 들판에서 후추 맛이 나는 민트를 발견해 처음 기록했고, 1721년에는 런던 약전에 올랐어요. 상업 재배는 18세기 중반 서리주 미첨 일대에서 시작됐는데, 그곳 이름을 딴 미첨 민트는 지금도 가장 널리 퍼진 계통이에요. 향은 오래됐지만 종 자체는 꽤 젊은 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Peppermint\"},{\"id\":\"bstory-mint-mitcham-500acres\",\"title\":\"미첨의 박하밭 500에이커\",\"hook\":\"1750년 무렵 시작된 미첨의 페퍼민트 재배는 1850년에 약 500에이커에 이르렀어요.\",\"body\":\"페퍼민트는 오랫동안 박하의 한 갈래로만 취급되다가 1696년 식물학자 존 레이가 별개의 종으로 갈라냈어요. 1721년에는 런던 약전에 정식으로 올랐지요. 상업 재배는 1750년 무렵 런던 남쪽 미첨에서 시작됐고, 1850년에는 재배 면적이 약 500에이커에 이르렀어요. 박하 자체는 훨씬 오래되어서 중세 유럽의 식물 목록에는 빠짐없이 올랐고 9세기 수녀원 정원에서도 길렀으며, 페퍼민트는 13세기 아이슬란드 약전에도 이름이 보여요. 초서는 민트가 가득하고 회향이 푸른 작은 길을 노래했고, 1568년 터너의 약초서는 정원 박하를 스피어민트로 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"http://botanical.com/botanical/mgmh/m/mints-39.html\"}]},\"5-29\":{\"photo\":{\"src\":\"/birth/tokkipul.jpg\",\"thumbSrc\":\"/birth/thumbs/tokkipul.jpg\",\"author\":\"Supportstorm\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Trifolium_repens_flower_April_2_2010.jpg\",\"familyLine\":\"작은 나비 모양 꽃 수십 개가 모여 하나의 공처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-clover-dinely-1681\",\"title\":\"성 패트릭 축일에 세 잎 풀을 다는 관습의 첫 기록\",\"hook\":\"1681년 영국인 여행자가 그 관습을 처음 적었어요.\",\"body\":\"성 패트릭이 세 잎 풀로 삼위일체를 설명했다는 이야기는 널리 알려져 있지만, 정작 그 관습이 문서에 처음 나타나는 것은 1681년이에요. 아일랜드를 여행한 영국인 토머스 디닐리가 3월 17일에 사람들이 세 잎 풀 샴로그를 미신처럼 달고, 숨결이 향기로워진다며 그것을 먹기도 한다고 적었어요. 삼위일체 설명 자체가 기록에 등장하는 것은 그보다도 나중이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"greennews.ie\",\"sourceUrl\":\"https://greennews.ie/the-history-of-the-shamrock-from-saint-patrick-to-campions-wild-irish-to-rebellion-and-nationhood/\"},{\"id\":\"bstory-clover-four-leaf-gene\",\"title\":\"네 잎이 되는 유전자를 찾아냈어요\",\"hook\":\"2010년 연구진이 네 잎 클로버를 만드는 유전자를 짚어 냈어요.\",\"body\":\"2010년 미국 조지아대의 웨인 패럿 연구진이 흰토끼풀에서 네 잎을 만드는 형질의 유전자 위치를 분자 표지로 짚어 냈어요. 잎에 붉은 무늬가 생기는 형질의 유전자도 함께 찾았고요. 흥미로운 것은 유전자가 있어도 네 잎이 늘 나오지는 않는다는 점이에요. 패럿의 말대로 햇빛이나 온도가 맞지 않으면 그냥 세 잎으로 자라요. 유전자와 환경이 어떻게 맞물리는지는 아직 다 풀리지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"news.uga.edu\",\"sourceUrl\":\"https://news.uga.edu/four-leaf-clover-spotting/\"}]},\"5-30\":{\"photo\":{\"src\":\"/birth/boratbit-railrak.jpg\",\"thumbSrc\":\"/birth/thumbs/boratbit-railrak.jpg\",\"author\":\"Kor!An (Андрей Корзун)\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Syringa_%27Gastello%27_03.JPG\",\"familyLine\":\"같은 라일락이라도 보랏빛이 짙어질수록 꽃송이가 더 무거워 보여요.\"},\"stories\":[{\"id\":\"bstory-lilac-purple-newhampshire\",\"title\":\"강인한 성품을 닮았다는 이유로 주화가 되었어요\",\"hook\":\"미국 뉴햄프셔주는 1919년 보랏빛 라일락을 주화로 정했어요.\",\"body\":\"1919년 뉴햄프셔주는 보랏빛 라일락을 주를 상징하는 꽃으로 정했어요. 선정 이유로 남은 문구는 이 꽃이 '화강암 주 사람들의 강인한 성품을 상징한다'는 것이었어요. 화강암 주는 뉴햄프셔의 별명이에요. 척박한 땅에서도 잘 사는 관목의 성질을 주민의 기질에 겹쳐 놓은 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"50states.com\",\"sourceUrl\":\"https://www.50states.com/flower/newhampshire.htm\"},{\"id\":\"bstory-lilac-purple-hat-draw\",\"title\":\"모자에서 뽑아 정한 꽃\",\"hook\":\"후보가 좁혀지지 않자 눈을 가리고 이름을 뽑았어요.\",\"body\":\"1919년의 선정 과정은 순탄하지 않았어요. 사과꽃과 자주색 아스터, 나리와 수련, 골든로드, 미나리아재비, 메이플라워까지 아홉 가지가 후보로 올라 표가 갈렸어요. 결국 상원은 보랏빛 라일락과 메이플라워, 자주색 아스터 세 이름을 모자에 넣고, 당시 상원 서기 얼 고든에게 눈가리개를 씌운 뒤 하나를 뽑게 했어요. 참고로 미국에서 가장 오래된 축에 드는 라일락은 1750년 총독 베닝 웬트워스가 잉글랜드에서 들여와 포츠머스 저택에 심은 나무예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"aroundconcord.com\",\"sourceUrl\":\"https://www.aroundconcord.com/2020/07/09/our-new-hampshire-lilac-and-how-it-came-to-be/\"}]},\"5-31\":{\"photo\":{\"src\":\"/birth/mureut.jpg\",\"thumbSrc\":\"/birth/thumbs/mureut.jpg\",\"author\":\"C T Johansson\",\"license\":\"CC BY 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Barnardia_japonica-IMG_9388.jpg\",\"familyLine\":\"늦여름에 분홍 꽃이 아래에서 위로 차례차례 올라가며 피어요.\"},\"stories\":[{\"id\":\"bstory-scilla-famine-food\",\"title\":\"흉년을 건너게 해 준 알뿌리\",\"hook\":\"무릇 알뿌리는 엿처럼 고아 먹던 구황식물이었어요.\",\"body\":\"무릇은 들과 밭둑에 흔한 풀이지만, 살기 어렵던 시절에는 중요한 구황식물이었어요. 땅속의 지름 2~3센티미터쯤 되는 알뿌리를 봄에 캐서 갈색 겉껍질을 벗기고 연한 소금물에 삶은 뒤, 미지근한 물에 서너 시간 담가 아린 맛을 우려내고 간장에 조려 먹었어요. 엿기름물과 함께 대여섯 시간 삭혀 조청을 고아 아이들 간식으로 삼기도 했고요. 손이 많이 가는 만큼 굶주림을 오래 버티게 해 준 음식이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"ecomedia.co.kr\",\"sourceUrl\":\"https://ecomedia.co.kr/news/newsview.php?ncode=1065603080002741\"},{\"id\":\"bstory-scilla-leaf-and-flower\",\"title\":\"잎과 꽃이 서로를 비켜 가요\",\"hook\":\"무릇은 꽃이 필 때 잎이 없어요.\",\"body\":\"무릇은 잎과 꽃이 좀처럼 함께 있지 않아요. 이른 봄에 가늘고 긴 잎이 먼저 올라왔다가, 꽃대가 설 즈음이면 그 잎이 사라져요. 그리고 꽃이 지고 나면 잎이 다시 돋아요. 상사화가 그렇듯 잎과 꽃이 서로를 비켜 가는 이 습성 때문에, 같은 자리에서 봄과 가을에 본 풀을 서로 다른 풀로 아는 사람도 많아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"newsje.com\",\"sourceUrl\":\"https://www.newsje.com/news/articleView.html?idxno=83981\"}]},\"6-1\":{\"stories\":[]},\"6-2\":{\"photo\":{\"src\":\"/birth/ppalgang-maebaltopkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/ppalgang-maebaltopkkot.jpg\",\"author\":\"gailhampshire from Cradley, Malvern, U.K\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Eastern_Red_Columbine_Aquilegia_canadensis_%2824439345658%29.jpg\",\"familyLine\":\"붉은 꽃이 고개를 숙이고, 노란 속만 아래로 내밀어요.\"},\"stories\":[]},\"6-3\":{\"photo\":{\"src\":\"/birth/ama.jpg\",\"thumbSrc\":\"/birth/thumbs/ama.jpg\",\"author\":\"Quartl\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Linum_usitatissimum_qtl1.jpg\",\"familyLine\":\"하늘색에 가까운 꽃이 아침에 열렸다가 한나절이면 져요.\"},\"stories\":[{\"id\":\"bstory-flax-dzudzuana\",\"title\":\"3만 년 전의 실\",\"hook\":\"조지아의 동굴에서 3만 년 전 아마 섬유가 나왔어요.\",\"body\":\"조지아 주주아나 동굴에서 야생 아마 섬유가 나왔고, 연대는 약 3만 년 전으로 측정됐어요. 사람이 만든 섬유로는 세계에서 가장 오래된 축에 들어요. 더 놀라운 것은 그 섬유가 그냥 뭉쳐 있던 것이 아니라 꼬이고 매듭이 지어져 있었고, 일부는 청록색과 분홍색으로 물들어 있었다는 점이에요. 옷을 지으려면 실이 먼저 있어야 하는데, 그 실이 이렇게 오래됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"캅카스\"},{\"key\":\"era\",\"text\":\"선사 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pubmed.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pubmed.ncbi.nlm.nih.gov/19745144/\"},{\"id\":\"bstory-flax-egypt-linen\",\"title\":\"파라오를 감싼 것도 아마였어요\",\"hook\":\"미라를 감은 천은 아마로 짠 리넨이에요.\",\"body\":\"고대 이집트에서 리넨은 그냥 옷감이 아니라 정결함의 상징이었어요. 신관은 리넨만 입었고 미라는 여러 겹의 리넨으로 감쌌어요. 아마 섬유는 젖으면 오히려 강해지고 펙틴이 물과 만나 서로를 붙잡기 때문에, 다른 섬유보다 훨씬 느리게 삭아요. 수천 년이 지난 무덤에서 리넨 조각이 형태를 유지한 채 나오는 이유예요. 파란 꽃이 피는 한해살이 풀이 사람의 시간을 가장 오래 붙들어 온 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이집트\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"collections.reading.ac.uk\",\"sourceUrl\":\"https://collections.reading.ac.uk/ure-musuem/wp-content/uploads/sites/4/2020/06/Linen_Ure_UoR.pdf\"}]},\"6-4\":{\"stories\":[]},\"6-5\":{\"stories\":[]},\"6-6\":{\"stories\":[]},\"6-7\":{\"stories\":[]},\"6-8\":{\"stories\":[]},\"6-9\":{\"stories\":[]},\"6-10\":{\"photo\":{\"src\":\"/birth/suyeompaeraengikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/suyeompaeraengikkot.jpg\",\"author\":\"Johann Jaritz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:P%C3%B6rtschach_Winklern_10.-Oktober-Stra%C3%9Fe_67_Bartnelke_21062024_1161.jpg\",\"familyLine\":\"짧은 꽃대 위로 작은 패랭이꽃이 빽빽하게 모여 한 다발이 돼요.\"},\"stories\":[{\"id\":\"bstory-sweetwilliam-unknown-name\",\"title\":\"이름의 주인을 아무도 모르는 꽃\",\"hook\":\"'스위트 윌리엄'의 윌리엄이 누구인지 확인된 적이 없어요.\",\"body\":\"수염패랭이꽃의 영어 이름 스위트 윌리엄에는 유래설이 여럿 붙어 있어요. 컴벌랜드 공 윌리엄 오거스터스라는 설, 요크의 성 윌리엄이라는 설, 셰익스피어라는 설, 정복왕 윌리엄이라는 설까지요. 그런데 어느 하나도 확인된 적이 없어요. 확실한 것은 1596년 영국 식물학자 존 제라드가 자기 정원 목록에 이미 이 이름을 적어 두었다는 사실뿐이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"britannica.com\",\"sourceUrl\":\"https://www.britannica.com/plant/sweet-William-plant\"}]},\"6-11\":{\"photo\":{\"src\":\"/birth/junggukpaemo.jpg\",\"thumbSrc\":\"/birth/thumbs/junggukpaemo.jpg\",\"author\":\"titanium22\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fritillaria_verticillata_var._thunbergii.jpg\",\"familyLine\":\"연둣빛 종이 아래를 보고 달리고, 안쪽에는 그물 무늬가 있어요.\"},\"stories\":[{\"id\":\"bstory-fritillaria-zhejiang-eight\",\"title\":\"저장의 여덟 약재 가운데 하나\",\"hook\":\"절패모는 중국 저장성이 자랑하는 여덟 약재에 들어가요.\",\"body\":\"중국패모의 비늘줄기를 말린 것을 절패모라 불러요. 중국에서는 저장성이 내는 이름난 약재 여덟 가지, 이른바 절팔미에 이 약재가 들어가요. 기침을 멎게 하고 가래를 삭이는 약으로 오래 쓰였고, 한국에서는 절패모, 일본에서는 세쓰바이모라 불러요. 같은 패모라도 산지에 따라 성질이 다르다고 보아 중국에서는 사천패모와 절패모를 따로 나누어 써요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6479889/\"},{\"id\":\"bstory-fritillaria-medicine-and-poison\",\"title\":\"약과 독이 한 뿌리에 있어요\",\"hook\":\"이 약재의 효능과 독성은 같은 성분에서 나와요.\",\"body\":\"현대 연구는 절패모에서 진해와 거담, 항염을 비롯한 열세 가지 약리작용을 확인했어요. 그런데 그 작용을 만드는 것은 대부분 알칼로이드 계열 성분이고, 같은 성분이 양이 넘치면 독으로 돌아서요. 그래서 이 약재를 다루는 논문들은 효능만큼이나 독성과 체내 대사를 함께 다뤄요. 오래 쓰였다는 사실이 안전하다는 뜻은 아니라는 것을, 이 뿌리가 조용히 알려 줘요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6479889/\"}]},\"6-12\":{\"photo\":{\"src\":\"/birth/rejeda-odorata.jpg\",\"thumbSrc\":\"/birth/thumbs/rejeda-odorata.jpg\",\"author\":\"Salicyna\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Reseda_odorata_2019-06-18_2335.jpg\",\"familyLine\":\"빛깔은 수수한데 향이 진해서 오래 향수 원료로 쓰였어요.\"},\"stories\":[{\"id\":\"bstory-mignonette-napoleon-myth\",\"title\":\"나폴레옹이 보냈다는 이야기의 진위\",\"hook\":\"나폴레옹이 이집트에서 조제핀에게 보낸 꽃이라는 말이 있어요.\",\"body\":\"레제다 오도라타에는 나폴레옹이 1798년 이집트 원정에서 씨앗을 조제핀에게 보냈다는 이야기가 따라다녀요. 북아프리카에 야생으로 자라는 풀이니 그럴듯하게 들려요. 그런데 이 꽃은 이미 1742년 파리에서 기르던 기록이 있어요. 원정보다 반세기 이른 셈이라 이야기 자체는 성립하지 않아요. 다만 식물을 좋아한 조제핀이 말메종 정원에서 이 꽃을 길렀다는 것은 사실로 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"hartley-botanic.com\",\"sourceUrl\":\"https://hartley-botanic.com/magazine/mignonette/\"},{\"id\":\"bstory-mignonette-paris-balcony\",\"title\":\"파리의 발코니를 뒤덮은 향기\",\"hook\":\"19세기 파리 아파트 발코니는 이 꽃 화분으로 가득했어요.\",\"body\":\"프랑스어 미뇨네트는 '작은 귀염둥이'라는 뜻이에요. 이름처럼 꽃은 수수한데 향이 유난히 좋아서, 19세기 파리에서는 발코니와 테라스를 이 화분으로 채우는 일이 유행했어요. 발코니 하나가 통째로 미뇨네트 화분으로 덮인 경우도 있었다고 해요. 빅토리아 시대 영국에서도 실내에 두고 향을 내는 화분 꽃으로 자리 잡았어요. 눈이 아니라 코로 기르던 꽃이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"motherearthgardener.com\",\"sourceUrl\":\"https://www.motherearthgardener.com/plant-profiles/grow-mignonette-zm0z18uzsphe/\"}]},\"6-13\":{\"photo\":{\"src\":\"/birth/digitalriseu.jpg\",\"thumbSrc\":\"/birth/thumbs/digitalriseu.jpg\",\"author\":\"Godot13\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Purple_Foxglove_%28Digitalis_purpurea%29_2008_02.jpg\",\"familyLine\":\"종 모양 꽃이 한쪽으로만 줄지어 달리고, 안쪽에 점무늬가 박혀 있어요.\"},\"stories\":[{\"id\":\"bstory-foxglove-withering-1785\",\"title\":\"슈롭셔의 노파에게서 배운 처방\",\"hook\":\"심장약 디기탈리스는 민간요법에서 출발했어요.\",\"body\":\"1775년 무렵 영국 의사 윌리엄 위더링은 슈롭셔의 한 노파가 부종을 고친다는 약초 처방을 쓴다는 이야기를 들었어요. 스무 가지 넘는 재료가 섞인 처방에서 그는 식물학 지식으로 핵심을 짚어 냈어요. 디기탈리스 푸르푸레아, 곧 디기탈리스였어요. 그는 10년 동안 158명의 환자 기록을 모아 1785년 디기탈리스에 관하여를 펴냈어요. 근대 심장약의 출발점으로 꼽히는 책이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/24886/pg24886-images.html\"},{\"id\":\"bstory-foxglove-mother-hutton\",\"title\":\"이름 없던 노파에게 붙은 가짜 이름\",\"hook\":\"'마더 허튼'은 1920년대 광고가 만든 인물이에요.\",\"body\":\"위더링은 그 노파의 이름을 남기지 않았어요. 그런데 1920년대에 한 제약회사가 디기탈리스 계열 약을 팔면서 광고에 '마더 허튼'이라는 노파를 등장시켰어요. 이름도 얼굴도 만들어 낸 것이었는데, 그 뒤로 이 이름이 실존 인물처럼 여러 글에 옮겨 다녔어요. 지금은 광고가 만든 허구라는 것이 정리됐지만, 정작 진짜 노파의 이름은 끝내 알 수 없게 되었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"barber.org.uk\",\"sourceUrl\":\"https://barber.org.uk/reclaiming-the-foxglove-2/\"}]},\"6-14\":{\"photo\":{\"src\":\"/birth/ttukkeongbyeolkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/ttukkeongbyeolkkot.jpg\",\"author\":\"Hans Hillewaert\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Anagallis_arvensis_%28habitus%29.jpg\",\"familyLine\":\"파란 별 같은 꽃이 흐린 날에는 아예 문을 닫아버려요.\"},\"stories\":[{\"id\":\"bstory-anagallis-weatherglass\",\"title\":\"가난한 사람의 기압계\",\"hook\":\"이 꽃은 하늘이 흐려지면 문을 닫아요.\",\"body\":\"뚜껑별꽃에는 '가난한 사람의 기압계', '양치기의 시계' 같은 별명이 붙어 있어요. 해가 구름에 가리거나 공기가 서늘해지면 꽃잎을 오므리고, 해가 다시 나면 연다는 성질 때문이에요. 맑은 날에도 오후 네 시쯤이면 닫혀요. 기압을 재는 도구가 귀하던 시절에는 밭 가장자리의 이 작은 붉은 꽃이 하늘을 읽는 눈금 노릇을 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mdc.mo.gov\",\"sourceUrl\":\"https://mdc.mo.gov/discover-nature/field-guide/scarlet-pimpernel-poor-mans-weatherglass\"},{\"id\":\"bstory-anagallis-scarlet-pimpernel\",\"title\":\"소설 속 의인이 남긴 작은 붉은 꽃\",\"hook\":\"프랑스 혁명기를 배경으로 한 소설의 주인공이 이 꽃을 표식으로 삼았어요.\",\"body\":\"1905년 오르치 남작부인이 낸 소설 스칼렛 핌퍼넬은 프랑스 혁명기 파리에서 단두대로 끌려갈 사람들을 몰래 구해 내는 영국 귀족의 이야기예요. 그는 정체를 감춘 채 남기는 편지 끝에 작고 붉은 꽃 한 송이만 그려 두었어요. 그 꽃이 뚜껑별꽃, 영어로 스칼렛 핌퍼넬이에요. 밭 가장자리에 흔한, 아무도 눈여겨보지 않는 꽃이라는 점이 정체를 감춘 인물의 표식으로 꼭 맞았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/ebooks/60\"}]},\"6-15\":{\"stories\":[]},\"6-16\":{\"photo\":{\"src\":\"/birth/tyuberojeu.jpg\",\"thumbSrc\":\"/birth/thumbs/tyuberojeu.jpg\",\"author\":\"JDP90 (Joydeep)\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Polianthes_tuberosa%2C_Burdwan%2C_West_Bengal%2C_India_31_01_2013.jpg\",\"familyLine\":\"해가 지고 나서야 향이 짙어지는 흰 꽃이에요.\"},\"stories\":[{\"id\":\"bstory-tuberose-omixochitl\",\"title\":\"아즈텍이 '뼈꽃'이라 부른 꽃\",\"hook\":\"튜베로즈의 나우아틀어 이름은 '뼈의 꽃'이에요.\",\"body\":\"튜베로즈는 멕시코 원산이에요. 아즈텍 사람들은 이 꽃을 오믹소치틀이라 불렀는데, 오미틀(뼈)과 소치틀(꽃)이 합쳐진 말이에요. 크림색에 가까운 흰빛과 굵은 꽃대를 뼈에 빗댄 이름으로 봐요. 꽃과 아름다움, 사랑의 여신 소치케찰에게 바치던 꽃이기도 했어요. 스페인어로도 '플로르 데 우에소', 곧 뼈꽃이라 불렸어요. 지금은 야생 개체가 발견되지 않아, 오래전에 완전히 재배화된 식물로 봐요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"link.springer.com\",\"sourceUrl\":\"https://link.springer.com/article/10.1007/BF02872987\"},{\"id\":\"bstory-tuberose-night-scent\",\"title\":\"밤에 진해지는 향\",\"hook\":\"튜베로즈는 해가 지고 나서 향이 가장 짙어져요.\",\"body\":\"튜베로즈는 유럽에 건너간 뒤 향료 식물로 자리 잡았어요. 1632년 카푸친회 수사 테오필 미뉘티가 프로방스에 들여왔다고 전해지고, 17세기부터 향수 원료로 증류됐어요. 이 꽃은 밤에 향이 짙어지는데 그 강도가 상당해서, 유럽에서는 젊은 여성이 밤에 튜베로즈 정원을 거니는 것을 말리는 말까지 돌았어요. '위험한 쾌락'이라는 꽃말은 이 평판을 그대로 물려받은 자리예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"premierepeau.com\",\"sourceUrl\":\"https://premierepeau.com/blogs/news/tuberose-night-blooming-flower-perfumery\"}]},\"6-17\":{\"photo\":{\"src\":\"/birth/tokkipul.jpg\",\"thumbSrc\":\"/birth/thumbs/tokkipul.jpg\",\"author\":\"Supportstorm\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Trifolium_repens_flower_April_2_2010.jpg\",\"familyLine\":\"작은 나비 모양 꽃 수십 개가 모여 하나의 공처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-clover-dinely-1681\",\"title\":\"성 패트릭 축일에 세 잎 풀을 다는 관습의 첫 기록\",\"hook\":\"1681년 영국인 여행자가 그 관습을 처음 적었어요.\",\"body\":\"성 패트릭이 세 잎 풀로 삼위일체를 설명했다는 이야기는 널리 알려져 있지만, 정작 그 관습이 문서에 처음 나타나는 것은 1681년이에요. 아일랜드를 여행한 영국인 토머스 디닐리가 3월 17일에 사람들이 세 잎 풀 샴로그를 미신처럼 달고, 숨결이 향기로워진다며 그것을 먹기도 한다고 적었어요. 삼위일체 설명 자체가 기록에 등장하는 것은 그보다도 나중이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"greennews.ie\",\"sourceUrl\":\"https://greennews.ie/the-history-of-the-shamrock-from-saint-patrick-to-campions-wild-irish-to-rebellion-and-nationhood/\"},{\"id\":\"bstory-clover-four-leaf-gene\",\"title\":\"네 잎이 되는 유전자를 찾아냈어요\",\"hook\":\"2010년 연구진이 네 잎 클로버를 만드는 유전자를 짚어 냈어요.\",\"body\":\"2010년 미국 조지아대의 웨인 패럿 연구진이 흰토끼풀에서 네 잎을 만드는 형질의 유전자 위치를 분자 표지로 짚어 냈어요. 잎에 붉은 무늬가 생기는 형질의 유전자도 함께 찾았고요. 흥미로운 것은 유전자가 있어도 네 잎이 늘 나오지는 않는다는 점이에요. 패럿의 말대로 햇빛이나 온도가 맞지 않으면 그냥 세 잎으로 자라요. 유전자와 환경이 어떻게 맞물리는지는 아직 다 풀리지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"news.uga.edu\",\"sourceUrl\":\"https://news.uga.edu/four-leaf-clover-spotting/\"}]},\"6-18\":{\"photo\":{\"src\":\"/birth/baekrihyang.jpg\",\"thumbSrc\":\"/birth/thumbs/baekrihyang.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Thymus_quinquecostatus_%28flower%29.JPG\",\"familyLine\":\"바위 위를 낮게 덮고, 스치기만 해도 향이 올라와요.\"},\"stories\":[{\"id\":\"bstory-thyme-roman-courage\",\"title\":\"병사에게 건네던 풀\",\"hook\":\"로마 병사는 용기를 얻으려 백리향 물에 몸을 담갔어요.\",\"body\":\"로마에서 백리향은 용기의 풀로 통했어요. 병사들은 싸움에 나가기 전 백리향을 우린 물에 몸을 담갔고, 떠나는 이에게 백리향 가지를 건네는 관습은 중세까지 이어졌다고 전해져요. 이 연결에는 말의 힘도 있었어요. 그리스어 티모스는 '용기, 기개'를 뜻하는 말이기도 했거든요. 향이 세고 오래가는 풀이 담대함의 상징이 되는 데는 그리 긴 설명이 필요하지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"endeavour.edu.au\",\"sourceUrl\":\"https://www.endeavour.edu.au/about-us/blog/the-fascinating-life-of-thyme\"},{\"id\":\"bstory-thyme-smoke-and-embalming\",\"title\":\"연기에서 온 이름\",\"hook\":\"백리향의 이름은 '연기를 피우다'에서 왔다는 설이 유력해요.\",\"body\":\"백리향의 영어 이름 thyme은 그리스어 티모스에서 왔는데, 이 말의 뿌리에는 '연기를 피우다'라는 뜻이 있어요. 고대 그리스 신전에서 이 풀을 태워 향을 올렸기 때문으로 봐요. 이집트에서는 쓰임이 더 실제적이었어요. 시신이 상하지 않게 하려고 백리향 기름으로 씻거나 관에 잎을 넣었어요. 지금은 부엌의 허브지만, 오래도록 이 풀이 놓인 자리는 제단과 무덤 쪽이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이집트\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"backthenhistory.com\",\"sourceUrl\":\"https://www.backthenhistory.com/articles/the-history-of-thyme\"}]},\"6-19\":{\"stories\":[]},\"6-20\":{\"photo\":{\"src\":\"/birth/kkoripul.jpg\",\"thumbSrc\":\"/birth/thumbs/kkoripul.jpg\",\"author\":\"Oleg Kosterin\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Veronica_linariifolia_91987120.jpg\",\"familyLine\":\"가는 잎 위로 연보랏빛 꽃이 꼬리처럼 길게 서요.\"},\"stories\":[{\"id\":\"bstory-veronica-vera-icon\",\"title\":\"'참된 형상'이라는 이름\",\"hook\":\"베로니카는 라틴어로 '참된 형상'이라는 뜻이에요.\",\"body\":\"꼬리풀속의 학명 Veronica는 라틴어 vera(참된)와 icon(형상)이 합쳐진 말, 곧 '참된 형상'에서 왔다고 봐요. 성 베로니카가 십자가를 지고 가던 그리스도에게 수건을 건넸고 그 수건에 얼굴이 찍혔다는 이야기에서 나온 말이에요. 중세 유럽에서 이 '베로니카의 수건'은 그리스도의 참모습을 담은 것으로 여겨졌어요. 꽃 가운데의 무늬가 그 수건에 찍힌 얼굴처럼 보인다고 해서 붙은 이름이라고 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"first-nature.com\",\"sourceUrl\":\"https://www.first-nature.com/flowers/veronica-chamaedrys.php\"},{\"id\":\"bstory-veronica-speedwell\",\"title\":\"'잘 가라'는 뜻의 이름\",\"hook\":\"영어 이름 speedwell은 작별 인사에서 왔어요.\",\"body\":\"꼬리풀의 영어 이름 speedwell은 '잘 가라, 무사히 가라'는 옛 인사말이에요. 두 갈래 설명이 전해져요. 하나는 이 풀을 달여 마시면 빨리 낫는다고 여겼기 때문이고, 다른 하나는 길가에서 이 꽃을 보면 여행길이 순조로워진다는 믿음 때문이에요. 실제로 꺾어 들면 꽃잎이 금세 떨어져 버리는 성질도 이 이름과 함께 이야기되곤 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"atozflowers.com\",\"sourceUrl\":\"https://www.atozflowers.com/flower/veronica/\"}]},\"6-21\":{\"photo\":{\"src\":\"/birth/dalmatikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/dalmatikkot.jpg\",\"author\":\"Christian Ferrer\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Oenothera_biennis%2C_Vic-la-Gardiole_01.jpg\",\"familyLine\":\"해가 넘어가야 꽃잎을 열고, 아침이면 시들어요.\"},\"stories\":[{\"id\":\"bstory-eveningprimrose-mutation-word\",\"title\":\"'돌연변이'라는 말이 태어난 공터\",\"hook\":\"네덜란드의 버려진 밭에서 유전학 용어 하나가 생겼어요.\",\"body\":\"1886년 네덜란드 힐베르쉼 근처, 농사를 짓다 버려진 땅에 달맞이꽃이 잔뜩 자라 있었어요. 식물학자 휘호 더프리스는 그 무리 안에 확연히 다른 개체들이 섞여 있는 것을 보았어요. 그는 이렇게 갑자기 나타나 대물림되는 변화를 뮈타치라고 불렀고, 이 말이 지금의 '돌연변이'예요. 그는 5만 4343개체에서 834건의 변이를 헤아렸다고 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"lindahall.org\",\"sourceUrl\":\"https://www.lindahall.org/about/news/scientist-of-the-day/hugo-de-vries/\"},{\"id\":\"bstory-eveningprimrose-mendel-rediscovery\",\"title\":\"멘델을 다시 찾아낸 세 사람 중 하나\",\"hook\":\"잊혀 있던 멘델의 법칙은 1900년에 세 사람이 동시에 되찾았어요.\",\"body\":\"더프리스는 달맞이꽃을 비롯한 여러 식물로 교배 실험을 이어 가다가 1900년, 오래 잊혀 있던 멘델의 유전 법칙에 이르렀어요. 같은 해 카를 코렌스와 에리히 체르마크도 각자 같은 결론에 닿았어요. 세 사람의 동시 재발견이 멘델의 논문을 다시 세상에 올려놓았고, 유전학이라는 분야가 그 시점부터 본격적으로 굴러가기 시작했어요. 그 출발점 한 축에 밤에 피는 이 노란 꽃이 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encyclopedia.com\",\"sourceUrl\":\"https://www.encyclopedia.com/people/science-and-technology/botany-biographies/hugo-de-vries\"}]},\"6-22\":{\"photo\":{\"src\":\"/birth/gamaksalnamu-0622.jpg\",\"thumbSrc\":\"/birth/thumbs/gamaksalnamu-0622.jpg\",\"author\":\"Cossey25\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Erie_Linden_Viburnum_Viburnum_dilatatum_%E2%80%98Erie%E2%80%99_leaves_summer_flower.jpg\",\"familyLine\":\"흰 꽃이 접시처럼 평평하게 모여 피고, 가을엔 붉은 열매만 남아요.\"},\"stories\":[{\"id\":\"bstory-viburnum-crow-rice\",\"title\":\"까마귀가 먹는 쌀이라는 이름\",\"hook\":\"가막살나무의 이름에는 까마귀가 들어 있다고 해요.\",\"body\":\"가막살나무라는 이름의 유래로 가장 널리 알려진 설은 촘촘하게 모여 피는 흰 꽃봉오리가 '까마귀가 먹는 쌀'처럼 보인다는 거예요. 다른 설도 있어요. '가막'이 검은색을 뜻하는 말이라, 줄기와 가지의 빛이 가무잡잡해서 붙었다는 이야기예요. 어느 쪽도 확정된 것은 없고 두 설이 나란히 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"atlasnews.co.kr\",\"sourceUrl\":\"http://www.atlasnews.co.kr/news/articleView.html?idxno=8867\"},{\"id\":\"bstory-viburnum-red-berries\",\"title\":\"붉게 익지만 새가 잘 먹지 않아요\",\"hook\":\"이름과 달리 새들은 이 열매를 그리 좋아하지 않아요.\",\"body\":\"가막살나무는 10월쯤 달걀 모양 열매가 붉게 익어요. 신맛이 도는데 사람이 먹을 수는 있어요. 이름이 새와 얽혀 있는데도 정작 새들은 이 열매를 그리 즐겨 먹지 않는다고 알려져 있어요. 그래서 겨울까지 가지에 붉은 열매가 남아 있는 모습을 흔히 볼 수 있어요. 관상수로 정원에 심고 울타리로도 쓰는 이유가 여기에 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"위키백과\",\"sourceUrl\":\"https://ko.wikipedia.org/wiki/%EA%B0%80%EB%A7%89%EC%82%B4%EB%82%98%EB%AC%B4\"},{\"id\":\"bstory-viburnum-otzi-arrow-shafts\",\"title\":\"외치의 화살통 속 나무\",\"hook\":\"알프스 빙하에서 나온 미라의 화살통에 가막살나무 가지가 들어 있었어요.\",\"body\":\"알프스 빙하에서 발견된 미라 외치는 도구 일습을 그대로 지니고 있었어요. 그중 화살통에는 아직 완성되지 않은 화살대 열두 개와, 부싯돌 촉을 단 완성된 화살 두 개가 들어 있었어요. 이 화살대를 만든 나무가 가막살나무속의 비부르눔 란타나와 층층나무였어요. 함께 나온 활은 주목을 깎다 만 것으로 길이가 1.82미터였고, 구리 도끼의 자루도 주목이었어요. 도끼 날은 순도 99.7퍼센트의 구리였고요. 부싯돌 단검의 손잡이는 물푸레나무, 칼집은 참피나무 속껍질이었어요. 나무마다 성질을 따져 용도를 갈라 쓴 흔적이 도구 전체에 남아 있고, 화살대에 가막살나무 가지를 고른 것도 그 선택 중 하나예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"알프스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"iceman.it\",\"sourceUrl\":\"https://www.iceman.it/en/equipment/\"},{\"id\":\"bstory-viburnum-kalyna\",\"title\":\"붉은 칼리나의 노래\",\"hook\":\"1914년 시치 소총병의 노래가 2022년 다시 우크라이나 저항의 상징이 됐어요.\",\"body\":\"우크라이나에서 칼리나, 곧 붉은 가막살나무 열매는 오래된 상징이에요. 민요가 이 열매의 이미지로 문을 연 다음 은유와 정치 이야기로 넘어가곤 했다고 음악인류학자 마리아 소네비츠키는 설명해요. 1914년 가사로 만들어진 노래 오, 초원의 붉은 칼리나는 1차 세계대전 때 오스트리아-헝가리군 안에 편성된 우크라이나 부대, 시치 소총병과 단단히 묶여 있었죠. 소련 시절에는 지나치게 민족주의적이라는 이유로 금지돼 1980년대 말까지 거의 불리지 않았고요. 2022년 2월 러시아의 전면 침공 뒤 붐박스의 안드리 흘리브뉴크가 부른 영상이 퍼졌고, 그해 11월 헤르손이 해방됐을 때 시민들은 이 노래를 목청껏 불렀어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"우크라이나\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theworld.org\",\"sourceUrl\":\"https://theworld.org/stories/2022/12/01/chervona-kalyna-ukrainian-song-has-become-symbol-freedom-and-resilience\"}]},\"6-23\":{\"photo\":{\"src\":\"/birth/jeopsikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/jeopsikkot.jpg\",\"author\":\"PJDespa\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Alcea_rosea_purple.jpg\",\"familyLine\":\"곧게 선 줄기를 따라 접시만 한 꽃이 아래에서 위로 올라가며 펴요.\"},\"stories\":[{\"id\":\"bstory-hollyhock-holy-hoc\",\"title\":\"'거룩한 아욱'이라는 이름\",\"hook\":\"hollyhock의 holly는 호랑가시나무가 아니라 '거룩한'이에요.\",\"body\":\"접시꽃의 영어 이름 hollyhock에서 hoc은 앵글로색슨어로 아욱을 뜻하는 말이었어요. 앞의 holly는 호랑가시나무가 아니라 holy, 곧 '거룩한'에서 왔다고 봐요. 십자군이 성지에서 가져온 아욱이라는 뜻이에요. 16세기 약초학자 윌리엄 터너가 이 꽃을 holyoke라 적은 기록이 남아 있어요. 원산은 중국 서남부 쪽이고, 실크로드와 지중해를 거쳐 유럽에 닿은 것으로 봐요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"uaex.uada.edu\",\"sourceUrl\":\"https://www.uaex.uada.edu/yard-garden/resource-library/plant-week/hollyhock.aspx\"},{\"id\":\"bstory-hollyhock-tokugawa-aoi\",\"title\":\"도쿠가와 가문의 문장은 접시꽃이 아니에요\",\"hook\":\"'세 잎 접시꽃'이라 번역돼 온 그 문장은 사실 족도리풀이에요.\",\"body\":\"일본 도쿠가와 가문의 문장은 영어권에서 오래 '세 잎 접시꽃'으로 옮겨졌어요. 그런데 그 문장의 아오이는 접시꽃이 아니라 후타바아오이, 곧 쥐방울덩굴과의 족도리풀 종류예요. 교토 가모 신사의 문장에서 온 도안이고, 가모 씨족과 인연이 깊던 미카와의 무사단이 쓰던 것을 마쓰다이라와 도쿠가와 가문이 물려받았다고 봐요. 게다가 실제 후타바아오이는 잎이 두 장인데 문장은 세 장이에요. 번역 한 번이 오래도록 다른 꽃을 가리킨 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"japanesewiki.com\",\"sourceUrl\":\"https://www.japanesewiki.com/culture/Mitsuba-aoi%20(Three%20Leaves%20of%20Hollyhock).html\"}]},\"6-24\":{\"photo\":{\"src\":\"/birth/beobena.jpg\",\"thumbSrc\":\"/birth/thumbs/beobena.jpg\",\"author\":\"Jwitos\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Verbena_hybrida_2.JPG\",\"familyLine\":\"작은 꽃이 둥글게 모여 한 송이처럼 보이고, 색이 아주 진해요.\"},\"stories\":[{\"id\":\"bstory-verbena-herba-sacra\",\"title\":\"제단을 쓸던 풀\",\"hook\":\"로마 사람들은 버베나를 '거룩한 풀'이라 불렀어요.\",\"body\":\"그리스에서는 버베나를 히에로보타네, 로마에서는 헤르바 사크라라 불렀어요. 둘 다 '거룩한 풀'이라는 뜻이에요. 로마 사제들은 이 풀을 묶어 빗자루를 만들어 제단을 쓸었고, 정화 의식 루스트라티오에 썼어요. 플리니우스는 로마인이 이 흔한 풀보다 더 높이 대접한 식물이 없다고 적으면서, 이것으로 유피테르의 상을 쓸고 집을 정하게 한다고 남겼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"blog.metmuseum.org\",\"sourceUrl\":\"https://blog.metmuseum.org/cloistersgardens/2011/07/01/holy-vervain/\"},{\"id\":\"bstory-verbena-druid-herb\",\"title\":\"드루이드의 네 가지 풀 가운데 하나\",\"hook\":\"플리니우스는 드루이드가 이 풀을 쓴다고 적었어요.\",\"body\":\"플리니우스는 박물지에서 버베나를 당대 드루이드가 쓰던 네 가지 성스러운 식물 가운데 하나로 적었어요. 켈트 전승에서는 한여름에, 달빛이 없는 밤에 이 풀을 거두어야 힘이 온전하다고 여겼다고 전해져요. 로마와 켈트가 서로 다른 신을 섬기면서도 같은 풀을 제의 자리에 놓았다는 점이 눈에 띄어요. 이름난 신전에서든 숲속 모닥불 곁에서든, 사람들은 이 수수한 풀을 손에 들었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"healthyhildegard.com\",\"sourceUrl\":\"https://www.healthyhildegard.com/vervain/\"}]},\"6-25\":{\"photo\":{\"src\":\"/birth/napalkkot.jpg\",\"thumbSrc\":\"/birth/thumbs/napalkkot.jpg\",\"author\":\"Bff\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ipomoea_nil_Gorlitsa20230530_20214.jpg\",\"familyLine\":\"새벽에 나팔을 열고 한낮이면 다시 오므려요.\"},\"stories\":[{\"id\":\"bstory-morningglory-henka-asagao\",\"title\":\"에도의 나팔꽃 광풍\",\"hook\":\"에도 사람들은 '이상하게 생긴' 나팔꽃에 열광했어요.\",\"body\":\"일본 에도 후기에 나팔꽃 유행이 두 차례 크게 일었어요. 분카와 분세이 연간(1804~1830), 그리고 가에이와 안세이 연간(1848~1860)이에요. 사람들이 찾은 것은 잘생긴 꽃이 아니라 헨카아사가오, 곧 변이 나팔꽃이었어요. 꽃잎이 국화처럼 갈라지거나 잎이 벚잎을 닮거나 덩굴이 이상하게 꼬인 개체를 귀하게 쳤어요. 이 유행은 메이지 유신 뒤의 혼란기에 한 번 사그라들었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ndl.go.jp\",\"sourceUrl\":\"https://www.ndl.go.jp/en/imagebank/column/asagao\"},{\"id\":\"bstory-morningglory-banzuke\",\"title\":\"스모처럼 순위를 매겼어요\",\"hook\":\"나팔꽃 품평회 결과는 스모 순위표 형식으로 인쇄됐어요.\",\"body\":\"에도의 나팔꽃 유행은 하나아와세라는 품평회로 굴러갔어요. 절이나 동네 마당에서 재배자들이 변이 나팔꽃을 늘어놓으면 등급을 매겼고, 그 결과를 스모의 순위표 반즈케와 똑같은 형식으로 한 장에 찍어 돌렸어요. 아침에 피었다가 낮이면 시드는 꽃을 두고 씨름꾼처럼 서열을 세운 셈이에요. 그 인쇄물과 도보가 남아 지금도 당시 품종을 확인할 수 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"sainsbury-institute.org\",\"sourceUrl\":\"https://www.sainsbury-institute.org/library-treasures/morning-glories-and-edo-period-japan/\"}]},\"6-26\":{\"photo\":{\"src\":\"/birth/huin-railrak.jpg\",\"thumbSrc\":\"/birth/thumbs/huin-railrak.jpg\",\"author\":\"Екатерина Борисова\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:%D0%9F%D1%80%D0%B8%D0%BC%D0%BE%D1%80%D1%81%D0%BA%D0%B8%D0%B9_%D0%BF%D0%B0%D1%80%D0%BA_%D0%9F%D0%BE%D0%B1%D0%B5%D0%B4%D1%8B%2C_%D1%81%D0%B8%D1%80%D0%B5%D0%BD%D1%8C_04.jpg\",\"familyLine\":\"흰 라일락은 색이 없는 대신 향이 더 크게 느껴져요.\"},\"stories\":[]},\"6-27\":{\"photo\":{\"src\":\"/birth/sigyekkot.jpg\",\"thumbSrc\":\"/birth/thumbs/sigyekkot.jpg\",\"author\":\"Petar Milošević\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Passiflora_caerulea_%28makro_close-up%29.jpg\",\"familyLine\":\"실 같은 부화관이 시계 눈금처럼 둘러서서 시계꽃이라 불려요.\"},\"stories\":[{\"id\":\"bstory-passionflower-five-wounds\",\"title\":\"수사가 꽃 안에서 읽은 수난\",\"hook\":\"시계꽃의 이름은 그리스도의 수난에서 왔어요.\",\"body\":\"1610년 멕시코의 아우구스티노회 수사 에마누엘 데 비예가스가 이 꽃의 구조에서 그리스도의 수난 장면을 읽어 내고, 스케치를 곁들여 유럽에 보고했어요. 실처럼 갈라진 일흔두 가닥의 부화관은 가시관, 위쪽의 세 암술머리는 세 개의 못, 그 아래 다섯 수술은 다섯 상처, 감아 오르는 덩굴손은 채찍으로 보았어요. 라틴어로 수난을 뜻하는 passio에서 Passiflora라는 이름이 나왔어요. 한국어 이름 시계꽃은 같은 구조를 시계 문자판으로 본 이름이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아메리카\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"udayton.edu\",\"sourceUrl\":\"https://udayton.edu/marianlibrary/marysgardens/p/passion-flower.php\"},{\"id\":\"bstory-passionflower-maypop\",\"title\":\"버지니아 밭에 흔하던 열매\",\"hook\":\"제임스타운 정착민들은 이 열매를 '마라콕'이라 불렀어요.\",\"body\":\"시계꽃속에는 북아메리카 자생종도 있어요. 1612년 제임스타운 식민지의 서기 윌리엄 스트레이치는 버지니아의 옥수수밭 사이로 덩굴이 기어 다니며 열매가 수레로 실을 만큼 열린다고 적었어요. 알곤킨 사람들은 이 열매를 마라콕이라 불렀고, 존 스미스도 같은 해 기록에 레몬 비슷한 상쾌한 열매로 남겼어요. 원주민은 열매를 생으로 먹거나 졸여 시럽을 만들었고, 뿌리는 종기와 상처에 썼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"historicjamestowne.org\",\"sourceUrl\":\"https://historicjamestowne.org/collections/artifacts/passionflower-seeds/\"}]},\"6-28\":{\"stories\":[]},\"6-29\":{\"stories\":[]},\"6-30\":{\"photo\":{\"src\":\"/birth/indong.jpg\",\"thumbSrc\":\"/birth/thumbs/indong.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lonicera_japonica_%27hall%27s_prolific%27._14-06-2020_%28d.j.b.%29_01.jpg\",\"familyLine\":\"흰 꽃으로 피었다가 며칠 뒤 노랗게 변해, 두 색이 한 가지에 걸려요.\"},\"stories\":[{\"id\":\"bstory-honeysuckle-chevrefoil\",\"title\":\"개암나무 가지에 새긴 이름\",\"hook\":\"트리스탄은 길가의 개암나무 가지에 자기 이름을 새겨 신호를 보냈어요.\",\"body\":\"12세기 마리 드 프랑스가 쓴 브르타뉴 이야기 셰브르푀유, 곧 인동이 있어요. 왕에게 쫓겨난 트리스탄은 이졸데가 지날 길목의 개암나무를 잘라 다듬고 거기에 자기 이름을 새겨 두어요. 이졸데는 그 표시를 알아보고 길에서 벗어나 숲으로 들어와요. 118행짜리 짧은 시이고 두 개의 필사본으로만 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"english.cam.ac.uk\",\"sourceUrl\":\"https://www.english.cam.ac.uk/research/plantlife/tristan-iseults-honeysuckle-hazel-marie-de-frances-chevrefoil-12th-century/\"},{\"id\":\"bstory-honeysuckle-hazel-bond\",\"title\":\"떼어 놓으면 둘 다 죽어요\",\"hook\":\"인동과 개암나무는 서로 없이 살지 못한다고 시는 말해요.\",\"body\":\"인동의 중심에는 짧은 비유 하나가 있어요. 인동이 개암나무 가지를 감고 오르면 둘은 한 몸처럼 자라고, 누군가 억지로 떼어 놓으면 개암나무가 곧 죽고 인동도 따라 죽는다는 거예요. 트리스탄은 이졸데에게 보내는 말로 그 비유를 남겨요. 그대 없이 나 없고 나 없이 그대 없다고요. 시의 제목이 꽃 이름인 이유가 여기에 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"people.clas.ufl.edu\",\"sourceUrl\":\"https://people.clas.ufl.edu/jshoaf/files/chevrefoil.pdf\"}]},\"7-1\":{\"photo\":{\"src\":\"/birth/danyangssukbujaengi.jpg\",\"thumbSrc\":\"/birth/thumbs/danyangssukbujaengi.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Aster_altaicus_kz03.jpg\",\"familyLine\":\"가늘고 긴 잎 위에 연보랏빛 국화꽃이 한 송이씩 앉아요.\"},\"stories\":[{\"id\":\"bstory-danyang-aster-lost-and-found\",\"title\":\"댐에 잠겼다가 다시 발견됐어요\",\"hook\":\"자생지가 물에 잠긴 뒤 20여 년 만에 다시 나타났어요.\",\"body\":\"단양쑥부쟁이는 한국에만 자라는 특산식물이에요. 남한강 가의 자갈과 모래가 섞인 척박한 강변이 삶터였는데, 1980년대 충주댐이 들어서면서 단양과 충주 일대의 자생지가 대부분 물에 잠겼어요. 사라진 줄 알았던 이 풀은 2005년 여주 남한강 일대에서 다시 발견됐어요. 지금은 멸종위기 야생생물 2급으로 지정돼 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bravo.etoday.co.kr\",\"sourceUrl\":\"https://bravo.etoday.co.kr/view/atc_view/9957\"},{\"id\":\"bstory-danyang-aster-dredged-soil\",\"title\":\"준설토 더미에서 다시 싹텄어요\",\"hook\":\"파낸 흙더미 위에서 멸종위기 식물이 자라 있었어요.\",\"body\":\"4대강 사업으로 최대 자생지가 또 한 번 위기를 맞자 강천섬에 대체 서식지를 만들어 옮겨 심는 작업이 이어졌어요. 그런데 2017년에는 뜻밖의 일이 있었어요. 강바닥에서 퍼 올려 쌓아 둔 준설토 더미에서 단양쑥부쟁이가 무리 지어 자라고 있는 것이 확인된 거예요. 물에 잠겨 있던 씨앗이 흙과 함께 올라와 싹을 틔운 셈이에요. 강가의 자갈밭을 고르는 이 풀의 습성이 그대로 드러난 장면이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"khan.co.kr\",\"sourceUrl\":\"https://www.khan.co.kr/article/201709291416001\"},{\"id\":\"bstory-fig-marigold-1937-naming\",\"title\":\"1937년에 이름을 얻은 풀\",\"hook\":\"남한강 자갈밭에만 사는 이 한국 특산 풀은 경쟁이 두려워 척박한 땅을 골랐어요.\",\"body\":\"단양쑥부쟁이는 1937년 일본 식물학자 기타무라 시로가 한반도 특산으로 보고하면서 학명을 얻었어요. 오랫동안 아스테르 알타이쿠스의 변종으로 불렸고, 최근 연구로 아스테르 단양겐시스라는 독립 종명을 갖게 됐어요. 국화과 두해살이풀로 키는 30에서 100센티미터, 잎이 솔잎처럼 가늘어 솔잎국화라고도 불려요. 지름 4센티미터쯤 되는 자주색 두상화를 8월부터 10월에 피우고요. 이 풀이 하필 강변 모래땅과 자갈밭을 고르는 이유는 경쟁에 약하기 때문이에요. 다른 식물과 섞이면 밀리니까 아예 남들이 버티기 힘든 척박한 땅으로 들어간 셈이죠. 지금은 환경부 지정 멸종위기 야생생물 2급이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"newspenguin.com\",\"sourceUrl\":\"https://www.newspenguin.com/news/articleView.html?idxno=18134\"},{\"id\":\"bstory-fig-marigold-gangcheon-island\",\"title\":\"강천섬의 150만 포기\",\"hook\":\"2005년 여주 남한강변에서 최대 군락이 발견됐고 4대강 사업 때 3만 8천 포기가 옮겨졌어요.\",\"body\":\"2005년 경기 여주 남한강변에서 단양쑥부쟁이 최대 군락지가 발견됐어요. 여주 강천면 굴암리의 강천섬을 비롯한 남한강 일대에는 150만여 개체가 사는 것으로 파악됐고요. 이 풀은 두해살이라 두 해째에 어른 허리 높이까지 자라 가을에 꽃을 피우고 죽어요. 척박한 땅을 좋아해서 몇 년에 한 번씩 홍수가 강천섬을 덮쳐 쌓인 모래를 쓸어내고 자갈밭을 다시 만들어 줘야 살아갈 수 있어요. 4대강 사업이 이 서식지를 없앨 거라는 우려가 커지자 정부는 3만 8천여 개체를 대체서식지로 옮겨 심었어요. 그해 4월 9일부터 11일까지 삼합지구에서만 2만 2천 개체가 이식됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"korea.kr\",\"sourceUrl\":\"https://www.korea.kr/news/policyNewsView.do?newsId=148695287\"}]},\"7-2\":{\"photo\":{\"src\":\"/birth/geumeocho.jpg\",\"thumbSrc\":\"/birth/thumbs/geumeocho.jpg\",\"author\":\"Dinesh Valke from Thane, India\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Antirrhinum_majus_%28423941477%29.jpg\",\"familyLine\":\"꽃 옆을 살짝 누르면 입처럼 벌어졌다가 다시 닫혀요.\"},\"stories\":[{\"id\":\"bstory-snapdragon-snout\",\"title\":\"코를 닮았다는 학명 용을 닮았다는 이름\",\"hook\":\"금어초의 학명은 '코를 닮았다'는 뜻이에요.\",\"body\":\"금어초의 속명 Antirrhinum은 그리스어 anti(닮은)와 rhis(코)가 합쳐진 말로 '코를 닮았다'는 뜻이에요. 반면 영어 이름 snapdragon은 꽃의 양옆을 눌렀다 놓으면 입이 용처럼 딱 벌어졌다 닫히는 데서 왔어요. 한국어 이름 금어초는 또 다른 것을 보았어요. 금붕어의 입이에요. 같은 꽃 하나를 두고 세 문화가 각각 코와 용과 물고기를 떠올린 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"flower.style\",\"sourceUrl\":\"https://www.flower.style/flowers-we-love/snapdragon\"},{\"id\":\"bstory-snapdragon-skull-pod\",\"title\":\"꽃이 지면 해골이 남아요\",\"hook\":\"금어초의 마른 씨방은 작은 두개골처럼 생겼어요.\",\"body\":\"금어초는 꽃이 지고 나면 씨방이 마르면서 굳어요. 지름 10~14밀리미터쯤 되는 이 씨방은 눈구멍 두 개와 벌어진 입이 있는 작은 두개골을 그대로 닮았고, 안에 아주 작은 씨앗이 잔뜩 들어 있어요. 화려한 꽃이 진 자리에 해골이 줄줄이 남는 셈이라, 요즘은 이 모습 때문에 가을 장식용으로 일부러 씨방을 남겨 두기도 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Antirrhinum_majus\"}]},\"7-3\":{\"photo\":{\"src\":\"/birth/huinsaek-yanggwibi.jpg\",\"thumbSrc\":\"/birth/thumbs/huinsaek-yanggwibi.jpg\",\"author\":\"Roman Eisele\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Heilbronn_-_B%C3%B6ckingen_-_Friedhof_-_wei%C3%9Fe_Mohnbl%C3%BCte_auf_Grab_%281.1%29.jpg\",\"familyLine\":\"구겨진 종이 같은 흰 꽃잎이 펴지면서 주름을 그대로 남겨요.\"},\"stories\":[{\"id\":\"bstory-whitepoppy-1933\",\"title\":\"전쟁에 가족을 잃은 여자들이 만든 흰 양귀비\",\"hook\":\"1933년 남편과 아들을 잃은 여성들이 흰 양귀비를 만들었어요.\",\"body\":\"1933년 영국 협동조합 여성길드가 흰 양귀비를 처음 만들었어요. 회원 상당수가 1차 세계대전에서 남편과 아버지, 아들과 형제를 잃은 사람들이었어요. 이들은 추모 행사가 점점 군사적으로 흘러가고 붉은 양귀비가 평화를 위한 노력과 멀어지는 것을 걱정했어요. 사무총장 엘리너 바턴은 1918년에 강했던 '다시는'이라는 마음이 해가 갈수록 약해진다고 말했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"thenews.coop\",\"sourceUrl\":\"https://www.thenews.coop/white-poppies-tell-the-story-of-the-alternative-remembrance-day/\"},{\"id\":\"bstory-whitepoppy-three-meanings\",\"title\":\"흰 양귀비가 말하는 세 가지\",\"hook\":\"흰 양귀비에는 세 가지 뜻이 담겨 있어요.\",\"body\":\"1936년부터 평화서약연맹이 흰 양귀비 배포를 맡아 지금까지 이어 오고 있어요. 이 꽃이 말하는 것은 세 가지예요. 군인이든 민간인이든 전쟁으로 죽은 모든 사람을 기억하는 것, 전쟁을 미화하거나 축하하는 일에 반대하는 것, 그리고 평화를 위해 계속 애쓰겠다는 약속이에요. 붉은 양귀비를 대신하려는 것이 아니라 함께 다는 사람도 많아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ppu.org.uk\",\"sourceUrl\":\"https://www.ppu.org.uk/remembrance/white-poppies-frequently-asked-questions\"}]},\"7-4\":{\"stories\":[]},\"7-5\":{\"stories\":[]},\"7-6\":{\"stories\":[]},\"7-7\":{\"photo\":{\"src\":\"/birth/seoyangkkachibapnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/seoyangkkachibapnamu.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ribes_uva-crispa_kz04.jpg\",\"familyLine\":\"가시 돋친 가지 아래로 초록빛 작은 꽃이 조용히 매달려요.\"},\"stories\":[{\"id\":\"bstory-gooseberry-egton-1800\",\"title\":\"1800년부터 이어진 구스베리 품평회\",\"hook\":\"잉글랜드의 한 마을은 220년 넘게 구스베리 무게를 재고 있어요.\",\"body\":\"잉글랜드 노스요크셔의 에그턴브리지에서는 1800년부터 구스베리 품평회가 열려요. 지금 남아 있는 구스베리 품평회 가운데 가장 오래된 것으로, 1900년에는 지역 신문이 100주년 대회라고 보도했어요. 겨루는 항목은 빨강과 노랑, 초록과 흰색 네 빛깔의 가장 무거운 열매, 한 자루에 달린 쌍둥이 열매, 그리고 열두 알 무게예요. 잉글랜드에 남은 구스베리 품평회는 이곳을 빼면 일곱 곳뿐이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"yorkshirepost.co.uk\",\"sourceUrl\":\"https://www.yorkshirepost.co.uk/heritage-and-retro/heritage/egton-bridge-gooseberry-show-2023-quaint-220-year-old-yorkshire-tradition-returns-as-competitors-size-up-their-fruit-4239626\"},{\"id\":\"bstory-gooseberry-same-scales\",\"title\":\"1935년부터 같은 저울을 써요\",\"hook\":\"이 대회는 90년 된 저울로 보리 낟알 단위를 재요.\",\"body\":\"에그턴브리지 대회는 1935년부터 같은 저울을 쓰고 있어요. 단위도 드램과 그레인인데, 그레인은 원래 보리 낟알 하나의 무게에서 나온 옛 단위예요. 1825년 무렵 기록에 남은 우승 무게는 지금의 절반쯤이에요. 200년 동안 사람들이 조금씩 더 굵은 열매를 길러 온 궤적이 같은 저울 위에 그대로 쌓여 있는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"egtongooseberryshow.org.uk\",\"sourceUrl\":\"https://egtongooseberryshow.org.uk/history/\"}]},\"7-8\":{\"photo\":{\"src\":\"/birth/beodeuputeu.jpg\",\"thumbSrc\":\"/birth/thumbs/beodeuputeu.jpg\",\"author\":\"Krzysztof Golik\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lotus_corniculatus_at_Lac_des_Plagnes_%282%29.jpg\",\"familyLine\":\"꼬투리가 새 발가락처럼 갈라져서 그런 이름이 붙었어요.\"},\"stories\":[{\"id\":\"bstory-birdsfoot-many-names\",\"title\":\"별명이 유난히 많은 풀\",\"hook\":\"영국에서 이 풀은 '달걀과 베이컨'이라고 불려요.\",\"body\":\"버드푸트, 곧 벌노랑이는 별명이 유난히 많은 풀이에요. 노른자 같은 노란 꽃과 붉은 기가 도는 꽃봉오리를 보고 '버터와 달걀', '달걀과 베이컨', '암탉과 병아리'라 불렀어요. 이름이 붙은 자리는 꽃만이 아니에요. 씨 꼬투리 여러 개가 한 점에서 갈라져 나오는 모습이 새 발가락을 닮아서 '새발', 좀 더 짓궂게는 '할머니 발톱'이라고도 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"wildlifetrusts.org\",\"sourceUrl\":\"https://www.wildlifetrusts.org/wildlife-explorer/wildflowers/common-birds-foot-trefoil\"},{\"id\":\"bstory-birdsfoot-butterfly-host\",\"title\":\"나비 애벌레의 밥상\",\"hook\":\"이 작은 노란 꽃은 여러 나비의 애벌레가 기대 사는 풀이에요.\",\"body\":\"벌노랑이는 콩과 식물이라 뿌리에 질소를 붙잡아 척박한 땅도 견뎌요. 그 덕에 풀밭 가장자리와 길가에 잘 자라는데, 영국에서는 이 풀이 여러 나비의 애벌레 먹이식물로 중요하게 꼽혀요. 흔하다는 이유로 눈에 잘 안 들어오는 풀이 실제로는 여러 종의 생사를 떠받치고 있는 셈이에요. 별명이 그렇게 많이 붙은 것도 그만큼 사람들 곁에 가까이 있었다는 뜻이고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"first-nature.com\",\"sourceUrl\":\"https://www.first-nature.com/flowers/lotus-corniculatus.php\"}]},\"7-9\":{\"stories\":[]},\"7-10\":{\"photo\":{\"src\":\"/birth/chorongkkot-0710.jpg\",\"thumbSrc\":\"/birth/thumbs/chorongkkot-0710.jpg\",\"author\":\"Yoko Nekonomania\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Flower%2C_Campanula_medium_%22Canterbury_bells%22_-_Flickr_-_nekonomania_%282%29.jpg\",\"familyLine\":\"종처럼 부푼 꽃이 아래를 보고 매달려 흔들려요.\"},\"stories\":[{\"id\":\"bstory-canterburybell-pilgrim-bells\",\"title\":\"순례자의 말방울\",\"hook\":\"캔터베리 벨은 순례길 말목에 달린 방울에서 온 이름이에요.\",\"body\":\"초롱꽃속의 캄파눌라 메디움에는 영어로 '캔터베리 벨'이라는 이름이 붙어 있어요. 캔터베리 대성당의 종을 닮았다는 설도 있지만, 더 자주 이야기되는 것은 순례자의 방울이에요. 토머스 베켓의 성지로 사람들을 실어 나르던 말의 목에 달린 방울이 이 꽃 모양이었다는 거예요. 종처럼 벌어진 꽃 여러 개가 줄기 하나에 달려 흔들리는 모습이 실제로 그렇게 보여요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/campanula-medium/\"},{\"id\":\"bstory-canterburybell-coventry\",\"title\":\"원래 이름은 코번트리 벨이었어요\",\"hook\":\"이 꽃은 한동안 다른 도시의 이름으로 불렸어요.\",\"body\":\"지금은 캔터베리 벨로 통하지만, 16~17세기 영국에서는 이 꽃을 '코번트리 벨'이라 불렀어요. 19세기에 이르러서야 지금의 이름으로 굳었다고 해요. 원산지는 프랑스 남동부와 이탈리아 중북부의 바위 비탈이고, 영국에는 16세기에 들어온 것으로 봐요. 꽃 이름이 도시 하나를 갈아탄 셈인데, 왜 바뀌었는지는 분명하게 남아 있지 않아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"thursd.com\",\"sourceUrl\":\"https://thursd.com/articles/canterbury-bell-flowers\"},{\"id\":\"bstory-campanula-rapunzel\",\"title\":\"라푼젤은 채소 이름이었어요\",\"hook\":\"그림 형제 동화의 라푼젤은 초롱꽃속 채소 캄파눌라 라푼쿨루스에서 온 이름이에요.\",\"body\":\"그림 형제 동화의 라푼젤은 사람 이름이기 전에 채소 이름이었어요. 임신한 아내가 이웃 마녀의 밭에서 훔쳐다 달라고 조른 그 풀, 캄파눌라 라푼쿨루스가 바로 라푼젤이거든요. 초롱꽃속에 속하는 이 식물은 서남아시아부터 중부 유럽, 북아프리카까지 분포하고, 잎은 시금치처럼 데쳐 먹고 순무 닮은 뿌리는 무처럼 썰어 먹었어요. 종소명 라푼쿨루스는 라틴어로 순무를 뜻하는 라파의 축소형이고요. 초롱꽃속에는 500종이 넘는 식물이 있는데 그 가운데 다수가 꽃과 잎과 뿌리를 모두 먹을 수 있어요. 그림 형제가 이 풀에 굳이 설명을 붙이지 않은 것을 보면, 당시 독자들에게 라푼젤은 설명이 필요 없는 흔한 밭작물이었던 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanistinthekitchen.blog\",\"sourceUrl\":\"https://botanistinthekitchen.blog/2015/01/13/rapunzel/\"},{\"id\":\"bstory-campanula-throatwort-signature\",\"title\":\"종탑 속 박쥐라 불린 꽃\",\"hook\":\"종소명 트라켈리움은 그리스어로 목을 뜻하고, 실제로 목 아픈 데 썼어요.\",\"body\":\"초롱꽃속의 캄파눌라 트라켈리움은 영어로 스로트워트, 그러니까 목풀이라고 불려요. 종소명 트라켈리움은 그리스어 트라켈로스, 곧 목에서 온 말이에요. 실제로 이 식물이 인후통을 낫게 한다고 믿던 시절이 있었어요. 생김새가 그 식물의 쓰임을 알려 준다는 약징주의의 사고방식이 이름과 약효를 한 덩어리로 묶어 놓은 거예요. 같은 식물에는 종탑 속 박쥐라는 별명도 붙어 있어요. 종 모양 꽃 안에 늘어선 수술이 종루에 매달린 박쥐처럼 보였기 때문이에요. 속명 캄파눌라 자체가 라틴어 캄파나, 곧 종에서 온 이름이고요. 유럽과 중앙아시아, 지중해에서 이란까지가 원산이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/campanula-trachelium/\"}]},\"7-11\":{\"photo\":{\"src\":\"/birth/aseupodel.jpg\",\"thumbSrc\":\"/birth/thumbs/aseupodel.jpg\",\"author\":\"Javier martin\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Asphodelus_albus_FlowersCloseup_2009March28_SierraMadrona.jpg\",\"familyLine\":\"마른 땅에서 흰 별 같은 꽃이 층층이 올라가요.\"},\"stories\":[{\"id\":\"bstory-asphodel-meadow\",\"title\":\"대부분의 사람이 가는 곳\",\"hook\":\"그리스 사람들은 저승의 대부분이 아스포델 들판이라고 생각했어요.\",\"body\":\"호메로스의 오디세이아 11권에서 오디세우스는 저승에 내려가 죽은 이들을 만나요. 아킬레우스가 그와 말을 마치고 걸어 나가는 곳이 아스포델 들판이에요. 엘리시온처럼 상을 받는 곳도, 타르타로스처럼 벌을 받는 곳도 아닌, 특별히 훌륭하지도 악하지도 않았던 대부분의 사람이 머무는 자리였어요. 밝지도 어둡지도 않은 그 들판을 채운 것이 이 창백한 꽃이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/1727/1727-h/1727-h.htm\"},{\"id\":\"bstory-asphodel-grave-plant\",\"title\":\"무덤가에 심던 꽃\",\"hook\":\"아스포델은 무덤에 심는 꽃이었어요.\",\"body\":\"아스포델이 저승과 묶인 데는 실제 풍습이 있었어요. 고대 지중해에서 이 풀은 무덤에 심는 꽃이었고, 무덤가에 절로 자라는 모습이 자주 눈에 띄었어요. 죽은 이에게 어울리는 풀이라는 인상이 거기서 왔어요. 꽃 빛깔도 한몫했어요. 희끄무레하고 색이 옅어서, 해도 기쁨도 없는 곳에 놓기에 알맞은 꽃으로 읽혔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"oldeuropeanculture.blogspot.com\",\"sourceUrl\":\"https://oldeuropeanculture.blogspot.com/2022/12/asphodelus.html\"}]},\"7-12\":{\"photo\":{\"src\":\"/birth/jopeunipbaepungdeung.jpg\",\"thumbSrc\":\"/birth/thumbs/jopeunipbaepungdeung.jpg\",\"author\":\"Qwert1234\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Solanum_japonense_3.JPG\",\"familyLine\":\"흰 별 모양 꽃이 지고 나면 작고 붉은 열매가 달려요.\"},\"stories\":[]},\"7-13\":{\"photo\":{\"src\":\"/birth/japchoui-kkot.jpg\",\"thumbSrc\":\"/birth/thumbs/japchoui-kkot.jpg\",\"author\":\"Humoyun Mehridinov\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Phleum_pratense_macro_01.jpg\",\"familyLine\":\"꽃잎이 없어 지나치기 쉬운데, 가까이 보면 수술이 촘촘히 걸려 있어요.\"},\"stories\":[]},\"7-14\":{\"photo\":{\"src\":\"/birth/peulrokseu.jpg\",\"thumbSrc\":\"/birth/thumbs/peulrokseu.jpg\",\"author\":\"Bff\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Phlox_paniculata_Tatjana20170812_9020.jpg\",\"familyLine\":\"다섯 잎 꽃이 둥글게 뭉쳐 한여름 내내 같은 자리를 지켜요.\"},\"stories\":[{\"id\":\"bstory-phlox-drummond-texas\",\"title\":\"씨앗을 부치고 그해에 죽은 사람\",\"hook\":\"드러먼드는 텍사스에서 채집을 마치고 아바나에서 세상을 떠났어요.\",\"body\":\"1833년 3월 스코틀랜드 식물학자 토머스 드러먼드가 텍사스 벨라스코에 닿아 채집을 시작했어요. 그는 21개월 동안 갤버스턴 섬에서 에드워즈 고원까지의 땅을 훑었어요. 그가 모은 것은 텍사스에서 채집돼 세계의 박물관과 연구기관으로 널리 흩어진 첫 표본들이었어요. 그리고 1835년 3월, 그는 쿠바 아바나에서 세상을 떠났어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"tshaonline.org\",\"sourceUrl\":\"https://www.tshaonline.org/handbook/entries/drummond-thomas\"},{\"id\":\"bstory-phlox-name-drummondii\",\"title\":\"그의 이름이 꽃에 남았어요\",\"hook\":\"이 꽃의 학명에는 채집자의 이름이 붙어 있어요.\",\"body\":\"플록스 드루몬디라는 학명은 스코틀랜드 식물학자 토머스 드러먼드의 이름에서 왔어요. 1833년부터 1835년까지의 텍사스 원정에서 그가 다른 여러 표본과 함께 이 식물을 영국으로 보냈기 때문이에요. 북아메리카가 고향인 이 꽃은 유럽 정원에서 개량된 뒤 다시 대서양을 건너와, 지금은 고향의 화단에서도 유럽식 이름으로 불려요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Phlox_drummondii\"}]},\"7-15\":{\"stories\":[]},\"7-16\":{\"stories\":[]},\"7-17\":{\"stories\":[]},\"7-18\":{\"stories\":[]},\"7-19\":{\"photo\":{\"src\":\"/birth/baekbuja.jpg\",\"thumbSrc\":\"/birth/thumbs/baekbuja.jpg\",\"author\":\"Meneerke bloem\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Aconitum_napellus_RHu_003.JPG\",\"familyLine\":\"투구 모양 꽃이 줄지어 서고, 아름다운 만큼 독이 강해요.\"},\"stories\":[{\"id\":\"bstory-aconite-cerberus\",\"title\":\"케르베로스의 침에서 돋았다는 풀\",\"hook\":\"오비디우스는 이 독초가 지옥문 개의 입에서 나왔다고 적었어요.\",\"body\":\"오비디우스의 변신 이야기에는 헤라클레스가 저승의 문지기 개 케르베로스를 끌어 올릴 때 그 입에서 떨어진 거품에서 이 독초가 돋았다는 이야기가 나와요. 같은 작품 7권에서는 마녀 메데이아가 아이게우스에게 이 독을 탄 잔을 건네게 해 아들 테세우스를 죽이려 해요. 잔이 입에 닿기 직전 아버지가 아들을 알아보면서 멈춰요. 그리스와 로마 문헌에서 이 풀은 늘 저승 쪽에서 올라와요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"penelope.uchicago.edu\",\"sourceUrl\":\"https://penelope.uchicago.edu/~grout/encyclopaedia_romana/aconite/aconite.html\"},{\"id\":\"bstory-aconite-wolfsbane\",\"title\":\"늑대를 잡던 화살촉\",\"hook\":\"영어 이름 wolfsbane은 실제 사냥법에서 나왔어요.\",\"body\":\"백부자가 속한 투구꽃속의 영어 이름 가운데 하나가 wolfsbane, 곧 '늑대의 독'이에요. 앵글로색슨 사람들이 늑대를 사냥할 때 화살촉을 이 풀의 즙에 담갔다가 썼기 때문이라고 전해져요. 유럽에서 이 풀은 '독의 여왕'으로 불릴 만큼 강한 독으로 통했고, 뿌리에 든 아코니틴은 지금도 극약으로 다뤄져요. 한국에 자라는 백부자 역시 독성이 강한 식물이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"daily.jstor.org\",\"sourceUrl\":\"https://daily.jstor.org/wolfsbane-a-poisonous-beauty/\"}]},\"7-20\":{\"photo\":{\"src\":\"/birth/gaji.jpg\",\"thumbSrc\":\"/birth/thumbs/gaji.jpg\",\"author\":\"JDP90 (Joydeep)\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Solanum_melongena_flower_12_09_2012.JPG\",\"familyLine\":\"보랏빛 별 모양 꽃 한가운데 노란 수술이 뭉쳐 있어요.\"},\"stories\":[{\"id\":\"bstory-eggplant-mad-apple\",\"title\":\"'미친 사과'라 불리던 열매\",\"hook\":\"유럽은 가지를 오래 '미친 사과'라 불렀어요.\",\"body\":\"가지의 영어 이름 aubergine은 아랍어 알바딘잔에서 왔어요. 그 말이 스페인어 berenjena가 되고, 이탈리아로 넘어가면서 '사과'를 뜻하는 mela에 이끌려 melanzana가 됐어요. 여기서 다시 mela insana, 곧 '미친 사과'라는 말로 굳었어요. 소리가 비슷하다는 이유로 붙은 별명인데, 이 이름이 오래 붙어 다니면서 가지에 대한 의심을 더 키웠어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"etymonline.com\",\"sourceUrl\":\"https://www.etymonline.com/word/aubergine\"},{\"id\":\"bstory-eggplant-fear-of-madness\",\"title\":\"먹으면 미친다고 여겨졌어요\",\"hook\":\"유럽은 가지가 열병과 간질과 광기를 부른다고 믿었어요.\",\"body\":\"가지는 가짓과 식물이라 흰독말풀과 엔젤트럼펫, 벨라도나와 까마중 같은 독초와 한 집안이에요. 그래서 서유럽은 오래 이 열매를 위험한 것으로 여겼어요. 가지를 먹으면 열이 나고 간질이 오며 심지어 미치기까지 한다는 믿음이 돌았어요. 그 시절 이 열매에 붙은 이름이 말라 인사나, 곧 '미친 사과'였어요. 지금은 세계 어디서나 먹는 채소지만, 유럽 식탁에 자리 잡기까지는 몇백 년이 걸렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ipm.missouri.edu\",\"sourceUrl\":\"https://ipm.missouri.edu/meg/2008/5/Year-of-the-Eggplant/\"}]},\"7-21\":{\"stories\":[]},\"7-22\":{\"photo\":{\"src\":\"/birth/paeraengikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/paeraengikkot.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Dianthus_superbus_var._speciosus_%28flower%29.JPG\",\"familyLine\":\"꽃잎 끝이 실처럼 잘게 갈라져 술이 늘어진 것처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-dianthus-jeong-seupmyeong\",\"title\":\"임금이 시 한 편을 듣고 벼슬을 내렸어요\",\"hook\":\"고려 예종은 패랭이꽃을 노래한 시를 듣고 그 자리에서 사람을 발탁했어요.\",\"body\":\"고려 중기 문인 정습명이 석죽화라는 시를 지었어요. 세상 사람은 붉은 모란을 좋아해 뜰 가득 심어 두지만, 거친 들판에도 이런 좋은 꽃떨기가 있는 줄은 아무도 모른다는 내용이에요. 귀한 모란과 흔한 패랭이꽃을 나란히 놓아 부귀를 좇는 세태를 비춘 시였어요. 예종이 이 시를 듣고 깊이 감탄해 그를 옥당, 곧 한림원에 특별히 천거했다고 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"고려\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"sgsg.hankyung.com\",\"sourceUrl\":\"https://sgsg.hankyung.com/article/2024041264371\"},{\"id\":\"bstory-dianthus-stone-bamboo\",\"title\":\"돌 틈에 난 대나무라는 이름\",\"hook\":\"패랭이꽃의 한자 이름은 '돌 대나무 꽃'이에요.\",\"body\":\"패랭이꽃의 한자 이름은 석죽화예요. 돌 틈에서 피어나는데 줄기의 마디가 대나무를 닮았다고 해서 붙은 이름이에요. 한국어 이름 패랭이꽃은 다른 것을 보았어요. 꽃잎이 벌어진 모양이 옛날 서민들이 쓰던 패랭이 모자를 닮았다는 거예요. 한자 이름은 대나무의 절개 쪽을, 우리말 이름은 서민의 모자 쪽을 가리켜요. 두 이름이 다 이 꽃을 낮고 단단한 자리에 놓아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"kyongbuk.co.kr\",\"sourceUrl\":\"https://www.kyongbuk.co.kr/news/articleView.html?idxno=2091120\"}]},\"7-23\":{\"stories\":[]},\"7-24\":{\"photo\":{\"src\":\"/birth/yeonryeongcho.jpg\",\"thumbSrc\":\"/birth/thumbs/yeonryeongcho.jpg\",\"author\":\"sunoochi from Sapporo, Hokkaido, Japan\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Trillium_camschatcense_%27Aomori%27_Ker_Gawl.%2C_Bot._Mag._22_t._855_%281805%29_%2849809064156%29.jpg\",\"familyLine\":\"잎 석 장 위에 흰 꽃 한 송이만 올려놓고 끝내요.\"},\"stories\":[]},\"7-25\":{\"photo\":{\"src\":\"/birth/malojumnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/malojumnamu.jpg\",\"author\":\"W. Bulach\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:00_3775_Schwarzer_Hollunder_%28Sambucus_nigra%29.jpg\",\"familyLine\":\"작은 흰 꽃 수백 개가 접시처럼 펼쳐지고, 향이 달아요.\"},\"stories\":[]},\"7-26\":{\"photo\":{\"src\":\"/birth/hyangssuk.jpg\",\"thumbSrc\":\"/birth/thumbs/hyangssuk.jpg\",\"author\":\"Tournasol7\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Artemisia_absinthium_in_Aveyron_%285%29.jpg\",\"familyLine\":\"은빛이 도는 잎에서 쓴 향이 나고, 압생트의 재료로 알려졌어요.\"},\"stories\":[{\"id\":\"bstory-wormwood-green-fairy\",\"title\":\"초록 요정이라 불린 술\",\"hook\":\"압생트는 '라 페 베르트' 곧 초록 요정이라 불렸어요.\",\"body\":\"압생트는 향쑥의 꽃과 잎으로 만드는 아니스 향의 독주예요. 스위스 뇌샤텔 주에서 시작해 19세기 프랑스에서 크게 퍼졌고, 문학과 그림 속에서 '라 페 베르트', 곧 초록 요정이라는 별명으로 불렸어요. 화가와 시인의 잔에 늘 이 초록 술이 있었다는 이미지가 그 시대에 만들어졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"sciencehistory.org\",\"sourceUrl\":\"https://www.sciencehistory.org/stories/magazine/the-devil-in-a-little-green-bottle-a-history-of-absinthe/\"},{\"id\":\"bstory-wormwood-thujone-ban\",\"title\":\"금지의 이유였던 성분은 누명에 가까웠어요\",\"hook\":\"압생트는 1915년까지 대부분의 나라에서 금지됐어요.\",\"body\":\"압생트는 스위스에서 1910년, 미국에서 1912년, 프랑스에서 1915년에 금지됐어요. 금지 근거로 지목된 것은 향쑥에 든 투욘이라는 성분이었어요. 많이 들어가면 신경계에 해롭다는 이유였어요. 그런데 최근 수십 년의 연구는 실제 압생트에 든 투욘 양이 아주 적어서, 신경에 해로운 수준에 이르려면 하루에 몇 리터를 마셔야 한다는 결론을 내놨어요. 문제는 투욘보다 도수 쪽이었던 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스위스\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"swissinfo.ch\",\"sourceUrl\":\"https://www.swissinfo.ch/eng/swiss-oddities/89345162/89345162\"}]},\"7-27\":{\"stories\":[]},\"7-28\":{\"photo\":{\"src\":\"/birth/paeraengikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/paeraengikkot.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Dianthus_superbus_var._speciosus_%28flower%29.JPG\",\"familyLine\":\"꽃잎 끝이 실처럼 잘게 갈라져 술이 늘어진 것처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-dianthus-jeong-seupmyeong\",\"title\":\"임금이 시 한 편을 듣고 벼슬을 내렸어요\",\"hook\":\"고려 예종은 패랭이꽃을 노래한 시를 듣고 그 자리에서 사람을 발탁했어요.\",\"body\":\"고려 중기 문인 정습명이 석죽화라는 시를 지었어요. 세상 사람은 붉은 모란을 좋아해 뜰 가득 심어 두지만, 거친 들판에도 이런 좋은 꽃떨기가 있는 줄은 아무도 모른다는 내용이에요. 귀한 모란과 흔한 패랭이꽃을 나란히 놓아 부귀를 좇는 세태를 비춘 시였어요. 예종이 이 시를 듣고 깊이 감탄해 그를 옥당, 곧 한림원에 특별히 천거했다고 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"고려\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"sgsg.hankyung.com\",\"sourceUrl\":\"https://sgsg.hankyung.com/article/2024041264371\"},{\"id\":\"bstory-dianthus-stone-bamboo\",\"title\":\"돌 틈에 난 대나무라는 이름\",\"hook\":\"패랭이꽃의 한자 이름은 '돌 대나무 꽃'이에요.\",\"body\":\"패랭이꽃의 한자 이름은 석죽화예요. 돌 틈에서 피어나는데 줄기의 마디가 대나무를 닮았다고 해서 붙은 이름이에요. 한국어 이름 패랭이꽃은 다른 것을 보았어요. 꽃잎이 벌어진 모양이 옛날 서민들이 쓰던 패랭이 모자를 닮았다는 거예요. 한자 이름은 대나무의 절개 쪽을, 우리말 이름은 서민의 모자 쪽을 가리켜요. 두 이름이 다 이 꽃을 낮고 단단한 자리에 놓아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"kyongbuk.co.kr\",\"sourceUrl\":\"https://www.kyongbuk.co.kr/news/articleView.html?idxno=2091120\"}]},\"7-29\":{\"photo\":{\"src\":\"/birth/seoninjang.jpg\",\"thumbSrc\":\"/birth/thumbs/seoninjang.jpg\",\"author\":\"PtrQs\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20200812_EchinopsisOxygona_DSC03453K1_PtrQs.jpg\",\"familyLine\":\"가시밖에 없던 몸에서 하룻밤 사이 큰 꽃이 열려요.\"},\"stories\":[{\"id\":\"bstory-cactus-cochineal\",\"title\":\"선인장의 피라 불린 붉은색\",\"hook\":\"아즈텍은 선인장에 붙은 벌레에서 나오는 붉은 물감을 '선인장의 피'라 불렀어요.\",\"body\":\"노팔선인장 줄기에는 연지벌레가 붙어 살아요. 이 벌레를 말려 빻으면 강렬한 진홍색 물감이 나오는데, 나우아틀어로 노체스틀리, 곧 '선인장의 피'라 불렀어요. 아즈텍 제국은 이 물감을 조공으로 거둘 만큼 귀하게 여겼어요. 1521년 테노치티틀란에 들어온 코르테스는 시장을 채운 새빨간 천을 보고 놀랐고, 이후 스페인에게 이 물감은 은 다음가는 수입원이 됐어요. 그 원료가 벌레라는 사실은 18세기까지 비밀로 지켜졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mexicolore.co.uk\",\"sourceUrl\":\"https://www.mexicolore.co.uk/aztecs/aztec-life/red-the-colour-of-cactus-blood\"},{\"id\":\"bstory-cactus-mexican-flag\",\"title\":\"국기 한가운데 선인장이 있어요\",\"hook\":\"멕시코 국기의 독수리는 선인장 위에 서 있어요.\",\"body\":\"멕시코 국기 한가운데에는 뱀을 문 독수리가 선인장 위에 앉아 있어요. 그 선인장이 노팔이에요. 건국 신화에 따르면 메시카 사람들은 독수리가 노팔 위에 앉아 뱀을 삼키는 자리를 찾으라는 계시를 받았고, 호수 한가운데 섬에서 그 광경을 보고 그곳에 테노치티틀란을 세웠어요. 지금의 멕시코시티예요. 도시의 시작을 알린 것이 선인장 한 그루였던 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nopalcactus.com\",\"sourceUrl\":\"https://nopalcactus.com/learn/nopal-mexican-flag\"}]},\"7-30\":{\"photo\":{\"src\":\"/birth/seoyangjong-borisu.jpg\",\"thumbSrc\":\"/birth/thumbs/seoyangjong-borisu.jpg\",\"author\":\"Meneerke bloem\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Tilia_cordata_flowers_002.jpg\",\"familyLine\":\"잎처럼 생긴 포 아래로 연노란 꽃이 매달려 향을 퍼뜨려요.\"},\"stories\":[{\"id\":\"bstory-linden-court-tree\",\"title\":\"재판이 열리던 나무 아래\",\"hook\":\"신성로마제국에서는 보리수 아래에서 재판을 열었어요.\",\"body\":\"신성로마제국에는 게리히츠린데, 곧 '재판 보리수'라는 것이 있었어요. 마을 회의와 재판을 이 나무 아래에서 열었어요. 게르만 부족법에서 온 관습으로, 재판정은 대개 마을 밖 트인 들판에 자유로운 하늘 아래 놓였어요. 같은 나무가 마을 한복판에 서 있으면 춤판이 벌어지는 탄츠린데가 되기도 했고요. 기독교화된 뒤에도 보리수는 정의와 보호의 나무로 남아, 성모나 열두 사도에게 다시 바쳐지곤 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"germangirlinamerica.com\",\"sourceUrl\":\"https://germangirlinamerica.com/the-linden-tree-in-germany-at-the-heart-of-germany/\"},{\"id\":\"bstory-linden-unter-den-linden\",\"title\":\"베를린 한복판 거리의 이름\",\"hook\":\"베를린의 '운터 덴 린덴'은 '보리수 아래'라는 뜻이에요.\",\"body\":\"베를린 미테 지구를 가로지르는 큰길 운터 덴 린덴은 '보리수 아래'라는 뜻이에요. 베를린 궁전에서 브란덴부르크 문까지 이어지는 이 길 가운데에 보리수가 줄지어 심겨 있어서 붙은 이름이에요. 독일에서 보리수는 마을 광장의 나무이자 재판과 축제의 나무였으니, 수도의 중심 거리가 이 나무의 이름을 단 것은 우연이 아니에요. 헤센주 셴켄펠트에는 9세기에 심었다는 보리수가 아직 서 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"jofisherroberts.substack.com\",\"sourceUrl\":\"https://jofisherroberts.substack.com/p/under-the-linden-tree\"}]},\"7-31\":{\"photo\":{\"src\":\"/birth/hobak.jpg\",\"thumbSrc\":\"/birth/thumbs/hobak.jpg\",\"author\":\"bastus917 (영철 이)\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cucurbita_moschata_-_flower.jpg\",\"familyLine\":\"손바닥만 한 노란 꽃이 아침에 활짝 열려요.\"},\"stories\":[{\"id\":\"bstory-pumpkin-stingy-jack\",\"title\":\"순무에 새긴 첫 잭오랜턴\",\"hook\":\"처음 잭오랜턴은 호박이 아니라 순무였어요.\",\"body\":\"아일랜드와 스코틀랜드에는 '인색한 잭' 이야기가 전해져요. 악마를 속인 대가로 천국에도 지옥에도 들지 못하고 지옥의 잉걸불 한 조각만 얻어 등을 밝히고 떠도는 사람이에요. 사람들은 그 잭을 쫓으려고 만성절 전야에 순무를 파서 무서운 얼굴을 새기고 안에 불씨를 넣어 창가에 두었어요. 아일랜드에는 호박이 없었으니, 처음 잭오랜턴의 재료는 순무와 감자였어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"irishtimes.com\",\"sourceUrl\":\"https://www.irishtimes.com/life-and-style/abroad/the-story-of-jack-o-lantern-if-you-knew-the-sufferings-of-that-forsaken-craythur-1.4065773\"},{\"id\":\"bstory-pumpkin-crossing-atlantic\",\"title\":\"대서양을 건너며 호박으로 바뀌었어요\",\"hook\":\"아일랜드 이민자들이 북아메리카에서 더 좋은 재료를 찾았어요.\",\"body\":\"1820년부터 1930년까지 450만 명에 이르는 아일랜드 사람들이 미국으로 건너갔어요. 이들이 가져간 관습 중 하나가 잭오랜턴이었는데, 북아메리카에는 순무보다 훨씬 파기 좋은 것이 흔했어요. 호박이었어요. 다만 호박 등이 핼러윈과 단단히 묶인 것은 19세기 들어서였고, 너새니얼 호손이 1835년과 1852년 소설에 호박 등과 호박 머리 허수아비를 등장시킨 것이 그 무렵의 기록으로 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nationalgeographic.com\",\"sourceUrl\":\"https://www.nationalgeographic.com/history/article/the-twisted-transatlantic-tale-of-american-jack-o-lanterns\"}]},\"8-1\":{\"stories\":[]},\"8-2\":{\"stories\":[]},\"8-3\":{\"photo\":{\"src\":\"/birth/subakpul.jpg\",\"thumbSrc\":\"/birth/thumbs/subakpul.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hibiscus_trionum_kz01.jpg\",\"familyLine\":\"한 시간이면 진다는 이름처럼, 아침에 열고 낮이면 접어요.\"},\"stories\":[{\"id\":\"bstory-hibiscus-trionum-flower-of-an-hour\",\"title\":\"한 시간의 꽃\",\"hook\":\"수박풀의 영어 이름은 '한 시간의 꽃'이에요.\",\"body\":\"수박풀의 영어 이름 flower-of-an-hour는 '한 시간의 꽃'이라는 뜻이에요. 이름 그대로 꽃이 몇 시간만 피었다가 시들어 버리기 때문이에요. 해가 나는 날에만 열리고, 흐리면 아예 피지 않기도 해요. 별명도 여럿이에요. 부푼 꽃받침이 방광을 닮았다고 해서 '방광 케트미아', 지중해를 거쳐 퍼졌다고 해서 '베니스 아욱', 그리고 짧게 피고 마는 성질을 두고 '정숙'이라고도 불러요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Hibiscus_trionum\"}]},\"8-4\":{\"photo\":{\"src\":\"/birth/oksusu.jpg\",\"thumbSrc\":\"/birth/thumbs/oksusu.jpg\",\"author\":\"Forest and Kim Starr\",\"license\":\"CC BY 3.0 us\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Starr-090801-3516-Zea_mays-female_flowers-Olinda-Maui_%2824970907975%29.jpg\",\"familyLine\":\"수염 한 올이 알 한 톨과 이어져 있어요.\"},\"stories\":[{\"id\":\"bstory-corn-teosinte\",\"title\":\"손가락만 한 이삭에서 시작했어요\",\"hook\":\"옥수수의 조상은 알이 몇 개 안 달린 풀이었어요.\",\"body\":\"옥수수의 조상은 멕시코에 자라는 테오신테라는 풀이에요. 이삭이 손가락만 하고 알도 몇 개 안 달리는 데다, 알마다 딱딱한 껍질이 감싸고 있어 그냥 먹기 어려워요. 약 9000년 전 멕시코 게레로와 미초아칸을 흐르는 발사스강 유역에서 사람들이 이 풀을 고르기 시작했어요. 그 지역 야생 테오신테의 유전적 다양성이 가장 높다는 점이 이곳을 출발지로 지목하는 근거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"선사 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"evolution.earthathome.org\",\"sourceUrl\":\"https://evolution.earthathome.org/grasses/andropogoneae/maize-domestication/\"},{\"id\":\"bstory-corn-starch-grains\",\"title\":\"8700년 전의 전분 알갱이\",\"hook\":\"옥수수의 가장 오래된 흔적은 눈에 보이지 않는 크기예요.\",\"body\":\"옥수수가 언제부터 재배됐는지를 알려 준 것은 이삭이 아니라 현미경으로 봐야 하는 흔적이었어요. 발사스 계곡의 시와톡스틀라 유적에서 나온 석기와 퇴적층에서 전분 알갱이와 식물규소체가 나왔고, 연대는 약 8700년 전으로 측정됐어요. 옥수수 알은 썩어 없어져도 갈던 돌에 눌어붙은 전분은 남았어요. 지금까지 확인된 옥수수의 가장 오래된 물리적 증거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"선사 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC2664021/\"}]},\"8-5\":{\"photo\":{\"src\":\"/birth/elrika.jpg\",\"thumbSrc\":\"/birth/thumbs/elrika.jpg\",\"author\":\"Leo Michels\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Erica_carnea_IP0803009.jpg\",\"familyLine\":\"잔가지에 작은 항아리 모양 꽃이 줄줄이 매달려요.\"},\"stories\":[{\"id\":\"bstory-heath-white-heather-luck\",\"title\":\"흰 헤더가 행운인 이유\",\"hook\":\"스코틀랜드에서 흰 헤더는 드물어서 행운으로 쳐요.\",\"body\":\"스코틀랜드 고원을 덮는 헤더는 대개 분홍과 보라예요. 흰 헤더는 드물게 나타나서, 찾으면 행운이 온다고 여겼어요. 여기에 이야기 하나가 붙어 있어요. 켈트 음유시인의 딸 말비나가 약혼자 오스카의 전사 소식을 전해 들으며 유품으로 헤더 가지를 받았는데, 그의 눈물이 떨어진 자리에서 헤더가 하얗게 변했다는 거예요. 슬픔 속에서도 이 꽃을 찾는 사람에게는 행운이 가기를 빌었다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"treesforlife.org.uk\",\"sourceUrl\":\"https://treesforlife.org.uk/into-the-forest/trees-plants-animals/plants/heather/heather-mythology-and-folklore/\"},{\"id\":\"bstory-heath-cluny-hiding\",\"title\":\"흰 헤더 밭에서 잠든 도망자\",\"hook\":\"컬로든 이후 쫓기던 씨족장이 흰 헤더 덕에 살아남았다고 해요.\",\"body\":\"흰 헤더가 행운이라는 믿음에는 역사와 얽힌 이야기도 있어요. 1746년 컬로든 전투 뒤 쫓기던 맥퍼슨 씨족장 클루니의 이완이 흰 헤더 밭에 누워 잠들었는데, 수색대가 그를 알아보지 못하고 지나갔다는 거예요. 1544년 클랜라날드는 흰 헤더를 달고 싸워 이겼다고 믿었고요. 19세기에는 발모럴을 아끼던 빅토리아 여왕이 이 믿음을 잉글랜드까지 퍼뜨렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"scottish-at-heart.com\",\"sourceUrl\":\"https://www.scottish-at-heart.com/scottish-heather.html\"}]},\"8-6\":{\"photo\":{\"src\":\"/birth/neungsohwa.jpg\",\"thumbSrc\":\"/birth/thumbs/neungsohwa.jpg\",\"author\":\"Prenn\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Campsis_grandiflora_06.JPG\",\"familyLine\":\"담을 타고 올라가 주황빛 나팔을 바깥으로 내밀어요.\"},\"stories\":[{\"id\":\"bstory-neungsohwa-eosahwa\",\"title\":\"하늘을 능가하는 꽃\",\"hook\":\"능소화는 장원급제한 사람의 화관에 꽂던 꽃으로 전해져요.\",\"body\":\"능소화는 '하늘을 능가하는 꽃'이라는 뜻이에요. 장원급제한 사람의 화관에 꽂아 주는 어사화로 쓰였다고 전해지면서 양반들이 특히 아꼈고, 그래서 양반꽃과 금등화, 자위화 같은 이름이 여럿 붙었어요. 조선시대에는 평민이 함부로 심지 못하게 했다는 이야기도 함께 전해져요. 옛 선비들은 이 꽃이 시들어 흩어지지 않고 송이째 떨어지는 모습을 지조로 읽었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"shinailbo.co.kr\",\"sourceUrl\":\"https://www.shinailbo.co.kr/news/articleView.html?idxno=1439053\"},{\"id\":\"bstory-neungsohwa-pollen-myth\",\"title\":\"꽃가루가 눈을 멀게 한다는 말은 사실이 아니에요\",\"hook\":\"국립산림과학원이 능소화 꽃가루를 직접 들여다봤어요.\",\"body\":\"능소화 꽃가루가 눈에 들어가면 실명한다는 말이 오래 돌았어요. 표면에 갈고리 같은 돌기가 있어 점막에서 떨어지지 않고 염증을 일으킨다는 설명이었어요. 2015년 국립산림과학원이 주사전자현미경으로 확인한 결과는 달랐어요. 꽃가루 표면은 갈고리가 아니라 매끈한 그물 모양이었고, 바람이 아니라 벌과 나비가 옮기는 충매화라 눈에 들어갈 확률 자체가 낮았어요. 다만 꿀샘에서 나오는 꿀에는 세포독성이 확인돼, 오래된 꿀을 먹거나 오래 피부에 닿게 하는 것은 피하라고 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"korea.kr\",\"sourceUrl\":\"https://www.korea.kr/briefing/pressReleaseView.do?newsId=156067948\"}]},\"8-7\":{\"photo\":{\"src\":\"/birth/seokryu-0807.jpg\",\"thumbSrc\":\"/birth/thumbs/seokryu-0807.jpg\",\"author\":\"Alvesgaspar ( talk )\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Punica_June_2009-1.jpg\",\"familyLine\":\"붉은 꽃받침이 두껍고 단단해서, 꽃일 때부터 열매를 닮았어요.\"},\"stories\":[{\"id\":\"bstory-pomegranate-grenade\",\"title\":\"수류탄의 어원이 이 열매예요\",\"hook\":\"석류와 수류탄은 같은 말에서 갈라져 나왔어요.\",\"body\":\"로마의 플리니우스는 석류를 말루스 푸니카, 곧 '카르타고의 사과'라 불렀어요. 로마가 카르타고를 거쳐 이 열매를 들여왔기 때문이에요. 학명 Punica granatum의 앞 절반이 여기서 왔고, granatum은 '씨앗이 많다'는 뜻이에요. 영어 pomegranate도 '씨 많은 사과'라는 같은 뜻이고요. 훗날 프랑스군은 손에 쥐는 크기에 알갱이가 가득 든 무기를 보고 같은 이름을 붙였어요. 그것이 지금의 grenade, 곧 수류탄이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"khkeeler.blogspot.com\",\"sourceUrl\":\"http://khkeeler.blogspot.com/2015/03/plant-story-pomegranates-punica_22.html\"},{\"id\":\"bstory-pomegranate-persephone-one-seed\",\"title\":\"호메로스 원전에는 한 알\",\"hook\":\"하데스가 페르세포네에게 몰래 먹인 석류는 여섯 알이 아니라 한 알이에요.\",\"body\":\"페르세포네가 석류 몇 알을 먹었느냐고 물으면 흔히 여섯 알이라는 답이 돌아오지만, 가장 오래된 문헌은 그렇게 말하지 않아요. 데메테르에게 바치는 호메로스 찬가 370행에서 375행 부근에서 하데스는 페르세포네에게 달콤한 석류 씨를 몰래 먹여요. 검은 옷을 입은 데메테르 곁에 딸이 영영 머물지 않게 하려는 계산이었어요. 410행에서 413행 부근에서는 페르세포네가 직접 말해요. 그가 몰래 내 입에 달콤한 것을, 석류 씨 하나를 넣고 내 뜻과 상관없이 맛보게 했다고요. 두 대목 모두 단수로 씨라고만 적고 개수를 밝히지 않아요. 여러 알이라는 설정은 훨씬 나중 판본에서 붙은 살이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"perseus.tufts.edu\",\"sourceUrl\":\"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0138%3Ahymn%3D2\"},{\"id\":\"bstory-pomegranate-613-seeds\",\"title\":\"석류 206개를 센 사람\",\"hook\":\"613알 전승을 확인하려고 대학원생이 석류 206개의 알을 손으로 셌어요.\",\"body\":\"유대 전통에는 석류 한 개에 씨가 613개 들어 있고 이것이 토라의 계명 613개와 맞아떨어진다는 말이 돌아요. 다만 이 숫자는 탈무드에 없어요. 베라코트는 석류가 씨로 가득하듯 이스라엘의 빈 사람들도 계명으로 가득하다고, 아가의 구절을 빌려 풍성함을 말할 뿐이에요. 613이라는 수를 언급한 것은 19세기의 하탐 소페르와 말빔 같은 후대 학자예요. 실제로 세어 본 사람도 있어요. 컬럼비아대 대학원생 알렉산더 하우볼트가 세계 각지에서 온 석류 206개의 알을 셌는데, 평균이 정확히 613개로 나왔어요. 하지만 낱개로 보면 165개부터 1,370개까지 흩어져 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이스라엘\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"jewishaction.com\",\"sourceUrl\":\"https://jewishaction.com/religion/jewish-law/whats_the_truth_about_pomegranate_seeds/\"}]},\"8-8\":{\"photo\":{\"src\":\"/birth/jindalrae.jpg\",\"thumbSrc\":\"/birth/thumbs/jindalrae.jpg\",\"author\":\"Rhododendrites\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rhododendron_mucronulatum_pink_peignoir_%2870036%29.jpg\",\"familyLine\":\"잎보다 꽃이 먼저 나와서 가지 전체가 분홍으로 덮여요.\"},\"stories\":[{\"id\":\"bstory-azalea-dugyeonju\",\"title\":\"아버지의 병을 고쳤다는 술\",\"hook\":\"면천 두견주에는 고려 개국공신의 딸 이야기가 붙어 있어요.\",\"body\":\"충남 당진 면천에는 진달래 꽃잎을 넣어 빚는 두견주가 전해져요. 진달래를 두견화라 부른 데서 온 이름이에요. 고려 개국공신 복지겸이 병들어 낫지 않자 어린 딸이 아미산에 올라 백일기도를 드렸고, 신선이 나타나 아미산에 핀 진달래로 술을 빚되 반드시 안샘 물을 쓰고 백일 뒤에 마시며 뜰에 은행나무 두 그루를 심으라 일렀다고 해요. 딸이 그대로 하자 아버지의 병이 나았다고 전해져요. 면천두견주는 국가무형유산으로 지정돼 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"고려\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"heritage.go.kr\",\"sourceUrl\":\"https://www.heritage.go.kr/heri/cul/culSelectDetail.do?VdkVgwKey=17%2C00860200%2C34&pageNo=1_1_1_0\"},{\"id\":\"bstory-azalea-hwajeon\",\"title\":\"삼짇날 개울가에서 부치던 꽃전\",\"hook\":\"음력 삼월 삼짇날에는 진달래를 따서 그 자리에서 전을 부쳤어요.\",\"body\":\"화전놀이는 고려 때부터 이어진 봄 풍습이에요. 음력 3월 3일 삼짇날, 마을 여성들이 번철과 찹쌀가루를 들고 산과 개울가로 나가 진달래를 따서 그 자리에서 화전을 부쳐 먹었어요. 진달래로 부친 것을 두견화전이라 불렀고, 꿀물이나 오미자즙에 꽃잎을 띄운 진달래화채와 함께 먹었어요. 조선 궁중에서도 궁녀들이 중전을 모시고 비원에 나가 화전을 부쳤다는 기록이 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"contents.history.go.kr\",\"sourceUrl\":\"https://contents.history.go.kr/mobile/km/view.do?levelId=km_010_0060_0030_0010\"}]},\"8-9\":{\"photo\":{\"src\":\"/birth/siseuteoseu.jpg\",\"thumbSrc\":\"/birth/thumbs/siseuteoseu.jpg\",\"author\":\"Alvesgaspar\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cistus_May_2014-10.jpg\",\"familyLine\":\"종이처럼 얇은 꽃잎이 하루 만에 지고, 다음 날 새 꽃이 다시 펴요.\"},\"stories\":[{\"id\":\"bstory-cistus-goat-beard\",\"title\":\"염소 수염에서 거두는 향\",\"hook\":\"라브다넘은 염소 수염에 엉킨 진을 잘라 모았어요.\",\"body\":\"시스터스, 곧 암장미의 잎과 가지에서는 끈적한 진이 나와요. 라브다넘이라 부르는 이 진은 고대부터 향료였는데, 거두는 방법이 특이했어요. 염소 떼를 이 덤불에 풀어놓았다가 수염과 털에 엉겨 붙은 진을 한 해에 한 번 수염째 잘라 모았어요. 크레타에서는 나무와 가죽끈으로 만든 라다니스테리온이라는 갈퀴 모양 도구로 덤불을 쓸어 진을 거두었고, 시세스 마을에서는 지금도 이 방식을 써요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"aromaticmedicineschool.com\",\"sourceUrl\":\"https://aromaticmedicineschool.com/labdanum-cistus-resin/\"},{\"id\":\"bstory-cistus-pharaoh-beard\",\"title\":\"파라오의 가짜 수염에 관한 가설\",\"hook\":\"파라오가 턱에 단 가짜 수염이 염소 수염이었다는 설이 있어요.\",\"body\":\"라브다넘을 모으던 도구 라다니스테리온은 도리깨를 닮았어요. 그래서 고대 이집트 신과 파라오가 손에 쥔 도리깨가 사실 이 채취 도구였다는 가설이 나왔어요. 여기에 이어지는 이야기가 하나 더 있어요. 파라오가 턱에 붙인 가짜 수염이 원래 향이 밴 염소 수염이었고, 그래서 왕의 주위에 늘 이 향이 감돌았다는 거예요. 어느 쪽도 확정된 학설은 아니지만, 향료 하나가 왕권의 도상까지 설명하려 한 흥미로운 시도예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이집트\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"premierepeau.com\",\"sourceUrl\":\"https://premierepeau.com/blogs/news/labdanum-the-resin-that-goats-harvest-without-knowing\"}]},\"8-10\":{\"photo\":{\"src\":\"/birth/ikki-0810.jpg\",\"thumbSrc\":\"/birth/thumbs/ikki-0810.jpg\",\"author\":\"Chmee2\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Polytrichum_commune_in_natural_monument_Knez_u_Hrazan_%281%29.JPG\",\"familyLine\":\"숲 바닥에 별 모양으로 촘촘히 서서 물기를 오래 붙잡아요.\"},\"stories\":[{\"id\":\"bstory-moss-sphagnum-field-dressing\",\"title\":\"늪에서 걷어 온 붕대\",\"hook\":\"1차 세계대전의 표준 지혈대는 공장이 아니라 늪에서 왔습니다. 그걸 걷은 사람은 여자와 아이들이었습니다.\",\"body\":\"1차 세계대전 초기에는 상처보다 패혈증으로 죽는 병사가 더 많았어요. 1915년에 군의관 찰스 캐스카트가 옛 기록을 떠올렸어요. 예전에는 물이끼로 상처를 싸맸다는 거예요. 시험해 보니 통했어요. 물이끼는 솜보다 두 배 넘는 피와 진물을 빨아들이고, 산성이라 세균이 잘 못 자라거든요. 그래서 전국 규모의 이끼 채집 사업이 시작됐어요. 보드민 무어에서 셰틀랜드까지, 여자들과 아이들이 차고 젖은 늪에 들어가 이끼를 걷었어요. 말리고 골라 무명 주머니에 채운 그 이끼가 영국과 자치령 군대의 표준 지혈대가 됐어요. 군복 안쪽에 꿰매 넣고 다니는 그 주머니예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"1910년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theconversation.com\",\"sourceUrl\":\"https://theconversation.com/war-and-peat-how-bog-moss-helped-save-thousands-of-lives-in-world-war-i-106630\"},{\"id\":\"bstory-moss-who-picked-it\",\"title\":\"그 이끼를 캔 사람들\",\"hook\":\"붕대가 될 이끼를 캔 것은 각지의 여자들과 아이들이었어요.\",\"body\":\"물이끼 붕대의 재료는 공장이 아니라 늪지에서 나왔어요. 그것을 캐고 말리고 자루에 채운 것은 온갖 나이의 여성과 아이들이었어요. 캐나다 적십자 온타리오 지부만 해도 1916년 한 해에 100만 장이 넘는 붕대를 만들어 보냈고, 1918년에는 영국에서 한 달에 100만 장이 병원으로 나갔어요. 전선 반대편도 사정은 같아서 독일에서는 민간인은 물론 연합군 포로까지 이 일에 동원됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-absorbency\",\"title\":\"제 무게 22배를 머금는 이끼\",\"hook\":\"세포의 90퍼센트가 죽은 세포라, 물이끼는 제 무게의 22배까지 물을 빨아들여요.\",\"body\":\"물이끼는 제 무게의 22배까지 물을 머금어요. 탈지면의 두 배죠. 세포의 90퍼센트가 죽은 세포라 애초에 물을 빨아들이게 생긴 구조예요. 게다가 세포벽이 음전하를 띠어 상처 둘레를 산성으로 만들고, 그 산성이 세균 번식을 막아요. 식물학자 아이작 베일리 밸푸어와 군의관 찰스 워커 캐스카트가 쓸 만한 두 종을 골라냈어요. 1916년 캐나다 적십자는 드레싱 100만 장 넘게, 압박포 200만 장 가까이, 패드 100만 장을 보냈고, 1918년에는 영국에서 매달 100만 장이 유럽과 이집트, 메소포타미아의 병원으로 나갔어요. 채집 안내문은 자루를 4분의 3만 채워 마른 땅으로 끌어낸 다음 그 위에서 춤을 춰 물을 빼라고 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-saihoji\",\"title\":\"설계되지 않은 이끼 정원\",\"hook\":\"교토 사이호지의 이끼 120종은 정원사가 심은 게 아니라 홍수와 방치가 만든 거예요.\",\"body\":\"교토 사이호지 정원을 덮은 이끼는 120종이에요. 그런데 처음부터 이끼 정원으로 설계된 게 아니에요. 무소 소세키가 이 절을 되살렸을 때만 해도 황금 연못에 뜬 섬들의 꼭대기는 수면과 거의 같은 높이였어요. 그 뒤 이 일대는 몇 번이나 홍수를 겪었고, 그때마다 연못 바닥을 쳐내 물 높이를 낮추면서 퍼낸 진흙을 섬 위에 쌓았어요. 이끼는 그 진흙에서 자라기 시작했어요. 특히 에도 시대, 절을 손볼 사람이 없어 허물어져 가는 동안 이끼가 두껍게 앉았고, 지금 사람들이 보러 오는 풍경은 그 방치의 결과예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mlit.go.jp\",\"sourceUrl\":\"https://www.mlit.go.jp/tagengo-db/en/R1-00439.html\"}]},\"8-11\":{\"stories\":[]},\"8-12\":{\"photo\":{\"src\":\"/birth/hyeopjukdo.jpg\",\"thumbSrc\":\"/birth/thumbs/hyeopjukdo.jpg\",\"author\":\"Alvesgaspar\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Nerium_oleander_September_2007-1.jpg\",\"familyLine\":\"잎도 가지도 독이 있어서, 예쁜 만큼 조심해야 해요.\"},\"stories\":[{\"id\":\"bstory-oleander-pompeii-garden\",\"title\":\"화산재 속에 남은 뿌리 자국\",\"hook\":\"폼페이의 정원은 뿌리가 남긴 빈 구멍으로 되살아났어요.\",\"body\":\"1950년대부터 고고학자 빌헬미나 야셈스키는 폼페이에서 새로운 방법을 썼어요. 나무가 썩으면 굳은 화산재 안에 뿌리 모양의 빈 구멍이 남는데, 거기에 석고를 부어 뿌리 형태를 떠낸 거예요. 이렇게 어떤 식물이 어디에 얼마만큼 심겨 있었는지가 드러났어요. 벽에 그려진 정원 그림과 대조하는 방법도 함께 썼고요. 그 그림과 뿌리 자국에 함께 등장하는 식물 가운데 하나가 협죽도예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이탈리아\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pompeiiarchaeologicalpark.com\",\"sourceUrl\":\"https://pompeiiarchaeologicalpark.com/gardens-of-pompeii/\"},{\"id\":\"bstory-oleander-hiroshima\",\"title\":\"히로시마에서 가장 먼저 핀 꽃\",\"hook\":\"원폭 뒤 폐허에서 가장 먼저 꽃을 피운 것이 협죽도였다고 전해져요.\",\"body\":\"1945년 히로시마에 원자폭탄이 떨어진 뒤, 한동안 이 땅에는 아무것도 자라지 못할 것이라는 말이 돌았어요. 그런데 얼마 지나지 않아 폐허에서 협죽도가 꽃을 피웠다고 전해져요. 이 꽃은 사람들에게 다시 시작할 수 있다는 신호로 남았고, 1973년 주민 투표로 히로시마의 시화가 되었어요. 협죽도가 가장 많이 피는 시기가 8월 초, 원폭이 떨어진 날 무렵이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"grunge.com\",\"sourceUrl\":\"https://www.grunge.com/1143535/how-the-atomic-bombs-made-the-oleander-the-flower-of-hiroshima/\"}]},\"8-13\":{\"photo\":{\"src\":\"/birth/goldeun-rodeu.jpg\",\"thumbSrc\":\"/birth/thumbs/goldeun-rodeu.jpg\",\"author\":\"Enrico Blasutto\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Solidago_virgaurea_ENBLA02.jpg\",\"familyLine\":\"가을 들판에서 노란 꽃이 막대처럼 곧게 서요.\"},\"stories\":[{\"id\":\"bstory-goldenrod-edison-rubber\",\"title\":\"세 사람이 돈을 모아 세운 식물 연구회사\",\"hook\":\"에디슨과 포드와 파이어스톤이 고무 나는 식물을 찾아 나섰어요.\",\"body\":\"1927년 헨리 포드와 토머스 에디슨, 하비 파이어스톤이 각자 2만 5000달러씩 내어 에디슨 식물연구회사를 세웠어요. 목표는 하나였어요. 미국에서 빨리 길러 고무를 뽑을 수 있는 식물을 찾는 것이었어요. 당시 세계 고무 공급은 영국이 사실상 쥐고 있었고, 미국은 그 사슬에서 벗어나고 싶어 했어요. 연구진은 1만 7000점이 넘는 식물 시료를 분석했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"halibutpointnotes.blogspot.com\",\"sourceUrl\":\"https://halibutpointnotes.blogspot.com/2019/11/goldenrod-and-science-part-1-industry.html\"},{\"id\":\"bstory-goldenrod-last-failure\",\"title\":\"에디슨이 끝내 이루지 못한 일\",\"hook\":\"성공에 익숙하던 사람이 남긴 몇 안 되는 실패예요.\",\"body\":\"수많은 후보를 살핀 끝에 에디슨이 고른 것은 에버글레이즈에 야생으로 자라는 잡초, 골든로드였어요. 그는 열대의 실험실에서 이 풀에 매달렸어요. 하지만 그 사이 화학회사들은 석유에서 합성고무를 만들기 시작했고, 식물에서 고무를 짜낸다는 발상은 곧 낡은 것이 되었어요. 에디슨은 끝까지 골든로드에 희망을 걸었지만, 이 연구는 성공에 익숙하던 그가 남긴 몇 안 되는 실패로 남았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"baltimoresun.com\",\"sourceUrl\":\"https://www.baltimoresun.com/news/bs-xpm-1999-10-04-9910040121-story.html\"}]},\"8-14\":{\"photo\":{\"src\":\"/birth/jeomeondeo.jpg\",\"thumbSrc\":\"/birth/thumbs/jeomeondeo.jpg\",\"author\":\"MurielBendel\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Teucrium_chamaedrys_Ligerz.jpg\",\"familyLine\":\"돌담 틈에 뿌리내리고 분홍빛 입술 모양 꽃을 달아요.\"},\"stories\":[{\"id\":\"bstory-germander-teucer\",\"title\":\"트로이 왕의 이름을 단 풀\",\"hook\":\"저먼더의 속명은 트로이의 첫 왕 테우크로스에서 왔어요.\",\"body\":\"저먼더의 속명 Teucrium은 트로이의 첫 왕으로 전해지는 테우크로스의 이름에서 왔어요. 디오스코리데스가 그의 이름을 딴 약초를 기록했고, 린네가 1753년에 그 이름을 속명으로 굳혔어요. 종소명 chamaedrys는 그리스어로 '땅의 참나무', 곧 난쟁이 참나무라는 뜻이에요. 잎이 참나무 잎을 작게 줄여 놓은 모양이라서예요. 영어 이름 germander도 이 chamaedrys가 프랑스어를 거치며 닳아 만들어진 말이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/teucrium-chamaedrys/\"},{\"id\":\"bstory-germander-charles-v\",\"title\":\"황제의 통풍을 고쳤다는 약 그리고 지금은 금지\",\"hook\":\"카를 5세의 통풍이 이 풀로 나았다는 기록이 있어요.\",\"body\":\"옛 약초서에는 신성로마제국 황제 카를 5세의 통풍이 저먼더를 다른 약초와 함께 포도주에 달여 60일 동안 마셔 나았다는 기록이 있어요. 이 풀은 통풍의 특효약으로 여겨져 '포틀랜드 가루'라는 유명한 약의 주요 재료이기도 했어요. 그런데 20세기 말 이 풀로 만든 제품을 먹은 사람들에게 간 손상이 보고되면서, 지금은 내복이 권장되지 않아요. 몇백 년의 명성이 몇 건의 사례로 뒤집힌 경우예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"herbs-treatandtaste.blogspot.com\",\"sourceUrl\":\"https://herbs-treatandtaste.blogspot.com/2012/02/wall-or-common-germander-no-longer.html\"}]},\"8-15\":{\"stories\":[]},\"8-16\":{\"photo\":{\"src\":\"/birth/tamarindeu.jpg\",\"thumbSrc\":\"/birth/thumbs/tamarindeu.jpg\",\"author\":\"Dinesh Valke from Thane, India\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Tamarindus_indica_%28517656695%29.jpg\",\"familyLine\":\"연노랑 꽃이 지고 나면 신맛 나는 갈색 꼬투리가 열려요.\"},\"stories\":[{\"id\":\"bstory-tamarind-indian-date\",\"title\":\"'인도의 대추'라는 이름\",\"hook\":\"타마린드는 아랍어로 '인도의 대추'라는 뜻이에요.\",\"body\":\"타마린드라는 이름은 아랍어 타므르 힌디에서 왔어요. '인도의 대추'라는 뜻이에요. 인도에서 중동으로 이 열매가 처음 건너갔을 때, 사람들이 갈색으로 쭈글쭈글한 꼬투리 속살을 자기들이 알던 대추야자에 빗대어 부른 이름이에요. 중세 라틴어 tamarindus를 거쳐 16세기 말 영어에 들어왔고, 마르코 폴로는 타마란디라고 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"인도\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"etymonline.com\",\"sourceUrl\":\"https://www.etymonline.com/word/tamarind\"},{\"id\":\"bstory-tamarind-african-origin\",\"title\":\"정작 고향은 인도가 아니에요\",\"hook\":\"'인도의 대추'라는 이름과 달리 원산지는 아프리카로 봐요.\",\"body\":\"이름은 인도를 가리키지만, 타마린드의 원산지는 동아프리카로 봐요. 아주 이른 시기에 인도로 건너가 그곳에서 널리 심기면서 인도의 것처럼 알려졌고, 아랍 상인들이 인도에서 이 열매를 받아 가면서 '인도의 대추'라는 이름이 굳었어요. 지금은 열대 전역에서 자라요. 이름이 원산지가 아니라 무역로의 마지막 기착지를 가리키는 경우예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아프리카\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"herbaria.plants.ox.ac.uk\",\"sourceUrl\":\"https://herbaria.plants.ox.ac.uk/bol/plants400/Profiles/st/Tamarindus\"}]},\"8-17\":{\"photo\":{\"src\":\"/birth/tyulripnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/tyulripnamu.jpg\",\"author\":\"Jacek Halicki\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:2015_Kwiat_tulipanowca_ameryka%C5%84skiego.jpg\",\"familyLine\":\"높은 가지 위에 튤립을 닮은 꽃이 초록빛으로 피어요.\"},\"stories\":[{\"id\":\"bstory-tuliptree-canoe-wood\",\"title\":\"카누를 만들던 나무\",\"hook\":\"튤립나무의 옛 이름 가운데 하나는 '카누 나무'예요.\",\"body\":\"튤립나무는 별명이 많아요. 꽃이 튤립을 닮았다고 튤립나무, 목재가 노랗다고 옐로 포플러, 그리고 카누 우드라는 이름도 있어요. 북아메리카 원주민이 굵은 줄기 속을 파내어 카누를 만들었기 때문이에요. 레나페 사람들이 부른 이름 무술헤멘시는 그대로 '카누를 만드는 나무'라는 뜻이에요. 곧게 높이 자라는 데다 목재가 가벼우면서도 무게에 비해 단단해서, 통나무 하나로 배를 만들기에 알맞았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"natlands.org\",\"sourceUrl\":\"https://www.natlands.org/news/tulip-tree-the-tree-of-many-names/\"}]},\"8-18\":{\"photo\":{\"src\":\"/birth/jeopsikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/jeopsikkot.jpg\",\"author\":\"PJDespa\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Alcea_rosea_purple.jpg\",\"familyLine\":\"곧게 선 줄기를 따라 접시만 한 꽃이 아래에서 위로 올라가며 펴요.\"},\"stories\":[{\"id\":\"bstory-hollyhock-holy-hoc\",\"title\":\"'거룩한 아욱'이라는 이름\",\"hook\":\"hollyhock의 holly는 호랑가시나무가 아니라 '거룩한'이에요.\",\"body\":\"접시꽃의 영어 이름 hollyhock에서 hoc은 앵글로색슨어로 아욱을 뜻하는 말이었어요. 앞의 holly는 호랑가시나무가 아니라 holy, 곧 '거룩한'에서 왔다고 봐요. 십자군이 성지에서 가져온 아욱이라는 뜻이에요. 16세기 약초학자 윌리엄 터너가 이 꽃을 holyoke라 적은 기록이 남아 있어요. 원산은 중국 서남부 쪽이고, 실크로드와 지중해를 거쳐 유럽에 닿은 것으로 봐요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"uaex.uada.edu\",\"sourceUrl\":\"https://www.uaex.uada.edu/yard-garden/resource-library/plant-week/hollyhock.aspx\"},{\"id\":\"bstory-hollyhock-tokugawa-aoi\",\"title\":\"도쿠가와 가문의 문장은 접시꽃이 아니에요\",\"hook\":\"'세 잎 접시꽃'이라 번역돼 온 그 문장은 사실 족도리풀이에요.\",\"body\":\"일본 도쿠가와 가문의 문장은 영어권에서 오래 '세 잎 접시꽃'으로 옮겨졌어요. 그런데 그 문장의 아오이는 접시꽃이 아니라 후타바아오이, 곧 쥐방울덩굴과의 족도리풀 종류예요. 교토 가모 신사의 문장에서 온 도안이고, 가모 씨족과 인연이 깊던 미카와의 무사단이 쓰던 것을 마쓰다이라와 도쿠가와 가문이 물려받았다고 봐요. 게다가 실제 후타바아오이는 잎이 두 장인데 문장은 세 장이에요. 번역 한 번이 오래도록 다른 꽃을 가리킨 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"japanesewiki.com\",\"sourceUrl\":\"https://www.japanesewiki.com/culture/Mitsuba-aoi%20(Three%20Leaves%20of%20Hollyhock).html\"}]},\"8-19\":{\"photo\":{\"src\":\"/birth/rosa-kaempion.jpg\",\"thumbSrc\":\"/birth/thumbs/rosa-kaempion.jpg\",\"author\":\"Syrio\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Silene_coronaria_Valternigo_02.jpg\",\"familyLine\":\"은빛 솜털 잎 위로 진한 자홍색 꽃이 홀로 서요.\"},\"stories\":[{\"id\":\"bstory-rosecampion-lamp-wick\",\"title\":\"잎을 심지로 썼어요\",\"hook\":\"속명 Lychnis는 '작은 등잔'이라는 뜻이에요.\",\"body\":\"로사 캠피온의 옛 속명 Lychnis는 그리스어 리크노스, 곧 손에 드는 작은 등잔에서 왔어요. 이 식물의 잎은 은회색 솜털로 두껍게 덮여 있는데, 그 솜털 잎을 말려 등잔 심지로 썼기 때문에 붙은 이름으로 봐요. 진한 자홍색 꽃이 은빛 잎 위에 떠 있는 모습이 어둠 속 불꽃 같아서라는 설명도 함께 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"missouribotanicalgarden.org\",\"sourceUrl\":\"https://www.missouribotanicalgarden.org/PlantFinder/PlantFinderDetails.aspx?kempercode=p840\"},{\"id\":\"bstory-rosecampion-crown\",\"title\":\"화관을 엮던 꽃\",\"hook\":\"종소명 coronaria는 '화관에 쓰는'이라는 뜻이에요.\",\"body\":\"종소명 coronaria는 라틴어로 '화관에 쓰는, 화관에 관한'이라는 뜻이에요. 고대에 이 꽃으로 관을 엮었다는 데서 온 이름이에요. 영어 이름 rose campion의 campion 역시 경기 우승자에게 씌우던 관에서 왔다는 설명이 함께 전해져요. 등잔의 심지와 승자의 관, 두 가지 쓰임이 학명 한 줄에 나란히 들어 있는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"piedmontmastergardeners.org\",\"sourceUrl\":\"https://www.piedmontmastergardeners.org/article/rose-campion/\"}]},\"8-20\":{\"stories\":[]},\"8-21\":{\"photo\":{\"src\":\"/birth/jipsinnamul.jpg\",\"thumbSrc\":\"/birth/thumbs/jipsinnamul.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Agrimonia_eupatoria_-_Keila.jpg\",\"familyLine\":\"가는 꽃대에 노란 꽃이 촘촘히 붙고, 열매는 옷에 잘 달라붙어요.\"},\"stories\":[{\"id\":\"bstory-agrimony-garclive\",\"title\":\"앵글로색슨이 '가클리페'라 부르던 풀\",\"hook\":\"이 풀은 천 년 전 영국 의서 세 권에 모두 들어 있어요.\",\"body\":\"짚신나물속의 아그리모니아 에우파토리아를 앵글로색슨 사람들은 가클리페라 불렀어요. 이 이름은 라크눙가와 볼드의 리치북, 의사 아풀레이우스의 약초서 같은 고대 영어 의학 필사본에 모두 나와요. 상처와 사마귀, 뱀에 물린 데에 썼다고 적혀 있어요. 잠과도 얽혀 있어서, 이 풀 한 가지를 머리맡에 두면 치울 때까지 깨지 않는다는 이야기도 함께 전해졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"thecommonplacebooke.wordpress.com\",\"sourceUrl\":\"https://thecommonplacebooke.wordpress.com/2018/01/07/the-old-english-herbal-appendix-a-comprehensive-list-of-herbs-in-the-three-anglo-saxon-curative-manuscripts-lacnunga-balds-leechbooks-and-the-herbarium-of-pseudo-apuleius-and-their-uses/\"},{\"id\":\"bstory-agrimony-arquebusade\",\"title\":\"총상에 쓰던 물\",\"hook\":\"15세기 전장에는 짚신나물로 만든 물약이 있었어요.\",\"body\":\"15세기 유럽에는 '아르케부사드 물'이라는 상처약이 있었어요. 아르케부스, 곧 화승총에 맞은 상처를 씻는 데 쓰던 물이라 붙은 이름이에요. 그 주재료가 짚신나물이었어요. 앵글로색슨 시대부터 상처에 쓰던 풀이 화약 무기가 등장한 뒤에도 같은 자리에 남은 셈이에요. 이 처방은 훨씬 뒤까지 약전에 남아 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"15세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Agrimonia_eupatoria\"}]},\"8-22\":{\"photo\":{\"src\":\"/birth/seupiria.jpg\",\"thumbSrc\":\"/birth/thumbs/seupiria.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Spiraea_japonica_%28flower%29.JPG\",\"familyLine\":\"잔꽃이 우산처럼 모여 분홍 구름 한 덩이처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-spiraea-aspirin-name\",\"title\":\"아스피린의 '스피르'가 여기서 왔어요\",\"hook\":\"아스피린이라는 이름 안에 이 식물이 들어 있어요.\",\"body\":\"1897년 바이엘의 펠릭스 호프만이 살리실산에 아세틸기를 붙이면 위를 덜 자극한다는 것을 알아냈고, 1899년 1월 이 물질에 아스피린이라는 이름이 붙었어요. 이름은 세 조각이에요. A는 아세틸, spir은 이 산을 얻던 식물 Spiraea ulmaria, 곧 메도스위트, in은 당시 약 이름에 흔히 붙이던 꼬리예요. 독일어로 살리실산을 슈피어조이레라 부르던 옛 이름이 그대로 남은 자리이기도 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"sciencehistory.org\",\"sourceUrl\":\"https://www.sciencehistory.org/stories/magazine/aspirin-turn-of-the-century-miracle-drug/\"},{\"id\":\"bstory-spiraea-elizabeth-strewing\",\"title\":\"엘리자베스 1세가 가장 좋아한 바닥 풀\",\"hook\":\"이 풀은 방바닥에 뿌려 두는 향기 풀로 으뜸이었어요.\",\"body\":\"아스피린에 이름을 준 그 식물, 메도스위트는 지금은 Spiraea가 아니라 Filipendula ulmaria로 분류돼요. 이 풀은 오래 실내에 뿌려 두는 향기 풀이었어요. 존 제라드는 1597년 허벌에 잎과 꽃이 다른 어떤 바닥 풀보다 뛰어나며, 여름철 집과 홀과 연회장에 뿌려 두면 그 향이 마음을 즐겁게 한다고 적었어요. 엘리자베스 1세도 자기 방에는 이 풀을 가장 좋아했다고 전해져요. 이름 meadowsweet도 초원이 아니라 벌꿀술 mead에서 왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"khkeeler.blogspot.com\",\"sourceUrl\":\"http://khkeeler.blogspot.com/2024/09/plant-story-meadowsweet-queen-of-meadow.html\"}]},\"8-23\":{\"photo\":{\"src\":\"/birth/seoyangjong-borisu.jpg\",\"thumbSrc\":\"/birth/thumbs/seoyangjong-borisu.jpg\",\"author\":\"Meneerke bloem\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Tilia_cordata_flowers_002.jpg\",\"familyLine\":\"잎처럼 생긴 포 아래로 연노란 꽃이 매달려 향을 퍼뜨려요.\"},\"stories\":[{\"id\":\"bstory-linden-court-tree\",\"title\":\"재판이 열리던 나무 아래\",\"hook\":\"신성로마제국에서는 보리수 아래에서 재판을 열었어요.\",\"body\":\"신성로마제국에는 게리히츠린데, 곧 '재판 보리수'라는 것이 있었어요. 마을 회의와 재판을 이 나무 아래에서 열었어요. 게르만 부족법에서 온 관습으로, 재판정은 대개 마을 밖 트인 들판에 자유로운 하늘 아래 놓였어요. 같은 나무가 마을 한복판에 서 있으면 춤판이 벌어지는 탄츠린데가 되기도 했고요. 기독교화된 뒤에도 보리수는 정의와 보호의 나무로 남아, 성모나 열두 사도에게 다시 바쳐지곤 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"germangirlinamerica.com\",\"sourceUrl\":\"https://germangirlinamerica.com/the-linden-tree-in-germany-at-the-heart-of-germany/\"},{\"id\":\"bstory-linden-unter-den-linden\",\"title\":\"베를린 한복판 거리의 이름\",\"hook\":\"베를린의 '운터 덴 린덴'은 '보리수 아래'라는 뜻이에요.\",\"body\":\"베를린 미테 지구를 가로지르는 큰길 운터 덴 린덴은 '보리수 아래'라는 뜻이에요. 베를린 궁전에서 브란덴부르크 문까지 이어지는 이 길 가운데에 보리수가 줄지어 심겨 있어서 붙은 이름이에요. 독일에서 보리수는 마을 광장의 나무이자 재판과 축제의 나무였으니, 수도의 중심 거리가 이 나무의 이름을 단 것은 우연이 아니에요. 헤센주 셴켄펠트에는 9세기에 심었다는 보리수가 아직 서 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"jofisherroberts.substack.com\",\"sourceUrl\":\"https://jofisherroberts.substack.com/p/under-the-linden-tree\"}]},\"8-24\":{\"stories\":[]},\"8-25\":{\"photo\":{\"src\":\"/birth/anseuryum.jpg\",\"thumbSrc\":\"/birth/thumbs/anseuryum.jpg\",\"author\":\"Alejandro Bayer Tamayo from Armenia, Colombia\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Anturio_rojo_%28Anthurium_andraeanum%29_-_Flickr_-_Alejandro_Bayer_%281%29.jpg\",\"familyLine\":\"꽃잎처럼 보이는 붉은 판은 사실 잎이 변한 포예요.\"},\"stories\":[{\"id\":\"bstory-anthurium-andre-1876\",\"title\":\"콜롬비아에서 찾아 자기 이름을 남긴 사람\",\"hook\":\"안스륨의 학명에는 발견자의 이름이 붙어 있어요.\",\"body\":\"프랑스 원예가이자 조경가였던 에두아르 앙드레가 1876년 콜롬비아에서 이 식물을 찾아 처음 기재했어요. 그의 이름을 따 학명이 Anthurium andraeanum이 되었어요. 콜롬비아와 에콰도르의 습하고 그늘진 숲에서 다른 나무에 붙어 자라는 착생식물이에요. 그는 표본을 벨기에 장 린덴의 원예장으로 보냈고, 19세기 말 유럽 온실에서 관상식물로 길러지기 시작했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"콜롬비아\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"monaconatureencyclopedia.com\",\"sourceUrl\":\"https://www.monaconatureencyclopedia.com/anthurium-andraeanum/?lang=en\"},{\"id\":\"bstory-anthurium-hawaii\",\"title\":\"하와이가 제2의 고향이 되었어요\",\"hook\":\"1889년 하와이로 건너간 뒤 이 꽃의 산지가 바뀌었어요.\",\"body\":\"안스륨은 1889년 새뮤얼 밀스 데이먼이 영국에서 하와이로 들여왔어요. 습하고 따뜻한 그늘이 원산지 조건과 맞아떨어져 잘 자랐어요. 1930년대 초부터 하와이에서만 나온 오바케 계통의 교배가 시작됐고, 1940년대에는 번식이 흔한 일이 될 만큼 재배가 퍼졌어요. 남아메리카에서 온 꽃이 태평양 한가운데를 새 고향으로 삼은 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"hawaiineotropica.com\",\"sourceUrl\":\"https://hawaiineotropica.com/anthuriums/\"}]},\"8-26\":{\"photo\":{\"src\":\"/birth/haiposiseu-orieo.jpg\",\"thumbSrc\":\"/birth/thumbs/haiposiseu-orieo.jpg\",\"author\":\"Dinesh Valke from Thane, India\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hypoxis_aurea_%283804595970%29.jpg\",\"familyLine\":\"풀 사이에서 노란 별 하나가 땅에 바짝 붙어 피어요.\"},\"stories\":[]},\"8-27\":{\"photo\":{\"src\":\"/birth/gobi.jpg\",\"thumbSrc\":\"/birth/thumbs/gobi.jpg\",\"author\":\"Kropsoq\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Osmunda_japonica_001.jpg\",\"familyLine\":\"돌돌 말린 어린 순이 천천히 풀리면서 잎이 돼요.\"},\"stories\":[{\"id\":\"bstory-osmunda-thor-name\",\"title\":\"천둥신인가 물가의 오스문드인가\",\"hook\":\"고비속의 학명 유래에는 설이 여럿이에요.\",\"body\":\"고비속의 학명 Osmunda가 어디서 왔는지는 여러 갈래로 전해져요. 하나는 색슨족이 천둥신 토르를 부르던 이름 오스문데르에서 왔다는 설이에요. 토르가 가족을 위험에서 지키려고 이 고사리 덤불 속에 숨겼다는 이야기가 붙어 있어요. 다른 하나는 1578년 라이트가 기록한 영어 이름 '물가의 오스문드'에서 왔다는 설이에요. 늪과 물가에 자라는 습성에서 온 이름이라는 거예요. 종소명 regalis는 라틴어로 '왕의'라는 뜻이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"wildadirondacks.org\",\"sourceUrl\":\"https://wildadirondacks.org/adirondack-ferns-royal-fern-osmunda-regalis.html\"},{\"id\":\"bstory-osmunda-orchid-fiber\",\"title\":\"난을 기르던 뿌리\",\"hook\":\"고비의 뿌리는 오래 난 재배용 재료로 쓰였어요.\",\"body\":\"고비속 식물은 뿌리줄기가 크고 단단한 덩이를 이뤄요. 이 섬유질 뿌리는 눌려도 잘 뭉개지지 않고 쉽게 물러지지 않아서, 난을 비롯한 여러 식물을 붙여 기르는 재료로 오래 쓰였어요. 착생란처럼 흙이 아니라 나무에 붙어 자라는 식물에게는 물을 머금으면서도 공기가 통하는 이 성질이 꼭 맞았어요. 다만 자생지에서 뿌리를 캐야 하는 재료라, 지금은 대체 재료로 많이 바뀌었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pza.sanbi.org\",\"sourceUrl\":\"https://pza.sanbi.org/osmunda-regalis\"}]},\"8-28\":{\"photo\":{\"src\":\"/birth/erinjium.jpg\",\"thumbSrc\":\"/birth/thumbs/erinjium.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Eryngium_planum_kz21.jpg\",\"familyLine\":\"꽃도 잎도 금속처럼 푸르고, 만지면 뻣뻣해요.\"},\"stories\":[{\"id\":\"bstory-eryngium-colchester-eringo\",\"title\":\"콜체스터의 설탕 절임\",\"hook\":\"잉글랜드의 한 도시는 굴과 이 뿌리 절임으로 유명했어요.\",\"body\":\"바다엉겅퀴의 뿌리는 17~18세기 잉글랜드에서 대규모로 캐어 설탕에 절였어요. '에린고'라 불린 이 과자는 기력을 돋우고 정욕을 북돋운다고 여겨졌어요. 에식스의 콜체스터가 그 중심이었는데, 이 도시는 굴과 에린고 두 가지로 이름이 났어요. 17세기에 로버트 버턴이라는 약제사가 그곳에 제조소를 열고 설탕과 오렌지꽃물로 절였고, 1600년대부터 1800년대 중반까지 생산이 이어졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"foxearth.org.uk\",\"sourceUrl\":\"http://www.foxearth.org.uk/blog/2005/09/candied-eringo-amending-defects-of.html\"},{\"id\":\"bstory-eryngium-falstaff\",\"title\":\"폴스타프가 외친 그 과자\",\"hook\":\"셰익스피어의 폴스타프는 하늘에서 에린고가 쏟아지길 빌어요.\",\"body\":\"셰익스피어의 윈저의 즐거운 아낙네들에서 폴스타프는 윈저 숲으로 포드 부인을 만나러 가며 이렇게 외쳐요. 하늘이여, 키싱 컴핏과 눈 같은 에린고를 뿌려 다오, 유혹의 폭풍이 몰아치게 하라고요. 여기서 '키싱 컴핏'은 입내를 좋게 하는 사탕이고, '에린고'가 바로 설탕에 절인 바다엉겅퀴 뿌리예요. 엘리자베스 시대 관객에게는 설명이 필요 없는 농담이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"the-history-girls.blogspot.com\",\"sourceUrl\":\"http://the-history-girls.blogspot.com/2013/07/kissing-comfits-and-snow-eringoes.html\"}]},\"8-29\":{\"photo\":{\"src\":\"/birth/kkotdambae.jpg\",\"thumbSrc\":\"/birth/thumbs/kkotdambae.jpg\",\"author\":\"Swaminathan from Gurgaon, India\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Nicotiana_alata.jpg\",\"familyLine\":\"해질 무렵 흰 별 모양 꽃이 열리고 향이 퍼져요.\"},\"stories\":[{\"id\":\"bstory-nicotiana-jean-nicot\",\"title\":\"왕비의 두통약으로 들어온 담배\",\"hook\":\"니코틴이라는 말은 한 외교관의 이름에서 왔어요.\",\"body\":\"1560년 리스본에 주재하던 프랑스 외교관 장 니코는 담배의 씨앗과 잎을 프랑스 왕대비 카트린 드 메디시스에게 보냈어요. 상처와 종기를 낫게 한다고 했고, 두통약으로 쓰는 법도 함께 알려 주었어요. 궁정에서 인기를 얻으면서 담배는 '에르브 드 라 렌', 곧 왕비의 풀이라 불렸어요. 1570년 무렵부터 유럽 식물학자들은 이 식물을 니코의 이름을 따 니코티아나라 부르기 시작했고, 그 성분의 이름이 니코틴이 되었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Jean_Nicot\"}]},\"8-30\":{\"photo\":{\"src\":\"/birth/jeomeondeo.jpg\",\"thumbSrc\":\"/birth/thumbs/jeomeondeo.jpg\",\"author\":\"MurielBendel\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Teucrium_chamaedrys_Ligerz.jpg\",\"familyLine\":\"돌담 틈에 뿌리내리고 분홍빛 입술 모양 꽃을 달아요.\"},\"stories\":[{\"id\":\"bstory-germander-teucer\",\"title\":\"트로이 왕의 이름을 단 풀\",\"hook\":\"저먼더의 속명은 트로이의 첫 왕 테우크로스에서 왔어요.\",\"body\":\"저먼더의 속명 Teucrium은 트로이의 첫 왕으로 전해지는 테우크로스의 이름에서 왔어요. 디오스코리데스가 그의 이름을 딴 약초를 기록했고, 린네가 1753년에 그 이름을 속명으로 굳혔어요. 종소명 chamaedrys는 그리스어로 '땅의 참나무', 곧 난쟁이 참나무라는 뜻이에요. 잎이 참나무 잎을 작게 줄여 놓은 모양이라서예요. 영어 이름 germander도 이 chamaedrys가 프랑스어를 거치며 닳아 만들어진 말이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/teucrium-chamaedrys/\"},{\"id\":\"bstory-germander-charles-v\",\"title\":\"황제의 통풍을 고쳤다는 약 그리고 지금은 금지\",\"hook\":\"카를 5세의 통풍이 이 풀로 나았다는 기록이 있어요.\",\"body\":\"옛 약초서에는 신성로마제국 황제 카를 5세의 통풍이 저먼더를 다른 약초와 함께 포도주에 달여 60일 동안 마셔 나았다는 기록이 있어요. 이 풀은 통풍의 특효약으로 여겨져 '포틀랜드 가루'라는 유명한 약의 주요 재료이기도 했어요. 그런데 20세기 말 이 풀로 만든 제품을 먹은 사람들에게 간 손상이 보고되면서, 지금은 내복이 권장되지 않아요. 몇백 년의 명성이 몇 건의 사례로 뒤집힌 경우예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"herbs-treatandtaste.blogspot.com\",\"sourceUrl\":\"https://herbs-treatandtaste.blogspot.com/2012/02/wall-or-common-germander-no-longer.html\"}]},\"8-31\":{\"photo\":{\"src\":\"/birth/tokkipul.jpg\",\"thumbSrc\":\"/birth/thumbs/tokkipul.jpg\",\"author\":\"Supportstorm\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Trifolium_repens_flower_April_2_2010.jpg\",\"familyLine\":\"작은 나비 모양 꽃 수십 개가 모여 하나의 공처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-clover-dinely-1681\",\"title\":\"성 패트릭 축일에 세 잎 풀을 다는 관습의 첫 기록\",\"hook\":\"1681년 영국인 여행자가 그 관습을 처음 적었어요.\",\"body\":\"성 패트릭이 세 잎 풀로 삼위일체를 설명했다는 이야기는 널리 알려져 있지만, 정작 그 관습이 문서에 처음 나타나는 것은 1681년이에요. 아일랜드를 여행한 영국인 토머스 디닐리가 3월 17일에 사람들이 세 잎 풀 샴로그를 미신처럼 달고, 숨결이 향기로워진다며 그것을 먹기도 한다고 적었어요. 삼위일체 설명 자체가 기록에 등장하는 것은 그보다도 나중이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"greennews.ie\",\"sourceUrl\":\"https://greennews.ie/the-history-of-the-shamrock-from-saint-patrick-to-campions-wild-irish-to-rebellion-and-nationhood/\"},{\"id\":\"bstory-clover-four-leaf-gene\",\"title\":\"네 잎이 되는 유전자를 찾아냈어요\",\"hook\":\"2010년 연구진이 네 잎 클로버를 만드는 유전자를 짚어 냈어요.\",\"body\":\"2010년 미국 조지아대의 웨인 패럿 연구진이 흰토끼풀에서 네 잎을 만드는 형질의 유전자 위치를 분자 표지로 짚어 냈어요. 잎에 붉은 무늬가 생기는 형질의 유전자도 함께 찾았고요. 흥미로운 것은 유전자가 있어도 네 잎이 늘 나오지는 않는다는 점이에요. 패럿의 말대로 햇빛이나 온도가 맞지 않으면 그냥 세 잎으로 자라요. 유전자와 환경이 어떻게 맞물리는지는 아직 다 풀리지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"21세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"news.uga.edu\",\"sourceUrl\":\"https://news.uga.edu/four-leaf-clover-spotting/\"}]},\"9-1\":{\"photo\":{\"src\":\"/birth/horangikkot.jpg\",\"thumbSrc\":\"/birth/thumbs/horangikkot.jpg\",\"author\":\"Citron\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Tigridia_pavonia_flower.jpg\",\"familyLine\":\"하루만 피고 지는 꽃이에요. 아침에 열려 저녁이면 시드는데 그 하루를 위해 호랑이 무늬 같은 얼룩을 꽃 안쪽에 새겨 두었어요.\"},\"stories\":[{\"id\":\"bstory-tigridia-one-day-bulb\",\"title\":\"꽃은 하루, 뿌리는 고구마 맛\",\"hook\":\"한 송이의 수명은 딱 하루인데, 아즈텍 사람들이 탐낸 건 꽃이 아니라 땅속이었어요.\",\"body\":\"호랑이꽃은 아침에 활짝 열렸다가 그날이 저물기 전에 시들어요. 한 송이의 수명이 딱 하루예요. 대신 줄기 하나에 여러 송이가 차례로 달려서, 매일 새 꽃이 열리고 매일 한 송이가 집니다. 그런데 멕시코의 아즈텍 사람들이 이 식물에서 눈여겨본 건 하루짜리 꽃이 아니라 땅속이었어요. 알뿌리를 캐서 식량으로 삼았고 약으로도 썼거든요. 노스캐롤라이나주립대 원예 자료는 이 뿌리를 구우면 고구마와 비슷한 맛이 난다고 적어 두었어요. 속에는 서른다섯 종쯤이 있고, 멕시코에서 남아메리카까지 퍼져 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/tigridia/\"},{\"id\":\"bstory-tigridia-oceloxochitl\",\"title\":\"1620년의 신부, 이름은 재규어꽃\",\"hook\":\"아즈텍 사람들은 이 꽃을 '표범 꽃'이라 불렀고, 그 이름을 딸에게도 붙였어요.\",\"body\":\"이 꽃의 아즈텍 이름은 오셀로쇼치틀이에요. 오셀로틀은 재규어나 오셀롯을, 쇼치틀은 꽃을 뜻하니 그대로 옮기면 '표범 꽃'이 돼요. 꽃 안쪽에 번진 얼룩무늬를 고양잇과 맹수의 털에 견준 이름이죠. 오리건대학이 운영하는 나우아틀어 사전은 이 이름이 티그리디아 파보니아를 가리키며, 사람들이 알뿌리를 캐서 열병과 불임을 다스리는 데도 썼다고 정리해요. 그런데 이름은 꽃에만 머물지 않았어요. 1620년 산 바르톨로메 카풀우악 교구 기록에는 마리아 오셀로쇼치틀이라는 여자가 디에고 로렌소와 혼인했다고 적혀 있어요. 정복이 끝나고 백 년이 지난 뒤에도 표범 꽃은 사람 이름으로 살아 있었던 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"nahuatl.wired-humanities.org\",\"sourceUrl\":\"https://nahuatl.wired-humanities.org/content/oceloxochitl\"}]},\"9-2\":{\"photo\":{\"src\":\"/birth/meksikan-aibi.jpg\",\"thumbSrc\":\"/birth/thumbs/meksikan-aibi.jpg\",\"author\":\"Amada44\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Cobaea_scandens_4529.jpg\",\"familyLine\":\"종처럼 매달린 꽃이 처음엔 연둣빛이었다가 며칠에 걸쳐 보랏빛으로 짙어져요. 한 덩굴에서 두 가지 색을 같이 보게 되는 이유예요.\"},\"stories\":[{\"id\":\"bstory-cobaea-bat-bells\",\"title\":\"박쥐를 위한 대성당 종\",\"hook\":\"초록으로 열려 보라로 지는 이 꽃은, 원산지에서 박쥐가 찾아와요.\",\"body\":\"북미 원예 도감은 이 덩굴을 '대성당 종', '수도원 종'이라고도 불러요. 늘어진 꽃이 컵과 받침 접시를 겹쳐 놓은 모양이라 컵앤소서 바인이라는 이름도 붙었고요. 꽃은 처음 열릴 때 초록빛이었다가 익으면서 보라로 물들고, 갓 벌어졌을 때는 사향 비슷한 불쾌한 냄새를 풍겨요. 한 송이가 덩굴에 매달려 있는 기간은 나흘쯤이에요. 원산지 멕시코와 남미 열대에서는 박쥐가 이 꽃을 수분하는데, 밤에 날아다니는 짐승에게는 고운 색보다 강한 냄새가 잘 통하니까요. 꽃을 찾아다니는 박쥐가 살지 않는 북미 동부에서는 그 방식이 통하지 않는다고 도감은 덧붙여요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/cobaea-scandens/\"},{\"id\":\"bstory-cobaea-cobo-43books\",\"title\":\"43권 중 17권만 남은 신부\",\"hook\":\"꽃 이름의 주인은 탈고와 출간 사이에 237년이 놓인 책을 썼어요.\",\"body\":\"속명 코바이아의 주인은 예수회 신부 베르나베 코보예요. 1580년에 태어나 1599년 스페인에서 리마로 건너갔고, 1657년 그곳에서 눈을 감을 때까지 신대륙에 머물렀어요. 그가 남긴 '신세계의 역사'는 원래 마흔세 권짜리였는데, 지금까지 전해지는 건 열일곱 권뿐이에요. 앞의 열네 권은 신대륙 자연사와 잉카의 역사를, 마지막 세 권은 리마 건설을 다뤄요. 그는 직접 본 것과 원주민 제보자에게 들은 것, 다른 스페인 연대기를 엮어 썼고 해석보다 관찰에 기운 문장을 남겼어요. 원고를 끝낸 해는 1653년, 활자가 된 해는 1890년. 탈고와 출간 사이에 237년이 놓여 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"페루·스페인\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"encyclopedia.com\",\"sourceUrl\":\"https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/cobo-bernabe-1580-1657\"}]},\"9-3\":{\"photo\":{\"src\":\"/birth/mageoriteu.jpg\",\"thumbSrc\":\"/birth/thumbs/mageoriteu.jpg\",\"author\":\"W. Bulach\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:00_4351_Strauchmargerite_(Argyranthemum_frutescens).jpg\",\"familyLine\":\"들국화처럼 보이지만 카나리아 제도에서 건너온 나무성 국화예요. 줄기 아래쪽이 해마다 조금씩 목질로 굳어 가요.\"},\"stories\":[{\"id\":\"bstory-marguerite-tenerife-hybrid\",\"title\":\"테네리페에서 두 번 태어난 종\",\"hook\":\"해안의 마거리트와 월계수림의 사촌이 만나, 새로운 종이 두 번 따로 생겼어요.\",\"body\":\"화분에서 흔히 보는 마거리트, 아르기란테뭄 프루테스켄스의 고향은 대서양의 카나리아 제도예요. 2023년 학술지 G3에 실린 연구는 테네리페 섬에서 벌어진 일을 유전자 발현 수준으로 들여다봤어요. 해발 200미터 아래 건조한 해안에 사는 프루테스켄스와 그 위 월계수림에 사는 브루소네티가 만나, 중간 고도 계곡에서 새로운 종을 낳았거든요. 남향 계곡에는 순딩기이, 북동향 계곡에는 렘시이. 둘은 서로 무관하게 따로 생겨났는데도 유전자 발현 양상이 비슷하게 수렴했어요. 부모 종 사이에서 다르게 발현되는 유전자는 2,786개였고, 그중에는 물 부족에 대한 반응에 관여하는 것들이 두드러졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스페인\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"academic.oup.com\",\"sourceUrl\":\"https://academic.oup.com/g3journal/article/13/10/jkad158/7207864\"},{\"id\":\"bstory-marguerite-japan-crossing\",\"title\":\"205번의 수분, 살아남은 두 포기\",\"hook\":\"새로운 꽃 색을 얻으려던 육종가들에게 남은 건 잡종 두 포기였어요.\",\"body\":\"마거리트는 일본에서 절화와 분화로 크게 팔리는 꽃이라, 새로운 색을 만드는 일이 곧 시장이 돼요. 문제는 기존 속간 교배로는 분홍과 빨강밖에 나오지 않았다는 것이었죠. 2023년 6월 학술지 플랜트 바이오테크놀로지에 실린 보고는 그 벽을 넘으려던 기록이에요. 흰 꽃이 피는 로단테뭄 호스마리엔세에 두상화 6개, 크림빛 카타난케에 82개, 대조군인 가야눔에 117개를 붙여 2016년과 2021년에 걸쳐 수분했어요. 수분 3주 뒤 밑씨를 꺼내 배지에서 키우는 방식이었고요. 그렇게 살아남은 잡종은 단 두 포기. 하나는 희거나 연분홍, 다른 하나는 붉은 설상화를 피웠고, 둘 다 꽃가루를 만들지 못했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC10797515/\"}]},\"9-4\":{\"photo\":{\"src\":\"/birth/baemmu.jpg\",\"thumbSrc\":\"/birth/thumbs/baemmu.jpg\",\"author\":\"Qwert1234\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Geum_japonicum_1.JPG\",\"familyLine\":\"노란 꽃이 지고 나면 갈고리 달린 씨앗 뭉치가 남아요. 지나가는 짐승 털에 붙어 멀리까지 따라가려는 거예요.\"},\"stories\":[{\"id\":\"bstory-geum-blessed-root\",\"title\":\"사탄이 달아나는 뿌리\",\"hook\":\"1491년 인쇄된 약초서는 이 뿌리가 집에 있으면 사탄이 달아난다고 적었어요.\",\"body\":\"뱀무의 영어 이름 허브 베넷은 중세 라틴어 헤르바 베네딕타, 곧 '축복받은 풀'에서 왔어요. 프라이어 박사는 이 이름이 성 베네딕토의 풀에서 비롯됐다고 봤는데, 성인이 독이 든 포도주를 축복하자 독이 잔에서 뛰쳐나갔다는 전설과 이어져요. 1491년에 인쇄된 약초서 오르투스 사니타티스는 아예 이렇게 적었어요. 뿌리가 집 안에 있으면 사탄은 아무것도 하지 못하고 달아나며, 그러므로 이 풀은 다른 모든 풀보다 먼저 축복받았다고요. 13세기 성당의 기둥머리 조각과 벽 장식에도 이 풀이 자주 나오는데, 세 갈래로 갈라진 잎은 삼위일체를, 다섯 장의 노란 꽃잎은 십자가의 다섯 상처를 뜻했다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드·독일\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://botanical.com/botanical/mgmh/a/avens083.html\"},{\"id\":\"bstory-geum-clove-root\",\"title\":\"정향 대신, 에일과 옷장에\",\"hook\":\"갓 캔 뿌리에서 정향 냄새가 나서, 사람들은 이걸 향신료처럼 썼어요.\",\"body\":\"뱀무는 뿌리에 향이 있어요. 갓 캔 뿌리에서 정향 냄새가 나고 계피 기운도 살짝 돌아서, 값비싼 정향 대신 썼어요. 수프와 스튜에 향신료로 넣었고, 에일에 향을 입히는 데도 썼고요. 잘 말린 뿌리는 리넨 옷장에 넣어 좀을 막는 방향제가 됐어요. 16세기에는 텃밭 채소처럼 널리 길렀다고 해요. 가루 낸 뿌리는 간헐열을 다스리는 데 키니네 대용으로 쓰이면서 한때 대단한 명성을 얻기도 했고요. 향이 가장 진한 때는 봄이라 뿌리도 봄에 캐는 게 좋고, 캔 뒤에는 아주 조심스럽게 말려 서늘하고 마른 곳에 밀폐해 두라고 적혀 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pfaf.org\",\"sourceUrl\":\"https://pfaf.org/user/Plant.aspx?LatinName=Geum+urbanum\"}]},\"9-5\":{\"photo\":{\"src\":\"/birth/neureupnamu-0905.jpg\",\"thumbSrc\":\"/birth/thumbs/neureupnamu-0905.jpg\",\"author\":\"Dalgial\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ulmus_davidiana_var._japonica_samara_at_winter.JPG\",\"familyLine\":\"잎보다 씨앗이 먼저 나무를 덮어요. 얇은 날개를 두른 씨가 가지마다 붙어 연둣빛 안개처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-elm-dutch-disease-women\",\"title\":\"네덜란드 병이라는 이름의 진짜 주인\",\"hook\":\"네덜란드 느릅나무병은 네덜란드 느릅나무의 병이 아닙니다. 그 병을 밝혀낸 네덜란드 여성들의 이름입니다.\",\"body\":\"느릅나무를 세계에서 지워 가는 병의 이름은 네덜란드 느릅나무병이에요. 네덜란드 느릅나무가 걸리는 병이라는 뜻으로 오해하기 쉬운데 아니에요. 1921년부터 네덜란드에서 이 병의 정체를 밝혀낸 연구자들 때문에 붙은 이름이에요. 베아트리체 스홀 슈바르츠가 박사학위 논문에서 병든 목재에서 나온 새 곰팡이를 정밀하게 기술하고 이름을 붙였어요. 그리고 그 곰팡이를 건강한 나무에 접종해 병을 재현했고요. 크리스티네 바위스만이 뒤를 이었어요. 두 사람 모두 요한나 베스테르데이크 밑에서 일했어요. 병의 고향은 아시아라는 게 지금의 정설이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"1920년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"auf.isa-arbor.com\",\"sourceUrl\":\"https://auf.isa-arbor.com/content/1/6/107\"},{\"id\":\"bstory-elm-okc-survivor-tree\",\"title\":\"주차장에 그늘을 드리우던 나무\",\"hook\":\"폭탄이 터지기 전, 그 느릅나무의 쓸모는 주차장에 그늘을 만드는 것이었습니다.\",\"body\":\"오클라호마시티 도심 주차장에 미국느릅나무 한 그루가 있었어요. 그 주차장에서 그늘이 있는 자리는 그 나무 아래뿐이었어요. 그래서 사람들은 나무 밑에 차를 대려고 일부러 일찍 출근했다고 해요. 1995년 4월 19일, 몇 미터 떨어진 곳에서 이천 킬로그램에 가까운 폭탄이 터졌어요. 백육십팔 명이 죽고 수백 명이 다쳤어요. 나무는 서 있었어요. 그런데 가지에 증거물이 걸려 있어서 수사를 위해 베어 낼 뻔했어요. 지금 그 나무는 서바이버 트리라고 불려요. 주차장 그늘나무였던 나무가요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"1990년대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"memorialmuseum.com\",\"sourceUrl\":\"https://memorialmuseum.com/experience/the-survivor-tree/\"},{\"id\":\"bstory-elm-married-vine\",\"title\":\"포도를 느릅나무에 시집보내다\",\"hook\":\"로마 농부들은 포도나무를 느릅나무에 올리는 일을 '혼인'이라 불렀어요.\",\"body\":\"로마 농부들은 포도나무를 느릅나무에 올리는 일을 두고 포도를 느릅나무에게 시집보낸다고 말했어요. 서기 50년 무렵 콜루멜라는 농서 '농업론'에 그 방법을 꼼꼼히 적었는데, 버팀목으로는 씨가 맺히지 않아 꺾꽂이로만 늘리는 아티니아 느릅나무를 권했고 소들도 들판 느릅나무보다 이 잎을 더 좋아한다고 덧붙였어요. 베르길리우스와 카툴루스는 이 농사 용어를 사람의 혼인으로 옮겨 왔어요. 튼튼하지만 열매를 맺지 못하는 남편이 느릅나무, 약하지만 열매를 맺는 아내가 포도나무라는 구도였죠. 1600년 무렵 셰익스피어의 아드리아나도 같은 말을 해요. 당신은 느릅나무예요, 나는 포도나무고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대~16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"iforest.sisef.org\",\"sourceUrl\":\"https://iforest.sisef.org/contents/?id=ifor1244-007\"},{\"id\":\"bstory-elm-dutch-women\",\"title\":\"병 이름에 남은 여성들\",\"hook\":\"네덜란드느릅나무병은 병이 시작된 곳이 아니라, 밝혀낸 사람들의 나라 이름이에요.\",\"body\":\"네덜란드느릅나무병이라는 이름은 병이 네덜란드에서 시작돼서가 아니라, 네덜란드 연구자들이 그 정체를 밝혀냈기 때문에 붙었어요. 1918년 가을부터 느릅나무가 죽는다는 보고가 이어지자 빌리 코멜린 스홀턴 연구소가 나섰고, 소장 요한나 베스테르데이크는 1921년까지 56명을 이 문제에 붙였는데 그중 절반 가까이가 여성이었어요. 마리 베아트리스 슈바르츠가 원인을 새로운 곰팡이로 지목해 이름 붙였고, 크리스티너 바위스만은 1927년 이 곰팡이의 또 다른 생활사 단계를 찾아냈어요. 바위스만은 1930년 미국 최초의 발병 사례를 확인했고, 1936년 초 갑자기 세상을 떠났어요. 1935년에 나온 저항성 계통에는 그의 이름이 붙었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"arboretum.harvard.edu\",\"sourceUrl\":\"https://arboretum.harvard.edu/arnoldia-stories/ulmus-x-hollandica-christine-buisman/\"}]},\"9-6\":{\"photo\":{\"src\":\"/birth/hanryeon.jpg\",\"thumbSrc\":\"/birth/thumbs/hanryeon.jpg\",\"author\":\"Ermell\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Close-up_of_Tropaeolum_majus_flowers_droplets_-20190830-RM-081005.jpg\",\"familyLine\":\"잎이 물을 밀어내서 빗방울이 구슬처럼 굴러다녀요. 꽃도 잎도 먹을 수 있어 예전부터 밥상에 자주 올랐어요.\"},\"stories\":[{\"id\":\"bstory-nasturtium-flashing-flowers\",\"title\":\"열아홉 살이 본 섬광\",\"hook\":\"1762년, 린네의 딸은 해 진 뒤 한련 꽃에서 빛이 번쩍이는 걸 봤어요.\",\"body\":\"1762년, 열아홉 살의 엘리사베트 크리스티나 폰 린네가 스웨덴 왕립과학원에 논문을 냈어요. 웁살라 근처 함마르뷔 농장의 정원에 어스름이 내릴 무렵, 한련 꽃에서 빛이 번쩍이는 걸 봤다는 내용이었죠. 혼자만 그렇게 보이는 건 아닌지 확인하려고 다른 사람들에게도 꽃을 보게 했고, 원인을 두고 인광일까 전기일까 따져 봤어요. 아버지는 분류학의 그 칼 폰 린네예요. 이 수수께끼는 오래도록 '엘리자베스 린네 현상'이라 불렸는데, 1914년 독일의 토마스가 답을 내놨어요. 꽃이 빛을 내는 게 아니라 황혼 빛 속에서 그 색을 받아들이는 우리 눈이 만들어 내는 착시라는 거였죠.\",\"notes\":[{\"key\":\"region\",\"text\":\"스웨덴\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nybg.org\",\"sourceUrl\":\"https://www.nybg.org/blogs/science-talk/tag/elisabeth-christina-von-linne/\"},{\"id\":\"bstory-nasturtium-borrowed-name\",\"title\":\"이름을 빌려 쓴 쪽은 한련이에요\",\"hook\":\"한련이 '나스투르티움'으로 불린 건 꽃 맛이 물냉이와 같았기 때문이에요.\",\"body\":\"한련의 영어 이름 나스투르티움은 사실 물냉이 무리의 속명이에요. 한련은 트로파이올룸 속이라 아무 관계가 없는데도 그 이름을 얻었습니다. 1787년 커티스의 보태니컬 매거진이 이유를 적어 두었어요. 한련 꽃을 씹으면 물냉이와 똑같은 맛이 나는데, 꽃 뒤로 뻗은 꿀주머니 쪽에 단맛이 더해져 있어서 샐러드에 넣기 좋다는 겁니다. 같은 지면은 이 식물을 페루 원산으로 소개하며 린네의 말을 빌려 1684년에 유럽으로 들어왔다고 적었고, 영국에서는 '큰 인도물냉이', 프랑스에서는 '그랑드 카퓌신'이라 불렀다고 전해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드·페루\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"en.wikisource.org\",\"sourceUrl\":\"https://en.wikisource.org/wiki/The_Botanical_Magazine/Volume_1/23\"}]},\"9-7\":{\"photo\":{\"src\":\"/birth/orenji.jpg\",\"thumbSrc\":\"/birth/thumbs/orenji.jpg\",\"author\":\"Javier martin\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Citrus_sinensis_CloseupFlowerSolanadelPino.jpg\",\"familyLine\":\"열매가 익는 동안 다음 해에 필 꽃봉오리가 같은 가지에 함께 맺혀요. 한 나무에서 꽃과 열매를 같이 보게 되는 이유예요.\"},\"stories\":[{\"id\":\"bstory-orange-victoria-1840-wreath\",\"title\":\"다이아몬드 대신 오렌지꽃 한 줄\",\"hook\":\"1840년 빅토리아 여왕은 머리에 보석 하나 없이 오렌지꽃 화관만 얹었어요.\",\"body\":\"1840년 2월 10일 빅토리아 여왕이 앨버트 공과 결혼했어요. 이튿날 더 타임스 궁정란은 여왕이 머리에 다이아몬드를 전혀 걸치지 않고 오렌지꽃 화관 하나만 썼다고 전합니다. 흰 새틴 드레스 가장자리도 오렌지꽃으로 둘렀고요. 식물학자 넬슨이 1840년부터 1913년까지 왕실 혼례 기록을 훑어보니, 여왕 본인의 결혼식에 쓰인 꽃은 오렌지꽃 단 한 종류였고 이후 일곱 번의 왕실 결혼식에 또 등장했어요. 앨버트는 결혼 전해인 1839년에 직접 도안한 브로치를 선물했는데, 금으로 만든 잎과 줄기에 흰 에나멜로 오렌지꽃 두 송이와 봉오리 두 개를 달아 둔 것이었습니다.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"빅토리아 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"heatherworld.org\",\"sourceUrl\":\"https://www.heatherworld.org/wp-content/uploads/2015/03/EC-Nelson-Vic-myrtle.pdf\"},{\"id\":\"bstory-orange-versailles-orangerie\",\"title\":\"겨울에 5도 아래로 내려가지 않는 방\",\"hook\":\"오렌지나무를 얼려 죽이지 않으려고 벽 두께 5미터짜리 건물을 지었어요.\",\"body\":\"베르사유의 오랑주리는 오렌지나무를 겨울에 얼려 죽이지 않으려고 지은 건물이에요. 1663년 루이 르 보가 처음 세웠고, 스무 해쯤 뒤 쥘 아르두앵 망사르가 길이와 폭을 두 배로 늘렸어요. 가운데 회랑은 길이가 150미터를 넘고 볼트 천장은 13미터, 벽 두께는 4~5미터예요. 여기에 이중창과 남향 배치가 더해져, 겨울에도 실내 온도가 5도 아래로 내려가지 않아요. 여름이면 3헥타르 화단에 화분 1,055개가 줄지어 나와 서죠. 오렌지나무와 야자, 협죽도, 석류가 섞여 있고, 포르투갈과 스페인과 이탈리아에서 건너온 나무들 가운데는 수령이 200년을 넘는 것도 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"en.chateauversailles.fr\",\"sourceUrl\":\"https://en.chateauversailles.fr/discover/estate/gardens/orangery\"}]},\"9-8\":{\"photo\":{\"src\":\"/birth/gat.jpg\",\"thumbSrc\":\"/birth/thumbs/gat.jpg\",\"author\":\"Shmunmun\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Brassica_juncea_Flower.jpg\",\"familyLine\":\"잎은 김치가 되고 씨앗은 겨자가 돼요. 매운맛은 잎이 상처를 입은 순간에야 만들어지는 방어 물질이에요.\"},\"stories\":[{\"id\":\"bstory-mustard-papal-mustardier\",\"title\":\"교황청의 겨자 담당관\",\"hook\":\"아비뇽의 교황 요한 22세는 겨자가 너무 좋아서 아예 직책을 만들었어요.\",\"body\":\"겨자를 향한 집착이 관직까지 만든 적이 있어요. 아비뇽의 교황 요한 22세는 식사에 쓸 겨자를 제대로 만들라며 교황의 겨자 담당관이라는 자리를 교황청에 두었습니다. 그보다 앞서 샤를마뉴는 모의 수도사들에게 겨자씨를 직접 기르고 갈아 바치라고 명했고, 그 계보가 지금도 도기 항아리에 담겨 팔리는 모 겨자로 이어져요. 프랑스 정부는 1390년에 겨자 제조 규정을 만들어 두었고, 1634년 루이 13세는 디종의 겨자 장인 스물세 명에게 디종 머스터드를 파는 독점권을 줬어요. 다만 '디종 머스터드'는 지금도 샴페인이나 로크포르와 달리 원산지 보호를 받지 않는 이름이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"중세~18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bonjourparis.com\",\"sourceUrl\":\"https://bonjourparis.com/history/the-rules-of-mustard/\"},{\"id\":\"bstory-mustard-triangle-of-u\",\"title\":\"우장춘이 그린 삼각형\",\"hook\":\"갓이 어디서 왔는지를 삼각형 하나로 정리한 사람은 우장춘이에요.\",\"body\":\"김치에 넣는 갓의 학명은 브라시카 융케아예요. 이 식물의 족보를 그린 사람이 우장춘이에요. 1935년, 일본에서 '우 나가하루'라는 이름으로 활동하던 그는 배추속 작물들의 관계를 삼각형 하나로 정리해 발표했어요. 꼭짓점에는 배추와 흑겨자와 양배추 세 종이 놓이고, 변에는 두 종이 합쳐져 생겨난 세 종이 놓여요. 배추와 흑겨자가 만나면 갓, 배추와 양배추가 만나면 유채, 흑겨자와 양배추가 만나면 에티오피아겨자가 되는 식이죠. 갓은 염색체가 2n=36인 사배체이고, 두 조상이 만난 시점은 3만 9천 년에서 5만 5천 년 전으로 추정돼요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본·한국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Triangle_of_U\"}]},\"9-9\":{\"photo\":{\"src\":\"/birth/gaetgaemichwi.jpg\",\"thumbSrc\":\"/birth/thumbs/gaetgaemichwi.jpg\",\"author\":\"Le.Loup.Gris\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Tripolium_pannonicum_(flowers).jpg\",\"familyLine\":\"바닷바람이 닿는 갯가에서 자라요. 소금기를 견디려고 잎을 도톰하게 채워 두는 쪽을 택했어요.\"},\"stories\":[{\"id\":\"bstory-sea-aster-salt-sacrifice-leaf\",\"title\":\"잎 한 장에 소금을 몰아넣어요\",\"hook\":\"남는 소금을 전부 잎 한 장에 밀어 넣고, 다 차면 그 잎을 통째로 버려요.\",\"body\":\"갯개미취는 밀물에 잠기는 갯벌에서 살아요. 문제는 소금을 어떻게 견디느냐인데, 방법이 대담합니다. 남아도는 소금을 몸 전체에 흩어놓지 않고 잎 한 장에 몰아넣거든요. 그 잎은 노랗거나 불그스름하게 변하고 두꺼워지면서 쭈글쭈글해져서 멀리서도 금방 구별돼요. 소금 창고 노릇을 다 하면 식물은 그 잎을 떨궈 버리고 다른 잎을 새 창고로 지정합니다. 네덜란드에서는 이 잎을 람소르라 부르며 채소로 먹는데, 꽃대가 올라오기 전인 4월부터 7월까지가 수확철이에요. 암스테르담의 북해운하와 에이 강가에서도 자랍니다.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"mediamatic.net\",\"sourceUrl\":\"https://www.mediamatic.net/en/page/387439/sea-aster\"},{\"id\":\"bstory-sea-aster-mining-bee\",\"title\":\"이 꽃에만 기대는 벌\",\"hook\":\"8월에 땅에서 나오는 벌 한 종은, 갯개미취 개화 시기에 몸을 맞췄어요.\",\"body\":\"갯개미취에 기대어 사는 벌이 있어요. 이름부터 '갯개미취 광부벌', 학명은 콜레테스 할로필루스예요. 이 벌은 8월에 땅에서 나오는데, 갯개미취가 꽃을 피우는 시기에 정확히 맞춰져 있어요. 나온 벌들은 이 꽃에서 꽃가루와 꿀을 모아 새끼를 먹여요. 세계적으로는 북해 연안에만 사는 벌이고, 영국에서는 이스트앵글리아와 템스강 하구가 중요한 서식지예요. 기후변화와 해수면 상승으로 염습지가 줄고 개발 압력이 겹치면서 처지가 나빠졌고요. 2013년 곤충보전단체 버그라이프는 이 벌이 자연 서식지뿐 아니라 사람이 만든 관리 초지나 모래 더미에도 둥지를 튼다는 걸 확인했어요. 먹이가 되는 꽃과 둥지 자리, 두 가지만 함께 있으면 된다는 거였죠.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"buglife.org.uk\",\"sourceUrl\":\"https://www.buglife.org.uk/projects/sea-aster-mining-bee/\"}]},\"9-10\":{\"stories\":[]},\"9-11\":{\"photo\":{\"src\":\"/birth/alroe.jpg\",\"thumbSrc\":\"/birth/thumbs/alroe.jpg\",\"author\":\"Philmarin\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:A.vera-suzana-1.jpg\",\"familyLine\":\"잎을 자르면 맑은 젤이 배어 나와요. 사막에서 물을 아끼려고 잎 안쪽에 저장고를 만들어 둔 거예요.\"},\"stories\":[{\"id\":\"bstory-aloe-arabian-homeland\",\"title\":\"500종 중에 왜 하필 이 한 종일까\",\"hook\":\"알로에는 500종이 넘는데, 시장을 가져간 건 사실상 한 종이에요.\",\"body\":\"알로에속에는 500종이 넘는 식물이 있어요. 2015년 BMC 진화생물학에 실린 연구에 따르면 그중 4분의 1쯤, 약 120종이 어딘가에서 약으로 쓰입니다. 그런데 실제로 상업 거래되는 건 열 종이 채 안 되고, 그중에서도 알로에 베라 한 종이 시장을 거의 다 가져갔어요. 영국 큐 왕립식물원과 코펜하겐 대학이 이끈 연구진이 계통수를 그려 보고 뜻밖의 위치를 확인했습니다. 알로에 베라는 아프리카가 아니라 아라비아반도 쪽 계통이고, 가장 가까운 친척 일곱 종이 모두 그 반도, 곧 알로에 분포의 최북단에 살고 있었어요. 연구진은 이 종이 이긴 이유로 약효가 아니라 홍해와 지중해를 잇는 옛 교역로 곁에 자랐다는 점을 들었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아라비아\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4342203/\"},{\"id\":\"bstory-aloe-4000-years\",\"title\":\"4천 년짜리 처방전\",\"hook\":\"기원전 2100년 점토판부터 1959년 FDA 승인까지, 같은 잎이 계속 등장해요.\",\"body\":\"알로에가 약으로 쓰인 기록은 무섭도록 오래됐어요. 기원전 2100년 무렵 메소포타미아 점토판이 알로에를 치유력 있는 식물로 적은 첫 기록으로 꼽히고, 기원전 1550년경 이집트의 에베르스 파피루스에는 안팎의 병에 쓰는 알로에 처방이 여럿 실려 있어요. 서기 70년쯤 디오스코리데스는 상처와 탈모, 궤양, 치질에 쓰라고 적었고요. 근대로 오면 1820년 미국 약전이 알로에를 완하제이자 피부 보호제로 올렸고, 1935년 콜린스 부부는 심한 방사선 피부염 환자에게 생잎을 붙여 가려움과 화끈거림이 빠르게 가라앉았다는 첫 증례를 보고했어요. 1959년에는 미국 FDA가 화상용 일반의약품 연고로 알로에를 승인했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이집트·미국\"},{\"key\":\"era\",\"text\":\"고대~20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/books/NBK92765/\"}]},\"9-12\":{\"photo\":{\"src\":\"/birth/keulrematiseu.jpg\",\"thumbSrc\":\"/birth/thumbs/keulrematiseu.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Clematis_terniflora_s4.jpg\",\"familyLine\":\"꽃잎처럼 보이는 흰 조각은 사실 꽃받침이에요. 진짜 꽃잎은 일찌감치 포기하고 꽃받침에 그 역할을 맡겼어요.\"},\"stories\":[{\"id\":\"bstory-clematis-beggars-plant\",\"title\":\"나그네의 기쁨, 거지의 풀\",\"hook\":\"같은 덩굴이 여행자에게는 기쁨이고 걸인에게는 상처를 내는 도구였어요.\",\"body\":\"클레마티스 비탈바에는 정반대인 이름이 둘 있어요. 하나는 나그네의 기쁨입니다. 1597년 존 제라드가 자신의 영국 약초서에서 붙인 이름인데, 길가와 산울타리를 뒤덮으며 그늘과 향기를 내주는 모습을 보고 지었어요. 다른 하나는 프랑스어 에르브 오 괴, 거지의 풀이에요. 이 덩굴의 즙이 살을 무르게 하는 성질이 있어서, 파리의 걸인들이 동정을 얻으려고 일부러 궤양 같은 상처를 내는 데 썼다고 해서 붙은 이름입니다. 정작 제라드 본인은 이 풀에서 아무 약효도 찾지 못했다고 적었고, 잎에는 약한 독성이 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스·잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"treesandshrubsonline.org\",\"sourceUrl\":\"https://www.treesandshrubsonline.org/articles/clematis/clematis-vitalba/\"},{\"id\":\"bstory-clematis-jackmanii\",\"title\":\"실생묘 300포기에서 나온 한 그루\",\"hook\":\"정원의 그 보라색 클레마티스는 1858년 워킹의 실생묘 300포기에서 나왔어요.\",\"body\":\"오늘날 정원에서 흔히 보는 큼직한 보라색 클레마티스는 대개 한 그루의 후손이에요. 1810년 윌리엄 잭맨이 영국 서리주 워킹에 50에이커짜리 묘목장을 열었고, 1830년 아들 조지가 뒤를 이었어요. 1858년 조지 잭맨 부자는 클레마티스 교배에 손을 댔는데, 첫 실생묘 300포기 가운데서 '클레마티스 잭마니'가 나왔어요. 1863년 영국 왕립원예협회 화훼위원회가 여기에 1등급 증서를 줬죠. 1872년에는 조지 잭맨 2세가 클레마티스만 다룬 첫 책을 냈고, 1923년 잭맨 묘목장 카탈로그에는 품종 서른여섯 가지가 실렸어요. 묘목장은 1960년 메이퍼드로 옮겼다가 1967년에 팔렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"wokingnewsandmail.co.uk\",\"sourceUrl\":\"https://www.wokingnewsandmail.co.uk/news/how-woking-flowered-into-a-famous-name-for-plant-lovers-578475\"}]},\"9-13\":{\"photo\":{\"src\":\"/birth/beodeunamu.jpg\",\"thumbSrc\":\"/birth/thumbs/beodeunamu.jpg\",\"author\":\"Medium69 (William Crochot)\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Salix_babylonica_(Saule_pleureur)_-_20150810_10h23_(11045).jpg\",\"familyLine\":\"가지가 아래로 흐르듯 늘어져요. 물가에 서서 수면에 닿을 만큼 길게 드리우는 게 이 나무의 습관이에요.\"},\"stories\":[{\"id\":\"bstory-willow-napoleon-tomb\",\"title\":\"세상에서 가장 많이 뜯긴 나무\",\"hook\":\"나폴레옹 무덤가 버드나무는 기념품 사냥꾼들에게 그루터기만 남을 만큼 뜯겼어요.\",\"body\":\"나폴레옹이 묻힌 세인트헬레나 섬 무덤가에는 버드나무가 있었어요. 그리고 그 나무는 곧 세상에서 가장 많이 뜯긴 나무가 됐죠. 1848년 이 섬을 찾은 사람은 기념품 사냥꾼들이 잎과 가지를 죄다 훑어 가서 나무가 그루터기만 남았고, 그때마다 원래 나무에서 꺾어 기른 묘목으로 다시 채워 넣었다고 적었어요. 그렇게 실려 나간 가지들은 캐나다에서 호주와 뉴질랜드까지 대영제국 곳곳에 다시 심겼어요. 영국 안에서만 해도 치체스터 주교관 정원, 웨스트민스터 사원 경내, 첼트넘 넵튠 분수 곁에 그 후손이 있었고, 서퍽 우드브리지의 나무는 1909년 학교를 짓느라 베였어요. 19세기 그림 중에는 줄기 사이에 황제의 옆모습을 숨겨 그린 것도 있고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"세인트헬레나\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"uk-sthelenaheritagetrust.org\",\"sourceUrl\":\"https://www.uk-sthelenaheritagetrust.org/post/the-world-of-napoleon-s-willows\"},{\"id\":\"bstory-willow-babylonica-misnomer\",\"title\":\"바빌론에 가 본 적 없는 학명\",\"hook\":\"수양버들의 학명은 성경 구절을 잘못 읽은 결과예요.\",\"body\":\"수양버들의 학명 살릭스 바빌로니카에는 잘못 꿴 첫 단추가 들어 있어요. 1753년 린네가 이 이름을 붙일 때, 그는 이 나무가 중동에서 왔다고 믿었어요. 시편 137편에서 바빌론에 끌려간 히브리 사람들이 시온을 그리며 버드나무 아래 울었다는 구절 때문이었죠. 나중에 밝혀진 사실은 두 가지였어요. 바빌론 강가의 그 버드나무는 사실 포플러의 한 종이었고, 수양버들의 고향은 중동이 아니라 중국 북부였다는 거예요. 그러니까 이 나무는 학명이 가리키는 땅에 자생한 적이 없어요. 그래도 이름은 그대로 남아, 지금도 전 세계 도감이 살릭스 바빌로니카라고 적고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"libraryexhibits.uvm.edu\",\"sourceUrl\":\"https://libraryexhibits.uvm.edu/omeka/exhibits/show/uvmtrees/weeping-willow-introduction/weeping-willow-history\"}]},\"9-14\":{\"photo\":{\"src\":\"/birth/mareumelro.jpg\",\"thumbSrc\":\"/birth/thumbs/mareumelro.jpg\",\"author\":\"Ввласенко\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Blooming_quince_(Cydonia_oblonga).jpg\",\"familyLine\":\"열매는 딱딱하고 시어서 그냥은 못 먹어요. 대신 향이 진해 방 안에 하나만 두어도 며칠씩 향이 남아요.\"},\"stories\":[{\"id\":\"bstory-quince-solon-bride\",\"title\":\"신부가 마르멜로를 깨무는 법\",\"hook\":\"아테네의 입법가 솔론은 신부가 침실에 들기 전 마르멜로를 먹게 하는 규정을 남겼어요.\",\"body\":\"플루타르코스가 쓴 솔론 전기 20장에는 이상한 조항이 하나 나와요. 상속녀의 혼인을 다루는 대목에서, 신부가 마르멜로 열매를 먹고 신랑과 함께 방에 갇혀야 한다는 요구가 솔론의 법으로 소개돼요. 혼인을 형식상 성립시키는 절차의 하나로 기록된 규정이에요. 로마 시대 전기 작가가 수백 년 뒤에 정리한 글이라 세부는 확실하지 않고, 적용 범위도 모든 혼인이 아니라 상속녀 쪽에 걸려 있어요. 그래도 딱딱하고 시큼해서 날로는 먹기 힘든 이 열매가 결혼의 문턱에 놓여 있었다는 사실만은 또렷하게 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"penelope.uchicago.edu\",\"sourceUrl\":\"https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Plutarch/Lives/Solon*.html\"},{\"id\":\"bstory-quince-marmalade-1480\",\"title\":\"마멀레이드의 진짜 첫 재료\",\"hook\":\"1480년 엑서터 상인이 쓴 편지 한 통이 이 단어의 영어 첫 기록이에요.\",\"body\":\"영어 마멀레이드는 원래 오렌지가 아니라 마르멜로에서 온 말이에요. 포르투갈어 마르멜라다가 마르멜로 잼을 뜻했고, 그 어근인 마르멜루가 곧 마르멜로거든요. 계보를 더 거슬러 가면 후기 라틴어와 그리스어의 사과와 꿀에 닿아요. 영어에 처음 기록된 것은 1480년 5월 13일 편지로, 엑서터의 상인 리처드 저민이 윌리엄 스토너에게 존 시먼이 엑서터에서 당신에게 오렌지와 마르멜레이트를 주었다고 적었어요. 두 번째로 이른 기록은 1514년 메리 튜더의 프랑스행 문서에 나와요. 당시 마멀레이드는 장미수나 사향으로 향을 낸 단단한 마르멜로 젤리를 네모나게 썰어 낸 과자였어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드·포르투갈\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"wordhistories.net\",\"sourceUrl\":\"https://wordhistories.net/2018/03/12/marmalade-portuguese-origin/\"}]},\"9-15\":{\"stories\":[]},\"9-16\":{\"photo\":{\"src\":\"/birth/yongdam.jpg\",\"thumbSrc\":\"/birth/thumbs/yongdam.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Gentiana_scabra_var._buergeri_(flower_s3).JPG\",\"familyLine\":\"해가 있을 때만 꽃을 열어요. 흐리거나 저물면 다시 오므려서 안쪽을 지켜요.\"},\"stories\":[{\"id\":\"bstory-gentian-king-gentius\",\"title\":\"왕의 이름이 붙은 쓴 뿌리\",\"hook\":\"속명 겐티아나는 기원전 2세기 일리리아의 마지막 왕 겐티우스에게서 왔어요.\",\"body\":\"용담속의 학명 겐티아나는 사람 이름이에요. 1931년에 나온 약초 사전은 플리니우스와 디오스코리데스를 근거로, 기원전 180년부터 167년까지 재위한 일리리아의 왕 겐티우스가 이 뿌리의 약효를 발견했다고 적어 두었어요. 노란용담의 뿌리는 보통 길이 30센티미터에 굵기 2.5센티미터쯤이지만, 때로는 1야드가 넘게 자라고 굵기도 5센티미터에 이른대요. 중세에는 독을 푸는 해독제로 쓰였고, 홉이 쓰이기 전에는 맥주에 쓴맛을 내는 재료로 이 뿌리를 넣었어요. 18세기에는 식전주로 용담 술을 마셨다는 기록도 함께 실려 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스·로마\"},{\"key\":\"era\",\"text\":\"고대~18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://www.botanical.com/botanical/mgmh/g/gentia08.html\"},{\"id\":\"bstory-gentian-devils-pitchfork\",\"title\":\"악마의 쇠스랑으로 캐는 뿌리\",\"hook\":\"용담 리큐어 한 병을 위해 7~10년 자란 뿌리를 특수한 갈래 삽으로 캐내야 해요.\",\"body\":\"프랑스에서 용담은 술이 되는 식물이에요. 1885년 프랑스에서 시작된 용담 리큐어는 지금도 대표적인 식전주로 남아 있는데, 향과 쓴맛의 원천은 오직 노란용담의 뿌리예요. 문제는 이 뿌리가 쉽게 얻어지지 않는다는 거예요. 심은 뒤 수확할 만큼 자라는 데만 7년에서 10년이 걸리고, 땅속 깊이 박힌 뿌리를 통째로 뽑으려면 겅사네르라 불리는 전문 채취꾼들이 악마의 쇠스랑이라는 이름이 붙은 특수한 갈래 삽을 써야 해요. 지금은 야생 용담 채취가 엄격하게 관리되고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"19세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"diffordsguide.com\",\"sourceUrl\":\"https://www.diffordsguide.com/beer-wine-spirits/category/1295/gentian-liqueurs\"}]},\"9-17\":{\"photo\":{\"src\":\"/birth/erika.jpg\",\"thumbSrc\":\"/birth/thumbs/erika.jpg\",\"author\":\"Robert Flogaus-Faust\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Erica_carnea_3_RF.jpg\",\"familyLine\":\"겨울 끝자락 눈 사이에서도 꽃을 피워요. 항아리처럼 오므린 꽃 모양이 추위를 견디는 방식이에요.\"},\"stories\":[{\"id\":\"bstory-erica-verticillata-return\",\"title\":\"야생에서 멸종한 에리카의 귀환\",\"hook\":\"야생에서 사라졌다던 에리카 베르티킬라타가 1984년 프리토리아의 한 공원에서 다시 발견됐어요.\",\"body\":\"남아프리카 케이프의 에리카 베르티킬라타는 20세기 후반에 야생에서 절멸했다고 판정된 식물이에요. 그런데 1984년, 프리토리아의 한 공원에서 살아 있는 개체가 나오면서 이야기가 뒤집혔어요. 커스텐보스 식물원이 이 나무를 받아 다시 길렀고 1990년에는 식물원 안에서 다른 계통 둘이 더 확인됐어요. 빈의 벨베데레 궁전 컬렉션에서 온 계통은 1796년에서 1799년 사이 조지 숄이 채집한 것까지 거슬러 올라가요. 지금은 론데블레이 자연보호구, 케닐워스 경마장 보전구역, 토카이 공원 세 곳에 다시 심겼지만 공식 등급은 여전히 야생 절멸이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"남아프리카\"},{\"key\":\"era\",\"text\":\"20세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pza.sanbi.org\",\"sourceUrl\":\"https://pza.sanbi.org/erica-verticillata\"},{\"id\":\"bstory-erica-white-heather-luck\",\"title\":\"흰 헤더가 목숨을 구했다는 말\",\"hook\":\"컬로든에서 도망친 족장은 흰 헤더 덤불 위에서 잠든 덕에 살아남았다고 했어요.\",\"body\":\"스코틀랜드에서 흰 헤더는 행운의 표시예요. 1544년 클랜 라날드는 보닛에 흰 헤더를 꽂고 싸워 이겼다며 승리를 그 꽃 덕으로 돌렸고, 클루니 맥퍼슨은 컬로든 전투 뒤 흰 헤더 덤불 위에서 잠든 덕에 수색대가 자신을 못 보고 지나쳤다고 했어요. 1884년 빅토리아 여왕은 시종 브라운이 흰 헤더를 찾아낸 일을 적으면서 하일랜더라면 누구도 그것을 그냥 지나치지 않는다고 썼어요. 헤더의 속명 칼루나는 쓸다라는 뜻의 그리스어에서 왔고, 실제로 오랫동안 빗자루 재료로 쓰였어요. 마른 헤더는 매트리스 틀을 채우거나 지붕을 이거나 바닷물에 견디는 밧줄을 꼬는 데도 썼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"treesforlife.org.uk\",\"sourceUrl\":\"https://treesforlife.org.uk/into-the-forest/trees-plants-animals/plants/heather/heather-mythology-and-folklore/\"}]},\"9-18\":{\"photo\":{\"src\":\"/birth/eonggeongkwi.jpg\",\"thumbSrc\":\"/birth/thumbs/eonggeongkwi.jpg\",\"author\":\"TANAKA Juuyoh (田中十洋)\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanese_Thistle_Cirsium_japonicum_bud-flower.jpg\",\"familyLine\":\"가시는 잎에만 있고 꽃에는 없어요. 먹히지 않으려는 방어와 벌을 부르려는 초대를 한 몸에 나눠 두었어요.\"},\"stories\":[{\"id\":\"bstory-thistle-order-1687\",\"title\":\"나를 건드리면 무사하지 못한다\",\"hook\":\"스코틀랜드 최고 훈장의 좌우명은 \\\"누구도 나를 무사히 건드리지 못한다\\\"예요.\",\"body\":\"엉겅퀴는 스코틀랜드 왕실 훈장의 이름이 됐어요. 시슬 훈장의 기원은 확정돼 있지 않은데, 영국 왕실 공식 설명은 809년 아카이우스 왕이 샤를마뉴와 동맹을 맺으며 만들어졌다는 전설과 함께, 엉겅퀴를 왕실 식물 배지로 채택한 제임스 3세를 나란히 언급해요. 제도로 확립된 건 1687년이에요. 제임스 7세가 새 규정을 두고 법적 기반을 갖추면서예요. 좌우명은 라틴어로 네모 메 임푸네 라케시트, 누구도 나를 무사히 건드리지 못한다는 뜻이에요. 기사는 열여섯 명이고, 예배당은 에든버러 세인트자일스 대성당 안의 시슬 채플이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"중세~17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"royal.uk\",\"sourceUrl\":\"https://www.royal.uk/the-order-of-the-thistle\"},{\"id\":\"bstory-thistle-dunbar-thrissill\",\"title\":\"엉겅퀴와 장미, 1503년\",\"hook\":\"1503년 시인 던바는 스코틀랜드를 엉겅퀴로, 잉글랜드를 장미로 세운 우화시를 썼어요.\",\"body\":\"엉겅퀴가 스코틀랜드의 상징이 된 과정은 전설보다 문서에서 또렷해요. 1931년 약초 사전은 문장으로서 가장 이른 기록으로 제임스 3세가 남긴 재산 목록을 꼽아요. 거기에 스리슬스, 곧 엉겅퀴를 수놓은 벽걸이가 올라 있었다는 거예요. 뒤이어 1503년에는 시인 윌리엄 던바가 제임스 4세와 잉글랜드 마거릿 공주의 혼인을 노래한 우화시 엉겅퀴와 장미를 썼어요. 스코틀랜드를 엉겅퀴로, 잉글랜드를 장미로 세운 이 시로 상징은 왕실 밖까지 퍼졌어요. 같은 책은 국화로 여겨지는 종을 스코치 시슬, 곧 오노포르둠 아칸티움으로 지목해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"15세기~16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://www.botanical.com/botanical/mgmh/t/thistl11.html\"}]},\"9-19\":{\"photo\":{\"src\":\"/birth/sacho.jpg\",\"thumbSrc\":\"/birth/thumbs/sacho.jpg\",\"author\":\"Julia Kruse\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Carex_pendula_inflorescens_(57).jpg\",\"familyLine\":\"꽃잎이 아예 없어요. 벌 대신 바람을 부르기로 하고 꾸미는 일을 통째로 그만둔 쪽이에요.\"},\"stories\":[{\"id\":\"bstory-carex-sami-shoe-grass\",\"title\":\"순록가죽 신발 속의 사초\",\"hook\":\"사미 사람들은 순록가죽 신발 안을 사초로 채워 북극의 겨울을 났어요.\",\"body\":\"북유럽 사미 사람들에게 사초는 신발 재료였어요. 2015년 민족식물학 학술지에 실린 노르웨이 조사 논문에 따르면, 가마스수오이드니 곧 신발 풀이라 불리는 사초속 식물들이 코마게르라는 가죽 신발 안을 채웠어요. 한 제보자는 다른 재료를 두고 신발 풀보다 훨씬 따뜻하다고 비교하기도 했고요. 겨울용과 여름용 신발에 쓰는 사초의 등급도 달랐다고 기록돼 있어요. 사미어에서는 사초와 향기풀을 모두 수오인닛이라는 한 갈래로 묶지만 쓰임은 갈렸어요. 사초는 보온, 향기풀은 향과 좀벌레 쫓기였어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"사프미·노르웨이\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC4690224/\"},{\"id\":\"bstory-carex-etchu-sugegasa\",\"title\":\"600년째 사초를 꿰매는 삿갓 마을\",\"hook\":\"규격에 재료 식물의 학명까지 못 박아 둔 일본 삿갓이 있어요.\",\"body\":\"일본 도야마현에는 1400년대부터 이어진 삿갓 공예 엣추 후쿠오카노 스게가사가 있어요. 다카오카시, 도나미시, 오야베시, 난토시 일대에서 만드는데, 규격상 재료는 사초속의 카레크스 야포니카나 그와 같은 성질을 가진 풀이어야 해요. 대나무로 우산살 같은 뼈대를 짠 다음 사초를 한 땀씩 꿰매 붙이고, 정수리에서 겹치는 부분을 얇게 다듬어 바깥 테두리 뼈대에 끼워 넣은 뒤 실로 조여 마무리해요. 에도 시대에 가가번이 생산을 장려하면서 일본 전역으로 퍼졌고, 지금도 농사일과 전통 축제에서 써요. 2017년 11월 30일에는 국가 전통적 공예품으로 지정됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"kougeihin.jp\",\"sourceUrl\":\"https://kougeihin.jp/en/craft/1419/\"}]},\"9-20\":{\"photo\":{\"src\":\"/birth/rojeumeri.jpg\",\"thumbSrc\":\"/birth/thumbs/rojeumeri.jpg\",\"author\":\"Daniel VILLAFRUELA\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rosmarinus_officinalis-Romarin_cultiv%C3%A9-Fleurs-20201009.jpg\",\"familyLine\":\"잎을 스치기만 해도 향이 손에 남아요. 바닷가 절벽에서 마르지 않으려고 기름을 품은 결과가 그 향이에요.\"},\"stories\":[{\"id\":\"bstory-rosemary-ophelia-remembrance\",\"title\":\"오필리아가 건넨 로즈메리\",\"hook\":\"\\\"여기 로즈메리가 있어요, 기억을 위한 것이에요\\\" — 오필리아의 대사예요.\",\"body\":\"셰익스피어 햄릿 4막 5장에서 정신을 놓은 오필리아는 사람들에게 풀과 꽃을 하나씩 나눠 줘요. 첫 번째가 로즈메리예요. 여기 로즈메리가 있어요, 기억을 위한 것이에요, 부디 사랑하는 이여 기억해 주세요. 이어서 생각을 뜻하는 팬지를 건네고, 회향과 매발톱꽃을 넘기고, 일요일의 은총초라 부르는 운향을 나눠요. 마지막에는 데이지를 내밀며 이렇게 말해요. 제비꽃도 드리고 싶지만 아버지가 돌아가셨을 때 모두 시들어 버렸다고요. 로즈메리를 기억의 풀로 못 박은 이 장면은 지금도 가장 많이 인용되는 꽃 대사예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기~17세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"shakespeare.mit.edu\",\"sourceUrl\":\"http://shakespeare.mit.edu/hamlet/hamlet.4.5.html\"},{\"id\":\"bstory-rosemary-anzac-gallipoli\",\"title\":\"갈리폴리 언덕에 자라던 풀\",\"hook\":\"안작 데이에 다는 로즈메리 가지는 갈리폴리에 야생으로 자라던 바로 그 풀이에요.\",\"body\":\"오스트레일리아와 뉴질랜드 사람들은 안작 데이가 되면 옷깃에 로즈메리 가지를 꽂아요. 오스트레일리아 전쟁기념관은 그 이유를 두 겹으로 설명해요. 하나는 오래된 믿음이에요. 이 향기로운 풀이 기억력을 좋게 한다고 예부터 여겨졌고, 그래서 문학과 민간전승에서 신의와 추모의 상징이 됐다는 거예요. 다른 하나는 지리예요. 안작 부대가 싸운 갈리폴리반도에 로즈메리가 야생으로 자라고 있었거든요. 그래서 로즈메리는 이 나라 사람들에게 특별한 뜻을 갖게 됐고, 지금도 추모일이면 레거시와 RSL 같은 재향군인 단체가 로즈메리 가지를 나눠 줘요.\",\"notes\":[{\"key\":\"region\",\"text\":\"오스트레일리아·튀르키예\"},{\"key\":\"era\",\"text\":\"20세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"awm.gov.au\",\"sourceUrl\":\"https://www.awm.gov.au/commemoration/customs-and-ceremony/rosemary\"}]},\"9-21\":{\"photo\":{\"src\":\"/birth/sapeuran.jpg\",\"thumbSrc\":\"/birth/thumbs/sapeuran.jpg\",\"author\":\"Zeynel Cebeci\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Crocus_sativus_-_Saffron_crocus_-_Safran_03.JPG\",\"familyLine\":\"꽃 한 송이에서 붉은 암술 세 가닥만 거둬요. 그래서 향신료 중에 가장 값이 비싼 자리에 있어요.\"},\"stories\":[{\"id\":\"bstory-autumn-crocus-byzantine-gout\",\"title\":\"독초를 통풍약으로 바꾼 5세기 의사들\",\"hook\":\"황제의 주치의는 이 독초로 고약을 개어 부어오른 관절에 붙이라고 했어요.\",\"body\":\"콜키쿰은 처음에 약이 아니라 독으로 기록됐어요. 1세기 디오스코리데스가 이 식물을 언급하기는 했지만 강한 독성을 강조했거든요. 그런데 5세기 비잔티움에서 판이 바뀌어요. 의철학자 세베루스 이아트로소피스타가 헤르모닥틸, 곧 콜키쿰을 통풍 치료에 처음 끌어들였고, 같은 시기 학자 테오도시우스도 같은 식물을 통풍 약초로 제안했어요. 레오 1세 황제의 주치의였던 야코부스 프시크레스토스는 이 풀로 끈적한 고약을 만들어 부어오른 관절에 붙이라고 권했어요. 흔히 콜키쿰을 통풍 치료에 도입한 사람으로 알려진 알렉산드로스 트랄레스는 사실 헤르모닥틸이 든 처방 여섯 가지를 남기면서 그 공을 앞의 세 사람에게 돌렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"비잔티움\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC7046033/\"},{\"id\":\"bstory-autumn-crocus-wild-garlic-poisoning\",\"title\":\"뿌리 하나와 잎 셋으로 끓인 차\",\"hook\":\"산마늘로 착각해 끓인 차 500밀리리터에 콜히친이 최소 10밀리그램 들어 있었어요.\",\"body\":\"2026년 학술지 톡식스에 실린 증례 보고는 이 식물이 왜 무서운지 보여 줘요. 한 환자가 콜키쿰을 산마늘로 착각해, 뿌리 하나와 잎 세 장으로 차 500밀리리터를 끓여 마셨어요. 연구진이 추정한 콜히친 섭취량은 최소 10밀리그램, 많으면 40밀리그램이 넘어요. 6시간 뒤 복통과 구토와 심한 설사가 시작됐고, 24시간째에는 착란과 어눌한 말이 겹쳤으며, 사흘째에는 급성 심장 기능 저하로 호흡 보조를 받았어요. 이 환자는 7일 만에 회복해 퇴원했지만, 논문이 인용한 이전 사례 열아홉 건 가운데 열 건은 사망이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13120402/\"}]},\"9-22\":{\"photo\":{\"src\":\"/birth/kweiking-geuraseu.jpg\",\"thumbSrc\":\"/birth/thumbs/kweiking-geuraseu.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Briza_media_-_keskmine_v%C3%A4rihein.jpg\",\"familyLine\":\"작은 이삭이 실 같은 자루에 매달려 바람만 스쳐도 떨려요. 이름도 그 떨림에서 왔어요.\"},\"stories\":[{\"id\":\"bstory-quaking-grass-many-names\",\"title\":\"별명이 스무 개 넘는 풀\",\"hook\":\"영국에서 이 풀은 '지진', '덜덜', '귀부인의 머리카락'으로 제각각 불려 왔어요.\",\"body\":\"퀘이킹 그라스는 이름 부자예요. 영국 왕립원예협회가 이 풀의 다른 이름으로 적어 둔 것만 해도 카우 퀘이크, 디더, 디더링 그라스, 도더 그라스, 도더링 딜리스, 도들 그라스, 어스퀘이크스, 지글조글스, 조키 그라스, 레이디스 헤어가 줄줄이 이어지고, 퀘이크 그라스와 셰이킹 그라스도 따로 있어요. 어스퀘이크스는 지진, 레이디스 헤어는 귀부인의 머리카락이라는 뜻이에요. 이유는 하나예요. 가느다란 꽃대 끝에 하트 모양 작은 이삭이 매달려 바람만 스쳐도 쉬지 않고 떨리거든요. 사람마다 그 떨림을 다르게 흉내 내다 보니 이름이 이렇게 불어났어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"rhs.org.uk\",\"sourceUrl\":\"https://www.rhs.org.uk/plants/2406/briza-media/details\"},{\"id\":\"bstory-quaking-grass-617-tetrads\",\"title\":\"617칸 중 213칸에 있던 풀\",\"hook\":\"1979년 조사에서 213개 구역에 있던 이 풀이 지금은 지역 희귀식물 목록에 올라 있어요.\",\"body\":\"퀘이킹 그라스는 마른 중성 또는 석회질 풀밭에서 자라요. 영국 레스터셔의 자연 기록 사이트에 따르면, 1979년에 나온 지역 식물지는 이 풀을 레스터셔 617개 조사 구역 가운데 213곳, 러틀랜드에서는 43곳에서 확인했어요. 지금은 사정이 달라졌어요. 서식지가 사라지면서 개체가 줄었고 지역 희귀식물 목록에 이름이 올랐거든요. 대신 이 풀은 레스터셔·레스터·러틀랜드 자연회복전략의 지표종으로 지정됐어요. 이 풀이 떨고 있는지 아닌지가 그 풀밭의 상태를 재는 잣대가 된 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"20세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"naturespot.org\",\"sourceUrl\":\"https://www.naturespot.org/species/quaking-grass\"}]},\"9-23\":{\"photo\":{\"src\":\"/birth/jumok.jpg\",\"thumbSrc\":\"/birth/thumbs/jumok.jpg\",\"author\":\"Photo (c)2007 Derek Ramsey (Ram-Man)\",\"license\":\"CC BY-SA 2.5\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanese_Yew_Taxus_cuspidata_Leaf_Closeup_3008px.jpg\",\"familyLine\":\"살아 천 년 죽어 천 년이라는 말이 붙은 나무예요. 붉은 열매만 달고 씨앗에는 독을 숨겨 두었어요.\"},\"stories\":[{\"id\":\"bstory-yew-mary-rose-longbows\",\"title\":\"바닷속에서 올라온 장궁 172자루\",\"hook\":\"1545년 침몰선에서 건진 주목 장궁은 연대가 확실한 유일한 궁술 유물군이에요.\",\"body\":\"헨리 8세의 기함 메리로즈호에서는 주목으로 만든 장궁 172자루가 올라왔어요. 배의 목록에는 250자루가 적혀 있었고, 이 유물들은 어느 시대를 통틀어도 연대가 정확히 특정되는 유일한 궁술 유물군이에요. 활은 모두 주목 한 토막으로 깎았는데, 단단한 심재와 잘 휘는 변재의 경계를 그대로 살려 천연 용수철처럼 만들었어요. 활 길이는 1839밀리미터에서 2113밀리미터 사이이고, 당기는 힘은 65파운드에서 175파운드까지 흩어지며 110파운드에 가장 몰려 있어요. 완전한 화살 2천여 개와 파편 7천여 점, 가죽 팔보호대 스물네 점도 함께 나왔는데 그중 두 점에는 아라곤의 캐서린과 헨리 8세의 문장이 나란히 새겨져 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"maryrose.org\",\"sourceUrl\":\"https://maryrose.org/discover/collections/the-weaponry-of-the-mary-rose/longbows-and-arrows/\"},{\"id\":\"bstory-yew-fortingall-sex-switch\",\"title\":\"수그루 노거수에 열린 붉은 열매 세 알\",\"hook\":\"5천 년 묵었을지 모르는 수그루 주목이 2015년에 가지 하나만 암그루가 됐어요.\",\"body\":\"퍼스셔 포팅걸 교회 마당에는 5천 년까지 거슬러 올라갈지 모른다는 주목 한 그루가 서 있어요. 나이의 근거는 1769년 토머스 페넌트가 잰 둘레 56피트인데, 나이테가 남아 있지 않아 확정은 어려워요. 이 나무는 줄곧 수그루로 알려져 있었는데, 2015년 10월 12일 에든버러 왕립식물원의 맥스 콜먼이 잘 익은 붉은 열매 세 알을 땄어요. 나무 전체가 아니라 수관 바깥쪽의 작은 가지 하나가 암그루처럼 행동하고 있었던 거예요. 주목을 비롯해 암수가 나뉜 침엽수는 성을 바꾸는 사례가 관찰되는데, 보통은 수관의 일부에서만 일어나요. 콜먼은 이 열매에서 얻은 씨앗 셋을 보전용 주목 산울타리에 넣었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"stories.rbge.org.uk\",\"sourceUrl\":\"https://stories.rbge.org.uk/archives/17622\"},{\"id\":\"bstory-yew-taxol-eight-trees\",\"title\":\"환자 한 명에 주목 여덟 그루\",\"hook\":\"초창기 항암제 택솔은 환자 한 명분을 얻으려 60년 자란 주목 여덟 그루를 베어야 했어요.\",\"body\":\"1962년 식물학자 아서 바클리가 미국 기퍼드핀초 국유림에서 태평양주목의 시료를 모았어요. 워싱턴 대학교 식물원 설명에 따르면 여기서 나온 물질이 훗날 항암제 택솔이 됐어요. 문제는 원료였어요. 초기 생산 방식으로는 환자 한 명을 치료하는 데 예순 살 된 주목 여덟 그루를 베어야 했거든요. 임상시험을 거쳐 1992년 난소암 치료제로 미국 FDA 승인을 받았고, 1994년에 첫 화학 합성에 성공했지만 수율이 너무 낮았어요. 지금은 나무를 죽이지 않고 유럽주목 등의 잎을 쓰는 반합성 방식으로 만들어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanicgardens.uw.edu\",\"sourceUrl\":\"https://botanicgardens.uw.edu/about/blog/2024/10/21/plant-profile-taxus-brevifolia/\"}]},\"9-24\":{\"photo\":{\"src\":\"/birth/orenji.jpg\",\"thumbSrc\":\"/birth/thumbs/orenji.jpg\",\"author\":\"Javier martin\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Citrus_sinensis_CloseupFlowerSolanadelPino.jpg\",\"familyLine\":\"열매가 익는 동안 다음 해에 필 꽃봉오리가 같은 가지에 함께 맺혀요. 한 나무에서 꽃과 열매를 같이 보게 되는 이유예요.\"},\"stories\":[{\"id\":\"bstory-orange-victoria-1840-wreath\",\"title\":\"다이아몬드 대신 오렌지꽃 한 줄\",\"hook\":\"1840년 빅토리아 여왕은 머리에 보석 하나 없이 오렌지꽃 화관만 얹었어요.\",\"body\":\"1840년 2월 10일 빅토리아 여왕이 앨버트 공과 결혼했어요. 이튿날 더 타임스 궁정란은 여왕이 머리에 다이아몬드를 전혀 걸치지 않고 오렌지꽃 화관 하나만 썼다고 전합니다. 흰 새틴 드레스 가장자리도 오렌지꽃으로 둘렀고요. 식물학자 넬슨이 1840년부터 1913년까지 왕실 혼례 기록을 훑어보니, 여왕 본인의 결혼식에 쓰인 꽃은 오렌지꽃 단 한 종류였고 이후 일곱 번의 왕실 결혼식에 또 등장했어요. 앨버트는 결혼 전해인 1839년에 직접 도안한 브로치를 선물했는데, 금으로 만든 잎과 줄기에 흰 에나멜로 오렌지꽃 두 송이와 봉오리 두 개를 달아 둔 것이었습니다.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"빅토리아 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"heatherworld.org\",\"sourceUrl\":\"https://www.heatherworld.org/wp-content/uploads/2015/03/EC-Nelson-Vic-myrtle.pdf\"},{\"id\":\"bstory-orange-versailles-orangerie\",\"title\":\"겨울에 5도 아래로 내려가지 않는 방\",\"hook\":\"오렌지나무를 얼려 죽이지 않으려고 벽 두께 5미터짜리 건물을 지었어요.\",\"body\":\"베르사유의 오랑주리는 오렌지나무를 겨울에 얼려 죽이지 않으려고 지은 건물이에요. 1663년 루이 르 보가 처음 세웠고, 스무 해쯤 뒤 쥘 아르두앵 망사르가 길이와 폭을 두 배로 늘렸어요. 가운데 회랑은 길이가 150미터를 넘고 볼트 천장은 13미터, 벽 두께는 4~5미터예요. 여기에 이중창과 남향 배치가 더해져, 겨울에도 실내 온도가 5도 아래로 내려가지 않아요. 여름이면 3헥타르 화단에 화분 1,055개가 줄지어 나와 서죠. 오렌지나무와 야자, 협죽도, 석류가 섞여 있고, 포르투갈과 스페인과 이탈리아에서 건너온 나무들 가운데는 수령이 200년을 넘는 것도 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"en.chateauversailles.fr\",\"sourceUrl\":\"https://en.chateauversailles.fr/discover/estate/gardens/orangery\"}]},\"9-25\":{\"photo\":{\"src\":\"/birth/megwiri.jpg\",\"thumbSrc\":\"/birth/thumbs/megwiri.jpg\",\"author\":\"Stefan.lefnaer\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Avena_fatua_sl6.jpg\",\"familyLine\":\"씨앗에 붙은 까끄라기가 습기에 따라 비틀렸다 풀렸다 해요. 그 힘으로 스스로 땅을 파고 들어가요.\"},\"stories\":[{\"id\":\"bstory-animated-oat-self-drilling-awn\",\"title\":\"죽은 조직으로 기어가는 씨앗\",\"hook\":\"메귀리 씨앗은 습도가 오르내리기만 해도 스스로 흙 속으로 파고들어요.\",\"body\":\"메귀리 열매는 씨앗이 든 작은 꾸러미에 뻣뻣한 까끄라기 두 개가 달린 구조예요. 이 까끄라기는 이미 죽은 조직인데도 움직여요. 젖거나 습해지면 밑동의 세포 구간이 기울면서 열매 양쪽의 까끄라기가 서로 엉키고, 그렇게 비틀리는 동안 탄성 에너지가 쌓여요. 이 에너지가 풀릴 때 열매가 앞으로 밀려 나가 흙 틈으로 파고들죠. 열매 옆면에 난 잔털은 몸이 흙에 박히도록 붙잡아 줘서 씨앗이 싹트기 좋은 자리에 자리 잡게 해요. 뿌리도 근육도 없이 습도 변화만으로 열매가 스스로 자리를 옮기고 흙에 박히는 구조예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"advancedsciencenews.com\",\"sourceUrl\":\"https://www.advancedsciencenews.com/these-plant-based-robots-will-help-with-reforestation/\"},{\"id\":\"bstory-animated-oat-hybribot\",\"title\":\"밀가루로 찍어 만든 씨앗 로봇\",\"hook\":\"메귀리 까끄라기를 붙인 60밀리그램짜리 로봇이 스스로 흙 속으로 들어가요.\",\"body\":\"2024년 5월 13일, 이탈리아기술연구원과 프라이부르크 대학 연구진이 메귀리 까끄라기를 그대로 붙인 소형 로봇 하이브리봇을 발표했어요. 제1저자는 이사벨라 피오렐로, 총괄은 이탈리아기술연구원 로보틱스 부문 부소장 바르바라 마촐라이예요. 자연 열매의 껍질 구조를 본떠 3D 미세가공으로 틀을 만들고, 밀가루로 몸체를 찍은 다음 에틸셀룰로스를 입혀 물에 견디게 했어요. 캡슐 무게는 60밀리그램으로 자연 열매의 약 세 배예요. 까끄라기 두 개가 습도에 따라 돌고 서로 엇갈리며 탄성 에너지를 모았다가 풀면서 캡슐을 흙 속으로 밀어 넣고, 갈라진 틈에 이르면 씨앗이 싹터요. 연구진은 토마토와 치커리, 분홍바늘꽃 씨앗으로 시험했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이탈리아·독일\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"opentalk.iit.it\",\"sourceUrl\":\"https://opentalk.iit.it/en/flour-and-oats-for-the-biohybrid-robot-useful-for-reforestation/\"}]},\"9-26\":{\"photo\":{\"src\":\"/birth/gam.jpg\",\"thumbSrc\":\"/birth/thumbs/gam.jpg\",\"author\":\"Frank Schulenburg\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fuyu_persimmon_fruits,_one_cut_open.jpg\",\"familyLine\":\"떫은맛은 익으면서 스스로 사라져요. 씨앗이 여물기 전에 먹히지 않으려고 걸어 둔 시간 잠금장치예요.\"},\"stories\":[{\"id\":\"bstory-date-plum-rootstock-frost\",\"title\":\"서리를 맞아야 달아지는 열매\",\"hook\":\"고욤나무 열매는 서리를 맞은 뒤에야 제맛이 들고, 말리면 대추야자 맛이 나요.\",\"body\":\"영문명 데이트 플럼은 감이 아니라 고욤나무를 가리켜요. 식물 정보 데이터베이스는 이 나무의 열매가 완전히 익었을 때, 거의 상하기 직전에 더없이 진한 맛이 난다고 적어요. 서늘한 여름에는 제대로 익지 않지만 서리를 맞으면 대개 아주 좋은 맛이 든다고 해요. 가을에 따서 무르익힌 뒤 먹고, 말리면 대추야자 같은 맛이 난대요. 열매는 지름 1~2센티미터로 10월과 11월에 익고요. 그런데 이 나무의 더 큰 쓰임은 열매가 아니에요. 감나무를 접붙일 때 뿌리 노릇을 하는 대목으로 쓰이거든요. 영하 15도까지 견뎌요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유라시아\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pfaf.org\",\"sourceUrl\":\"https://pfaf.org/user/Plant.aspx?LatinName=Diospyros+lotus\"},{\"id\":\"bstory-date-plum-17c-england\",\"title\":\"이름값 못 한 과일나무\",\"hook\":\"이름에 대추야자와 자두를 다 붙이고도 정작 과일로는 대접받지 못한 나무예요.\",\"body\":\"고욤나무는 유럽 정원에 일찍 들어왔어요. 영국 수목 문헌을 온라인으로 옮긴 자료는 이 나무가 17세기 초 영국에서 재배됐지만, 완전히 내한성이 있는데도 정원에서 흔해진 적은 없다고 적어요. 이유는 열매예요. 열매는 잘 달리지만 끝까지 떫어서 먹기에 알맞지 않다고 기록돼 있어요. 크기는 지름 1.3에서 2센티미터쯤이고 색은 자줏빛이나 노란빛이에요. 원산지는 중국과 히말라야, 어쩌면 소아시아까지로 봐요. 대추야자와 자두를 이름에 다 붙여 놓고도 정작 과일나무 자리는 얻지 못한 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기~19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"treesandshrubsonline.org\",\"sourceUrl\":\"http://www.treesandshrubsonline.org/articles/diospyros/diospyros-lotus/\"}]},\"9-27\":{\"photo\":{\"src\":\"/birth/tteokgalnamu-0927.jpg\",\"thumbSrc\":\"/birth/thumbs/tteokgalnamu-0927.jpg\",\"author\":\"LiCheng Shih\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Quercus_dentata_(44354176202).jpg\",\"familyLine\":\"잎이 참나무 무리에서 가장 커요. 예전엔 이 잎에 떡을 싸서 쪄 먹었고 이름도 거기서 왔어요.\"},\"stories\":[{\"id\":\"bstory-oak-boscobel-all-day\",\"title\":\"왕이 하루를 보낸 나무\",\"hook\":\"군인들이 숲을 뒤지는 동안, 왕은 참나무 위에 앉아 그들을 내려다보고 있었습니다.\",\"body\":\"1651년 9월, 우스터 전투에서 진 스물한 살의 찰스는 쫓기는 몸이 됐어요. 보스코벨 하우스에 숨어들었는데, 같이 도망 중이던 윌리엄 케어리스가 집도 숲도 위험하다고 했어요. 대신 한 가지 방법을 알고 있다고요. 삼사 년 전에 가지를 쳐서 잎이 빽빽하게 자란 참나무 한 그루였어요. 두 사람은 그 나무에 올라가 하루를 통째로 보냈어요. 찰스는 삼십 년 뒤 새뮤얼 피프스에게 그날을 이렇게 구술했어요. 나무 위에서 보니 군인들이 숲 여기저기를 뒤지며 오가는 게 보였다고요. 왕정복고 뒤 그의 생일 5월 29일은 오크 애플 데이가 됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"english-heritage.org.uk\",\"sourceUrl\":\"https://www.english-heritage.org.uk/visit/places/boscobel-house-and-the-royal-oak/history/charles-ii-and-the-royal-oak/\"},{\"id\":\"bstory-oak-dodona-oracle\",\"title\":\"잎 소리를 듣고 신탁을 읽었습니다\",\"hook\":\"그리스에서 가장 오래된 신탁소는 건물이 아니라 참나무 한 그루였습니다.\",\"body\":\"그리스 북서부 에페이로스의 골짜기에 도도나가 있어요. 제우스의 신탁소로 고대 그리스 세계 전체에 이름이 알려진 곳이에요. 이곳의 중심에는 신전 건물이 아니라 참나무 한 그루가 있었어요. 사제들이 그 잎이 스치는 소리를 듣고 신의 뜻을 읽었다고 해요. 이 신탁소는 헬레니즘 시대에 크게 확장돼서 그리스에서 손꼽히는 규모의 극장까지 들어섰어요. 끝은 급작스러웠어요. 4세기에 테오도시우스 황제가 이교 성소를 금지하면서 그 참나무가 뽑혔어요. 이후 이 자리에는 기독교 바실리카가 들어섰고, 6세기 중엽에 완전히 버려졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"worldhistory.org\",\"sourceUrl\":\"https://www.worldhistory.org/Dodona/\"},{\"id\":\"bstory-oak-iron-gall-ink\",\"title\":\"참나무 혹으로 만든 잉크\",\"hook\":\"중세부터 19세기까지 유럽의 글씨는 대부분 참나무 벌레혹으로 만든 잉크였어요.\",\"body\":\"참나무 가지에 벌레가 알을 낳으면 나무가 방어 반응으로 둥근 혹을 만들어요. 이 혹을 황산철, 물, 아라비아검과 섞으면 철몰식자잉크가 돼요. 예일대 도서관의 필사 재료 프로젝트는 이 잉크를 중세부터 19세기까지 필사본에서 가장 자주 발견되는 잉크라고 설명해요. 렘브란트와 반 고흐, 빅토르 위고도 이 잉크로 그림을 그렸고요. 문제는 시간이에요. 이 잉크의 산도는 보통 pH 1에서 3 사이라, 산이 종이를 타고 번지면서 섬유를 끊고 글자를 파랑검정에서 갈색으로 바꿔 놔요. 옛 문서를 위협하는 가장 큰 원인 가운데 하나예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"중세~19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"travelingscriptorium.com\",\"sourceUrl\":\"https://travelingscriptorium.com/2013/03/21/iron-gall-ink/\"}]},\"9-28\":{\"photo\":{\"src\":\"/birth/saekbireum.jpg\",\"thumbSrc\":\"/birth/thumbs/saekbireum.jpg\",\"author\":\"Kor!An (Корзун Андрей)\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Amaranthus_tricolor_(in_a_flowerbed)_02.jpg\",\"familyLine\":\"꽃보다 잎이 화려해요. 붉고 노란 물이 잎에 번져서 멀리서 보면 꽃밭처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-amaranth-milton-immortal-amarant\",\"title\":\"낙원에서 옮겨 심은 꽃\",\"hook\":\"밀턴은 아마란스를 사람이 죄를 지은 뒤 낙원에서 하늘로 옮겨진 꽃으로 그렸어요.\",\"body\":\"존 밀턴의 실낙원 3권 351행 부근에는 천사들의 관을 묘사하는 대목이 나와요. 아마란스와 금을 엮은 관이라는 구절이에요. 밀턴은 이어서 이 꽃의 내력을 붙여요. 불멸의 아마란스는 한때 낙원에서 생명나무 곁에 피기 시작했지만, 사람이 죄를 지은 뒤 처음 자라던 하늘로 다시 옮겨졌고 지금은 생명의 샘 위에 그늘을 드리우며 핀다는 거예요. 다트머스 대학이 운영하는 밀턴 원문 사이트에서 이 대목을 그대로 읽을 수 있어요. 시들지 않는 꽃이라는 이미지가 17세기 영시에 자리 잡은 순간이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"milton.host.dartmouth.edu\",\"sourceUrl\":\"https://milton.host.dartmouth.edu/reading_room/pl/book_3/text.shtml\"},{\"id\":\"bstory-amaranth-tehuacan-4000bce\",\"title\":\"8천 년을 이어 온 씨앗\",\"hook\":\"멕시코 테우아칸 계곡에서 나온 아마란스 씨앗은 기원전 4000년까지 거슬러 올라가요.\",\"body\":\"아마란스는 아메리카에서 아주 오래된 작물이에요. 2026년 프런티어스 인 플랜트 사이언스에 실린 종설은 멕시코에서 이 식물을 주식이자 종교 의례의 재료로 써 온 역사가 6천 년에서 8천 년에 이른다고 정리해요. 테우아칸 계곡에서 발견된 아마란투스 크루엔투스의 씨앗과 식물체는 기원전 4000년의 것이고요. 그런데 스페인 식민 지배가 시작되면서 재배가 금지됐고, 아마란스는 급격히 줄어들었어요. 그래도 완전히 끊기지는 않았어요. 원주민 공동체 안에서 살아남았고, 1970년대에 영양가가 다시 주목받으면서 밭으로 돌아왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"멕시코\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC13022712/\"}]},\"9-29\":{\"photo\":{\"src\":\"/birth/sagwa-0929.jpg\",\"thumbSrc\":\"/birth/thumbs/sagwa-0929.jpg\",\"author\":\"Relativity\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Malus_domestica_(Apple)_flowers_3.jpg\",\"familyLine\":\"꽃은 분홍으로 열렸다가 하얗게 바래요. 벌에게 지금이 제일 좋은 때라고 알려 주는 신호예요.\"},\"stories\":[{\"id\":\"bstory-apple-almaty\",\"title\":\"사과의 아버지라는 이름의 도시\",\"hook\":\"카자흐스탄 알마티의 옛 이름은 '사과의 아버지'예요.\",\"body\":\"재배 사과의 조상은 카자흐스탄 톈산산맥에 자생하는 말루스 시에베르시예요. 20세기 초 러시아 식물학자 니콜라이 바빌로프가 알마티 근교에서 사과나무가 야생으로 빽빽하게 얽혀 자라는 숲을 보고 이곳을 사과의 고향으로 지목했고, 훗날 유전체 분석이 그 짐작을 뒷받침했어요. 알마티의 옛 이름 알마아타는 '사과의 아버지'라는 뜻이에요. 다만 소련 시절 개발로 야생 사과 숲의 상당 부분이 사라졌고, 지금은 남은 숲을 지키는 일이 과제로 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"카자흐스탄\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/travel/saving-the-apples-ancient-ancestor-in-the-forests-of-kazakhstan-180983493/\"},{\"id\":\"bstory-apple-graft-and-cider\",\"title\":\"씨앗으로 심으면 부모를 닮지 않아요\",\"hook\":\"사과 씨를 심으면 그 사과가 나오지 않아요.\",\"body\":\"사과는 씨앗으로 번식하면 부모와 전혀 다른 나무가 나와요. 그래서 과수원은 원하는 품종의 가지를 대목에 붙이는 접붙이기로 나무를 복제해요. 미국의 존 채프먼, 이른바 조니 애플시드는 반대로 씨앗만 뿌리고 다녔어요. 접붙이기를 창조에 손대는 일로 여겼다고 전해져요. 그렇게 나온 사과는 대개 그냥 먹기엔 떫어서 대부분 사과술로 짜였어요. 미국 개척지의 사과나무는 먹을거리라기보다 마실 거리에 가까웠던 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"wildabundance.net\",\"sourceUrl\":\"https://www.wildabundance.net/blog/johnny-appleseed/\"},{\"id\":\"bstory-apple-newton-tree\",\"title\":\"뉴턴의 사과나무는 아직 산다\",\"hook\":\"1816년 폭풍에 쓰러진 나무가 그 자리에서 다시 뿌리를 내려 지금도 서 있어요.\",\"body\":\"뉴턴이 사과 떨어지는 걸 본 건 1666년 늦여름이었대요. 품종은 플라워 오브 켄트로, 15세기 기록까지 거슬러 올라가는 요리용 사과예요. 이 이야기는 뉴턴 본인이 볼테르와 존 콘듀잇, 윌리엄 스터클리 같은 사람들에게 직접 들려준 것이고, 글로 남은 첫 기록은 뉴턴이 세상을 떠난 1726년 콘듀잇의 메모예요. 1806년 에드먼드 터너의 책은 울스소프 정원의 특정 나무를 그 나무로 지목하면서 그 나무는 아직 남아 있고 방문객에게 보여진다고 적었어요. 1816년 폭풍이 나무를 쓰러뜨렸지만 남은 부분이 다시 뿌리를 내렸고, 그 나무가 지금도 울스소프에 서 있어요. 수령은 350년이 넘어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"york.ac.uk\",\"sourceUrl\":\"https://www.york.ac.uk/physics-engineering-technology/about/newtons-apple-tree/\"},{\"id\":\"bstory-apple-chapman-cider\",\"title\":\"자니 애플시드는 술나무를 심었다\",\"hook\":\"그가 심은 사과는 먹으려는 게 아니라, 발효시켜 사이다를 담그기 위한 것이었어요.\",\"body\":\"1774년 매사추세츠에서 태어난 존 채프먼은 1790년대부터 펜실베이니아에서 일리노이까지 옮겨 다니며 정착민보다 먼저 과수원을 만들고 되팔았어요. 그런데 그가 심은 사과는 그대로 먹기엔 너무 시었어요. 그는 스베덴보리교 신자였고, 그 교리가 접붙이기를 금했거든요. 접을 붙이면 식물이 아파한다고 봤대요. 그래서 오직 씨앗으로만 심었고, 씨에서 난 사과는 거의 다 발효용, 곧 하드 사이다용이었어요. 당시 오하이오 컴퍼니는 100에이커를 얻으려면 3년 안에 사과나무 쉰 그루와 복숭아나무 스무 그루를 심으라고 요구했으니, 그의 묘목은 정착 증서나 다름없었어요. 금주법 시대에는 그 신 사과나무들이 단속에 베여 나갔다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"18세기~19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/arts-culture/real-johnny-appleseed-brought-applesand-booze-american-frontier-180953263/\"},{\"id\":\"bstory-apple-eris-discord\",\"title\":\"초대받지 못한 여신의 사과\",\"hook\":\"결혼식에 부르지 않았다는 이유로 던진 황금 사과 하나가 트로이 전쟁을 불렀어요.\",\"body\":\"불화의 여신 에리스는 헤시오도스의 신통기에서 밤의 여신 닉스가 마지막으로 낳은 자식으로 나와요. 펠레우스와 테티스의 결혼식에 초대받지 못한 에리스는 가장 아름다운 이에게라고 새긴 황금 사과를 던져 넣었어요. 아테나와 헤라, 아프로디테가 서로 자기 것이라 다투자 제우스는 판정을 트로이 왕자 파리스에게 떠넘겼지요. 아프로디테는 세상에서 가장 아름다운 여인 헬레네를 주겠다고 약속해 사과를 차지했고요. 파리스가 헬레네를 데려가면서 그리스 연합군이 트로이로 향했고, 십 년 전쟁이 시작됐어요. 불화의 사과라는 말은 여기서 나왔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"worldhistory.org\",\"sourceUrl\":\"https://www.worldhistory.org/Eris/\"}]},\"9-30\":{\"photo\":{\"src\":\"/birth/samnamu-0930.jpg\",\"thumbSrc\":\"/birth/thumbs/samnamu-0930.jpg\",\"author\":\"MrPanyGoff\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanese_cedar_cones_-_Cryptomeria_japonica.jpg\",\"familyLine\":\"가지 끝마다 작은 방울 같은 열매가 달려요. 곧게 자라는 성질 때문에 오래도록 기둥감으로 쓰였어요.\"},\"stories\":[{\"id\":\"bstory-sugi-yakushima-thousand-years\",\"title\":\"천 년이 기준선인 숲\",\"hook\":\"야쿠시마에서는 천 년을 넘긴 삼나무만 야쿠스기라고 부릅니다. 그 아래는 아직 어린나무입니다.\",\"body\":\"가고시마 남쪽 바다에 야쿠섬이 있어요. 작은 섬인데 산이 높고 비가 억수같이 내려요. 그 습한 산속에 삼나무 원시림이 있어요. 여기서는 나무를 부르는 기준이 남달라요. 천 년을 넘긴 삼나무만 야쿠스기라고 부르거든요. 천 년이 안 된 나무는 그냥 어린 삼나무예요. 이 숲은 1993년에 유네스코 세계자연유산이 됐어요. 등재 사유에는 천 년을 넘긴 삼나무 원시림이 이 섬의 핵심이라고 적혀 있어요. 작은 섬 하나에 식물만 천구백 종이 살고 있고요. 같은 삼나무인데 어느 산에서는 꽃가루 골칫거리이고, 이 섬에서는 세계유산이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"whc.unesco.org\",\"sourceUrl\":\"https://whc.unesco.org/en/list/662\"},{\"id\":\"bstory-cedar-nikko-avenue\",\"title\":\"세계에서 가장 긴 삼나무길\",\"hook\":\"1628년부터 스무 해에 걸쳐 삼나무 20만 그루를 심어 만든 35.41킬로미터짜리 가로수길이에요.\",\"body\":\"일본 도치기현 이마이치를 중심으로 세 갈래 길이 모이는 닛코의 삼나무 가로수길은 기네스 세계기록이 인정한 세계에서 가장 긴 가로수길이에요. 총 길이가 35.41킬로미터, 그러니까 약 22마일이에요. 1628년부터 1648년까지 스무 해에 걸쳐 삼나무 20만 그루를 심어 만들었고, 그중 1만 3500그루 넘게 아직 살아 있어요. 남은 나무들의 평균 키는 27미터고요. 심은 나무의 대부분은 지난 400년 사이에 사라졌지만, 남은 것만으로도 이 길은 여전히 세계 최장 기록을 지키고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"guinnessworldrecords.com\",\"sourceUrl\":\"https://www.guinnessworldrecords.com/world-records/longest-avenue-of-trees\"},{\"id\":\"bstory-cedar-pollen-policy\",\"title\":\"40억 그루가 만든 꽃가루\",\"hook\":\"전후 일본이 심은 삼나무 40억 그루가 지금은 국민 다섯 중 한 명을 괴롭혀요.\",\"body\":\"일본은 2차 대전이 끝난 뒤 헐벗은 산을 되살리고 건설 목재를 대려고 삼나무를 대대적으로 심었어요. 1950년부터 1970년까지 산에 꽂힌 삼나무만 40억 그루가 넘어요. 그런데 값싼 수입 목재가 들어오면서 국내 목재 수요가 사라졌고, 베어 내지 못한 나무들은 그대로 자라 꽃가루를 뿜기 시작했지요. 지금 일본에서 가훈쇼라 부르는 꽃가루 알레르기는 국민 다섯 명 중 한 명에게 나타나요. 30년 사이 꽃가루 농도는 다섯 배, 환자 수는 세 배로 늘었고요. 2007년 도야마현 임업연구소가 꽃가루를 만들지 않는 품종을 개발하는 등 대안이 나왔지만, 무화분·저화분 품종은 아직 해마다 심는 묘목의 10퍼센트를 조금 넘는 수준이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nippon.com\",\"sourceUrl\":\"https://www.nippon.com/en/nipponblog/m00081/\"},{\"id\":\"bstory-cedar-jomon-sugi\",\"title\":\"1966년에야 발견된 조몬스기\",\"hook\":\"둘레 16.4미터의 이 삼나무는 1966년에야 세상에 알려졌어요.\",\"body\":\"규슈 남쪽 야쿠시마섬 깊은 산속에 조몬스기라는 삼나무가 서 있어요. 키는 25.3미터로 압도적이진 않은데, 줄기 둘레가 16.4미터나 돼요. 나이는 2000년에서 7200년 사이로 추정되고, 연륜 측정으로는 최소 2000년이라는 값이 나왔어요. 놀라운 건 이 나무가 1966년에야 공식적으로 알려졌다는 점이에요. 근처에는 1580년대에 잘려 나간 거대한 삼나무의 그루터기, 이른바 윌슨 그루터기가 남아 있어요. 지금은 뿌리가 상할까 봐 밑동에서 15미터 떨어진 전망대에서만 볼 수 있고, 왕복 열 시간쯤 걸어야 닿아요. 야쿠시마는 1993년 세계자연유산이 되었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"japan.travel\",\"sourceUrl\":\"https://www.japan.travel/en/spot/596/\"}]},\"10-1\":{\"stories\":[]},\"10-2\":{\"photo\":{\"src\":\"/birth/salgu.jpg\",\"thumbSrc\":\"/birth/thumbs/salgu.jpg\",\"author\":\"Victor Vizu\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Prunus_armeniaca_flowers_in_Kharkov.jpg\",\"familyLine\":\"매화가 진 자리에 이어서 피어요. 잎이 나기 전에 꽃부터 터뜨려서 가지가 통째로 하얘져요.\"},\"stories\":[{\"id\":\"bstory-apricot-xinglin\",\"title\":\"치료비 대신 살구나무를 심었다\",\"hook\":\"중병이 나은 사람은 다섯 그루, 가벼운 병은 한 그루. 몇 해 뒤 살구나무는 10만 그루가 됐어요.\",\"body\":\"삼국시대 오나라의 의원 동봉은 여산에 숨어 살면서 환자를 봤는데, 돈을 받지 않았대요. 대신 조건을 걸었어요. 중한 병이 나은 사람은 살구나무 다섯 그루, 가벼운 병이 나은 사람은 한 그루를 심으라는 것이었죠. 몇 해가 지나자 그 자리에 살구나무가 10만 그루 넘게 들어서 울창한 숲이 됐어요. 여기서 나온 말이 행림, 곧 살구나무 숲이에요. 이 말은 훗날 훌륭한 의원을 높여 부르는 표현이 되었고, 지금도 중화권에서는 의료계 전체를 행림이라 부르고 병원 이름에도 즐겨 붙여요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"wisdomlib.org\",\"sourceUrl\":\"https://www.wisdomlib.org/definition/xing-lin\"},{\"id\":\"bstory-apricot-genome-origin\",\"title\":\"살구의 고향은 중국이 아니다\",\"hook\":\"600개 가까운 게놈을 읽어 보니, 살구는 중앙아시아에서 두 번 따로 길들여진 과일이었어요.\",\"body\":\"살구는 오랫동안 중국이 원산지라고 여겨졌어요. 열매와 나무의 생김새를 근거로 한 판단이었죠. 그런데 살구속 나무 926그루를 분석하고 그중 578개체의 게놈을 직접 해독한 연구가 이 통념을 흔들었어요. 결과는 이랬어요. 중국 재배 살구는 약 2900년 전 중앙아시아 남부의 야생 집단에서, 유럽 재배 살구는 약 2250년 전 중앙아시아 북부의 야생 집단에서 각각 따로 갈라져 나왔어요. 한 곳에서 퍼진 게 아니라 서로 다른 야생 집단에서 두 번 따로 길들여졌다는 뜻이에요. 유럽과 중국 살구는 겉모습이 비슷하게 수렴했지만, 선택의 흔적이 남은 게놈 부위조차 서로 달랐고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중앙아시아\"},{\"key\":\"era\",\"text\":\"고대~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC8233370/\"}]},\"10-3\":{\"photo\":{\"src\":\"/birth/danpungnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/danpungnamu.jpg\",\"author\":\"Dietmar Rabich\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanischer_Ahorn_--_2021_--_3946.jpg\",\"familyLine\":\"잎이 붉어지는 건 초록이 빠져나간 뒤에야 원래 색이 드러나는 거예요. 붉은색은 새로 칠한 게 아니라 내내 안에 있었어요.\"},\"stories\":[{\"id\":\"bstory-maple-flag-debate\",\"title\":\"새벽 2시 15분에 정해진 단풍잎\",\"hook\":\"270번의 연설 끝에 캐나다 국기의 단풍잎이 통과된 시각은 새벽 2시 15분이었어요.\",\"body\":\"캐나다 국기의 단풍잎은 순순히 정해지지 않았어요. 1964년 6월 15일 의회에서 국기 논쟁이 열렸고, 연설이 270번 이어졌어요. 총리 레스터 피어슨은 파란 띠에 단풍잎 세 장을 넣은 도안을 밀었는데, 왕립군사대학 문리대학장이던 조지 스탠리가 세 장보다 한 장이 낫다고 설득했어요. 자유당 일곱, 보수당 다섯, 나머지 정당 셋으로 꾸린 위원회가 9월 중순부터 여섯 주 동안 도안을 골랐고, 12월 15일 토론종결 동의가 152 대 85로 통과됐어요. 그리고 12월 17일 새벽 2시 15분, 163 대 78로 단풍잎 한 장이 확정됐어요. 새 국기가 처음 게양된 건 1965년 2월 15일이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"캐나다\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"canadashistory.ca\",\"sourceUrl\":\"https://www.canadashistory.ca/explore/politics-law/the-great-flag-debate\"},{\"id\":\"bstory-maple-syrup-heist\",\"title\":\"물로 채워진 메이플시럽 통\",\"hook\":\"2012년 여름 퀘벡의 시럽 비축고를 열어 보니, 통 안에는 시럽 대신 물이 들어 있었어요.\",\"body\":\"퀘벡에는 세계 메이플시럽 전략 비축고가 있어요. 세인트루이드블랑포르 창고에 통을 쌓아 두고 물량과 시세를 조절하죠. 2012년 여름 점검에서 검사원이 통을 열었더니 어떤 통은 비어 있었고, 어떤 통은 물로 채워져 있었어요. 사라진 시럽은 9500통, 비축량의 8분의 1가량이었고 시가로 1800만 캐나다달러가 넘었어요. 범인들은 그걸 1000만 캐나다달러쯤에 팔아넘겼고요. 같은 해 12월부터 체포가 시작돼 주범 리샤르 발리에르는 2016년 유죄 판결을 받았어요. 2022년 3월 31일 캐나다 대법원은 그에게 910만 캐나다달러 벌금과 8년형을 확정했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"캐나다\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"forbes.com\",\"sourceUrl\":\"https://www.forbes.com/sites/nicholasreimann/2022/03/31/ringleader-of-great-canadian-maple-syrup-heist-ordered-to-pay-multi-million-dollar-fine/\"}]},\"10-4\":{\"photo\":{\"src\":\"/birth/hop.jpg\",\"thumbSrc\":\"/birth/thumbs/hop.jpg\",\"author\":\"LuckyStarr\",\"license\":\"CC BY 2.5\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Humulus_Lupulus_Hopfendolde-mit-hopfengarten.jpg\",\"familyLine\":\"솔방울처럼 생긴 이 열매가 맥주의 쓴맛을 맡아요. 암그루에만 달려서 밭에는 암그루만 심어요.\"},\"stories\":[{\"id\":\"bstory-hop-reinheitsgebot\",\"title\":\"맥주에 홉만 남긴 1516년 법령\",\"hook\":\"1516년 바이에른 법령은 맥주 재료를 보리·홉·물 셋으로 못 박았어요.\",\"body\":\"1516년 바이에른의 잉골슈타트에서 빌헬름 4세와 루트비히 10세가 맥주 재료를 보리와 홉, 물 셋으로 제한하는 법령을 내렸어요. 순수함을 위해서라기보다 값 때문이었어요. 밀맥주가 인기를 끌면서 빵에 쓸 곡물값이 오르자 밀을 맥주에서 밀어낸 거지요. 효모가 목록에 없는 건 당시 아무도 발효의 원리를 몰랐기 때문이고요. 이 법의 원래 이름은 대용물 금지령이었고, 순수령이라는 이름은 1918년 바이에른 의회의 한 의원이 처음 붙였어요. 1871년에는 독일 세법 안으로 들어갔고, 1987년 유럽공동체 재판에서 수입 맥주에는 적용할 수 없다는 판단이 나왔어요. 정작 귀족들은 특별 허가를 받아 밀맥주를 계속 마셨고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"16세기~20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"origins.osu.edu\",\"sourceUrl\":\"https://origins.osu.edu/milestones/april-2016-keeping-beer-pure-1516-reinheitsgebot\"},{\"id\":\"bstory-hop-kent-picking\",\"title\":\"런던 사람들의 홉 따는 휴가\",\"hook\":\"해마다 8월이면 런던 사람 수만 명이 켄트의 홉밭으로 떠났어요.\",\"body\":\"영국에서 홉 수확철은 런던 노동자 가족의 연례 휴가이기도 했어요. 1930년대에는 수만 명이 해마다 켄트로 내려갔어요. 홉 따는 철에 맞춰 값싼 임시 열차가 편성됐고, 사람들은 런던브리지역에서 패덕우드나 얄딩행 기차를 탔어요. 짐은 손수레나 유모차에 실었고요. 도착하면 농장 오두막에서 몇 주를 지냈는데, 화장실은 땅에 판 구덩이였고 밥은 바깥 모닥불에 지어 먹었어요. 그래서 오두막을 손보러 일주일 먼저 내려가는 집도 많았어요. 홉 덩굴이 높으면 남자들이 죽마를 신고 땄고, 딴 홉은 포크라 부르는 큰 자루에 담아 건조장으로 보냈어요. 1930년대에 수확 기계가 들어오면서 1960년대에는 이 풍경이 거의 사라졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기~20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"londonmuseum.org.uk\",\"sourceUrl\":\"https://www.londonmuseum.org.uk/collections/london-stories/hop-picking-londoners-working-holiday/\"}]},\"10-5\":{\"photo\":{\"src\":\"/birth/jongryeonamu.jpg\",\"thumbSrc\":\"/birth/thumbs/jongryeonamu.jpg\",\"author\":\"Rillke\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Trachycarpus_fortunei_inflorescence.jpg\",\"familyLine\":\"줄기를 갈색 섬유가 그물처럼 감싸요. 그 섬유를 벗겨 밧줄과 빗자루를 만들어 썼어요.\"},\"stories\":[{\"id\":\"bstory-windmill-palm-robert-fortune\",\"title\":\"세계 최북단 야자나무\",\"hook\":\"스코틀랜드 서덜랜드에 선 종려나무가 세계에서 가장 북쪽의 노지 야자로 알려져 있어요.\",\"body\":\"종려나무의 학명 트라키카르푸스 포르투네이에 붙은 뒤쪽 이름은 스코틀랜드 식물 채집가 로버트 포춘의 것이에요. 그는 에든버러 왕립식물원에서 일하다 런던 원예협회로 옮겼고, 1843년 협회의 파견으로 중국에 갔어요. 이 야자를 만난 곳은 저우산, 옛 이름 주산섬이었고 그래서 영어권에서는 지금도 주산 야자라고 불러요. 1848년에는 동인도회사의 의뢰로 다시 중국에 들어가 좋은 차나무 품종을 찾았고요. 이 야자의 진짜 놀라운 점은 추위예요. 에든버러는 물론 스코틀랜드 북서쪽 끝에서도 노지에서 겨울을 나서, 서덜랜드의 스코리에 있는 나무는 세계에서 가장 북쪽의 야외 야자로 꼽혀요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국·스코틀랜드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"stories.rbge.org.uk\",\"sourceUrl\":\"https://stories.rbge.org.uk/archives/5118\"},{\"id\":\"bstory-windmill-palm-ticino\",\"title\":\"스위스 남쪽의 야자 숲\",\"hook\":\"정원에 심은 종려나무가 티치노 숲을 열대처럼 바꿔 놓았어요.\",\"body\":\"스위스 남단 티치노에서는 종려나무가 골칫거리예요. 지난 오십 년 사이 정원에 심긴 나무들이 씨를 퍼뜨려 숲으로 번졌고, 마을 근처 숲은 열대처럼 보일 정도가 됐거든요. 연방 연구소가 숲 스무 곳을 조사해 봤더니, 야자가 빽빽한 열 곳은 야자가 없는 곳보다 식물 종수가 뚜렷하게 적었어요. 다만 무척추동물 수에는 차이가 없었고요. 지금은 해발 900미터 아래에 머물러 있지만, 기후가 더 따뜻해지면 더 높은 곳까지 올라갈 것으로 봐요. 연구진이 약 2천 명에게 의견을 물었을 때는 금지보다 꽃과 열매를 미리 떼어 내자는 쪽이 호응을 얻었어요. 티치노 당국은 전기톱으로 자른 뒤 드릴로 생장점을 파괴하는 2단계 제거법을 권고하고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스위스\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"wsl.ch\",\"sourceUrl\":\"https://www.wsl.ch/en/news/the-ticino-palm-an-inconvenient-beauty-under-scrutiny/\"}]},\"10-6\":{\"photo\":{\"src\":\"/birth/gaeamnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/gaeamnamu.jpg\",\"author\":\"小石川人晃\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Male_inflorescence_of_Corylus_heterophylla_var._thunbergii.jpg\",\"familyLine\":\"잎보다 먼저 긴 꼬리 같은 수꽃이 늘어져요. 바람이 지나갈 때마다 노란 가루를 털어 보내요.\"},\"stories\":[{\"id\":\"bstory-hazel-salmon-of-knowledge\",\"title\":\"아홉 그루 개암나무의 지혜\",\"hook\":\"개암을 삼킨 연어를 굽던 소년이 엄지를 데며 지혜를 통째로 얻었어요.\",\"body\":\"켈트 사람들은 성스러운 못 둘레에 개암나무 아홉 그루가 서 있다고 믿었어요. 나무에서 떨어진 개암을 물속 연어가 받아먹으면 그 지혜가 통째로 연어에게 옮겨간다고요. 아일랜드 판본에서는 연어 한 마리가 마법의 열매를 전부 삼켰다고 해요. 그 연어를 굽는 일을 맡은 건 드루이드의 어린 제자 핀 막 쿠월이었어요. 굽던 물이 튀어 엄지에 닿자 그는 무심코 손가락을 입에 넣었고, 지혜는 그렇게 스승이 아니라 소년에게 건너갔어요. 개암나무가 찾아 주는 게 지혜만은 아니었어요. 갈라진 개암 가지는 물길을 찾는 점술가들이 특히 아끼던 도구였고요. 게일어로 개암은 콜이라, 스코틀랜드 콜섬 같은 지명에 그 이름이 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드·스코틀랜드\"},{\"key\":\"era\",\"text\":\"고대~중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"treesforlife.org.uk\",\"sourceUrl\":\"https://treesforlife.org.uk/into-the-forest/trees-plants-animals/trees/hazel/hazel-mythology-and-folklore/\"},{\"id\":\"bstory-hazel-filbert-saint\",\"title\":\"성인의 축일에 익는 열매\",\"hook\":\"영어로 개암을 뜻하는 '필버트'는 7세기 수도원장의 축일에서 왔어요.\",\"body\":\"영어에서 개암을 부르는 또 다른 이름 필버트는 13세기 후반 앵글로프랑스어 필베르에서 왔어요. 이 말은 7세기 프랑크 왕국의 수도원장 성 필베르의 이름이에요. 왜 성인의 이름이 열매에 붙었을까요. 구력으로 8월 22일인 그의 축일 무렵에 개암이 익기 때문이에요. 정작 필베르라는 이름 자체는 고대 고지 독일어에서 온 것으로, 아주 밝다는 뜻이고요. 이런 작명은 유럽에서 드물지 않아요. 독일에서는 개암을 성 람베르트의 이름을 따 람베르츠누스라 부르고, 붉은 까치밥나무 열매는 성 요한 축일에서 이름을 따 요하니스베레라고 하거든요. 열매 이름이 곧 달력 노릇을 한 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"etymonline.com\",\"sourceUrl\":\"https://www.etymonline.com/word/filbert\"}]},\"10-7\":{\"photo\":{\"src\":\"/birth/jeonnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/jeonnamu.jpg\",\"author\":\"Darius Baužys\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Abies_holophylla_lt.jpg\",\"familyLine\":\"솔방울이 아래로 매달리지 않고 위를 향해 서요. 다 익으면 통째로 떨어지지 않고 비늘부터 흩어져요.\"},\"stories\":[{\"id\":\"bstory-fir-blackheads-tree\",\"title\":\"나무를 태우며 춤춘 상인들\",\"hook\":\"1441년 탈린의 미혼 상인들은 나무 둘레를 돌며 춤춘 뒤, 그 나무에 불을 붙였어요.\",\"body\":\"크리스마스트리의 초기 기록은 지금 우리가 아는 모습과 꽤 달라요. 1441년 탈린과 1510년 리가에서 나무를 세운 축제가 있었는데, 탈린의 미혼 상인 조합인 검은머리 형제단은 나무 둘레를 돌며 춤을 춘 다음 그 나무에 불을 질렀다고 해요. 리가에는 1510년 첫 새해 나무를 세웠다는 명판이 지금도 붙어 있고요. 나무에 촛불을 달았다는 이야기는 16세기 마르틴 루터의 것으로 전해지지만 확실한 사실로 보긴 어려워요. 영국에 이 풍습이 들어온 계기는 1800년 조지 3세의 왕비 샬럿이 연 파티였고, 1848년 윈저성 여왕의 크리스마스트리 그림이 실리면서 널리 퍼졌어요. 보통 가정의 거실까지 들어온 건 1920년대예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"에스토니아·라트비아·영국\"},{\"key\":\"era\",\"text\":\"중세~20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"historic-uk.com\",\"sourceUrl\":\"https://www.historic-uk.com/CultureUK/The-Christmas-Tree/\"},{\"id\":\"bstory-fir-andersen-tale\",\"title\":\"안데르센이 쓴 전나무의 최후\",\"hook\":\"동화 속 전나무는 크리스마스 다음 날 아침, 곧장 어두운 다락으로 끌려가요.\",\"body\":\"한스 크리스티안 안데르센에게는 전나무라는 동화가 있어요. 주인공은 숲의 어린 전나무인데, 주변 풍경에는 눈길도 주지 않고 오로지 빨리 크고 싶어 해요. 참새들이 와서, 잘려 간 전나무들이 따뜻한 방 안에서 금빛 사과와 생강빵과 장난감과 수백 개의 촛불로 꾸며지더라고 전하자 그 마음은 더 커지죠. 결국 전나무는 베여 큰 응접실에 세워지고 화려하게 장식돼요. 아이들은 달려들어 장식을 뜯어 가고, 어른은 험프티덤프티 이야기를 들려줘요. 그리고 다음 날 아침, 하인들이 나무를 어두운 다락으로 끌고 가요. 나중에는 마당에 버려져 아이들에게 부서지고, 하인이 도끼로 쪼개 불에 넣어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"덴마크\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"andersen.sdu.dk\",\"sourceUrl\":\"https://andersen.sdu.dk/vaerk/hersholt/TheFirTree_e.html\"}]},\"10-8\":{\"photo\":{\"src\":\"/birth/paseulri.jpg\",\"thumbSrc\":\"/birth/thumbs/paseulri.jpg\",\"author\":\"Jeffery Martin\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Parsley_leaves.jpg\",\"familyLine\":\"접시 가장자리 장식으로만 쓰이기엔 아까운 잎이에요. 씹으면 입 안의 냄새를 정리해 주는 쪽에 더 재주가 있어요.\"},\"stories\":[{\"id\":\"bstory-parsley-timoleon\",\"title\":\"무덤의 풀이 승리의 관이 되다\",\"hook\":\"파슬리를 잔뜩 실은 노새 떼를 만난 병사들은 죽음의 징조라며 얼어붙었어요.\",\"body\":\"시칠리아로 건너간 코린토스의 장군 티몰레온이 언덕을 오르던 중이었어요. 고개만 넘으면 적진이 내려다보이는 자리였는데, 하필 파슬리를 잔뜩 실은 노새 떼와 마주쳤어요. 병사들은 굳어 버렸어요. 그리스 사람들은 죽은 이의 무덤에 파슬리 화환을 두르는 관습이 있었거든요. 불길한 징조로 읽은 거죠. 티몰레온은 행렬을 세우고 다르게 말했어요. 승리의 관이 제 발로, 그것도 미리 손에 굴러들어 온 것이라고요. 코린토스 사람들이 이스트미아 경기 우승자에게 씌워 주는 관이 바로 파슬리 관이었으니까요. 그는 먼저 자기 머리에 파슬리를 두르고 병사들에게도 씌웠어요. 플루타르코스가 티몰레온 26장에 적어 둔 장면이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스·시칠리아\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"penelope.uchicago.edu\",\"sourceUrl\":\"https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Plutarch/Lives/Timoleon*.html\"},{\"id\":\"bstory-parsley-devil-seed\",\"title\":\"아홉 번 뿌려야 나는 씨\",\"hook\":\"파슬리 씨가 늦게 트는 건 악마가 다 가져가기 때문이라고 여겼어요.\",\"body\":\"파슬리 씨앗은 유난히 늦게 싹을 틔워요. 영국 슈롭셔 사람들은 여기에 이유를 붙였어요. 악마가 뿌린 씨를 죄다 가져가고 마지막 하나만 남긴다는 거예요. 그래서 아홉 번은 뿌려야 한다고 했지요. 씨앗이 지옥까지 갔다 오느라 늦는다는 이야기도 있었고, 그래서 성금요일 정오와 세 시 사이에 심으라는 전통이 따라붙었어요. 옮겨 심는 일은 더 조심스러웠어요. 파슬리를 옮기면 집안에 초상이 난다고 믿었거든요. 이런 불길함은 뿌리가 깊어요. 그리스와 로마 모두 파슬리를 죽음과 연결지었고, 그리스 사람들은 잘라 두어도 오래 푸른빛이 남는다는 이유로 무덤을 파슬리로 꾸몄으니까요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"icysedgwick.com\",\"sourceUrl\":\"https://www.icysedgwick.com/parsley-folklore/\"}]},\"10-9\":{\"photo\":{\"src\":\"/birth/hoehyang.jpg\",\"thumbSrc\":\"/birth/thumbs/hoehyang.jpg\",\"author\":\"Javier martin\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Foeniculum_vulgare_FlowersCloseup_15July2009_ParqueNaturalLagunasdelaMata.jpg\",\"familyLine\":\"씨앗을 씹으면 은은한 단맛이 돌아요. 인도에서는 식사 끝에 한 줌씩 내주는 게 오랜 습관이에요.\"},\"stories\":[{\"id\":\"bstory-fennel-marathon\",\"title\":\"회향밭에서 벌어진 전투\",\"hook\":\"마라톤이라는 지명은 원래 그리스어로 회향을 뜻하는 말이었어요.\",\"body\":\"마라톤은 원래 식물 이름이었어요. 고대 그리스어 마라톤이 회향을 가리켰고, 아테네 북동쪽 평원에 회향이 무성해서 그 이름이 붙었거든요. 말뜻은 높이 자라는 풀이라고 해요. 회향은 그리스 의학에서도 자리가 컸어요. 히포크라테스 이름으로 전해지는 저작에는 회향이 들어간 처방이 서른 가지가 넘고, 그 가운데 상당수가 불임이나 산후 회복 같은 부인과 처방이에요. 1세기의 디오스코리데스는 약물지에서 씨와 잎, 뿌리, 줄기의 쓰임을 따로 나눠 적었고요. 2세기의 갈레노스는 이집트에서 쓰던 회향 안약 처방을 남겼어요. 뱀이 허물을 벗을 때 어린 회향 순을 먹고 시력을 되찾는다는 이야기도 오래 전해졌지요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"ahpa.org\",\"sourceUrl\":\"https://www.ahpa.org/herbs_in_history_fennel\"},{\"id\":\"bstory-fennel-infinocchiare\",\"title\":\"'속이다'가 된 회향\",\"hook\":\"이탈리아어에서 회향에서 나온 동사 하나는 오늘날 거의 언제나 '속이다'라는 뜻으로 쓰여요.\",\"body\":\"이탈리아어에는 인피노키아레라는 동사가 있어요. 회향을 뜻하는 피노키오에서 곧장 나온 말이에요. 본래 뜻은 음식에 회향 씨로 향을 낸다인데, 정작 이 뜻으로 쓰는 일은 드물어요. 오늘날 이 단어는 거의 언제나 속이다, 구슬려 넘기다라는 뜻으로 쓰여요. 그 사람한테 속아 넘어가지 않게 조심하라는 식으로 말하죠. 왜 향신료 이름이 사기의 동사가 됐는지에 대해서는 여러 설명이 돌아다니는데, 이탈리아 사전은 그 두 번째 뜻의 유래가 아직 확실하지 않다고 분명히 적어 두었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이탈리아\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"treccani.it\",\"sourceUrl\":\"https://www.treccani.it/vocabolario/infinocchiare/\"}]},\"10-10\":{\"photo\":{\"src\":\"/birth/melron.jpg\",\"thumbSrc\":\"/birth/thumbs/melron.jpg\",\"author\":\"Frantishak\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Flower_of_Cucumis_melo.jpg\",\"familyLine\":\"한 그루에 수꽃과 암꽃이 따로 피어요. 열매를 맺는 건 밑동이 볼록한 암꽃 쪽이에요.\"},\"stories\":[{\"id\":\"bstory-melon-cantalupo\",\"title\":\"늑대 우는 언덕의 멜론\",\"hook\":\"캔털루프라는 이름은 로마 근교 교황의 여름 별장에서 왔다고 전해져요.\",\"body\":\"캔털루프라는 말이 영어에 처음 등장한 건 1739년이에요. 프랑스어를 거쳐 이탈리아어 칸탈루포에서 왔는데, 로마 근교에 있던 교황의 여름 별장 이름이었어요. 아르메니아에서 들어온 멜론을 유럽에서 처음 기른 곳이 그곳이었다는 이야기지요. 칸탈루포라는 지명 자체는 노래하는 늑대로 풀이돼요. 늑대가 울던 자리라는 뜻이라고들 하고요. 다만 어원학자들은 이 설명을 그대로 믿지는 않아요. 늑대 이야기도, 아르메니아에서 왔다는 부분도 나중에 붙인 민간어원일 수 있다고 보거든요. 이름 하나에 교황과 늑대와 아르메니아가 다 들어 있는데, 정작 확실한 건 1739년이라는 연도뿐인 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이탈리아\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"etymonline.com\",\"sourceUrl\":\"https://www.etymonline.com/word/cantaloupe\"},{\"id\":\"bstory-melon-chamoe\",\"title\":\"참외도 멜론이라는 사실\",\"hook\":\"참외는 멜론과 같은 종이고, 지금 품종의 뿌리는 1957년에 들어왔어요.\",\"body\":\"참외는 식물학적으로 멜론과 같은 종이에요. 학명이 쿠쿠미스 멜로로 같고, 그 안의 한 재배군이지요. 맛은 허니듀 멜론과 오이의 중간쯤이라고 표현되는데, 서양 멜론보다 덜 달고 90퍼센트 가까이가 수분이에요. 이름은 진짜 오이라는 뜻에서 왔고요. 지금 우리가 먹는 참외의 뿌리도 생각보다 최근이에요. 일본 도야마에서 개발된 은천참외가 1957년 한국에 들어와 순식간에 주력 품종이 됐고, 1984년에 나온 금싸라기은천을 비롯한 그 후손들이 지금까지 이어지고 있거든요. 생산은 한 곳에 몰려 있어요. 경상북도 성주군 한 곳이 전국 생산량의 약 70퍼센트를 차지해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Korean_melon\"}]},\"10-11\":{\"photo\":{\"src\":\"/birth/bucheokkot.jpg\",\"thumbSrc\":\"/birth/thumbs/bucheokkot.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lythrum_salicaria_flowers_-_Kulna.jpg\",\"familyLine\":\"물가에서 곧게 서서 보랏빛 탑을 쌓아요. 백중에 부처님께 올리던 꽃이라 이름이 그렇게 붙었어요.\"},\"stories\":[{\"id\":\"bstory-lythrum-two-million-seeds\",\"title\":\"한 포기가 씨앗 200만 개\",\"hook\":\"부처꽃 한 포기는 200만 개가 넘는 씨앗을 만들어 낼 수 있어요.\",\"body\":\"부처꽃 무리는 북미에서 습지의 골칫거리로 통해요. 1800년대 초 배의 바닥짐에 섞여 들어왔고, 소화기 질환에 쓰는 약초로 일부러 들여오기도 했으며, 양봉가들이 꿀을 얻으려고 심기도 했어요. 1830년대에는 이미 뉴잉글랜드에 자리를 잡았고, 운하와 물길을 따라 퍼져 나갔죠. 확산의 비결은 씨앗이에요. 한 포기가 200만 개가 넘는 씨앗을 만들 수 있거든요. 그래서 미국은 벌레를 풀었어요. 갈레루셀라 칼마리엔시스와 갈레루셀라 푸실라라는 잎벌레 두 종을 생물학적 방제용으로 방사한 거예요. 이 벌레들은 잎을 갉고 눈을 공격해 부처꽃의 생장과 씨앗 생산을 떨어뜨렸고, 어느 정도 성과를 냈어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"19세기~오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nyis.info\",\"sourceUrl\":\"https://nyis.info/invasive_species/purple-loosestrife/\"},{\"id\":\"bstory-lythrum-darwin-trimorphic\",\"title\":\"다윈이 센 열여덟 가지 짝짓기\",\"hook\":\"부처꽃은 꽃 모양이 세 가지라, 다윈은 가능한 수분 조합을 열여덟 가지로 헤아렸어요.\",\"body\":\"찰스 다윈은 부처꽃에 오래 매달렸어요. 이 꽃은 한 종인데 암술과 수술의 길이 배치가 서로 다른 세 가지 형태로 피거든요. 다윈은 저서 같은 종에 속하는 식물의 서로 다른 꽃 형태에서 이 세 형태가 서로를 수분시키는 방식을 따져, 가능한 조합이 열여덟 가지라고 셈했어요. 그중 가운데 길이의 암술대를 가진 형태는 특히 암컷 성질이 두드러진다고 적었고요. 그는 규칙에서 벗어난 조합으로 얻은 자손도 길러 봤는데, 세 형태 모두에서 키가 작고 번식력이 떨어지는 개체가 나왔고 아예 씨를 맺지 못하는 것도 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/3807/pg3807.txt\"}]},\"10-12\":{\"photo\":{\"src\":\"/birth/wolgyul.jpg\",\"thumbSrc\":\"/birth/thumbs/wolgyul.jpg\",\"author\":\"Hans Hillewaert\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Vaccinium_vitis-idaea_(flowering).jpg\",\"familyLine\":\"고산과 툰드라의 추위 속에서 자라요. 잎을 겨울에도 떨구지 않고 눈 밑에서 그대로 버텨요.\"},\"stories\":[{\"id\":\"bstory-bilberry-raf-nightvision\",\"title\":\"빌베리 잼과 야간시력 전설\",\"hook\":\"조종사가 빌베리 잼을 먹고 밤눈이 밝아졌다는 이야기에는 문서 증거가 없어요.\",\"body\":\"2차 세계대전 때 영국 공군 조종사들이 어둠 속에서 독일기를 잡아낸 비결이 빌베리 잼이라는 이야기가 널리 퍼졌어요. 맥길대학교 과학협회는 이 이야기를 검토하면서, 조종사들이 실제로 빌베리 잼을 먹었다는 문서 증거는 없다고 정리했어요. 진짜 비결은 기밀이던 기상 요격 레이더였고, 소문은 그 장비를 감추려고 군이 퍼뜨렸다는 설명이 붙어요. 같은 이야기가 당근 판본으로도 돌아다녔고요. 과학 쪽 검증도 신통치 않았어요. 플로리다의 해군항공우주연구소와 텔아비브대학교 연구진이 안토시아닌을 최대 40밀리그램까지 담은 추출물을 젊은 남성들에게 주고 야간 시력을 여러 방식으로 측정했는데, 두 곳 모두 개선이 없다는 결론을 냈어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mcgill.ca\",\"sourceUrl\":\"https://www.mcgill.ca/oss/article/nutrition-you-asked/it-true-bilberries-are-good-eyes\"},{\"id\":\"bstory-bilberry-vattenlingon\",\"title\":\"물에 담가 겨울을 난 열매\",\"hook\":\"설탕이 귀하던 시절 스웨덴 사람들은 월귤을 그냥 물에 담가 이듬해까지 보관했어요.\",\"body\":\"스웨덴에서 월귤은 겨울을 버티게 해준 열매였어요. 이 열매에는 벤조산이 많아서 끓이지 않아도 잘 상하지 않아요. 그래서 설탕이 사치품이던 시절에는 열매를 통째로 물에 담가 병에 넣어 두었는데, 이걸 바트링곤, 곧 물월귤이라고 불렀어요. 이렇게 두면 다음 수확 철까지 버텼고, 마실 것이자 괴혈병 대비책 노릇도 했어요. 채집은 지금도 이어져요. 스웨덴에는 만인의 권리라 불리는 자연 접근권이 있어서 누구나 숲에 들어가 월귤을 딸 수 있고, 열매는 대체로 8월에서 9월 사이에 익어요. 사람들은 스크래블러라 부르는 빗처럼 생긴 채집 도구로 훑어 담아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스웨덴\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"stockholmmuseum.com\",\"sourceUrl\":\"https://www.stockholmmuseum.com/stockholm-unveiled/food-drink/lingon.htm\"}]},\"10-13\":{\"photo\":{\"src\":\"/birth/jopapnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/jopapnamu.jpg\",\"author\":\"영철 이 from 광주 광역시\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Spiraea_prunifolia_var._simpliciflora_2014.4.5_(13679069895).jpg\",\"familyLine\":\"가지마다 흰 꽃이 좁쌀처럼 촘촘히 붙어요. 튀긴 좁쌀을 붙여 놓은 것 같다고 해서 이름이 생겼어요.\"},\"stories\":[{\"id\":\"bstory-spiraea-aspirin-etymology\",\"title\":\"아스피린 이름 속의 조팝나무\",\"hook\":\"아스피린의 '스피르'는 조팝나무속 학명 스피라이아에서 잘라 온 조각이에요.\",\"body\":\"아스피린이라는 이름에는 조팝나무속 학명이 박혀 있어요. 1828년 요제프 부흐너가 버드나무에서 유효 성분을 뽑아 살리신이라 이름 붙였고, 1830년에는 메도스위트에서도 같은 성분을 찾아냈어요. 당시 메도스위트의 학명이 스피라이아 울마리아였어요. 1853년에는 샤를 프레데리크 제라르가 살리실산의 구조를 밝히고 아세틸살리실산을 합성했고, 1897년 바이엘의 펠릭스 호프만이 살리실산에 아세틸기를 붙여 위를 덜 자극하게 만들었어요. 바이엘은 1899년 이 물질에 아스피린이라는 이름을 붙이고 같은 해 상표로 등록했어요. 아세틸의 A, 스피라이아에서 딴 스피르, 그 시절 약 이름에 흔히 붙던 인을 이어 붙인 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pharmaceutical-journal.com\",\"sourceUrl\":\"https://pharmaceutical-journal.com/article/infographics/a-history-of-aspirin\"},{\"id\":\"bstory-spiraea-jobap-name\",\"title\":\"조밥에서 온 이름 조팝나무\",\"hook\":\"꽃이 만발한 모습이 튀긴 좁쌀을 붙여 놓은 것 같아 조팝나무가 되었어요.\",\"body\":\"조팝나무라는 이름은 밥에서 왔어요. 한국민족문화대백과사전은 꽃이 만발한 식물체의 모양이 튀긴 좁쌀을 붙여 놓은 것같이 보인다고 해서 이 이름이 붙었다고 설명해요. 학명은 스피라이아 프루니폴리아 변종이고, 산과 들에서 흔하게 자라 키가 2미터쯤 되며 4~5월에 흰 꽃이 피어요. 어린순은 나물로 먹었고, 뿌리는 한약재로 썼어요. 해열과 수렴 효과가 있다고 보아 학질, 감모발열, 신경통, 인후종통, 설사, 대하에 쓰였고, 절학칠보음이나 상산음 같은 처방에 들어갔어요. 중국에서는 이 식물을 수선국이라 부르는데, 효녀 수선의 이름을 따서 붙였다는 이야기가 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0052732\"}]},\"10-14\":{\"stories\":[]},\"10-15\":{\"photo\":{\"src\":\"/birth/seuwiteu-bajeul.jpg\",\"thumbSrc\":\"/birth/thumbs/seuwiteu-bajeul.jpg\",\"author\":\"PumpkinSky\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ocimum_basilicum_CG_NBG_LR.jpg\",\"familyLine\":\"꽃대가 올라오면 잎 맛이 옅어져요. 그래서 향을 쓰려는 사람은 꽃봉오리를 미리 잘라 줘요.\"},\"stories\":[{\"id\":\"bstory-basil-isabella\",\"title\":\"바질 화분에 묻힌 연인의 머리\",\"hook\":\"리버풀 미술관에 걸린 그림 한 점이 바질 화분의 끔찍한 비밀을 담고 있어요.\",\"body\":\"이탈리아 작가 보카치오가 남긴 이야기에서 부유한 상인 집안의 딸 이사벨라는 가난한 도제 로렌초와 사랑에 빠져요. 오빠들은 로렌초를 죽여 묻어 버리고, 이사벨라는 시신을 찾아내 목을 잘라 바질 화분에 묻은 뒤 눈물로 물을 줘요. 존 키츠가 이 이야기를 시로 옮겼고, 열아홉 살 존 에버렛 밀레이가 1848년부터 그 시를 그림으로 그렸어요. 리버풀 워커 미술관 소장번호 WAG 1637이 그 작품이에요. 화면 뒤쪽 허브 화분이 결말을 미리 흘리고, 오빠 하나는 이사벨라의 개를 걷어차고 있으며, 두 연인은 핏빛 오렌지를 나눠 들고 있어요. 라파엘전파 양식으로 그려진 최초의 그림 가운데 하나예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"liverpoolmuseums.org.uk\",\"sourceUrl\":\"https://www.liverpoolmuseums.org.uk/artifact/isabella\"},{\"id\":\"bstory-basil-culpeper\",\"title\":\"뇌에 전갈이 생긴다던 풀\",\"hook\":\"17세기 영국 약초서는 바질을 놓고 저자들이 변호사처럼 물어뜯는다고 적었어요.\",\"body\":\"17세기 영국의 약초학자 니콜라스 컬페퍼는 컴플리트 허벌의 바질 항목을 이렇게 열어요. 모든 저자가 이 풀을 놓고 서로 귀를 물어뜯으며 변호사들처럼 욕을 주고받는다고요. 갈레노스와 디오스코리데스는 바질을 먹는 것 자체가 적절하지 않다고 보았대요. 컬페퍼는 힐라리우스라는 사람이 바질 냄새를 자주 맡다가 뇌에 전갈이 생겼다고 주장한 일, 미잘두스가 바질을 말똥 속에 넣어 썩히면 독충이 생긴다고 쓴 일도 함께 옮겨 놓았어요. 반대로 독 있는 짐승에게 물리거나 말벌이나 뿔말벌에 쏘인 자리에 붙이면 독을 빠르게 빨아낸다고도 적었고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/49513/49513-h/49513-h.htm\"}]},\"10-16\":{\"stories\":[]},\"10-17\":{\"photo\":{\"src\":\"/birth/podo.jpg\",\"thumbSrc\":\"/birth/thumbs/podo.jpg\",\"author\":\"Jules Verne Times Two\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Bunch_of_grapes_amidst_vine_leaves,_Ponte_de_Sor_(approx._GPS_location)_julesvernex2.jpg\",\"familyLine\":\"껍질에 앉은 뿌연 가루는 먼지가 아니에요. 수분을 지키려고 스스로 두른 밀랍이라 씻으면 사라져요.\"},\"stories\":[{\"id\":\"bstory-grape-planchon-phylloxera\",\"title\":\"뿌리를 파헤친 식물학자\",\"hook\":\"1868년 여름 플랑숑은 죽어가는 포도나무를 뽑아 뿌리에서 노란 진딧물을 찾아냈어요.\",\"body\":\"1866년부터 론강 일대의 포도밭이 이유 없이 말라 죽기 시작했어요. 1868년 여름 프랑스는 3인 조사위원회를 꾸렸고, 여기에 몽펠리에의 식물학자 쥘에밀 플랑숑이 들어갔어요. 이미 죽은 포도나무에서는 아무것도 나오지 않았는데, 아직 살아 있는 나무를 뽑아 보니 뿌리에 현미경으로 봐야 할 만큼 작은 노란 진딧물이 잔뜩 붙어 있었어요. 플랑숑은 이 벌레를 필록세라속으로 분류했어요. 학계는 벌레가 원인이 아니라 결과일 뿐이라며 반박했지만, 1870년대 초 미국 곤충학자 찰스 밸런타인 라일리가 미국에도 이 벌레가 흔한데 미국 포도나무는 견뎌 낸다고 알려 줘요. 플랑숑은 1873년 미국으로 건너가 라일리를 만났고, 미국 대목을 들여와 프랑스 품종을 접붙이자고 권했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"lindahall.org\",\"sourceUrl\":\"https://www.lindahall.org/about/news/scientist-of-the-day/jules-emile-planchon/\"},{\"id\":\"bstory-grape-300000-franc-prize\",\"title\":\"30만 프랑짜리 포도 현상금\",\"hook\":\"필록세라를 잡는 사람에게 30만 프랑을 주겠다고 하자 3년간 600건이 쏟아졌어요.\",\"body\":\"필록세라가 프랑스 포도밭에서 처음 눈에 띈 해는 1863년이에요. 1868년 정부가 만든 위원회가 진딧물을 원인으로 지목했고, 1870년에는 미국 곤충학자가 프랑스 품종을 미국 대목에 접붙이자는 해법을 내놨어요. 그사이 프랑스 정부는 치료법을 처음 찾아내는 사람에게 30만 프랑이 넘는 상금을 주겠다고 내걸었어요. 1874년부터 1877년까지 무려 600건의 방법이 접수됐어요. 결국 살아남은 답은 접목이었어요. 이미 필록세라를 견디는 미국 포도나무 뿌리 위에 프랑스 품종을 붙이는 방식이었고, 1890년대가 되자 프랑스 전역으로 퍼졌어요. 이 방법은 지금도 세계 곳곳의 포도밭에서 최선의 대책으로 쓰이고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"thisdayinwinehistory.com\",\"sourceUrl\":\"https://thisdayinwinehistory.com/the-great-french-blight/\"}]},\"10-18\":{\"photo\":{\"src\":\"/birth/neonchulwolgyul.jpg\",\"thumbSrc\":\"/birth/thumbs/neonchulwolgyul.jpg\",\"author\":\"Krzysztof Ziarnek, Kenraiz\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Vaccinium_oxycoccos_kz05.jpg\",\"familyLine\":\"이끼 늪 위를 실처럼 기어 다니며 자라요. 열매가 물에 뜨는 성질이 있어 수확할 때 밭에 물을 채워요.\"},\"stories\":[{\"id\":\"bstory-cranberry-1959-scare\",\"title\":\"추수감사절을 삼킨 크랜베리\",\"hook\":\"1959년 11월 9일 장관의 발표 한마디에 미국 밥상에서 크랜베리가 사라졌어요.\",\"body\":\"1959년 11월 9일, 추수감사절을 3주도 남기지 않은 시점에 미국 보건교육복지부 장관 아서 플레밍이 경고를 냈어요. 태평양 북서부에서 나온 크랜베리가 제초제 아미노트리아졸에 노출됐다는 내용이었어요. 실험실 쥐에서 갑상선 기능이 억제되고 종양이 생겼다는 결과가 근거였고, 1958년 식품첨가물 개정법의 딜레이니 조항이 법적 발판이었어요. 반응은 즉각적이었어요. 11월 중순까지 생과 판매가 전년 대비 63퍼센트, 통조림은 73퍼센트 떨어졌어요. 아이젠하워 대통령 부부는 추수감사절 식탁에 크랜베리 소스 대신 사과 소스를 올렸어요. 닉슨 부통령은 위스콘신 만찬에서 크랜베리를 네 접시나 비웠고, 같은 날 케네디 상원의원은 크랜베리 주스를 마셨어요. 정부는 나중에 재배 농가에 800만 달러가 넘는 보상금을 풀었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"history.com\",\"sourceUrl\":\"https://www.history.com/articles/great-cranberry-scare-thanksgiving-1959\"},{\"id\":\"bstory-cranberry-craneberry\",\"title\":\"두루미 머리를 닮은 꽃\",\"hook\":\"왐파노아그는 이 열매를 1만 2천 년 동안 거둬 왔어요.\",\"body\":\"매사추세츠의 왐파노아그 사람들은 이 열매를 사수무니아시라 부르며 1만 2천 년 동안 거둬 왔어요. 생으로 먹고, 말려서 나삼페라는 곡물가루에 섞고, 고기와 기름에 개어 몇 달을 가는 페미컨으로 만들었죠. 전통 치료사들은 열과 부기, 뱃멀미에 이 열매를 썼고요. 영국인들은 꽃이 샌드힐두루미의 머리를 닮았다고 해서 크레인베리라 불렀고 그 이름이 굳어 크랜베리가 됐어요. 1816년, 독립전쟁에 참전했던 헨리 홀 선장은 모래가 덮인 자리에서 야생 크랜베리가 더 잘 자라는 것을 알아채고 덩굴을 옮겨 심으며 모래를 뿌리기 시작했어요. 1871년에 첫 재배자 조합이 생겼고, 1885년 플리머스 카운티는 1347에이커, 바른스터블 카운티는 2408에이커를 재배했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"cranberries.org\",\"sourceUrl\":\"https://www.cranberries.org/history\"}]},\"10-19\":{\"photo\":{\"src\":\"/birth/ppalgang-bongseonhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/ppalgang-bongseonhwa.jpg\",\"author\":\"Yercaud-elango\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Impatiens_balsamina_hybrid-4-xavier_cottage-yercaud-salem-India.jpg\",\"familyLine\":\"여문 씨주머니를 건드리면 탁 터지며 씨를 튕겨 내요. 학명에 참을성 없다는 뜻이 붙은 이유예요.\"},\"stories\":[{\"id\":\"bstory-balsam-baekban\",\"title\":\"백반과 괭이밥의 화학\",\"hook\":\"봉선화 꽃잎만 찧어서는 손톱이 물들지 않아요.\",\"body\":\"봉선화라는 이름은 꽃 모양이 봉황을 닮았다는 데서 왔어요. 원산지는 인도와 말레이시아, 중국이고요. 우리나라에서는 여름이면 소녀들이 봉선화 꽃잎에 괭이밥 잎을 섞고 백반이나 소금을 조금 넣어 함께 빻은 다음 손톱에 얹어 물을 들였어요. 꽃잎만으로는 색이 제대로 들지 않기 때문이에요. 괭이밥에 든 수산이 손톱을 부드럽게 만들어 색소가 스며들게 하고, 소금은 색을 붙잡아 두는 매염제 노릇을 했어요. 붉은색이 사악한 기운을 물리친다는 믿음도 얹혀 있어서, 봉선화 물들이기에는 몸을 지키려는 뜻도 함께 담겨 있다고 봐요. 이 풍속은 조선 후기 세시풍속을 정리한 동국세시기에 기록으로 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0023931\"},{\"id\":\"bstory-balsam-hongnanpa\",\"title\":\"소설집에 실린 바이올린곡\",\"hook\":\"우리가 아는 가곡 봉선화는 처음에 가사 없는 바이올린곡이었어요.\",\"body\":\"가곡 봉선화는 처음부터 노래가 아니었어요. 1920년 홍난파가 펴낸 단편소설집 처녀혼에 애수라는 제목의 바이올린곡으로 처음 실렸어요. 소설집 안에 악보를 함께 넣은 셈이죠. 여기에 김형준이 가사를 붙이면서 성악곡이 되었고, 1925년에 나온 세계명작가곡집에 수록됐어요. 울 밑에 선 봉선화로 시작하는 그 노래예요. 곡이 먼저 있고 노랫말이 나중에 붙은 순서라, 지금 우리가 부르는 가사는 그 바이올린 선율이 세상에 나오고 몇 해 뒤에 만들어진 것이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0064008\"}]},\"10-20\":{\"stories\":[{\"id\":\"bstory-indian-hemp-itatamat\",\"title\":\"매듭으로 쓴 여자의 일기\",\"hook\":\"결혼한 날부터 굵어지는 실타래 하나가 한 사람의 연대기였어요.\",\"body\":\"미국 농무부 자연자원보전청 식물 안내서는 아포시넘 칸나비눔, 곧 인디언 헴프의 여러 쓰임 가운데 이타타마트를 사람들에게 가장 중요한 것으로 꼽아요. 날을 세는 공이라는 뜻이에요. 여자는 결혼한 날부터 이 식물 섬유로 꼰 긴 실에 매듭을 지어 자기 삶의 사건들을 기록했어요. 아이가 태어난 날, 누군가 죽은 날, 유난했던 날에는 구슬이나 조개껍데기 같은 표지를 함께 매달았죠. 매듭이 쌓이면서 실타래는 점점 굵어졌고, 손에 쥐기 어려울 만큼 커지면 새 공을 감기 시작했어요. 종이도 달력도 없이 실 한 가닥이 한 사람의 연대기가 된 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"plants.sc.egov.usda.gov\",\"sourceUrl\":\"https://plants.sc.egov.usda.gov/DocumentLibrary/plantguide/pdf/pg_apca.pdf\"},{\"id\":\"bstory-indian-hemp-cordage\",\"title\":\"한 포기에서 나오는 끈 75센티\",\"hook\":\"잘 꼰 인디언 헴프 밧줄은 수백 파운드를 견뎠다고 해요.\",\"body\":\"인디언 헴프 줄기는 서리가 내린 늦가을, 붉은 갈색으로 뻣뻣해졌을 때 밑동을 잘라 거뒀어요. 겉껍질과 목질 심 사이에 있는 섬유층을 조개껍데기나 흑요석, 뼈로 긁어 벗겨 내고, 줄기를 아래에서 위로 네 갈래로 쪼갠 다음 속의 나무 심을 손으로 걷어 냈죠. 파이우트 사람들은 긁어내지 않고 마른 줄기를 그냥 쪼개 부러뜨린 뒤 껍질을 비벼 털어 냈어요. 손에 물을 묻히고 허벅지 위에서 굴려 꼬면 마찰이 커져 실이 단단해졌고요. 한 포기에서 쓸 만한 섬유는 75센티미터쯤 나왔어요. 잘 꼰 밧줄은 현대 대마 밧줄에 맞먹어 수백 파운드에서 끊어졌고, 물에 젖어도 줄지 않고 힘을 유지했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"primitiveways.com\",\"sourceUrl\":\"https://primitiveways.com/hemp_dogbane.html\"}]},\"10-21\":{\"photo\":{\"src\":\"/birth/eonggeongkwi.jpg\",\"thumbSrc\":\"/birth/thumbs/eonggeongkwi.jpg\",\"author\":\"TANAKA Juuyoh (田中十洋)\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanese_Thistle_Cirsium_japonicum_bud-flower.jpg\",\"familyLine\":\"가시는 잎에만 있고 꽃에는 없어요. 먹히지 않으려는 방어와 벌을 부르려는 초대를 한 몸에 나눠 두었어요.\"},\"stories\":[{\"id\":\"bstory-thistle-order-1687\",\"title\":\"나를 건드리면 무사하지 못한다\",\"hook\":\"스코틀랜드 최고 훈장의 좌우명은 \\\"누구도 나를 무사히 건드리지 못한다\\\"예요.\",\"body\":\"엉겅퀴는 스코틀랜드 왕실 훈장의 이름이 됐어요. 시슬 훈장의 기원은 확정돼 있지 않은데, 영국 왕실 공식 설명은 809년 아카이우스 왕이 샤를마뉴와 동맹을 맺으며 만들어졌다는 전설과 함께, 엉겅퀴를 왕실 식물 배지로 채택한 제임스 3세를 나란히 언급해요. 제도로 확립된 건 1687년이에요. 제임스 7세가 새 규정을 두고 법적 기반을 갖추면서예요. 좌우명은 라틴어로 네모 메 임푸네 라케시트, 누구도 나를 무사히 건드리지 못한다는 뜻이에요. 기사는 열여섯 명이고, 예배당은 에든버러 세인트자일스 대성당 안의 시슬 채플이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"중세~17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"royal.uk\",\"sourceUrl\":\"https://www.royal.uk/the-order-of-the-thistle\"},{\"id\":\"bstory-thistle-dunbar-thrissill\",\"title\":\"엉겅퀴와 장미, 1503년\",\"hook\":\"1503년 시인 던바는 스코틀랜드를 엉겅퀴로, 잉글랜드를 장미로 세운 우화시를 썼어요.\",\"body\":\"엉겅퀴가 스코틀랜드의 상징이 된 과정은 전설보다 문서에서 또렷해요. 1931년 약초 사전은 문장으로서 가장 이른 기록으로 제임스 3세가 남긴 재산 목록을 꼽아요. 거기에 스리슬스, 곧 엉겅퀴를 수놓은 벽걸이가 올라 있었다는 거예요. 뒤이어 1503년에는 시인 윌리엄 던바가 제임스 4세와 잉글랜드 마거릿 공주의 혼인을 노래한 우화시 엉겅퀴와 장미를 썼어요. 스코틀랜드를 엉겅퀴로, 잉글랜드를 장미로 세운 이 시로 상징은 왕실 밖까지 퍼졌어요. 같은 책은 국화로 여겨지는 종을 스코치 시슬, 곧 오노포르둠 아칸티움으로 지목해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"15세기~16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://www.botanical.com/botanical/mgmh/t/thistl11.html\"}]},\"10-22\":{\"photo\":{\"src\":\"/birth/beotpul.jpg\",\"thumbSrc\":\"/birth/thumbs/beotpul.jpg\",\"author\":\"阿橋 HQ\",\"license\":\"CC BY-SA 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:%E9%87%8E%E6%85%88%E5%A7%91_Sagittaria_trifolia_-%E9%AB%98%E9%9B%84%E5%8E%9F%E7%94%9F%E6%A4%8D%E7%89%A9%E5%9C%92_Kaohsiung_Original_Botanical_Garden,_Taiwan-_(26111914217).jpg\",\"familyLine\":\"잎이 화살촉을 닮아서 이름이 붙었어요. 물속에 잠긴 잎은 화살촉 대신 가늘고 긴 모양으로 자라요.\"},\"stories\":[{\"id\":\"bstory-arrowhead-kuwai-osechi\",\"title\":\"싹이 트는 설날 음식 쿠와이\",\"hook\":\"일본에서는 큼직한 싹이 솟는 쿠와이를 두고 '싹이 나온다'며 오세치에 올려요.\",\"body\":\"일본에서 벗풀 무리의 알뿌리는 쿠와이라 불리며 새해 음식인 오세치에 빠지지 않아요. 둥근 알뿌리에서 굵은 싹이 쑥 솟은 모양이 싹이 튼다, 곧 앞길이 열린다는 뜻으로 읽히기 때문이에요. 일본어 이름이 출세를 뜻하는 말과 소리가 겹치는 점도 한몫했고요. 쿠와이 재배는 메이지 초기에 벼농사가 어려운 도쿄 근교 반습지에서 자리를 잡았고 메이지 말에는 전국으로 퍼졌어요. 사이타마의 소카·가와구치·이와쓰키가 대표 산지였고, 히로시마 후쿠야마는 1902년 무렵 아시다강 관개수를 끌어 쓰며 산지가 됐어요. 1955년 이후 도시화와 고된 손일 탓에 재배가 크게 줄었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"foodinjapan.org\",\"sourceUrl\":\"https://www.foodinjapan.org/japan/kuwai/\"},{\"id\":\"bstory-arrowhead-fukuyama\",\"title\":\"후쿠야마가 쥔 70퍼센트\",\"hook\":\"일본에서 나오는 쿠와이의 약 70퍼센트가 한 도시에서 나와요.\",\"body\":\"쿠와이는 논처럼 물을 댄 진흙 바닥에서 자라요. 간장 회사 깃코만이 정리한 식재료 사전에 따르면 일본에서 나오는 쿠와이의 약 70퍼센트를 히로시마현 후쿠야마시가 대고 있어요. 먹는 부분은 땅속 알뿌리인데 부드러운 식감에 쌉싸래한 맛이 뒤에 남아요. 조려 먹거나 튀기고, 크림에 넣어 스튜로 끓이거나 얇게 저며 칩으로 만들기도 해요. 알뿌리에서 굵게 솟은 싹은 행운을 부른다고 여겨져 새해 요리에 없어서는 안 될 재료로 꼽히고요. 겨울에 진흙 속에서 캐낸 알뿌리가 그대로 정월 찬합에 오르는 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"kikkoman.com\",\"sourceUrl\":\"https://www.kikkoman.com/en/cookbook/glossary/kuwai.html\"}]},\"10-23\":{\"photo\":{\"src\":\"/birth/huindokmalpul.jpg\",\"thumbSrc\":\"/birth/thumbs/huindokmalpul.jpg\",\"author\":\"John Tann from Sydney, Australia\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Datura_stramonium_flower_(8975477148).jpg\",\"familyLine\":\"해가 지고 나서야 나팔 같은 꽃을 열어요. 밤에 오는 나방만 상대하기로 정한 거예요. 온몸에 독이 있으니 만지고 나면 손을 씻어 주세요.\"},\"stories\":[{\"id\":\"bstory-datura-jamestown\",\"title\":\"열하루를 잃어버린 병사들\",\"hook\":\"1676년 제임스타운의 병사들은 샐러드 한 접시에 열하루를 통째로 잃었어요.\",\"body\":\"1676년 베이컨의 반란을 진압하러 제임스타운에 주둔한 영국 병사들이 흰독말풀 무리를 삶아 넣은 샐러드를 먹었어요. 로버트 베벌리는 1705년 버지니아의 역사와 현재에 그 광경을 적어 두었어요. 병사들은 며칠 동안 완전히 얼이 빠진 바보가 되었는데, 하나는 깃털을 공중에 불어 올리고 다른 하나는 그것을 향해 사납게 지푸라기를 던졌으며, 또 하나는 발가벗은 채 구석에 앉아 원숭이처럼 이를 드러내고 얼굴을 찡그렸다고 해요. 제 오물 위에 뒹굴지 않도록 가둬 두어야 했고요. 열하루 만에 제정신이 돌아온 병사들은 그동안의 일을 하나도 기억하지 못했어요. 그 뒤로 이 풀은 제임스타운 위드라 불렸고, 발음이 뭉개져 짐슨위드가 됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"capitalnaturalist.blogspot.com\",\"sourceUrl\":\"http://capitalnaturalist.blogspot.com/2014/11/jamestown-weed.html\"},{\"id\":\"bstory-datura-tropane-alkaloids\",\"title\":\"악마의 나팔과 천식약\",\"hook\":\"흰독말풀에는 아트로핀 같은 알칼로이드가 들어 있어 소량은 천식약으로 쓰였어요.\",\"body\":\"흰독말풀은 이름이 여러 개예요. 짐슨위드는 제임스타운 위드가 줄어든 말이고, 그 밖에 악마의 나팔, 악마의 덫, 가시사과 같은 이름으로도 불려요. 이 식물에는 트로판 알칼로이드 세 가지가 들어 있어요. 스코폴라민, 히오스시아민, 아트로핀이에요. 적은 양은 천식과 근육 경련, 파킨슨병 치료에 쓰이기도 했어요. 하지만 양이 많아지면 이야기가 달라져요. 동공이 커지고 열이 나고 갈증이 심해지며, 몸의 균형이 무너지고 혼란과 환각, 섬망이 오고, 얼굴이 붉어지고 맥이 빠르고 약해지며 호흡이 힘들어지다가 경련과 혼수까지 갈 수 있어요. 원예 도감은 이 식물의 독성 등급을 높음으로 매기고, 모든 부분에 독이 있다고 적어 두었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/datura-stramonium/\"}]},\"10-24\":{\"photo\":{\"src\":\"/birth/maehwa.jpg\",\"thumbSrc\":\"/birth/thumbs/maehwa.jpg\",\"author\":\"Laitche\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Flowers_of_Prunus_mume_(Armenaca_mume_%E2%80%98Bumpi%E2%80%99)_at_Nagai_Botanical_Garden,_February_2024_-_5452.jpg\",\"familyLine\":\"눈이 채 녹기 전에 피어요. 잎도 나기 전에 꽃부터 여는 성질이라 향이 유난히 멀리 가요.\"},\"stories\":[{\"id\":\"bstory-mume-lin-bu-plum-wife\",\"title\":\"매화를 아내로, 학을 자식으로\",\"hook\":\"북송의 임포는 서호 고산에 숨어 매화를 아내로, 학을 자식으로 삼았어요.\",\"body\":\"북송의 시인 임포는 벼슬길을 마다하고 항저우 서호 고산에 초막을 짓고 살았어요. 그 둘레에 매화를 심고 학을 길렀는데 평생 장가를 들지 않아, 사람들은 매화를 아내로 삼고 학을 자식으로 삼았다고 말했어요. 매처학자라는 말이 여기서 나왔고 이후 은거하는 선비의 상징처럼 굳어졌어요. 명나라 화가 두근은 15세기 후반에 달빛 아래 거니는 시인 임포라는 족자를 그렸어요. 지팡이를 짚은 사람이 매화나무를 바라보며 느리게 걷는 그림인데, 임포가 남긴 매화 시의 한 장면이에요. 굽은 매화 줄기와 바위를 짙고 옅은 먹으로 나눠 찍어낸 붓질이 특히 생생하고, 지금은 클리블랜드 미술관이 소장하고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"clevelandart.org\",\"sourceUrl\":\"https://www.clevelandart.org/art/1954.582\"},{\"id\":\"bstory-mume-tobiume-dazaifu\",\"title\":\"교토에서 하룻밤에 날아온 매화\",\"hook\":\"좌천된 스가와라노 미치자네를 따라 매화나무가 규슈까지 날아왔다고 해요.\",\"body\":\"매화는 나라 시대에 당나라에서 들어온 새롭고 우아한 나무였어요. 헤이안 시대의 학자 스가와라노 미치자네가 이 꽃을 몹시 아꼈고, 그가 다자이후로 좌천되던 날 매화나무를 두고 와카 한 수를 지었다고 전해져요. 전설은 여기서 한 걸음 더 나가요. 교토에 남겨진 매화 한 그루가 주인을 그리워한 나머지 하룻밤 사이에 규슈까지 날아와 다시 그의 곁에 섰다는 거예요. 이 나무가 도비우메, 곧 날아온 매화이고, 다자이후 덴만구 본전 옆에 선 매화가 바로 그 나무로 여겨져요. 근처 에노키샤 신사 옆에는 도비우메가 처음 내려앉았다는 자리에서 150미터쯤 떨어진 곳에 또 다른 도비우메가 서 있고, 미치자네의 아이 구마마로의 무덤 곁에는 꽃잎이 여섯 장인 특이한 매화가 자라요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"dazaifu-japan-heritage.jp\",\"sourceUrl\":\"https://www.dazaifu-japan-heritage.jp/en/bunkazai/detail.php?cId=336\"}]},\"10-25\":{\"photo\":{\"src\":\"/birth/danpungnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/danpungnamu.jpg\",\"author\":\"Dietmar Rabich\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japanischer_Ahorn_--_2021_--_3946.jpg\",\"familyLine\":\"잎이 붉어지는 건 초록이 빠져나간 뒤에야 원래 색이 드러나는 거예요. 붉은색은 새로 칠한 게 아니라 내내 안에 있었어요.\"},\"stories\":[{\"id\":\"bstory-maple-flag-debate\",\"title\":\"새벽 2시 15분에 정해진 단풍잎\",\"hook\":\"270번의 연설 끝에 캐나다 국기의 단풍잎이 통과된 시각은 새벽 2시 15분이었어요.\",\"body\":\"캐나다 국기의 단풍잎은 순순히 정해지지 않았어요. 1964년 6월 15일 의회에서 국기 논쟁이 열렸고, 연설이 270번 이어졌어요. 총리 레스터 피어슨은 파란 띠에 단풍잎 세 장을 넣은 도안을 밀었는데, 왕립군사대학 문리대학장이던 조지 스탠리가 세 장보다 한 장이 낫다고 설득했어요. 자유당 일곱, 보수당 다섯, 나머지 정당 셋으로 꾸린 위원회가 9월 중순부터 여섯 주 동안 도안을 골랐고, 12월 15일 토론종결 동의가 152 대 85로 통과됐어요. 그리고 12월 17일 새벽 2시 15분, 163 대 78로 단풍잎 한 장이 확정됐어요. 새 국기가 처음 게양된 건 1965년 2월 15일이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"캐나다\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"canadashistory.ca\",\"sourceUrl\":\"https://www.canadashistory.ca/explore/politics-law/the-great-flag-debate\"},{\"id\":\"bstory-maple-syrup-heist\",\"title\":\"물로 채워진 메이플시럽 통\",\"hook\":\"2012년 여름 퀘벡의 시럽 비축고를 열어 보니, 통 안에는 시럽 대신 물이 들어 있었어요.\",\"body\":\"퀘벡에는 세계 메이플시럽 전략 비축고가 있어요. 세인트루이드블랑포르 창고에 통을 쌓아 두고 물량과 시세를 조절하죠. 2012년 여름 점검에서 검사원이 통을 열었더니 어떤 통은 비어 있었고, 어떤 통은 물로 채워져 있었어요. 사라진 시럽은 9500통, 비축량의 8분의 1가량이었고 시가로 1800만 캐나다달러가 넘었어요. 범인들은 그걸 1000만 캐나다달러쯤에 팔아넘겼고요. 같은 해 12월부터 체포가 시작돼 주범 리샤르 발리에르는 2016년 유죄 판결을 받았어요. 2022년 3월 31일 캐나다 대법원은 그에게 910만 캐나다달러 벌금과 8년형을 확정했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"캐나다\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"forbes.com\",\"sourceUrl\":\"https://www.forbes.com/sites/nicholasreimann/2022/03/31/ringleader-of-great-canadian-maple-syrup-heist-ordered-to-pay-multi-million-dollar-fine/\"}]},\"10-26\":{\"photo\":{\"src\":\"/birth/suyeong-1026.jpg\",\"thumbSrc\":\"/birth/thumbs/suyeong-1026.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rumex_acetosa_-_Hapu_oblikas.jpg\",\"familyLine\":\"잎을 씹으면 새콤한 맛이 돌아요. 그 신맛 때문에 옛날 아이들이 들에서 간식처럼 뜯어 먹었어요.\"},\"stories\":[{\"id\":\"bstory-sorrel-acetaria\",\"title\":\"1699년 샐러드 책의 필수 재료\",\"hook\":\"존 이블린은 수영을 샐러드에서 결코 빼서는 안 될 재료라고 못 박았어요.\",\"body\":\"1699년 영국의 존 이블린은 샐러드만 다룬 책 아세타리아를 펴냈어요. 그 목록의 예순한 번째 항목이 수영이에요. 잎이 둥근 프랑스 종과 잎이 넓은 독일 종을 나누어 적고, 그린란드 수영이 가장 낫다고 했죠. 성질은 차고, 씻어 내리며, 시고, 식욕을 돋우고, 열을 가라앉히고, 간을 식히고, 심장을 튼튼하게 한다고 썼어요. 무엇보다 그는 수영을 괴혈병을 막고 부패를 막는 재료로 보았어요. 나머지 재료에 상큼한 날을 세워 주어서 오렌지와 레몬 같은 신맛 재료가 없을 때 그 자리를 대신하니, 결코 빼서는 안 된다고 못 박았고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/15517/15517-h/15517-h.htm\"},{\"id\":\"bstory-sorrel-salts-of-lemon\",\"title\":\"잉크 얼룩을 지운 레몬염\",\"hook\":\"수영에서 나온 옥살산은 '레몬염'이라는 이름으로 팔려 얼룩을 지우는 데 쓰였어요.\",\"body\":\"수영의 신맛은 옥살산에서 나와요. 그런데 이 성분은 먹는 것 말고도 쓸모가 있었어요. 수영에서 나온 옥살산염은 레몬염이라는 이름으로 상품이 되어, 밀짚을 표백하거나 리넨에 앉은 녹 자국을 빼거나 잉크 얼룩을 지우는 데 쓰였어요. 약으로도 오래 썼어요. 1세기의 그리스 의사 디오스코리데스와 로마의 대 플리니우스 시절부터 등장하는데, 몸을 식혀 주는 풀로 여겨 열병과 피부 종양, 황달, 몸속 궤양에 썼고 헌데와 멍, 종기, 수두에도 발랐어요. 화살촉 모양 잎은 1700년대까지 유럽 중세 채마밭에서 익숙한 풍경이었어요. 값이 싸고 어디서나 구할 수 있어 가난한 사람의 풀이라는 별명도 붙었고, 도싯의 아이들은 잎을 간식처럼 뜯어 먹었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"eatweeds.co.uk\",\"sourceUrl\":\"https://www.eatweeds.co.uk/sorrel-rumex-acetosa\"}]},\"10-27\":{\"stories\":[]},\"10-28\":{\"photo\":{\"src\":\"/birth/mugunghwa-1028.jpg\",\"thumbSrc\":\"/birth/thumbs/mugunghwa-1028.jpg\",\"author\":\"Didier Descouens\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:(MHNT)_Hibiscus_syriacus_Pink_Rose_of_Sharon_hibiscus_flower_-_Les_Martels,_Giroussens_Tarn.jpg\",\"familyLine\":\"한 송이는 하루면 지지만 다음 봉오리가 곧바로 이어 피어요. 여름 내내 꽃이 끊기지 않는 이유예요.\"},\"stories\":[{\"id\":\"bstory-mugunghwa-80000-seedlings-burned\",\"title\":\"묘목 팔만 주를 불태운 사건\",\"hook\":\"학교 실습지에서 기른 무궁화 묘목이 전국으로 나갔습니다. 1933년 일제는 그 묘목 팔만 주를 태웠습니다.\",\"body\":\"남궁억은 민족교육자였어요. 강원도 홍천에 모곡학교를 세우고, 학생 실습지에서 무궁화 묘목을 길렀어요. 그 묘목을 전국 각지로 보냈고요. 나라꽃을 심는 일 자체가 운동이었던 거예요. 1933년, 일제는 이 일이 불온사상을 고취하고 치안을 어지럽힌다고 했어요. 모곡학교 교직원과 교회 목사, 남궁억의 친척까지 모두 잡아갔어요. 그리고 무궁화 묘목 팔만 주를 불태웠어요. 이 사건을 취조하던 중에 기독교인들의 비밀결사 십자당이 드러나면서 일이 더 커졌고, 수많은 사람이 함께 붙잡혔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"1930년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0018951\"},{\"id\":\"bstory-mugunghwa-shanhaijing-junzi\",\"title\":\"아침에 피고 저녁에 지는 풀\",\"hook\":\"이천 년도 더 된 중국 지리서에 군자의 나라와 그 나라의 풀 한 포기가 적혀 있습니다.\",\"body\":\"산해경 해외동경에 이런 대목이 있어요. 그 북쪽에 군자국이 있는데, 사람들이 의관을 갖추고 칼을 차며, 짐승을 먹이고 큰 호랑이 두 마리를 곁에 두고, 서로 사양하며 다투지 않는다고요. 그리고 한 문장이 더 붙어요. 훈화초가 있는데 아침에 피고 저녁에 진다고요. 후대 사람들은 이 훈화초를 무궁화로 읽었어요. 무궁화가 하루 만에 지는 꽃이거든요. 다투지 않는 나라에 하루짜리 꽃이 핀다는 그림이 오래 남았어요. 다만 훈화초가 정말 무궁화였는지, 군자국이 어디였는지는 원문이 말해 주지 않아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국·한국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"ctext.org\",\"sourceUrl\":\"https://ctext.org/shan-hai-jing/hai-wai-dong-jing\"},{\"id\":\"bstory-rose-of-sharon-no-law\",\"title\":\"법으로 정한 적 없는 나라꽃\",\"hook\":\"무궁화를 국화로 삼는다고 못 박은 법 조항은 없어요.\",\"body\":\"무궁화는 법으로 국화라고 정해진 적이 없어요. 관습으로 그렇게 여겨 온 꽃이에요. 그 대신 기록이 아주 오래됐어요. 기원전 8세기에서 3세기 사이에 엮인 산해경은 우리 땅의 꽃을 훈화초라 적으며 아침에 피었다가 저녁에 진다고 했고, 신라 효공왕이 당나라에 보낸 국서는 우리나라를 무궁화의 땅이라는 뜻의 근역이라 불렀어요. 강희안의 양화소록에는 단군이 나라를 열 때 무궁화가 비로소 나왔다는 전승이 실려 있고요. 결정적인 계기는 개화기였어요. 애국가 후렴에 무궁화 삼천리 화려강산이라는 구절이 들어가면서 무궁화는 조선의 국화가 되어 오늘에 이르렀어요. 꽃이 7월부터 10월까지 백 일 넘게 이어 피어서 붙은 이름이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0018949\"},{\"id\":\"bstory-rose-of-sharon-namgung-eok\",\"title\":\"1933년, 불태워진 묘목 10만 주\",\"hook\":\"일제 경찰은 학생들을 시켜 무궁화 묘포를 뽑게 하고 그 자리에 벚나무를 심었어요.\",\"body\":\"강원도 홍천 보리울에 모곡학교를 세운 남궁억은 무궁화 묘목을 길러 전국에 보급했어요. 무궁화를 심는 일이 민족의식을 지키는 일이라고 보았기 때문이에요. 1933년, 모곡학교 교사 김복동의 일기장을 압수한 경찰이 수사를 시작했어요. 남궁억과 유자훈, 김복동, 남궁모 등 관련자들은 한 달 넘게 혹독한 취조와 고문을 받은 뒤 서울로 넘겨졌죠. 강원도 경찰국은 모곡학교 학생들을 동원해 묘포의 무궁화를 뽑게 했고, 10만 주에 가까운 묘목이 모두 불에 탔어요. 일제는 뽑아낸 자리에 일본 국화인 사쿠라를 심었고, 모곡학교는 폐교되어 공립학교로 편입됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"christiantoday.co.kr\",\"sourceUrl\":\"https://www.christiantoday.co.kr/news/326782\"},{\"id\":\"bstory-rose-of-sharon-bible-mistranslation\",\"title\":\"샤론의 장미는 무궁화가 아니다\",\"hook\":\"성경의 '샤론의 장미'는 무궁화가 아니라 사프란이나 백합류였을 가능성이 커요.\",\"body\":\"영어권에서 무궁화를 부르는 이름 로즈 오브 샤론은 1611년 킹제임스 성경의 아가에서 처음 쓰였어요. 그런데 학자들은 이 번역이 히브리어 하바첼렛 하샤론을 잘못 옮긴 것으로 봐요. 이스라엘 샤론 평야에서 자라던 사프란이나 바다수선화, 튤립, 마돈나백합 쪽이었을 가능성이 크다는 거예요. 지금 우리가 로즈 오브 샤론이라 부르는 식물은 학명이 히비스쿠스 시리아쿠스, 곧 시리아의 히비스커스인데 실제로는 아시아가 원산이에요. 이름이 두 번 어긋난 셈이에요. 게다가 장미도 아니에요. 아욱과에 속해서 접시꽃, 목화, 오크라, 마시멜로와 친척이고, 아시아에서는 영원히 지지 않는 꽃이라 불렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중동\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"vineyardgazette.com\",\"sourceUrl\":\"https://vineyardgazette.com/news/2011/08/25/rose-without-thorn\"}]},\"10-29\":{\"photo\":{\"src\":\"/birth/haedanghwa.jpg\",\"thumbSrc\":\"/birth/thumbs/haedanghwa.jpg\",\"author\":\"ArildV\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rosa_rugosa_Tj%C3%B6rn_June_2026_01.jpg\",\"familyLine\":\"바닷가 모래언덕에 뿌리를 박고 살아요. 소금바람을 견디려고 잎에 깊은 주름을 잡아 두었어요.\"},\"stories\":[{\"id\":\"bstory-rugosa-invasive-europe\",\"title\":\"유럽 해안을 덮은 해당화\",\"hook\":\"고향에선 멸종위기종인데 유럽 해안사구에서는 골칫거리예요.\",\"body\":\"해당화의 학명은 로사 루고사이고 중국과 한반도, 일본, 북쪽으로 캄차카반도까지가 원래 사는 곳이에요. 1796년 일본에서 영국으로 들어간 뒤 유럽 각지로 퍼졌어요. 야생화 기록은 독일이 1845년, 덴마크가 1875년, 스웨덴이 1918년이고, 2001년까지 유럽 열여섯 나라에서 야생화한 개체군이 확인됐어요. 북서유럽 해안에서는 크고 빽빽한 덤불을 이뤄 그 자리의 토박이 식물을 밀어내요. 2018년 사이언티픽 리포츠에 실린 연구를 보면 유럽 개체군은 원산지 중국 개체군보다 생장과 번식 형질이 두 배에서 네 배까지 높았고, 제곱미터당 종자 수는 4.2배였어요. 정작 중국에서는 자생 개체군이 빠르게 줄어 멸종위기종으로 지정돼 있고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5893583/\"},{\"id\":\"bstory-rugosa-korean-coast\",\"title\":\"우리 해안에서 사라진 꽃\",\"hook\":\"예전에는 우리나라 모든 해안 모래밭에서 볼 수 있던 꽃이에요.\",\"body\":\"해당화는 장미과의 낙엽관목으로 키가 1.5미터쯤 자라요. 줄기에는 가시와 가시털, 융모가 함께 나 있고 잎은 두껍고 주름이 많으며 표면에 윤기가 돌아요. 5월부터 7월 사이에 지름 6에서 9센티미터쯤 되는 붉은 자주색 꽃이 피는데, 향이 아주 강해서 꽃은 향수 원료로 쓰였어요. 열매는 8월에 황적색으로 익고요. 한국민족문화대백과사전은 해당화가 바닷가 모래밭과 산기슭에서 자라 우리나라 전 해안 모래땅에서 볼 수 있었으나 지금은 원형 그대로 남아 있는 곳이 드물다고 적고 있어요. 꽃과 뿌리껍질, 열매는 모두 약재로 썼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0062490\"}]},\"10-30\":{\"photo\":{\"src\":\"/birth/robelria.jpg\",\"thumbSrc\":\"/birth/thumbs/robelria.jpg\",\"author\":\"Nicola van Berkel\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lobelia_erinus_flower_(02).jpeg\",\"familyLine\":\"꽃이 위아래로 갈라져 나비 모양을 만들어요. 아래쪽 세 갈래가 벌이 내려앉을 자리예요.\"},\"stories\":[{\"id\":\"bstory-lobelia-thomson-trial\",\"title\":\"1809년, 로벨리아 살인 재판\",\"hook\":\"약초상 새뮤얼 톰슨은 로벨리아로 사람을 죽였다는 혐의로 감옥에 갇혔어요.\",\"body\":\"1809년 11월 10일, 미국 매사추세츠 뉴버리포트에서 약초상 새뮤얼 톰슨이 체포됐어요. 러벌이라는 청년을 치료하다 죽게 했다는 이유였는데, 고발자인 프렌치 의사는 톰슨이 치명적인 독인 로벨리아로 그를 죽였다고 주장했어요. 톰슨은 난방도 없는 감방에서 한 달을 보낸 뒤 12월 20일 세일럼 법정에 섰고, 재판장은 시어필러스 파슨스였어요. 검찰 측 증인 하우 의사는 문제의 가루가 로벨리아라고 증언했지만, 변호인은 하우가 로벨리아를 알아보지도 못하며 그 가루는 사실 마시로즈메리 뿌리였다는 점을 밝혀냈어요. 법원은 톰슨을 무죄로 풀어 줬어요. 이듬해 3월 톰슨이 프렌치를 상대로 낸 손해배상 소송은 오히려 져서 600달러가 넘는 소송비만 떠안았고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"henriettes-herb.com\",\"sourceUrl\":\"https://www.henriettes-herb.com/eclectic/dmna/thomson.html\"},{\"id\":\"bstory-lobelia-lobel-royal-botanist\",\"title\":\"제임스 1세의 왕실 식물학자\",\"hook\":\"로벨리아라는 이름은 몽펠리에에서 공부한 플랑드르 의사에게서 왔어요.\",\"body\":\"로벨리아라는 속명은 플랑드르 출신 의사이자 식물학자 마티아스 드 로벨에게서 따왔어요. 1538년에 태어나 몽펠리에에서 공부한 뒤 유럽 여러 나라를 옮겨 다니며 일했고, 마지막에는 잉글랜드에 자리를 잡아 제임스 1세의 주치의이자 왕실 식물학자가 됐어요. 외떡잎식물과 쌍떡잎식물이 서로 다르다는 걸 처음 알아본 식물학자로도 꼽혀요. 그의 이름을 단 로벨리아속은 지금까지 439종이 인정되는 큰 무리인데, 화단의 자잘한 한해살이풀부터 동아프리카 산지에서 굵고 짧은 줄기를 세우는 거대종까지 생김새가 제각각이에요. 북아메리카의 로벨리아 인플라타는 호흡기 질환 치료에 쓰였고, 이 무리를 대표하는 알칼로이드 로벨린이 그 약효의 배경이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"herbaria.plants.ox.ac.uk\",\"sourceUrl\":\"https://herbaria.plants.ox.ac.uk/bol/plants400/Profiles/KL/Lobelia\"}]},\"10-31\":{\"photo\":{\"src\":\"/birth/kalra.jpg\",\"thumbSrc\":\"/birth/thumbs/kalra.jpg\",\"author\":\"Bernard Spragg. NZ from Christchurch, New Zealand\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Arum_lily_(Zantedeschia_aethiopica)_(46592567661).jpg\",\"familyLine\":\"깔때기처럼 말린 흰 부분은 꽃잎이 아니라 잎이 변한 덮개예요. 진짜 꽃은 그 안에 선 노란 기둥에 촘촘히 붙어 있어요.\"},\"stories\":[{\"id\":\"bstory-calla-easter-lily-1926\",\"title\":\"1926년, 손으로 만든 부활절 백합\",\"hook\":\"아일랜드 공화파 여성들이 손수 접은 흰 꽃 배지가 100년을 버텼어요.\",\"body\":\"1916년 부활절 봉기 10주년이던 1926년, 아일랜드 공화파 여성 조직 쿠먼 나 만이 흰 백합 모양의 배지를 만들어 팔기 시작했어요. 공장에서 찍어 낸 물건이 아니라 여성들이 하나하나 손으로 만든 꽃이었고, 흰 꽃잎에 초록 밑동과 주황 꽃술을 넣어 아일랜드 삼색기를 그대로 옮겨 놨어요. 판매 수익은 아일랜드 공화파 수감자 유가족 기금으로 갔는데, 자원병과 정치범의 미망인과 아이들, 나이 든 부양가족을 돕는 돈이었어요. 이 꽃은 봉기에서 목숨을 잃은 이들을 기억하는 표식이 됐고, 부활절 일요일 성당 문 앞에서 팔리다가 지금도 공화파 추모 행사의 옷깃에 달려요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"brooklynirish.org\",\"sourceUrl\":\"https://brooklynirish.org/2026/04/02/100-years-of-the-easter-lily/\"},{\"id\":\"bstory-calla-okeeffe-25000\",\"title\":\"칼라 여섯 점에 2만 5천 달러\",\"hook\":\"1928년 4월, 익명의 수집가가 오키프의 작은 칼라 그림 여섯 점을 사들였어요.\",\"body\":\"1928년 4월, 이름을 밝히지 않은 수집가가 조지아 오키프의 작은 칼라 그림 여섯 점을 2만 5천 달러에 사들였어요. 당시 살아 있는 화가의 작품에 매겨진 최고가였어요. 오키프는 그해에만 칼라를 여섯 번 그렸는데, 스승 아서 웨슬리 다우에게서 배운 연작 방식이었어요. 하나의 생각을 오래 붙들고 아주 사실적인 그림에서 출발해도, 같은 대상을 거듭 그리다 보면 형태가 점점 단순해져 결국 추상만 남는다는 게 본인의 설명이었죠. 1929년 붉은 바탕의 칼라 그림을 두고 평론가 머독 펨버턴은 그 시즌에 본 어떤 작품 못지않게 짜릿하다고 썼어요. 같은 해 미겔 코바루비아스는 뉴요커에 칼라를 든 오키프를 그려 우리의 백합 성모라는 제목을 붙였고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"sothebys.com\",\"sourceUrl\":\"https://www.sothebys.com/en/auctions/ecatalogue/2018/contemporary-art-evening-sale-n09932/lot.15.html\"}]},\"11-1\":{\"photo\":{\"src\":\"/birth/seoyangmogwa.jpg\",\"thumbSrc\":\"/birth/thumbs/seoyangmogwa.jpg\",\"author\":\"Rosser1954\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Medlar_(Mespilus_germanica)_flower,_Ayrshire.jpg\",\"familyLine\":\"서리를 맞고 무르기 전에는 먹을 수 없어요. 겨울이 지나야 비로소 단맛이 도는 늦된 열매예요.\"},\"stories\":[{\"id\":\"bstory-medlar-open-arse-literature\",\"title\":\"셰익스피어의 모과 농담\",\"hook\":\"서양모과의 옛 별명은 '오픈어스'였고, 초서와 셰익스피어가 그 이름으로 농담을 했어요.\",\"body\":\"서양모과는 벌어진 열매 끝 모양 때문에 영어권에서 오픈어스라는 별명으로 불렸어요. 초서는 캔터베리 이야기 청지기의 서시에서 늙어 가는 자신을 이 열매에 빗대, 오픈어스처럼 되어 간다면 그 열매는 썩기 전까지 갈수록 나빠질 뿐이라고 말하게 했어요. 셰익스피어는 로미오와 줄리엣 2막 1장에서 머큐시오가 모과나무 아래 숨은 로미오를 두고 같은 별명으로 음담을 던지게 했고요. 뜻대로 하세요 3막 2장에서는 로절린드가 터치스톤에게 익기도 전에 썩을 거라며 그게 바로 모과의 미덕이라고 쏘아붙여요. D. H. 로런스도 1923년 시 모과와 마가목 열매에서 이 열매를 다뤘어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"eastgatelarder.co.uk\",\"sourceUrl\":\"https://www.eastgatelarder.co.uk/blog/literary-medlars\"},{\"id\":\"bstory-medlar-bletting-frost\",\"title\":\"서리를 맞아야 먹는 과일\",\"hook\":\"설탕이 흔해지기 전 유럽의 겨울 단맛은 물러 터진 열매에서 왔어요.\",\"body\":\"서양모과는 장미과의 작은 나무로 남동유럽에서 중앙아시아에 걸쳐 자라고, 늦봄에 장미를 닮은 희거나 연분홍인 꽃을 큼직하게 피워요. 수천 년 동안 재배됐고 고대 그리스와 로마에서도 중요한 과실수였는데, 이유는 단순해요. 딴 직후에는 딱딱하고 떫어서 먹을 수 없지만 서리를 맞히거나 서늘한 곳에 두고 블레팅이라 부르는 물러짐을 기다리면, 흰 과육이 갈색으로 변하면서 단맛이 올라와요. 설탕이 널리 퍼진 1500년경 이전까지 가을과 겨울에 얻을 수 있는 몇 안 되는 단맛이었던 셈이에요. 빅토리아 시대 잉글랜드에서 다시 유행해 형편이 넉넉한 집에서 젤리와 술을 담갔고요. 프랑스 이름 퀼 드 시앵은 개 엉덩이라는 뜻인데, 쭈그러진 꽃받침 자국을 보고 붙인 말이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"arboretumfoundation.org\",\"sourceUrl\":\"https://arboretumfoundation.org/2019/09/26/medlar/\"}]},\"11-2\":{\"photo\":{\"src\":\"/birth/rupineoseu.jpg\",\"thumbSrc\":\"/birth/thumbs/rupineoseu.jpg\",\"author\":\"George Chernilevsky\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lupinus_polyphyllus_UA_2026_G4.jpg\",\"familyLine\":\"뿌리에 공기 중의 질소를 붙잡아 두는 세균을 길러요. 척박한 땅에 먼저 들어가 흙을 기름지게 만들어요.\"},\"stories\":[{\"id\":\"bstory-lupine-hilda-hamlin-maine\",\"title\":\"메인주 길가를 물들인 주머니 속 씨앗\",\"hook\":\"산책길마다 주머니에서 루피너스 씨를 흘리고 다닌 할머니가 있었어요.\",\"body\":\"힐다 에드워즈 햄린은 1904년 십 대 나이에 미국 메인주 크리스마스 코브로 왔어요. 스미스 칼리지 교수였던 삼촌이 부른 길이었죠. 삼촌이 세상을 떠난 뒤 러더퍼드섬의 여름 별장을 물려받은 그는 해마다 그곳에서 여름을 보내며, 주머니에 넣어 둔 루피너스 씨를 해안 산책길에 흘리고 다녔어요. 남의 차를 얻어 탈 때는 창밖으로 씨를 던지기도 했고요. 이 조용한 씨뿌리기는 1971년 잡지 기사로 처음 세상에 알려졌어요. 근처 더매리스코타에 살며 그를 알고 지내던 그림책 작가 바버라 쿠니는 1982년 미스 럼피우스로 그의 이야기를 옮겼고, 이 책은 전미도서상을 받아 지금도 고전 목록에 오르내려요. 힐다는 1989년, 101번째 생일을 두 주 앞두고 세상을 떠났어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"maine.gov\",\"sourceUrl\":\"https://www.maine.gov/sos/maineatlas/explore-the-atlas/hilda-edwards-hamlin-lupine-lady\"},{\"id\":\"bstory-lupine-tarwi-andes\",\"title\":\"안데스의 쓴 콩 타르위\",\"hook\":\"안데스 사람들은 루피너스 씨앗을 물에 며칠씩 담가 쓴맛을 빼고 먹어 왔어요.\",\"body\":\"안데스에는 루피너스 무타빌리스, 케추아어로 타르위, 아이마라어로 타우리라 부르는 루피너스가 있어요. 씨앗의 단백질 함량이 46에서 48퍼센트, 기름이 16에서 23퍼센트나 되지만 그대로는 쓴맛이 강해 먹을 수 없어요. 그래서 물에 이삼일 담가 물에 녹는 알칼로이드를 빼내는 과정을 반드시 거쳐요. 페루 중부 만타로 계곡에서 약 1800년 전으로 연대가 매겨진 흔적이 나왔고, 나스카 무덤과 티와나쿠 도기에서도 확인돼요. 잉카 이전 시기의 의례용 그릇에는 타르위 그림이 그려져 있고요. 콩과답게 뿌리혹으로 질소를 고정해 척박한 땅에서도 자라고 해발 800미터에서 3000미터까지 견뎌요.\",\"notes\":[{\"key\":\"region\",\"text\":\"안데스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"scalar.usc.edu\",\"sourceUrl\":\"https://scalar.usc.edu/works/plants-and-people/tarwi-a-forgotten-gift-from-the-andes\"}]},\"11-3\":{\"photo\":{\"src\":\"/birth/beurionia.jpg\",\"thumbSrc\":\"/birth/thumbs/beurionia.jpg\",\"author\":\"Magnus Manske\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:P1000629_Bryonia_dioica_(Cucurbitaceae)_Flower_(detail).JPG\",\"familyLine\":\"덩굴손이 용수철처럼 감기며 몸을 끌어올려요. 뿌리는 사람 키만큼 굵어지기도 하지만 독이 있어 먹지 않아요.\"},\"stories\":[{\"id\":\"bstory-bryony-mandrake-mould-fraud\",\"title\":\"흙 속에 거푸집을 묻는 사기\",\"hook\":\"어린 브리오니아 뿌리에 틀을 씌우면 한 철 만에 사람 모양이 나왔어요.\",\"body\":\"잉글랜드에는 진짜 맨드레이크가 야생으로 자라지 않았지만, 사람 모양 뿌리를 원하는 손님은 늘 있었어요. 그래서 사기꾼들은 흰브리오니아의 굵은 덩이뿌리를 맨드레이크라 속여 팔았어요. 1832년에 나온 그린의 유니버설 허벌이 그 수법을 적어 뒀는데, 한창 자라는 어린 브리오니아 둘레의 흙을 파헤치고 원하는 모양의 거푸집을 뿌리에 씌워 두면 한 철 만에 그 틀대로 뿌리가 차오른다는 거예요. 뿌리 자체가 워낙 크게 자라는 식물이라 가능한 일이었어요. 존 제라드는 반 헌드레드웨이트, 그러니까 25킬로그램이 넘고 한 살배기 아이만 한 뿌리를 봤다고 적었고요. 참고로 이 뿌리는 피부에 닿기만 해도 붉어지고 물집이 잡힐 만큼 독해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://botanical.com/botanical/mgmh/b/brywhi77.html\"},{\"id\":\"bstory-bryony-fenland-mandrake-contest\",\"title\":\"선술집 벽난로 위의 뿌리 대회\",\"hook\":\"케임브리지셔 습지 사람들은 사람 닮은 뿌리를 캐 와 술집에서 겨뤘어요.\",\"body\":\"케임브리지셔 펜 지방에는 흰브리오니아 뿌리를 잉글랜드 맨드레이크로 삼는 관습이 있었어요. 갈래진 굵은 뿌리를 캐서 사람 모양으로 다듬고, 밀알을 박아 싹을 틔워 머리카락처럼 만들기도 했죠. 펜 사람들은 그중 가장 사람을 닮은 뿌리를 골라 씻고 자기 표시를 새긴 뒤 마을 선술집으로 가져갔어요. 뿌리들은 술집 벽난로 선반 위에 나란히 놓였고, 누구 것이 사람 형상에 가장 가까운지 주인 아주머니가 심사해 상을 줬대요. 캐낸 뿌리는 으깨어 쥐구멍에 넣어 쥐를 쫓거나, 구슬로 깎아 아이 이앓이 목걸이를 만들거나, 부적처럼 간직하는 데 썼고요. 뿌리 깎기 자체는 1597년 존 제라드의 허벌에 이미 적혀 있고, 펜의 술집 대회는 1969년 에니드 포터가 기록으로 남겼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"folklorefinder.uk\",\"sourceUrl\":\"https://folklorefinder.uk/legends/the-fenland-mandrake\"}]},\"11-4\":{\"photo\":{\"src\":\"/birth/golgosari.jpg\",\"thumbSrc\":\"/birth/thumbs/golgosari.jpg\",\"author\":\"Nicolas Weghaupt\",\"license\":\"CC0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Asplenium_scolopendrium_leaves.jpg\",\"familyLine\":\"고사리인데 잎이 갈라지지 않고 혓바닥처럼 통째로 길어요. 뒷면에 줄무늬처럼 늘어선 것이 홀씨주머니예요.\"},\"stories\":[{\"id\":\"bstory-harts-tongue-deer-centipede\",\"title\":\"사슴 혀와 지네 다리\",\"hook\":\"잎은 수사슴의 혀를, 잎 뒷면 홀씨주머니 줄은 지네 다리를 닮아 이름이 붙었어요.\",\"body\":\"골고사리의 영어 이름 하츠텅은 잎 모양이 다 자란 수사슴의 혀를 닮았다고 해서 붙었어요. 종소명 스콜로펜드리움은 그리스어로 지네를 뜻하는 스콜로펜드라에서 왔는데, 잎 뒷면에 줄줄이 늘어선 홀씨주머니가 꼭 지네 다리처럼 보이기 때문이에요. 속명 아스플레니움은 비장과 얽혀 있고요. 1653년 니컬러스 컬페퍼는 이 고사리가 비장과 간이 굳고 막힌 데, 그리고 간과 위의 열에 듣는다고 적었어요. 그리스 의사 디오스코리데스는 뱀에 물리거나 쏘인 데 좋다고 했고, 잎을 태워 습포로 붙이는 방식이 전해졌어요. 이 고사리가 살무사 다니는 곳에 잘 자란다는 이야기도 있었는데, 쐐기풀 옆에 소리쟁이가 나는 것처럼 해독제가 늘 곁에 있다는 식이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"northwestnatureandhistory.co.uk\",\"sourceUrl\":\"https://northwestnatureandhistory.co.uk/2023/09/26/the-harts-tongue-fern/\"},{\"id\":\"bstory-harts-tongue-syracuse-sinkholes\",\"title\":\"싱크홀 바닥에만 남은 고사리\",\"hook\":\"미국에 남은 골고사리의 90퍼센트가 뉴욕주 시러큐스 근처에 몰려 있어요.\",\"body\":\"골고사리의 북아메리카 변종은 아무 데서나 살지 못해요. 빙하가 깎아 낸 웅덩이 지형, 백운암과 석회암 같은 석회질 암반, 싱크홀과 동굴 입구, 서늘하고 축축한 너덜지대의 짙은 그늘이 조건이에요. 뉴욕주에 남은 개체군은 스무 곳이 채 안 되고 그마저 시러큐스 주변에 몰려 있는데, 미국 전체에 알려진 개체의 90퍼센트가 이 좁은 지역에 있어요. 미국 어류및야생동물국은 이 변종을 멸종위기종보호법상 위협종으로 지정했고, 1989년 연방관보에 최종 규칙이 실렸어요. 법의 보호를 받기 전에는 채석과 광산 개발로 큰 개체군이 통째로 사라지기도 했어요. 지금은 이 고사리가 자라는 곳에서 새로 광산이 열릴 가능성은 낮다고 봐요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"guides.nynhp.org\",\"sourceUrl\":\"https://guides.nynhp.org/harts-tongue-fern/\"}]},\"11-5\":{\"stories\":[{\"id\":\"bstory-danyang-aster-lost-and-found\",\"title\":\"댐에 잠겼다가 다시 발견됐어요\",\"hook\":\"자생지가 물에 잠긴 뒤 20여 년 만에 다시 나타났어요.\",\"body\":\"단양쑥부쟁이는 한국에만 자라는 특산식물이에요. 남한강 가의 자갈과 모래가 섞인 척박한 강변이 삶터였는데, 1980년대 충주댐이 들어서면서 단양과 충주 일대의 자생지가 대부분 물에 잠겼어요. 사라진 줄 알았던 이 풀은 2005년 여주 남한강 일대에서 다시 발견됐어요. 지금은 멸종위기 야생생물 2급으로 지정돼 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bravo.etoday.co.kr\",\"sourceUrl\":\"https://bravo.etoday.co.kr/view/atc_view/9957\"},{\"id\":\"bstory-danyang-aster-dredged-soil\",\"title\":\"준설토 더미에서 다시 싹텄어요\",\"hook\":\"파낸 흙더미 위에서 멸종위기 식물이 자라 있었어요.\",\"body\":\"4대강 사업으로 최대 자생지가 또 한 번 위기를 맞자 강천섬에 대체 서식지를 만들어 옮겨 심는 작업이 이어졌어요. 그런데 2017년에는 뜻밖의 일이 있었어요. 강바닥에서 퍼 올려 쌓아 둔 준설토 더미에서 단양쑥부쟁이가 무리 지어 자라고 있는 것이 확인된 거예요. 물에 잠겨 있던 씨앗이 흙과 함께 올라와 싹을 틔운 셈이에요. 강가의 자갈밭을 고르는 이 풀의 습성이 그대로 드러난 장면이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"khan.co.kr\",\"sourceUrl\":\"https://www.khan.co.kr/article/201709291416001\"},{\"id\":\"bstory-fig-marigold-1937-naming\",\"title\":\"1937년에 이름을 얻은 풀\",\"hook\":\"남한강 자갈밭에만 사는 이 한국 특산 풀은 경쟁이 두려워 척박한 땅을 골랐어요.\",\"body\":\"단양쑥부쟁이는 1937년 일본 식물학자 기타무라 시로가 한반도 특산으로 보고하면서 학명을 얻었어요. 오랫동안 아스테르 알타이쿠스의 변종으로 불렸고, 최근 연구로 아스테르 단양겐시스라는 독립 종명을 갖게 됐어요. 국화과 두해살이풀로 키는 30에서 100센티미터, 잎이 솔잎처럼 가늘어 솔잎국화라고도 불려요. 지름 4센티미터쯤 되는 자주색 두상화를 8월부터 10월에 피우고요. 이 풀이 하필 강변 모래땅과 자갈밭을 고르는 이유는 경쟁에 약하기 때문이에요. 다른 식물과 섞이면 밀리니까 아예 남들이 버티기 힘든 척박한 땅으로 들어간 셈이죠. 지금은 환경부 지정 멸종위기 야생생물 2급이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"newspenguin.com\",\"sourceUrl\":\"https://www.newspenguin.com/news/articleView.html?idxno=18134\"},{\"id\":\"bstory-fig-marigold-gangcheon-island\",\"title\":\"강천섬의 150만 포기\",\"hook\":\"2005년 여주 남한강변에서 최대 군락이 발견됐고 4대강 사업 때 3만 8천 포기가 옮겨졌어요.\",\"body\":\"2005년 경기 여주 남한강변에서 단양쑥부쟁이 최대 군락지가 발견됐어요. 여주 강천면 굴암리의 강천섬을 비롯한 남한강 일대에는 150만여 개체가 사는 것으로 파악됐고요. 이 풀은 두해살이라 두 해째에 어른 허리 높이까지 자라 가을에 꽃을 피우고 죽어요. 척박한 땅을 좋아해서 몇 년에 한 번씩 홍수가 강천섬을 덮쳐 쌓인 모래를 쓸어내고 자갈밭을 다시 만들어 줘야 살아갈 수 있어요. 4대강 사업이 이 서식지를 없앨 거라는 우려가 커지자 정부는 3만 8천여 개체를 대체서식지로 옮겨 심었어요. 그해 4월 9일부터 11일까지 삼합지구에서만 2만 2천 개체가 이식됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"korea.kr\",\"sourceUrl\":\"https://www.korea.kr/news/policyNewsView.do?newsId=148695287\"}]},\"11-6\":{\"photo\":{\"src\":\"/birth/deunggolnamul.jpg\",\"thumbSrc\":\"/birth/thumbs/deunggolnamul.jpg\",\"author\":\"小石川人晃\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Eupatorium_japonicum_(at_Tsukuba_Botanical_Garden,_Ibaraki,_Japan)_01.jpg\",\"familyLine\":\"꽃이 지고 마르면서 향이 진해져요. 그 향 때문에 예부터 말려서 몸에 지니고 다녔어요.\"},\"stories\":[{\"id\":\"bstory-eupatorium-milk-sickness-bixby\",\"title\":\"송아지로 증명한 우유병의 정체\",\"hook\":\"1834년 일리노이 숲에서 쇼니족 노파가 한 여의사에게 풀 한 포기를 가리켰어요.\",\"body\":\"애나 피어스는 1800년대 초 필라델피아에서 태어나 어릴 때 일리노이 남부로 옮겨 왔어요. 필라델피아에서 간호와 조산, 치과를 배우고 돌아와 카운티에서 유일한 의료인이 됐죠. 그 사이 우유병이 그의 어머니와 올케를 데려갔어요. 1834년, 소를 찾아 숲을 헤매던 그는 강제 이주를 피해 숨어 지내던 쇼니족 노파를 만났어요. 노파는 능선에 자란 흰등골나물을 가리켰고, 애나는 송아지에게 이 풀을 먹여 우유병 특유의 떨림 증상이 나타나는 걸 확인했어요. 3년에 걸친 계몽과 제거 운동으로 일리노이 남동부에서 이 풀은 거의 사라졌어요. 미 농무부가 독성 성분 분석을 발표한 건 1927년, 그가 죽고 오십 년 가까이 지난 뒤였고 그의 이름은 실리지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/innovation/how-1800s-midwife-solved-poisionous-mystery-180982343/\"},{\"id\":\"bstory-eupatorium-mithridates\",\"title\":\"독을 마시던 왕의 이름\",\"hook\":\"등골나물속의 학명은 스물다섯 나라 말을 했다는 폰토스 왕에게서 왔어요.\",\"body\":\"등골나물속의 학명 에우파토리움은 폰토스의 왕 미트리다테스 6세의 별칭 에우파토르에서 왔다고 해요. 기원전 132년부터 63년까지 산 인물인데, 기억력이 대단해 스물다섯 가지 언어를 구사했다고 전해지고 암살을 두려워한 나머지 치사량에 못 미치는 독을 조금씩 계속 먹어 몸을 길들였어요. 이 방법에는 그의 이름을 딴 미트리다티즘이라는 말이 붙었고, 만능 해독제를 뜻하는 미트리다트라는 단어도 남았고요. 그가 약으로 썼다고 전해지는 식물이 이 무리예요. 다만 이름의 유래를 왕이 아니라, 그가 두 강이 만나는 자리에 세운 도시 에우파토리아에서 찾는 설명도 있어요. 그 강가에 이 풀이 무성하게 자랐다는 거죠.\",\"notes\":[{\"key\":\"region\",\"text\":\"아나톨리아\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"pontosworld.com\",\"sourceUrl\":\"https://pontosworld.com/index.php/pontus/i-m-feeling-lucky/275-eupatorium\"}]},\"11-7\":{\"stories\":[]},\"11-8\":{\"photo\":{\"src\":\"/birth/ganeundongjakkot.jpg\",\"thumbSrc\":\"/birth/thumbs/ganeundongjakkot.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Silene_flos-cuculi_flower_-_Niitv%C3%A4lja.jpg\",\"familyLine\":\"꽃잎이 넷으로 깊게 찢어져 헝클어진 것처럼 보여요. 일부러 그렇게 갈라 두어 멀리서도 눈에 띄어요.\"},\"stories\":[{\"id\":\"bstory-ragged-robin-flos-cuculi\",\"title\":\"뻐꾸기가 울면 피는 꽃\",\"hook\":\"학명 flos-cuculi는 '뻐꾸기의 꽃', 셰익스피어 시대에는 '까마귀꽃'이라 불렸어요.\",\"body\":\"가는동자꽃의 학명에서 플로스쿠쿨리는 뻐꾸기의 꽃이라는 뜻이에요. 5월에서 6월, 뻐꾸기가 돌아와 울기 시작할 무렵에 꽃이 피기 때문이에요. 꽃잎 하나가 좁은 네 갈래로 깊게 갈라져 헝클어진 것처럼 보이는데, 영어 이름 래기드 로빈이 여기서 왔어요. 셰익스피어 시대에는 크로플라워, 곧 까마귀꽃이라 불렸고 햄릿에서 오필리아가 엮은 화환의 꽃 가운데 하나로 등장해요. 잉글랜드에서는 6월 11일 성 바나바 축일에 바쳐진 꽃인데, 그 무렵이 건초를 만드는 철이었기 때문이에요. 축축한 초지와 습한 숲에 살고 혀가 긴 벌이 특히 좋아해요. 빅토리아 시대 꽃말로는 열정, 혐오, 재치가 함께 붙어 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plantlife.org.uk\",\"sourceUrl\":\"https://www.plantlife.org.uk/plants-and-fungi/ragged-robin/\"},{\"id\":\"bstory-ragged-robin-cuckoo-spit\",\"title\":\"뻐꾸기 침이라 불린 거품\",\"hook\":\"초지에 맺힌 하얀 거품은 뻐꾸기가 뱉은 게 아니라 거품벌레 애벌레의 은신처예요.\",\"body\":\"봄이면 초지 식물의 잎겨드랑이에 하얀 거품 덩어리가 생겨요. 영국에서는 이걸 뻐꾸기 침이라 불렀는데, 뻐꾸기 울음이 들리기 시작하는 계절에 나타나기 때문이지 새와는 아무 상관이 없어요. 실제로 이 거품을 만드는 건 거품벌레 애벌레예요. 영국에는 거품벌레가 열 종 있고 그중 초원거품벌레가 가장 흔해요. 거품은 대개 5월에서 7월 사이에 보이고 식물이 자라는 데는 대체로 지장이 없어요. 다만 애벌레가 새순 끝을 빨면 자란 모양이 뒤틀릴 수 있어요. 거품벌레는 물관 즙을 빨아 먹기 때문에 세균병을 옮길 수 있는데, 영국에서는 아직 그 병이 확인되지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"rhs.org.uk\",\"sourceUrl\":\"https://www.rhs.org.uk/biodiversity/cuckoo-spit-spittlebugs\"}]},\"11-9\":{\"stories\":[{\"id\":\"bstory-myrrh-ovid-myrrha-tree\",\"title\":\"나무가 되어 흘린 눈물\",\"hook\":\"오비디우스의 미르라는 초승달이 아홉 번 뜰 동안 도망친 끝에 나무가 됐어요.\",\"body\":\"오비디우스의 변신 이야기 10권에는 키프로스 왕 키니라스의 딸 미르라가 나와요. 아버지를 향한 금지된 사랑에 시달리다 목숨을 끊으려 한 그를 유모가 발견하고, 첫 수확을 바치는 케레스 축제 아흐레 동안 아버지의 침실로 들여보내요. 술에 취한 키니라스는 상대가 딸인 줄 몰랐고, 마침내 등불을 들어 얼굴을 확인한 순간 칼을 뽑아요. 어둠 속으로 달아난 미르라는 초승달이 아홉 번 돌아올 때까지 헤매다 사바 사람들의 땅에 이르러, 산 자의 세계에서도 죽은 자의 세계에서도 자신을 쫓아내 달라고 빌어요. 신들이 응답해 발끝에서 뿌리가 뻗어 나오고 그는 몰약나무가 돼요. 그 눈물이 굳은 것이 몰약이고, 나무껍질을 가르고 태어난 아이가 아도니스예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ovid.lib.virginia.edu\",\"sourceUrl\":\"https://ovid.lib.virginia.edu/trans/Metamorph10.htm\"},{\"id\":\"bstory-myrrh-pliny-nero-poppaea\",\"title\":\"아라비아 한 해 생산량을 하루에\",\"hook\":\"네로는 아내 포파이아의 장례에서 아라비아의 1년치 향료를 태웠다고 해요.\",\"body\":\"대 플리니우스는 박물지 12권에서 몰약을 꽤 자세히 다뤄요. 아라비아 곳곳에서 나고, 사바이 사람들이 트로글로디테스의 땅까지 가서 구해 온다고 적었죠. 나무는 다섯 큐빗쯤 자라고 가시가 있으며 줄기는 유향나무보다 굵고 단단하게 뒤틀려 있대요. 해마다 두 번 껍질을 째서 수액을 받는데, 째기 전에 저절로 흘러나오는 스탁테가 가장 값나갔어요. 가격은 등급마다 갈렸어요. 스탁테가 파운드당 3데나리우스에서 50데나리우스까지, 재배한 몰약은 최고 11데나리우스였고요. 플리니우스는 감정가들의 말이라며, 네로 황제가 아내 포파이아의 장례에서 하루에 태운 향료가 아라비아의 한 해 생산량보다 많았다는 기록을 인용해 뒀어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"attalus.org\",\"sourceUrl\":\"https://www.attalus.org/pliny/hn12b.html\"}]},\"11-10\":{\"photo\":{\"src\":\"/birth/buyong.jpg\",\"thumbSrc\":\"/birth/thumbs/buyong.jpg\",\"author\":\"Wee Hong\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hibiscus_mutabilis_(190111-1618).jpg\",\"familyLine\":\"아침에 흰 꽃으로 열렸다가 저녁이면 붉게 물들어요. 하루 사이에 색이 변한다고 해서 취부용이라고도 불러요.\"},\"stories\":[{\"id\":\"bstory-confederate-rose-chengdu-furong\",\"title\":\"성벽을 덮은 부용꽃\",\"hook\":\"오대 시기 후촉의 황제가 청두 성벽에 부용을 심게 하면서 도시 별칭이 생겼어요.\",\"body\":\"중국 쓰촨성 청두에는 부용성이라는 별칭이 있어요. 오대 시기 이 땅을 다스리던 후촉의 황제가 성벽을 빙 둘러 부용을 심게 한 데서 나온 이름이에요. 이후 청두는 부용성으로 불렸고, 줄여 용성이라 하는 약칭이 지금까지 도시의 별명으로 남아 있어요. 청두는 기록으로만 2,300년이 넘는 역사를 지녔고, 처음 이름을 얻은 뒤로 한 번도 이름이 바뀌지 않은 드문 도시예요. 3,700년에서 4,500년 전 사람이 살던 흔적이 있고, 4,000여 년 전 고촉 사람들이 이곳에 나라를 세웠으며, 2,300년쯤 전 지금의 청두 자리로 수도를 옮겼어요. 북송 대에 이르러서는 세계에서 가장 이른 지폐 교자가 태어난 도시가 됐고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"en.chinaculture.org\",\"sourceUrl\":\"https://en.chinaculture.org/focus/focus/cities/2010-07/06/content_384687.htm\"},{\"id\":\"bstory-confederate-rose-zui-furong\",\"title\":\"하루에 세 번 옷을 갈아입는 꽃\",\"hook\":\"오전 열 시와 오후 다섯 시의 같은 꽃이 완전히 다른 색이에요.\",\"body\":\"부용의 종소명 무타빌리스는 변한다는 뜻이에요. 그중에서도 취부용, 곧 취한 미인이라 불리는 품종은 하루 사이에 색이 세 번 바뀌어요. 2023년에 나온 연구는 같은 그루에서 오전 8시에 흰 꽃, 오후 1시에 분홍 꽃, 오후 5시에 붉은 꽃을 각각 따서 유전자 발현과 대사물질을 함께 분석했어요. 그런데 색이 짙어지는 동안 플라보노이드나 안토시아닌 같은 흔한 색소 경로가 두드러지게 활성화되지는 않았고, 대신 L-이소류신과 팔미트산, L-메티오닌을 비롯한 열아홉 가지 대사물질이 꾸준히 늘어났어요. 부용은 청두를 상징하는 시화이기도 하다고 이 논문도 적어 두었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC10452391/\"}]},\"11-11\":{\"stories\":[]},\"11-12\":{\"photo\":{\"src\":\"/birth/remon.jpg\",\"thumbSrc\":\"/birth/thumbs/remon.jpg\",\"author\":\"Filo gèn'\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Citrus_limon_(flower).jpg\",\"familyLine\":\"꽃봉오리 바깥은 연보라인데 열리면 안쪽이 하얘요. 열매의 신맛과 달리 꽃향은 달아요.\"},\"stories\":[{\"id\":\"bstory-lemon-lind-scurvy-trial\",\"title\":\"배 위에서 벌인 열두 명의 실험\",\"hook\":\"1747년 군함에서 괴혈병 환자 열두 명이 여섯 조로 나뉘었어요.\",\"body\":\"1747년 5월, 영국 군함 솔즈베리호의 군의관 제임스 린드는 괴혈병에 걸린 선원 열두 명을 두 명씩 여섯 조로 나눴어요. 한 조에는 사과주, 다른 조에는 황산 엘릭서, 또 다른 조에는 식초와 바닷물, 마늘과 겨자 반죽을 주고, 마지막 한 조에만 오렌지와 레몬을 먹였어요. 결과는 갈렸어요. 감귤을 먹은 두 사람만 눈에 띄게 회복했고, 그중 한 명은 엿새 만에 근무에 복귀했으며 다른 한 명은 나머지 환자들을 간호할 만큼 기력을 되찾았어요. 린드는 1753년 괴혈병에 관한 논고로 이 기록을 남겼지만 해군성은 40년 넘게 움직이지 않았어요. 1781년 길버트 블레인이 레몬주스 배급을 건의했을 때도 비용을 이유로 거절당했고, 실험에서 48년이 지난 1795년에야 하루 4분의 3온스 배급이 명령됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"hekint.org\",\"sourceUrl\":\"https://hekint.org/2017/01/29/the-mysteries-of-james-lind-and-scurvy/\"},{\"id\":\"bstory-lemon-sicily-mafia\",\"title\":\"레몬밭에서 자란 마피아\",\"hook\":\"괴혈병을 막는 과일이 되자, 시칠리아 레몬밭에 보호비를 걷는 조직이 붙어요.\",\"body\":\"레몬이 괴혈병을 막는다는 사실이 알려진 1800년 무렵부터 유럽과 미국의 레몬 수요가 치솟아요. 지중해 기후 덕에 시칠리아가 그 수요를 떠안았고, 물을 대고 담을 두른 감귤 과수원은 좁은 땅에서 큰돈을 만드는 밭이 됐어요. 문제는 그 돈을 지켜 줄 공권력이 약했다는 점이에요. 맨체스터대의 알레시아 이소피, 퀸스대 벨파스트의 아르칸젤로 디미코, 예테보리대의 올라 올손은 1881년부터 1886년까지 진행된 다미아니 조사를 파고들었어요. 하급심 판사 179명에게 어떤 범죄가 흔하고 왜 생기는지 물은 대규모 설문이었죠. 분석 결과 1880년대 마피아의 분포는 감귤 재배와 유독 강하게 겹쳤고, 다른 어떤 작물이나 산업도 같은 관계를 보이지 않았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이탈리아\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"manchester.ac.uk\",\"sourceUrl\":\"https://www.manchester.ac.uk/about/news/citrus-fruits-mafia/\"}]},\"11-13\":{\"photo\":{\"src\":\"/birth/remon-beobena.jpg\",\"thumbSrc\":\"/birth/thumbs/remon-beobena.jpg\",\"author\":\"Metrónomo\",\"license\":\"CC BY-SA 2.5 ar\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Aloysia_citrodora_-_flowers.jpg\",\"familyLine\":\"잎을 문지르면 레몬보다 더 레몬 같은 향이 나요. 정작 레몬과는 아무 사이도 아니에요.\"},\"stories\":[{\"id\":\"bstory-lemon-verbena-maria-luisa\",\"title\":\"여왕의 이름을 얻은 향기\",\"hook\":\"속명 알로이시아는 스페인 국왕 카를로스 4세의 왕비 마리아 루이사에게서 왔어요.\",\"body\":\"레몬 버베나의 속명 알로이시아는 사람 이름에서 왔어요. 스페인 국왕 카를로스 4세의 왕비였던 파르마의 마리아 루이사를 기린 이름이죠. 그래서 스페인어권에서는 지금도 이 풀을 이에르바 루이사, 곧 루이사의 풀이라고 불러요. 종소명 시트리오도라는 그대로 레몬 향이 나는이라는 뜻이라, 학명을 소리 내어 읽으면 왕비의 이름과 레몬 향이 나란히 붙어 있는 셈이에요. 원산지는 유럽이 아니라 아르헨티나와 칠레예요. 유럽으로 건너온 뒤로는 보고 즐기려고가 아니라 기름을 얻으려고 길렀고, 그렇게 향료 재료로 자리를 잡았어요. 지금은 잎을 말려 차로 우리거나 요리에 넣고, 포푸리에 향을 보태는 데도 써요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스페인\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/aloysia-citriodora/\"},{\"id\":\"bstory-lemon-verbena-verveine-velay\",\"title\":\"1859년 르퓌의 초록 술\",\"hook\":\"프랑스 오베르뉴의 화산 도시에서 버베나를 간판에 내건 리큐어가 태어나요.\",\"body\":\"프랑스 오베르뉴 지방의 르퓌앙블레는 화산 바위 위에 세워진 순례 도시예요. 이곳에서 1859년, 파제스라는 이름으로 식물 리큐어가 만들어져요. 술 이름은 베르벤 뒤 블레, 그러니까 블레 지방의 베르벤이라는 뜻이에요. 이름 그대로 베르벤을 앞세운 술이고, 지금도 이 지역을 대표하는 특산품으로 남아 있어요. 증류소는 인근 생제르맹라프라드에 있고, 방문객이 이 술의 문화와 역사를 따라가 볼 수 있는 견학 코스를 운영해요. 향으로만 기억되던 잎이 한 도시의 이름과 묶여 160년 넘게 이어져 온 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"프랑스\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"vedrenne.fr\",\"sourceUrl\":\"https://vedrenne.fr/en/\"}]},\"11-14\":{\"photo\":{\"src\":\"/birth/sonamu-1114.jpg\",\"thumbSrc\":\"/birth/thumbs/sonamu-1114.jpg\",\"author\":\"Shuvaev\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Pinus_densiflora,_Morris_Arboretum_04.jpg\",\"familyLine\":\"잎이 두 개씩 짝을 지어 나요. 그 한 쌍이 붙어 있는 모양 때문에 예부터 부부에 빗대어 이야기됐어요.\"},\"stories\":[{\"id\":\"bstory-pine-jeongipumsong\",\"title\":\"벼슬 받은 소나무 한 그루\",\"hook\":\"임금의 가마가 걸리자 스스로 가지를 들어 올렸다는 나무가 있어요.\",\"body\":\"충청북도 보은군 속리산 어귀에는 정이품송이라 불리는 소나무가 서 있어요. 1464년, 세조 10년에 임금이 법주사로 행차하다 이 나무 아래를 지나게 되는데, 처진 가지에 가마가 걸릴 참이었대요. 연이 걸린다는 말이 떨어지자 나무가 스스로 가지를 위로 들어 올려 임금을 지나가게 했다는 이야기가 전해져요. 세조는 그 공을 기려 정이품 벼슬을 내렸고, 그래서 이름이 정이품송이 됐어요. 실제 나무는 높이 약 15미터, 가슴높이 줄기둘레 약 4.7미터에 가지가 동서로 19.9미터, 남북으로 19미터 뻗어 있고, 수령은 500년에서 600년으로 추정돼요. 1962년 12월 7일 천연기념물로 지정됐지만 1970년대 이후 솔잎혹파리 피해를 입어 1982년에는 보호구역과 철책이 설치됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0030407\"},{\"id\":\"bstory-pine-sehando\",\"title\":\"유배지에서 그린 송백\",\"hook\":\"벼슬을 잃은 사람 곁에 남은 제자에게, 김정희는 소나무 그림을 보내요.\",\"body\":\"1844년, 김정희는 제주도 유배지에 있었어요. 지위도 권력도 사라진 자리였죠. 그때 역관 이상적은 두 번이나 북경에서 귀한 책을 구해 스승에게 보냈어요. 김정희는 그 마음에 답해 종이에 먹만으로 그림 한 장을 그려 건넵니다. 세로 23센티미터, 가로 69.2센티미터의 작은 화면에 허름한 집 한 채가 놓이고, 그 좌우로 소나무와 잣나무가 두 그루씩 마주 서 있어요. 겨울에도 잎을 떨구지 않는 나무를 지조의 상징으로 세운 구도예요. 이 그림이 세한도예요. 1974년 국보로 지정됐고 지금은 서울 국립중앙박물관에 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0038956\"},{\"id\":\"bstory-pine-prometheus\",\"title\":\"4862개의 나이테\",\"hook\":\"1964년, 세상에서 가장 오래 산 나무가 나이를 재려던 사람의 손에 잘려 나갔어요.\",\"body\":\"1964년 여름, 지리학자 도널드 커리는 네바다주 휠러피크에서 브리슬콘 소나무를 조사하고 있었어요. WPN-114라는 번호를 붙인 나무에서 온전한 시료를 얻지 못하자 그는 산림청 허가를 받아 나무를 베고 단면을 통째로 살폈죠. 세어 보니 나이테가 4,862개였어요. 혹독한 해에는 테가 아예 생기지 않는 점을 감안하면 실제 나이는 약 4,900살로 추정됐고요. 당시까지 확인된 가장 오래된 나무였고, 2위였던 캘리포니아의 브리슬콘 소나무는 4,847살이었어요. 2012년에는 같은 지역에서 5,065살 된 나무가 발견됐죠. 프로메테우스라 불린 그 나무의 단면 조각은 지금 그레이트베이슨 방문자센터에 전시돼 있고, 브리슬콘 소나무는 연방 토지에서 보호받고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nps.gov\",\"sourceUrl\":\"https://www.nps.gov/grba/learn/historyculture/the-prometheus-story.htm\"}]},\"11-15\":{\"photo\":{\"src\":\"/birth/hwanggeumssari.jpg\",\"thumbSrc\":\"/birth/thumbs/hwanggeumssari.jpg\",\"author\":\"Ermell\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Bunten_Kronwicke_(Securigera_varia)_Bl%C3%BCte-20200626-RM-173640.jpg\",\"familyLine\":\"분홍 꽃이 둥글게 모여 왕관처럼 보여요. 비탈이 무너지지 않게 붙잡아 두려고 일부러 심기도 해요.\"},\"stories\":[{\"id\":\"bstory-crown-vetch-penngift\",\"title\":\"고속도로가 심은 콩과 풀\",\"hook\":\"1953년 펜실베이니아에서 나온 품종 '펜기프트'가 미국 고속도로 사면을 뒤덮었어요.\",\"body\":\"황금싸리는 지중해 연안이 고향인 콩과 식물인데, 미국에서는 흙이 무너지지 않게 붙잡는 용도로 팔려 나갔어요. 펜실베이니아 주립대의 버턴 머서와 프레드 그라우가 사료용과 침식 방지용으로 개량한 품종 펜기프트가 1953년에 나왔고, 먼저 펜실베이니아 턴파이크 비탈에 심겼죠. 1960년대와 70년대에 주간고속도로망이 전국으로 뻗어 나가는 동안 이 풀도 쉬지 않고 함께 뿌려졌어요. 1981년에는 펜실베이니아 주의회가 펜기프트를 주의 공식 미화·보전 식물로 선포하기까지 했고요. 그렇게 국가 기간시설과 함께 퍼진 이 풀은, 지금은 많은 사람에게 침입성 잡초로 불려요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"uaex.uada.edu\",\"sourceUrl\":\"https://www.uaex.uada.edu/yard-garden/resource-library/plant-week/crownvetch-7-13-07.aspx\"},{\"id\":\"bstory-crown-vetch-spread\",\"title\":\"네 해 만에 9제곱미터\",\"hook\":\"비탈을 붙잡으라고 심은 풀이 한 포기로 네 해 만에 9제곱미터를 덮어 버려요.\",\"body\":\"황금싸리는 유럽과 서남아시아, 북아프리카가 원산이에요. 미국에서는 임시 지피식물, 흙 유실 방지, 그리고 알팔파처럼 질소를 붙잡는 역할까지 노리고 북부 3분의 2 지역의 주간고속도로 갓길과 물길 둑에 대대적으로 심었어요. 문제는 속도였죠. 한 포기가 네 해 만에 70에서 100제곱피트, 그러니까 6에서 9제곱미터를 통째로 덮어요. 땅속에서 갈라지며 기는줄기는 길이가 3미터에 이르기도 하고요. 씨앗과 줄기 양쪽으로 번지면서 자생 식물 위를 덮어 그늘을 만들어 버리고, 씨앗에는 독성이 있다고 보고돼 있어요. 도로변을 지키라고 보낸 식물이 결국 도로변 바깥까지 차지한 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mdc.mo.gov\",\"sourceUrl\":\"https://mdc.mo.gov/discover-nature/field-guide/crown-vetch\"}]},\"11-16\":{\"stories\":[]},\"11-17\":{\"photo\":{\"src\":\"/birth/meowi.jpg\",\"thumbSrc\":\"/birth/thumbs/meowi.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Japans_hoefblad_(Petasites_japonicus)_02.JPG\",\"familyLine\":\"잎이 나기 전에 꽃부터 땅을 뚫고 올라와요. 그 꽃봉오리를 이른 봄 나물로 먹어요.\"},\"stories\":[{\"id\":\"bstory-butterbur-plague-petasos\",\"title\":\"페스트를 막는다던 큰 잎\",\"hook\":\"그리스식 챙 넓은 모자에서 속명을 얻고, 역병 약초로 불리던 잎이에요.\",\"body\":\"머위가 속한 페타시테스라는 속명은 목동들이 쓰던 챙 넓은 펠트 모자, 페타소스에서 왔어요. 잎이 그대로 모자로 삼을 만큼 컸기 때문이에요. 실제로 영국에서는 이 무리의 잎을 자생 식물 가운데 가장 크다고 보고, 지름이 90센티미터에 이르기도 한다고 적어요. 영어 이름 버터버는 더운 날 이 잎으로 버터를 싸 두던 관습에서 나왔다고 전해져요. 독일어로는 역병 뿌리라 불렸는데 병을 옮긴다는 뜻이 아니라 역병에 쓸 수 있던 몇 안 되는 약초였다는 뜻이에요. 1578년 라이트의 본초서는 이 식물을 역병에 듣는 으뜸 약이라 적었고, 제라드는 말린 뿌리 가루를 포도주에 타면 땀을 내고 심장에서 독기를 몰아낸다고 썼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://botanical.com/botanical/mgmh/b/butbur96.html\"},{\"id\":\"bstory-butterbur-koropokkuru\",\"title\":\"머위 잎 아래 작은 사람\",\"hook\":\"아이누말 코로폭쿠루는 그대로 옮기면 '머위 잎 밑에 사는 사람'이라는 뜻이에요.\",\"body\":\"홋카이도 아이누 사람들 사이에 전해지는 코로폭쿠루는 이름 자체가 설명이에요. 코로는 머위, 폭은 아래, 쿠루는 사람이니 합치면 머위 잎 밑에 사는 이들이 되죠. 키가 아주 작고 몸놀림이 재빠르며 피부가 불그스름했다고 하고, 아이누가 이 땅에 들어오기 전부터 살던 종족으로 이야기돼요. 이들은 얼굴을 보이지 않는 거래를 했어요. 밤이 되면 아이누 집 창가에 사슴이나 물고기, 사냥한 짐승을 놓아 두고 답례만 받아 갔죠. 그러다 한 아이누 젊은이가 창가로 나온 코로폭쿠루 여인의 손을 덥석 붙잡는 일이 벌어졌어요. 그 무례에 상한 이들은 숲과 북쪽 땅으로 사라졌고, 이후로는 흔적만 남기고 다시 나타나지 않았다고 해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아이누\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"yokaidb.com\",\"sourceUrl\":\"https://yokaidb.com/yokai-03431/\"}]},\"11-18\":{\"stories\":[]},\"11-19\":{\"photo\":{\"src\":\"/birth/beomuigwi-1119.jpg\",\"thumbSrc\":\"/birth/thumbs/beomuigwi-1119.jpg\",\"author\":\"JackyM59\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Millepertuis_%C3%A0_calice_persistant_(hypericum_calycinum).jpg\",\"familyLine\":\"노란 꽃잎 위로 수술이 수염처럼 한가득 뻗어요. 이름의 수염은 그 수술을 두고 한 말이에요.\"},\"stories\":[{\"id\":\"bstory-saxifraga-rock-breaker\",\"title\":\"바위를 깨는 풀이라는 이름\",\"hook\":\"속명 자체가 바위를 깬다는 뜻입니다. 실제로 이 풀은 바위 틈에 뿌리를 박고 시간을 들여 돌을 벌립니다.\",\"body\":\"범의귀속의 속명 삭시프라가는 라틴어 두 낱말을 붙인 이름이에요. 삭숨은 바위, 프란게레는 깨뜨린다는 뜻이에요. 합치면 바위를 깨는 풀이 돼요. 허풍이 아니에요. 이 무리는 그늘진 벼랑이나 이끼 낀 바위 틈에 자리를 잡고, 그 틈에 뿌리를 밀어 넣어 시간을 들여 돌을 조금씩 벌려 놓거든요. 사람 눈에는 그저 작고 여린 풀인데, 하는 일은 바위 쪼개기예요. 무거운 점토질 흙도 견뎌서 지피식물로 곧잘 쓰이고요. 도감에서는 무릎 높이도 안 되는 풀 옆에 이 사나운 이름이 나란히 붙어 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/saxifraga-stolonifera/\"},{\"id\":\"bstory-aarons-beard-wheler1676\",\"title\":\"1676년 한 그루에서\",\"hook\":\"영국과 아일랜드 야생 개체가 전부 1676년 들여온 정원 계통 하나에서 갈라졌대요.\",\"body\":\"아론의 수염이라 불리는 히페리쿰 칼리키눔은 불가리아와 튀르키예 북서부가 고향이에요. 영국 제도에는 1676년에 조지 휠러 경이 이스탄불 근처에서 가져와 심었죠. 놀라운 건 그다음이에요. 영국과 아일랜드에서 야생으로 자라는 개체가 전부 그때 들어온 정원 계통 하나에서 갈라져 나온 것으로 보인다는 거예요. 비결은 번식 방식에 있어요. 이 아관목은 영국과 아일랜드에서 꽃이 대체로 자가불화합성이라 씨를 잘 맺지 못하는데, 대신 땅속줄기가 흙 속을 빠르게 달리며 한자리에 오래 남는 복제 군락을 만들거든요. 350년 가까이 같은 개체가 몸을 늘려 온 셈이죠. 다만 새 원예 품종이 들어오면 그 벽이 깨져 침입성이 커질 수 있다는 경고도 함께 붙어 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"bsbi.org\",\"sourceUrl\":\"https://bsbi.org/in-your-area/local-botany/co-fermanagh/fermanagh-species-accounts/hypericum-calycinum-l\"},{\"id\":\"bstory-aarons-beard-londonpride\",\"title\":\"폭격 자리에 핀 런던 프라이드\",\"hook\":\"대공습 폭격 터를 뒤덮은 범의귀속 풀이 1941년 봄 노래의 제목이 됐어요.\",\"body\":\"런던 프라이드는 범의귀속의 교잡종 삭시프라가 우르비움을 가리키는 이름이에요. 스페인 피레네산맥의 종과 아일랜드 서부의 종이 만나 생긴 잡종으로, 적어도 17세기부터 알려져 있었죠. 숟가락 모양 잎이 방석처럼 깔리고 초여름에 분홍빛이 도는 흰 꽃이 작게 올라와요. 2차 세계대전 공습으로 런던 곳곳이 폐허가 되자 이 작은 풀이 폭격 자리를 빠르게 덮었어요. 노엘 카워드는 1941년 봄 대공습 한복판에서 시민들의 사기를 북돋우려 같은 이름의 노래 런던 프라이드를 썼고요. 이 식물은 1993년 영국왕립원예협회의 가든 메리트상을 받았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"gardenofeaden.blogspot.com\",\"sourceUrl\":\"https://gardenofeaden.blogspot.com/2017/02/which-plant-is-london-pride.html\"}]},\"11-20\":{\"photo\":{\"src\":\"/birth/byugeulraseu.jpg\",\"thumbSrc\":\"/birth/thumbs/byugeulraseu.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Anchusa_officinalis_inflorescence_-_Kulna.jpg\",\"familyLine\":\"꽃봉오리는 붉은데 열리면 파래져요. 벌에게 어느 꽃에 아직 꿀이 남았는지 알려 주는 신호예요.\"},\"stories\":[{\"id\":\"bstory-bugloss-ox-tongue-name\",\"title\":\"소의 혀라 불린 잎\",\"hook\":\"1530년대 영어에 들어온 이 이름은 그리스어로 '소의 혀'라는 뜻이에요.\",\"body\":\"뷰글라스라는 이름은 1530년대 영어 기록에 등장해요. 프랑스어 뷔글로스를 거쳐 라틴어로, 다시 그리스어 부글로소스로 거슬러 올라가요. 부스는 소, 글로사는 혀예요. 그러니까 말 그대로 소의 혀를 가진이라는 뜻이에요. 이름을 정한 근거는 꽃이 아니라 잎이었어요. 이 무리의 잎은 길쭉한 데다 표면이 까슬까슬하게 거칠어서, 소가 핥을 때의 그 감촉을 그대로 떠올리게 했거든요. 부스의 뿌리인 인도유럽조어는 산스크리트어와 라틴어, 고대영어로도 갈라져 나갔어요. 지금 영어의 카우와 뷰글라스가 한 핏줄인 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"etymonline.com\",\"sourceUrl\":\"https://www.etymonline.com/search?q=bugloss\"},{\"id\":\"bstory-bugloss-viper-signature\",\"title\":\"뱀처럼 얼룩진 줄기\",\"hook\":\"씨앗이 뱀 머리를 닮았다는 이유로 독사에 물린 데 쓰이던 풀이에요.\",\"body\":\"뷰글라스라는 이름을 나눠 쓰는 식물 중에 바이퍼스 뷰글라스가 있어요. 속명부터 뱀이에요. 에키움은 그리스어 에키스, 곧 독사에서 왔거든요. 이유는 씨앗이었어요. 옛사람들은 이 씨앗이 뱀 머리를 쏙 닮았다고 봤고, 그러니 뱀에게 물린 상처에도 들을 거라고 믿었어요. 줄기도 한몫했어요. 영국의 윌리엄 콜스는 이 식물의 줄기가 온통 뱀이나 독사처럼 얼룩덜룩하다며, 독과 전갈에 쏘인 데 더없이 좋은 약이라고 적었어요. 생김새가 곧 쓰임을 알려 준다는 약징주의의 전형이에요. 파킨슨은 증류수나 뿌리가 가슴 두근거림과 실신, 우울에 좋다고도 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://botanical.com/botanical/mgmh/b/bugvip85.html\"}]},\"11-21\":{\"photo\":{\"src\":\"/birth/chorongkkot-1121.jpg\",\"thumbSrc\":\"/birth/thumbs/chorongkkot-1121.jpg\",\"author\":\"Rudolphous\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20210620_Hortus_botanicus_Leiden_-_Campanula_punctata_var._hondoensis_(flowers).jpg\",\"familyLine\":\"고개를 숙인 종 안쪽에 자주색 점이 흩뿌려져 있어요. 그 점을 따라가면 꿀이 있는 자리가 나와요.\"},\"stories\":[{\"id\":\"bstory-canterburybell-pilgrim-bells\",\"title\":\"순례자의 말방울\",\"hook\":\"캔터베리 벨은 순례길 말목에 달린 방울에서 온 이름이에요.\",\"body\":\"초롱꽃속의 캄파눌라 메디움에는 영어로 '캔터베리 벨'이라는 이름이 붙어 있어요. 캔터베리 대성당의 종을 닮았다는 설도 있지만, 더 자주 이야기되는 것은 순례자의 방울이에요. 토머스 베켓의 성지로 사람들을 실어 나르던 말의 목에 달린 방울이 이 꽃 모양이었다는 거예요. 종처럼 벌어진 꽃 여러 개가 줄기 하나에 달려 흔들리는 모습이 실제로 그렇게 보여요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/campanula-medium/\"},{\"id\":\"bstory-canterburybell-coventry\",\"title\":\"원래 이름은 코번트리 벨이었어요\",\"hook\":\"이 꽃은 한동안 다른 도시의 이름으로 불렸어요.\",\"body\":\"지금은 캔터베리 벨로 통하지만, 16~17세기 영국에서는 이 꽃을 '코번트리 벨'이라 불렀어요. 19세기에 이르러서야 지금의 이름으로 굳었다고 해요. 원산지는 프랑스 남동부와 이탈리아 중북부의 바위 비탈이고, 영국에는 16세기에 들어온 것으로 봐요. 꽃 이름이 도시 하나를 갈아탄 셈인데, 왜 바뀌었는지는 분명하게 남아 있지 않아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"thursd.com\",\"sourceUrl\":\"https://thursd.com/articles/canterbury-bell-flowers\"},{\"id\":\"bstory-campanula-rapunzel\",\"title\":\"라푼젤은 채소 이름이었어요\",\"hook\":\"그림 형제 동화의 라푼젤은 초롱꽃속 채소 캄파눌라 라푼쿨루스에서 온 이름이에요.\",\"body\":\"그림 형제 동화의 라푼젤은 사람 이름이기 전에 채소 이름이었어요. 임신한 아내가 이웃 마녀의 밭에서 훔쳐다 달라고 조른 그 풀, 캄파눌라 라푼쿨루스가 바로 라푼젤이거든요. 초롱꽃속에 속하는 이 식물은 서남아시아부터 중부 유럽, 북아프리카까지 분포하고, 잎은 시금치처럼 데쳐 먹고 순무 닮은 뿌리는 무처럼 썰어 먹었어요. 종소명 라푼쿨루스는 라틴어로 순무를 뜻하는 라파의 축소형이고요. 초롱꽃속에는 500종이 넘는 식물이 있는데 그 가운데 다수가 꽃과 잎과 뿌리를 모두 먹을 수 있어요. 그림 형제가 이 풀에 굳이 설명을 붙이지 않은 것을 보면, 당시 독자들에게 라푼젤은 설명이 필요 없는 흔한 밭작물이었던 거예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"독일\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanistinthekitchen.blog\",\"sourceUrl\":\"https://botanistinthekitchen.blog/2015/01/13/rapunzel/\"},{\"id\":\"bstory-campanula-throatwort-signature\",\"title\":\"종탑 속 박쥐라 불린 꽃\",\"hook\":\"종소명 트라켈리움은 그리스어로 목을 뜻하고, 실제로 목 아픈 데 썼어요.\",\"body\":\"초롱꽃속의 캄파눌라 트라켈리움은 영어로 스로트워트, 그러니까 목풀이라고 불려요. 종소명 트라켈리움은 그리스어 트라켈로스, 곧 목에서 온 말이에요. 실제로 이 식물이 인후통을 낫게 한다고 믿던 시절이 있었어요. 생김새가 그 식물의 쓰임을 알려 준다는 약징주의의 사고방식이 이름과 약효를 한 덩어리로 묶어 놓은 거예요. 같은 식물에는 종탑 속 박쥐라는 별명도 붙어 있어요. 종 모양 꽃 안에 늘어선 수술이 종루에 매달린 박쥐처럼 보였기 때문이에요. 속명 캄파눌라 자체가 라틴어 캄파나, 곧 종에서 온 이름이고요. 유럽과 중앙아시아, 지중해에서 이란까지가 원산이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/campanula-trachelium/\"}]},\"11-22\":{\"photo\":{\"src\":\"/birth/maejanamu.jpg\",\"thumbSrc\":\"/birth/thumbs/maejanamu.jpg\",\"author\":\"Salicyna\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Berberis_koreana_2016-05-17_0149.jpg\",\"familyLine\":\"가지마다 뾰족한 가시가 돋아요. 가을이면 그 가시 사이로 붉은 열매가 줄줄이 매달려요.\"},\"stories\":[{\"id\":\"bstory-berberis-eradication-1918\",\"title\":\"밀을 위해 뽑힌 나무\",\"hook\":\"1918년부터 미국은 밀 녹병을 막겠다며 매자나무를 국가 차원에서 뽑아냈어요.\",\"body\":\"매자나무는 밀 줄기녹병균의 중간숙주예요. 이 관계를 사람들은 과학이 증명하기 훨씬 전부터 눈치채고 있었죠. 1660년 프랑스 루앙에서는 매자나무 재배를 금지하는 법이 통과됐고, 북아메리카 식민지에서도 코네티컷이 1726년, 매사추세츠가 1754년, 로드아일랜드가 1766년에 잇따라 금지령을 냈어요. 1916년 줄기녹병이 크게 돌자 규제는 주 단위로 번졌어요. 연방 박멸 사업은 1918년 스테이크먼의 지휘로 출발했고 열세 개 주에서 시작해 1923년 워싱턴, 1935년 미주리와 펜실베이니아, 1955년 캔자스까지 확대됐어요. 1919년에는 연방 검역으로 주 사이 이동까지 막았고, 사업은 1975년부터 1980년 사이에 단계적으로 종료됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ars.usda.gov\",\"sourceUrl\":\"https://www.ars.usda.gov/midwest-area/stpaul/cereal-disease-lab/docs/barberry/barberry/\"},{\"id\":\"bstory-berberis-darwin-beagle\",\"title\":\"다윈이 보낸 매자나무\",\"hook\":\"비글호에서 채집한 관목에, 큐 왕립식물원이 다윈의 이름을 붙여요.\",\"body\":\"매자나무속에는 다윈의 이름이 그대로 붙은 종이 있어요. 베르베리스 다위니예요. 찰스 다윈이 비글호 항해 중에 이 식물을 채집해 영국 큐 왕립식물원으로 표본을 보냈고, 표본을 받은 윌리엄 후커가 종소명을 다윈에게서 따 왔어요. 원산지는 칠레와 아르헨티나, 남아메리카 남단의 서늘한 숲이에요. 진화론으로 기억되는 인물이지만 다윈은 항해 내내 표본을 모아 본국으로 부치던 채집가이기도 했고, 이 관목은 그 일상의 결과물 가운데 하나예요. 태평양 연안 기후에 잘 맞아 지금도 정원수로 많이 심고, 분류상으로는 매자나무과에 속해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"칠레\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/berberis-darwinii/\"}]},\"11-23\":{\"photo\":{\"src\":\"/birth/yangchi-1123.jpg\",\"thumbSrc\":\"/birth/thumbs/yangchi-1123.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Uitrollend_blad_van_een_mannetjesvaren_(Dryopteris_filix-mas)_28-04-2025_(d.j.b.)_02.jpg\",\"familyLine\":\"새잎이 돌돌 말린 채로 올라와 천천히 풀려요. 꽃도 씨앗도 없이 홀씨만으로 억겁을 건너온 무리예요.\"},\"stories\":[{\"id\":\"bstory-fern-seed-walk-invisible\",\"title\":\"고사리 씨앗을 쥐면 투명해집니다\",\"hook\":\"셰익스피어의 등장인물은 이렇게 말합니다. 우리에겐 고사리 씨앗 처방이 있으니 보이지 않게 다닌다고요.\",\"body\":\"헨리 4세 1부에 이런 대사가 나와요. 우리에겐 고사리 씨앗 처방이 있으니 보이지 않게 다닌다고요. 관객이 웃으려면 그 말을 알아들어야 하잖아요. 그러니까 그 시절 영국 사람들은 고사리 씨앗이 사람을 투명하게 만든다고 믿었던 거예요. 채집법도 정해져 있었어요. 한여름 밤 자정, 고사리 잎 아래에 백랍 접시 열두 장을 겹쳐 놓아요. 자정에 푸른 꽃이 열리며 금빛 씨앗 한 알이 떨어지는데, 그게 접시 열한 장을 뚫고 열두 번째 접시에 내려앉는다는 거예요. 사실 고사리는 꽃도 씨앗도 없어요. 잎 뒷면의 갈색 점, 그건 포자예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기~19세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"britishfairies.wordpress.com\",\"sourceUrl\":\"https://britishfairies.wordpress.com/2018/02/18/fern-seed-and-invisibility/\"},{\"id\":\"bstory-fern-boyi-shuqi-wei\",\"title\":\"주나라 곡식을 안 먹겠다며 캐 먹은 것\",\"hook\":\"두 형제는 주나라 곡식을 먹지 않겠다며 산에 들어가 풀을 캐 먹었습니다. 그러다 굶어 죽었습니다.\",\"body\":\"사기 백이열전에 나오는 이야기예요. 백이와 숙제는 고죽군의 두 아들이었어요. 무왕이 은나라를 치는 것을 두고 신하가 임금을 죽이는 일이라며 말렸지만 소용없었어요. 천하가 주나라를 섬기게 되자 두 사람은 그것을 부끄럽게 여겼어요. 의롭게 주나라 곡식을 먹지 않겠다며 수양산에 숨어 미를 캐 먹었어요. 굶어 죽기 직전에 노래 하나를 지었고, 그러고는 수양산에서 굶어 죽었어요. 여기 나오는 미를 우리말로는 오래도록 고사리라고 옮겨 왔어요. 다만 그 풀이 실제로 어떤 식물이었는지는 갈려요. 고사리로 보는 쪽도, 살갈퀴 종류로 보는 쪽도 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"ctext.org\",\"sourceUrl\":\"https://ctext.org/shiji/bo-yi-lie-zhuan\"},{\"id\":\"bstory-fern-fernseed-invisible\",\"title\":\"고사리 씨앗을 가진 도둑\",\"hook\":\"셰익스피어의 강도는 고사리 씨앗 처방으로 투명해진다고 자랑해요.\",\"body\":\"양치식물은 꽃도 씨앗도 맺지 않아요. 포자로 번지죠. 그런데 눈에 보이지 않는 씨앗이 있다면 그걸 지닌 사람도 보이지 않게 되지 않을까. 이 논리가 유럽에 오래 떠돌았어요. 셰익스피어는 헨리 4세 1부 2막 1장에서 그 믿음을 그대로 무대에 올려요. 강도 개즈힐이 이렇게 말해요. 우리는 성 안에 있는 것처럼 마음 놓고 훔친다, 우리에게는 고사리 씨앗 처방이 있어서 보이지 않게 다니거든. 그러자 여관 지배인이 곧바로 받아쳐요. 글쎄, 네가 보이지 않게 다니는 건 고사리 씨앗보다 밤 덕이 더 클 것 같은데.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"shakespeare.mit.edu\",\"sourceUrl\":\"https://shakespeare.mit.edu/1henryiv/1henryiv.2.1.html\"},{\"id\":\"bstory-fern-pteridomania-1855\",\"title\":\"1855년 영국을 덮친 고사리 열병\",\"hook\":\"킹즐리는 딸들이 걸린 유행에 '프테리도마니아'라는 병명을 붙였어요.\",\"body\":\"1855년 5월, 찰스 킹즐리는 글라우코스, 혹은 바닷가의 경이라는 책을 냅니다. 그 안에 이런 문장이 있어요. 당신의 딸들도 아마 요즘 유행하는 프테리도마니아에 걸려서, 고사리를 모으고 사들이고, 그것을 기를 워드 상자까지 장만하고, 발음도 안 되는 학명을 두고 다투고 있을 거라고요. 그 상자 값은 아버지가 치른다는 말도 괄호로 덧붙여요. 프테리도마니아는 킹즐리가 만든 말이에요. 양치식물을 뜻하는 그리스어 어근에 광기를 뜻하는 마니아를 붙였죠. 그러면서도 그는 이 유행이 소설이나 자수보다 딸들을 더 활기차고 밝게 만든다고 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"빅토리아 시대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/695/pg695.txt\"}]},\"11-24\":{\"photo\":{\"src\":\"/birth/gamaksalnamu-1124.jpg\",\"thumbSrc\":\"/birth/thumbs/gamaksalnamu-1124.jpg\",\"author\":\"Ryuch\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Gamaksal-tree-fruit.jpg\",\"familyLine\":\"가을이면 붉은 열매가 가지를 늘어뜨릴 만큼 촘촘히 달려요. 서리를 맞고 나서야 새들이 찾아와요.\"},\"stories\":[{\"id\":\"bstory-viburnum-crow-rice\",\"title\":\"까마귀가 먹는 쌀이라는 이름\",\"hook\":\"가막살나무의 이름에는 까마귀가 들어 있다고 해요.\",\"body\":\"가막살나무라는 이름의 유래로 가장 널리 알려진 설은 촘촘하게 모여 피는 흰 꽃봉오리가 '까마귀가 먹는 쌀'처럼 보인다는 거예요. 다른 설도 있어요. '가막'이 검은색을 뜻하는 말이라, 줄기와 가지의 빛이 가무잡잡해서 붙었다는 이야기예요. 어느 쪽도 확정된 것은 없고 두 설이 나란히 전해져요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"atlasnews.co.kr\",\"sourceUrl\":\"http://www.atlasnews.co.kr/news/articleView.html?idxno=8867\"},{\"id\":\"bstory-viburnum-red-berries\",\"title\":\"붉게 익지만 새가 잘 먹지 않아요\",\"hook\":\"이름과 달리 새들은 이 열매를 그리 좋아하지 않아요.\",\"body\":\"가막살나무는 10월쯤 달걀 모양 열매가 붉게 익어요. 신맛이 도는데 사람이 먹을 수는 있어요. 이름이 새와 얽혀 있는데도 정작 새들은 이 열매를 그리 즐겨 먹지 않는다고 알려져 있어요. 그래서 겨울까지 가지에 붉은 열매가 남아 있는 모습을 흔히 볼 수 있어요. 관상수로 정원에 심고 울타리로도 쓰는 이유가 여기에 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"위키백과\",\"sourceUrl\":\"https://ko.wikipedia.org/wiki/%EA%B0%80%EB%A7%89%EC%82%B4%EB%82%98%EB%AC%B4\"},{\"id\":\"bstory-viburnum-otzi-arrow-shafts\",\"title\":\"외치의 화살통 속 나무\",\"hook\":\"알프스 빙하에서 나온 미라의 화살통에 가막살나무 가지가 들어 있었어요.\",\"body\":\"알프스 빙하에서 발견된 미라 외치는 도구 일습을 그대로 지니고 있었어요. 그중 화살통에는 아직 완성되지 않은 화살대 열두 개와, 부싯돌 촉을 단 완성된 화살 두 개가 들어 있었어요. 이 화살대를 만든 나무가 가막살나무속의 비부르눔 란타나와 층층나무였어요. 함께 나온 활은 주목을 깎다 만 것으로 길이가 1.82미터였고, 구리 도끼의 자루도 주목이었어요. 도끼 날은 순도 99.7퍼센트의 구리였고요. 부싯돌 단검의 손잡이는 물푸레나무, 칼집은 참피나무 속껍질이었어요. 나무마다 성질을 따져 용도를 갈라 쓴 흔적이 도구 전체에 남아 있고, 화살대에 가막살나무 가지를 고른 것도 그 선택 중 하나예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"알프스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"iceman.it\",\"sourceUrl\":\"https://www.iceman.it/en/equipment/\"},{\"id\":\"bstory-viburnum-kalyna\",\"title\":\"붉은 칼리나의 노래\",\"hook\":\"1914년 시치 소총병의 노래가 2022년 다시 우크라이나 저항의 상징이 됐어요.\",\"body\":\"우크라이나에서 칼리나, 곧 붉은 가막살나무 열매는 오래된 상징이에요. 민요가 이 열매의 이미지로 문을 연 다음 은유와 정치 이야기로 넘어가곤 했다고 음악인류학자 마리아 소네비츠키는 설명해요. 1914년 가사로 만들어진 노래 오, 초원의 붉은 칼리나는 1차 세계대전 때 오스트리아-헝가리군 안에 편성된 우크라이나 부대, 시치 소총병과 단단히 묶여 있었죠. 소련 시절에는 지나치게 민족주의적이라는 이유로 금지돼 1980년대 말까지 거의 불리지 않았고요. 2022년 2월 러시아의 전면 침공 뒤 붐박스의 안드리 흘리브뉴크가 부른 영상이 퍼졌고, 그해 11월 헤르손이 해방됐을 때 시민들은 이 노래를 목청껏 불렀어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"우크라이나\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theworld.org\",\"sourceUrl\":\"https://theworld.org/stories/2022/12/01/chervona-kalyna-ukrainian-song-has-become-symbol-freedom-and-resilience\"}]},\"11-25\":{\"photo\":{\"src\":\"/birth/angaenamu.jpg\",\"thumbSrc\":\"/birth/thumbs/angaenamu.jpg\",\"author\":\"Didier Descouens\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:(MHNT)_Cotinus_coggygria_-_inflorescence.jpg\",\"familyLine\":\"꽃이 지고 나면 가느다란 자루만 남아 뿌옇게 부풀어요. 나무 전체가 연기에 싸인 것처럼 보여서 연기나무라고도 불러요.\"},\"stories\":[{\"id\":\"bstory-smoke-tree-venetian-sumach-dye\",\"title\":\"연기처럼 보이는 열매자루\",\"hook\":\"안개나무의 연기는 꽃이 아니라 열매를 맺지 못한 꽃자루 뭉치예요.\",\"body\":\"안개나무를 스모크 플랜트라고 부르는 건 진짜 연기가 피어서가 아니에요. 이 나무는 꽃을 잔뜩 피우지만 대부분이 열매를 맺지 못하고 떨어지는데, 그 자리에 남은 꽃자루가 길게 늘어나 깃털 같은 술이 돼요. 청록빛 잎과 어우러져 멀리서 보면 나무 전체가 연기에 싸인 것처럼 보이죠. 쓰임도 분명했어요. 뿌리와 줄기에서는 주황빛에 가까운 노란 염료를 얻었어요. 다만 색이 잘 날아가는 편이라 오래 버티지는 못했대요. 잎은 무두질에 대량으로 쓰였고요. 원산지는 남유럽인데 영국의 겨울도 견딜 만큼 튼튼해서 정원수로 흔히 심었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"https://botanical.com/botanical/mgmh/s/sumach97.html\"},{\"id\":\"bstory-smoke-tree-civil-war-dye\",\"title\":\"군복을 물들인 나무\",\"hook\":\"남북전쟁 동안 미국안개나무는 군복 염료를 얻으려 대량으로 베여 나갔어요.\",\"body\":\"북아메리카에도 안개나무가 있어요. 코티누스 오보바투스, 미국안개나무예요. 켄터키와 테네시, 앨라배마 북부에서 서쪽으로 오클라호마까지, 그리고 텍사스 중부에 걸쳐 자생해요. 자리는 까다롭게 골라요. 석회암이 드러난 초지, 북향이나 동향의 바위 절벽처럼 척박한 곳을 좋아하죠. 여름이면 시든 꽃차례에 분홍에서 자줏빛으로 도는 잔털이 15에서 25센티미터 길이로 자욱하게 퍼져, 나무 전체가 흐릿한 연기에 싸인 것처럼 보여요. 그런데 남북전쟁 때 이 나무의 목재가 병사들의 군복을 물들일 염료를 만드는 데 대량으로 쓰였어요. 지금은 단풍이 곱다는 이유로 정원에 심는 나무지만, 한때는 베어 넘겨 색을 뽑아내는 자원이었던 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/cotinus-obovatus/\"}]},\"11-26\":{\"photo\":{\"src\":\"/birth/seoyangtoppul.jpg\",\"thumbSrc\":\"/birth/thumbs/seoyangtoppul.jpg\",\"author\":\"Petar Milošević\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Yarrow_(Achillea_millefolium).jpg\",\"familyLine\":\"잎이 톱니처럼 잘게 갈라져요. 상처에 붙여 피를 멎게 하던 풀이라 전장에서 늘 곁에 두었어요.\"},\"stories\":[{\"id\":\"bstory-yarrow-achilles\",\"title\":\"아킬레우스와 톱풀의 시차\",\"hook\":\"톱풀이 아킬레우스의 약초가 된 건 트로이 전쟁 한참 뒤의 일이에요.\",\"body\":\"서양톱풀의 속명 아킬레아는 트로이 전쟁의 영웅 아킬레우스에서 왔어요. 그런데 이 연결은 일리아스가 전하는 가장 오래된 이야기층에는 없어요. 아킬레우스와 텔레포스의 싸움이라는 일화 자체가 기원전 5세기에야 등장하고, 그가 톱풀로 상처를 치료했다는 대목은 서기 1세기 플리니우스에 이르러서야 확인돼요. 정작 약효 기록은 착실히 쌓였어요. 1세기 디오스코리데스는 톱풀이 피 흐르는 상처를 아물게 하고 염증과 출혈을 줄인다고 적었어요. 갈레노스는 출혈과 설사, 부인과 질환에 쓴다고 되풀이했고, 이븐 시나는 갈레노스의 짧은 기록을 별다른 추가 없이 그대로 옮겼어요. 라틴어로는 군인의 풀, 영어로는 상처풀이라는 이름이 남았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스·로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ahpa.org\",\"sourceUrl\":\"https://www.ahpa.org/herbs_in_history_yarrow\"},{\"id\":\"bstory-yarrow-divination\",\"title\":\"49개만 세는 산가지\",\"hook\":\"주역 점의 산가지가 톱풀 줄기인데, 50개로 시작해 한 개는 끝까지 손대지 않아요.\",\"body\":\"주역 점에 쓰는 산가지가 바로 톱풀 줄기예요. 계사전이 전하는 방법은 산가지 50개로 시작하지만, 한 개를 빼놓고 49개만 손으로 가릅니다. 왜 하필 톱풀이었을까요. 리처드 러트는 줄기가 곧고 질기고 가벼워 다루기 좋았다는 실용적인 이유를 들어요. 토머스 후드는 톱풀이 조상의 무덤가에 자라는 풀이라, 그것을 손에 쥐면 죽은 이와 통한다고 믿었기 때문이라고 봐요. 후드는 빼놓은 한 개를 아직 차지 않은 달로, 손으로 만지는 49개를 다 찬 달의 위상으로 풀이해요. 톱풀 점은 상나라 갑골에서 이어진 거북 배딱지 점과 짝을 이루는 두 갈래 점법이었고, 정작 어떤 톱풀인지는 번역자마다 갈려요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"yijing.nl\",\"sourceUrl\":\"https://www.yijing.nl/YiMagic/yarrow.html\"}]},\"11-27\":{\"photo\":{\"src\":\"/birth/buknamu.jpg\",\"thumbSrc\":\"/birth/thumbs/buknamu.jpg\",\"author\":\"小石川人晃\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rhus_javanica_with_autumn_leaves.jpg\",\"familyLine\":\"가을이면 이름 그대로 새빨갛게 물들어요. 잎에 생기는 벌레집을 예부터 약재와 염료로 거뒀어요.\"},\"stories\":[{\"id\":\"bstory-rhus-saltfruit\",\"title\":\"소금이 열리는 나무, 염부목\",\"hook\":\"가을이 깊으면 열매에 하얀 소금기가 앉아서, 산골에서는 이걸 소금 대신 썼어요.\",\"body\":\"붉나무의 한자 이름은 염부목, 또는 목염이에요. 소금 염에 살갗 부, 말 그대로 소금 껍질을 두른 나무라는 뜻이죠. 가을이 깊어질수록 열매의 과육이 소금을 발라 놓은 것처럼 하얗게 변하고 제법 짠맛이 나서, 소금이 귀하던 시절 산골에서는 이걸 소금 대용으로 썼어요. 한국민족문화대백과사전은 붉나무를 옻나무과 낙엽 소교목으로 적고, 키 5~9미터, 줄기 지름 10~15센티미터, 잎은 길이 30~40센티미터의 홀수깃모양겹잎이라고 설명해요. 이 나무에 달리는 벌레혹인 오배자는 타닌이 많아 가죽 가공의 귀중한 자원이었고, 동의보감은 피부 질환과 종기, 입안이 헌 데를 다스리는 데 쓴다고 기록했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0075136\"},{\"id\":\"bstory-rhus-gall-tannin\",\"title\":\"벌레혹 무게의 60퍼센트가 타닌\",\"hook\":\"진딧물이 알을 낳으면 나무가 타닌 덩어리로 감싸는데, 말리면 무게의 60퍼센트가 타닌이에요.\",\"body\":\"붉나무 가지에 진딧물이 알을 낳으면, 나무는 그 알을 감싸면서 혹을 키워요. 이게 오배자예요. 나무가 스스로 만든 기관이 아니라 산란에 대한 반응으로 생긴 조직이에요. 말린 오배자는 무게의 60퍼센트가 넘게 타닌이라 수백 년 동안 가죽 무두질과 옷감 염색, 잉크 제조에 쓰였고 한약재로도 함께 쓰였어요. 색이 재미있어요. 오배자만 쓰면 옷감이 베이지색에서 그치는데, 철과 만나는 순간 타닌이 회색으로 확 가라앉아요. 양털은 군더더기 없는 강철빛 회색이 되고, 무명과 명주는 보랏빛이 도는 짙은 회색이 돼요. 참고로 지금 천연 타닌이자 염료로 유통되는 오배자는 한국에서 나와요.\",\"notes\":[{\"key\":\"region\",\"text\":\"동아시아\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"shepherdtextiles.com\",\"sourceUrl\":\"https://shepherdtextiles.com/dyeing-with-sumac-galls\"}]},\"11-28\":{\"stories\":[]},\"11-29\":{\"photo\":{\"src\":\"/birth/bakariseu.jpg\",\"thumbSrc\":\"/birth/thumbs/bakariseu.jpg\",\"author\":\"Macleay Grass Man\",\"license\":\"CC BY 2.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Baccharis_halimifolia_flower_female_NC1.jpg\",\"familyLine\":\"암그루에만 솜털 같은 씨앗이 달려요. 가을 바닷가에서 나무 한 그루가 통째로 하얘 보이는 건 그 솜털 때문이에요.\"},\"stories\":[{\"id\":\"bstory-baccharis-bacchus\",\"title\":\"바쿠스의 이름을 단 잡초\",\"hook\":\"속명은 술의 신 바쿠스에서 왔지만, 정작 소가 많이 먹으면 중독되는 잡초예요.\",\"body\":\"바카리스속의 이름은 술의 신 바쿠스에서 왔어요. 북미 원예 자료는 속명 바카리스를 술의 신의 이름을 딴 것이라고 못 박아요. 그런데 이 속의 대표 격인 바카리스 할리미폴리아는 술과는 거리가 멀어요. 미국 동부와 캐나다, 멕시코의 주로 해안 지대에 자라고, 소금 습지와 모래땅, 길가와 들판처럼 축축하고 어수선한 자리를 좋아해요. 종소명 할리미폴리아는 잎이 시스투스속 식물을 닮았다는 뜻인데, 그처럼 잎에 수지 기운이 돌아요. 소가 많이 뜯어 먹으면 중독되고, 암그루가 겨울에 씨를 바람에 실어 사방으로 날려 보내서 농지 주변에서는 잡초 취급을 받아요. 제초제도 잘 듣지 않아 손으로 뽑아내는 게 가장 확실한 방법이라고 적혀 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/baccharis-halimifolia/\"},{\"id\":\"bstory-baccharis-carqueja\",\"title\":\"날개 수로 종을 가른다\",\"hook\":\"잎이 아니라 줄기에 달린 날개로 광합성을 하고, 그 날개 개수로 종을 구별해요.\",\"body\":\"바카리스속에는 인정된 종만 약 442종이 있고, 브라질 한 나라에만 180종이 카칭가와 세하두, 아마존, 대서양림, 팜파, 판타나우에 흩어져 살아요. 그중 카르케하라 불리는 무리는 잎 대신 줄기에 광합성하는 날개, 곧 클라도드가 붙어 있어요. 이 날개는 줄기 축을 따라 두 장에서 다섯 장이 나는데, 어떤 종은 보통 두 장, 다른 종은 세 장이라 날개 수가 종을 가르는 표지가 돼요. 약전에 이름을 올린 건 셋뿐이에요. 바카리스 트리메라는 브라질 약전에, 아르티쿨라타와 크리스파는 아르헨티나 약전에 실려 있고요. 아르헨티나에서는 다른 종을 섞어 파는 위조가 보고돼서, 2024년 연구진이 브라질 일곱 종을 현미경으로 감별하는 기준을 세웠어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"브라질\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC11548319/\"}]},\"11-30\":{\"photo\":{\"src\":\"/birth/nakyeop-mareun-pul.jpg\",\"thumbSrc\":\"/birth/thumbs/nakyeop-mareun-pul.jpg\",\"author\":\"Serge Quadrado\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Autumn_Grass.jpg\",\"familyLine\":\"빛깔이 다 빠지고 나면 결만 남아요. 그 마른 결이 서로 얽혀서 겨울 동안 땅을 덮어 줘요.\"},\"stories\":[{\"id\":\"bstory-dry-grasses-greenaway-1884\",\"title\":\"마른 풀에는 이야기가 없어요\",\"hook\":\"이 이름으로 찾을 수 있었던 건 빅토리아 꽃말집의 한 줄짜리 표제어뿐이었어요.\",\"body\":\"이 날의 꽃 이름은 특정 식물이 아니라 상태예요. 표에는 낙엽 마른 풀, 영문으로는 드라이 그라시스라고만 적혀 있거든요. 그래서 이야기를 찾을 대상 자체가 없었어요. 조사자들이 마지막으로 확인한 것은 1884년 케이트 그리너웨이가 펴낸 꽃말집이었어요. 이 책에는 마른 아마가 유용함, 죽은 잎이 슬픔, 풀이 복종과 유용함, 온전한 짚이 결합, 부러진 짚이 계약 파기로 실려 있어요. 드라이 그라시스라는 표제어는 아예 없고요. 이 이름 뒤에 놓인 것은 어느 나라 어느 시대의 설화도 아니고, 빅토리아 시대 영국에서 꽃마다 뜻을 붙여 팔던 작은 사전 한 권의 한 줄이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"빅토리아 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/31591/31591-h/31591-h.htm\"}]},\"12-1\":{\"photo\":{\"src\":\"/birth/ssukgukhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/ssukgukhwa.jpg\",\"author\":\"Agnes Monkelbaan\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Bloemen_van_Boerenwormkruid_(Tanacetum_vulgare)._17-08-2025._(actm.)_02.jpg\",\"familyLine\":\"꽃잎이 없이 노란 단추만 동그랗게 모여요. 향이 강해서 예부터 벌레를 쫓는 데 썼어요.\"},\"stories\":[{\"id\":\"bstory-tansy-dunster\",\"title\":\"총장의 관을 채운 쑥국화\",\"hook\":\"하버드 초대 총장의 유해를 지목한 근거는 관 속을 가득 채운 쑥국화였어요.\",\"body\":\"19세기에 케임브리지의 옛 묘지에서 호고가들이 무덤 여러 기를 열었어요. 하버드 대학 초대 총장 헨리 던스터의 유해를 찾기 위해서였죠. 그들이 던스터라고 지목한 것은 방수포에 싸인 유해 하나였는데, 관 속이 쑥국화로 가득 채워져 있었어요. 시신 냄새를 감추려고 넣는 향기 나는 풀이었죠. 그 관을 근거로 기념비가 세워졌고, 지금도 묘석의 금속판에는 헨리 던스터, 1609년에서 1659년, 하버드 칼리지 초대 총장이라고 적혀 있어요. 다만 발굴 과정을 사적으로 기록한 존 랭던 시블리는 자기 일기에 정말 던스터를 찾은 게 맞는지 의심을 남겼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"news.harvard.edu\",\"sourceUrl\":\"https://news.harvard.edu/gazette/story/2015/10/in-the-old-burying-ground/\"},{\"id\":\"bstory-tansy-athanasia\",\"title\":\"죽지 않는다는 뜻의 이름\",\"hook\":\"탠지라는 말은 그리스어 '불사'가 닳고 닳아 남은 흔적이에요.\",\"body\":\"쑥국화의 영어 이름 탠지는 13세기 중엽 문헌에 탄세이로 처음 나타나요. 고대 프랑스어와 통속 라틴어, 후기 라틴어를 거슬러 올라가면 그리스어 아타나시아, 곧 불사에 닿아요. 아타나토스는 죽지 않는이라는 뜻이고, 부정을 뜻하는 접두사와 죽음을 뜻하는 타나토스가 붙어 만들어진 말이에요. 어원 사전은 이 풀이 좀처럼 시들거나 스러지지 않는 성질 때문에 그런 이름을 얻었을 것이라고 봐요. 그리고 15세기 중엽이 되면 탠지라는 말이 풀 이름을 넘어 쑥국화 즙으로 맛을 낸 푸딩까지 가리키게 돼요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"etymonline.com\",\"sourceUrl\":\"https://www.etymonline.com/word/tansy\"}]},\"12-2\":{\"photo\":{\"src\":\"/birth/ikki-0122.jpg\",\"thumbSrc\":\"/birth/thumbs/ikki-0122.jpg\",\"author\":\"Hans Hillewaert\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Polytrichum_commune_.jpg\",\"familyLine\":\"뿌리가 없어서 몸 전체로 물을 마셔요. 바싹 말라도 비 한 번이면 다시 초록으로 돌아와요.\"},\"stories\":[{\"id\":\"bstory-moss-sphagnum-field-dressing\",\"title\":\"늪에서 걷어 온 붕대\",\"hook\":\"1차 세계대전의 표준 지혈대는 공장이 아니라 늪에서 왔습니다. 그걸 걷은 사람은 여자와 아이들이었습니다.\",\"body\":\"1차 세계대전 초기에는 상처보다 패혈증으로 죽는 병사가 더 많았어요. 1915년에 군의관 찰스 캐스카트가 옛 기록을 떠올렸어요. 예전에는 물이끼로 상처를 싸맸다는 거예요. 시험해 보니 통했어요. 물이끼는 솜보다 두 배 넘는 피와 진물을 빨아들이고, 산성이라 세균이 잘 못 자라거든요. 그래서 전국 규모의 이끼 채집 사업이 시작됐어요. 보드민 무어에서 셰틀랜드까지, 여자들과 아이들이 차고 젖은 늪에 들어가 이끼를 걷었어요. 말리고 골라 무명 주머니에 채운 그 이끼가 영국과 자치령 군대의 표준 지혈대가 됐어요. 군복 안쪽에 꿰매 넣고 다니는 그 주머니예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"1910년대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"theconversation.com\",\"sourceUrl\":\"https://theconversation.com/war-and-peat-how-bog-moss-helped-save-thousands-of-lives-in-world-war-i-106630\"},{\"id\":\"bstory-moss-who-picked-it\",\"title\":\"그 이끼를 캔 사람들\",\"hook\":\"붕대가 될 이끼를 캔 것은 각지의 여자들과 아이들이었어요.\",\"body\":\"물이끼 붕대의 재료는 공장이 아니라 늪지에서 나왔어요. 그것을 캐고 말리고 자루에 채운 것은 온갖 나이의 여성과 아이들이었어요. 캐나다 적십자 온타리오 지부만 해도 1916년 한 해에 100만 장이 넘는 붕대를 만들어 보냈고, 1918년에는 영국에서 한 달에 100만 장이 병원으로 나갔어요. 전선 반대편도 사정은 같아서 독일에서는 민간인은 물론 연합군 포로까지 이 일에 동원됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-absorbency\",\"title\":\"제 무게 22배를 머금는 이끼\",\"hook\":\"세포의 90퍼센트가 죽은 세포라, 물이끼는 제 무게의 22배까지 물을 빨아들여요.\",\"body\":\"물이끼는 제 무게의 22배까지 물을 머금어요. 탈지면의 두 배죠. 세포의 90퍼센트가 죽은 세포라 애초에 물을 빨아들이게 생긴 구조예요. 게다가 세포벽이 음전하를 띠어 상처 둘레를 산성으로 만들고, 그 산성이 세균 번식을 막아요. 식물학자 아이작 베일리 밸푸어와 군의관 찰스 워커 캐스카트가 쓸 만한 두 종을 골라냈어요. 1916년 캐나다 적십자는 드레싱 100만 장 넘게, 압박포 200만 장 가까이, 패드 100만 장을 보냈고, 1918년에는 영국에서 매달 100만 장이 유럽과 이집트, 메소포타미아의 병원으로 나갔어요. 채집 안내문은 자루를 4분의 3만 채워 마른 땅으로 끌어낸 다음 그 위에서 춤을 춰 물을 빼라고 했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"20세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"smithsonianmag.com\",\"sourceUrl\":\"https://www.smithsonianmag.com/science-nature/how-humble-moss-helped-heal-wounds-thousands-WWI-180963081/\"},{\"id\":\"bstory-moss-saihoji\",\"title\":\"설계되지 않은 이끼 정원\",\"hook\":\"교토 사이호지의 이끼 120종은 정원사가 심은 게 아니라 홍수와 방치가 만든 거예요.\",\"body\":\"교토 사이호지 정원을 덮은 이끼는 120종이에요. 그런데 처음부터 이끼 정원으로 설계된 게 아니에요. 무소 소세키가 이 절을 되살렸을 때만 해도 황금 연못에 뜬 섬들의 꼭대기는 수면과 거의 같은 높이였어요. 그 뒤 이 일대는 몇 번이나 홍수를 겪었고, 그때마다 연못 바닥을 쳐내 물 높이를 낮추면서 퍼낸 진흙을 섬 위에 쌓았어요. 이끼는 그 진흙에서 자라기 시작했어요. 특히 에도 시대, 절을 손볼 사람이 없어 허물어져 가는 동안 이끼가 두껍게 앉았고, 지금 사람들이 보러 오는 풍경은 그 방치의 결과예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"mlit.go.jp\",\"sourceUrl\":\"https://www.mlit.go.jp/tagengo-db/en/R1-00439.html\"}]},\"12-3\":{\"stories\":[]},\"12-4\":{\"photo\":{\"src\":\"/birth/suyeong-1026.jpg\",\"thumbSrc\":\"/birth/thumbs/suyeong-1026.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Rumex_acetosa_-_Hapu_oblikas.jpg\",\"familyLine\":\"잎을 씹으면 새콤한 맛이 돌아요. 그 신맛 때문에 옛날 아이들이 들에서 간식처럼 뜯어 먹었어요.\"},\"stories\":[{\"id\":\"bstory-sorrel-acetaria\",\"title\":\"1699년 샐러드 책의 필수 재료\",\"hook\":\"존 이블린은 수영을 샐러드에서 결코 빼서는 안 될 재료라고 못 박았어요.\",\"body\":\"1699년 영국의 존 이블린은 샐러드만 다룬 책 아세타리아를 펴냈어요. 그 목록의 예순한 번째 항목이 수영이에요. 잎이 둥근 프랑스 종과 잎이 넓은 독일 종을 나누어 적고, 그린란드 수영이 가장 낫다고 했죠. 성질은 차고, 씻어 내리며, 시고, 식욕을 돋우고, 열을 가라앉히고, 간을 식히고, 심장을 튼튼하게 한다고 썼어요. 무엇보다 그는 수영을 괴혈병을 막고 부패를 막는 재료로 보았어요. 나머지 재료에 상큼한 날을 세워 주어서 오렌지와 레몬 같은 신맛 재료가 없을 때 그 자리를 대신하니, 결코 빼서는 안 된다고 못 박았고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/files/15517/15517-h/15517-h.htm\"},{\"id\":\"bstory-sorrel-salts-of-lemon\",\"title\":\"잉크 얼룩을 지운 레몬염\",\"hook\":\"수영에서 나온 옥살산은 '레몬염'이라는 이름으로 팔려 얼룩을 지우는 데 쓰였어요.\",\"body\":\"수영의 신맛은 옥살산에서 나와요. 그런데 이 성분은 먹는 것 말고도 쓸모가 있었어요. 수영에서 나온 옥살산염은 레몬염이라는 이름으로 상품이 되어, 밀짚을 표백하거나 리넨에 앉은 녹 자국을 빼거나 잉크 얼룩을 지우는 데 쓰였어요. 약으로도 오래 썼어요. 1세기의 그리스 의사 디오스코리데스와 로마의 대 플리니우스 시절부터 등장하는데, 몸을 식혀 주는 풀로 여겨 열병과 피부 종양, 황달, 몸속 궤양에 썼고 헌데와 멍, 종기, 수두에도 발랐어요. 화살촉 모양 잎은 1700년대까지 유럽 중세 채마밭에서 익숙한 풍경이었어요. 값이 싸고 어디서나 구할 수 있어 가난한 사람의 풀이라는 별명도 붙었고, 도싯의 아이들은 잎을 간식처럼 뜯어 먹었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"eatweeds.co.uk\",\"sourceUrl\":\"https://www.eatweeds.co.uk/sorrel-rumex-acetosa\"}]},\"12-5\":{\"photo\":{\"src\":\"/birth/aembeurosia.jpg\",\"thumbSrc\":\"/birth/thumbs/aembeurosia.jpg\",\"author\":\"Meneerke bloem\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Ambrosia_artemisiifolia_male_and_female_flowers_01.jpg\",\"familyLine\":\"이름은 신들의 음식이라는 뜻인데 정작 꽃가루로 사람을 고생시켜요. 한 그루가 한 철에 십억 개 넘는 꽃가루를 날려요.\"},\"stories\":[{\"id\":\"bstory-ambrosia-godsfood\",\"title\":\"신들의 음식이라는 잡초\",\"hook\":\"속명 암브로시아는 '신들의 음식'인데, 실제로는 알레르기의 대표 원인 잡초예요.\",\"body\":\"돼지풀의 속명 암브로시아는 그리스어로 신들의 음식, 또는 불사의 음료라는 뜻이에요. 종소명 아르테미시이폴리아는 잎이 쑥속을 닮았다는 뜻이고요. 이름은 이렇게 신화적인데 실제 이력은 정반대예요. 영어권에서는 이 풀을 건초열 잡초라고도 불러요. 북아메리카 대부분이 원산이고 지금은 미국 전 주와 캐나다 각 주는 물론 세계 곳곳에 귀화했어요. 수꽃이 늦여름부터 가을까지 어마어마한 양의 꽃가루를 바람에 실어 보내는데, 이게 알레르기와 꽃가루병, 접촉피부염을 일으키는 대표 원인이에요. 씨앗은 흙 속에서 5년까지 발아력을 유지하고, 키는 보통 30에서 90센티미터, 크면 1.8미터까지 자라요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/ambrosia-artemisiifolia/\"},{\"id\":\"bstory-ambrosia-ophraella\",\"title\":\"잎벌레가 꽃가루를 82퍼센트 줄였다\",\"hook\":\"2013년 북이탈리아에서 우연히 발견된 잎벌레 한 종이 유럽의 알레르기 지도를 바꾸는 중이에요.\",\"body\":\"유럽에서 돼지풀 꽃가루로 알레르기를 앓는 사람은 약 1,350만 명, 여기 드는 비용은 해마다 74억 유로로 추산돼요. 그런데 2013년 북이탈리아에서 예상 밖의 손님이 발견됐어요. 사람이 일부러 풀어놓은 것이 아니라 우연히 흘러든 잎벌레 오프라엘라 콤무나였어요. 북이탈리아에서는 돼지풀의 최대 100퍼센트가 이 벌레에게 갉아먹혔고, 피해가 심해 아예 꽃을 피우지 못할 정도였어요. 야외 실험에서 이 벌레는 돼지풀의 꽃가루 생산을 평균 82퍼센트 줄였어요. 연구진은 이 벌레가 유럽에서 살 수 있는 지역 전체로 퍼지면 환자가 약 230만 명, 16.9퍼센트 줄고 의료비는 해마다 11억 유로쯤 절약된다고 계산했어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC7174423/\"}]},\"12-6\":{\"photo\":{\"src\":\"/birth/bawichwi.jpg\",\"thumbSrc\":\"/birth/thumbs/bawichwi.jpg\",\"author\":\"Alpsdake\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Saxifraga_stolonifera_(flower_s7).jpg\",\"familyLine\":\"위쪽 꽃잎 세 장은 짧고 아래쪽 두 장만 길게 늘어져요. 한쪽으로 기울어진 그 모양이 이 꽃의 얼굴이에요.\"},\"stories\":[{\"id\":\"bstory-saxifraga-4505m\",\"title\":\"해발 4505미터의 꽃\",\"hook\":\"스위스 돔 봉우리 정상 40미터 아래에서 꽃을 피운 바위취가 유럽 최고 기록이에요.\",\"body\":\"2011년 5월 바젤 대학이 기록 하나를 발표했어요. 식물학자 크리스티안 쾨르너가 스위스 발레주의 돔 봉우리에서, 정상보다 겨우 40미터 아래인 해발 4,505미터 지점에 자주범의귀가 꽃을 피운 것을 확인했다는 내용이었어요. 유럽에서 기록된 가장 높은 곳의 꽃식물이고, 발표문은 이곳이 꽃식물이 확인된 지점 가운데 세계에서 가장 추운 곳일 것이라고 했어요. 이 자리는 밤이면 기온이 0도 아래로 떨어지고, 겨울에는 영하 20.9도까지 내려가며, 여름에도 최고 18.1도에 그쳐요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스위스\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"phys.org\",\"sourceUrl\":\"https://phys.org/news/2011-05-4505m-swiss-alps.html\"},{\"id\":\"bstory-saxifraga-stonebreaker\",\"title\":\"돌을 깨는 풀이라는 이름\",\"hook\":\"'돌을 깬다'는 속명의 돌은 바위가 아니라 몸속 결석을 가리키는 말이었어요.\",\"body\":\"삭시프라가는 라틴어로 돌을 깨는이라는 뜻인데, 이 돌은 바위가 아니라 몸속 결석을 가리켜요. 옛 약징주의는 몸의 어느 부위를 닮은 풀이 그 부위의 병을 고친다고 봤고, 범의귀류의 잎이 콩팥 모양이라 콩팥병, 그중에서도 결석에 쓴다고 여겼어요. 영국에서는 윌리엄 터너가 1568년에 이 풀을 처음 언급했고, 1597년 제라드의 허벌은 이 풀을 화이트 삭시프라지라 부르며 뿌리가 오줌을 잘 나오게 하고 콩팥과 방광을 씻어내며 돌을 깬다고 적었어요. 제라드는 뿌리에 달린 알갱이를 후추알만 한 붉은 알갱이나 둥근 뿌리라고 묘사했는데, 약재상들은 그걸 세멘 삭시프라게 알바이라는 이름으로 팔았어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botsocscot.wordpress.com\",\"sourceUrl\":\"https://botsocscot.wordpress.com/2023/04/09/plant-of-the-week-10th-april-2023-meadow-saxifrage-saxifraga-granulata/\"}]},\"12-7\":{\"photo\":{\"src\":\"/birth/yangchi-1123.jpg\",\"thumbSrc\":\"/birth/thumbs/yangchi-1123.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Uitrollend_blad_van_een_mannetjesvaren_(Dryopteris_filix-mas)_28-04-2025_(d.j.b.)_02.jpg\",\"familyLine\":\"새잎이 돌돌 말린 채로 올라와 천천히 풀려요. 꽃도 씨앗도 없이 홀씨만으로 억겁을 건너온 무리예요.\"},\"stories\":[{\"id\":\"bstory-fern-seed-walk-invisible\",\"title\":\"고사리 씨앗을 쥐면 투명해집니다\",\"hook\":\"셰익스피어의 등장인물은 이렇게 말합니다. 우리에겐 고사리 씨앗 처방이 있으니 보이지 않게 다닌다고요.\",\"body\":\"헨리 4세 1부에 이런 대사가 나와요. 우리에겐 고사리 씨앗 처방이 있으니 보이지 않게 다닌다고요. 관객이 웃으려면 그 말을 알아들어야 하잖아요. 그러니까 그 시절 영국 사람들은 고사리 씨앗이 사람을 투명하게 만든다고 믿었던 거예요. 채집법도 정해져 있었어요. 한여름 밤 자정, 고사리 잎 아래에 백랍 접시 열두 장을 겹쳐 놓아요. 자정에 푸른 꽃이 열리며 금빛 씨앗 한 알이 떨어지는데, 그게 접시 열한 장을 뚫고 열두 번째 접시에 내려앉는다는 거예요. 사실 고사리는 꽃도 씨앗도 없어요. 잎 뒷면의 갈색 점, 그건 포자예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기~19세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"britishfairies.wordpress.com\",\"sourceUrl\":\"https://britishfairies.wordpress.com/2018/02/18/fern-seed-and-invisibility/\"},{\"id\":\"bstory-fern-boyi-shuqi-wei\",\"title\":\"주나라 곡식을 안 먹겠다며 캐 먹은 것\",\"hook\":\"두 형제는 주나라 곡식을 먹지 않겠다며 산에 들어가 풀을 캐 먹었습니다. 그러다 굶어 죽었습니다.\",\"body\":\"사기 백이열전에 나오는 이야기예요. 백이와 숙제는 고죽군의 두 아들이었어요. 무왕이 은나라를 치는 것을 두고 신하가 임금을 죽이는 일이라며 말렸지만 소용없었어요. 천하가 주나라를 섬기게 되자 두 사람은 그것을 부끄럽게 여겼어요. 의롭게 주나라 곡식을 먹지 않겠다며 수양산에 숨어 미를 캐 먹었어요. 굶어 죽기 직전에 노래 하나를 지었고, 그러고는 수양산에서 굶어 죽었어요. 여기 나오는 미를 우리말로는 오래도록 고사리라고 옮겨 왔어요. 다만 그 풀이 실제로 어떤 식물이었는지는 갈려요. 고사리로 보는 쪽도, 살갈퀴 종류로 보는 쪽도 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"ctext.org\",\"sourceUrl\":\"https://ctext.org/shiji/bo-yi-lie-zhuan\"},{\"id\":\"bstory-fern-fernseed-invisible\",\"title\":\"고사리 씨앗을 가진 도둑\",\"hook\":\"셰익스피어의 강도는 고사리 씨앗 처방으로 투명해진다고 자랑해요.\",\"body\":\"양치식물은 꽃도 씨앗도 맺지 않아요. 포자로 번지죠. 그런데 눈에 보이지 않는 씨앗이 있다면 그걸 지닌 사람도 보이지 않게 되지 않을까. 이 논리가 유럽에 오래 떠돌았어요. 셰익스피어는 헨리 4세 1부 2막 1장에서 그 믿음을 그대로 무대에 올려요. 강도 개즈힐이 이렇게 말해요. 우리는 성 안에 있는 것처럼 마음 놓고 훔친다, 우리에게는 고사리 씨앗 처방이 있어서 보이지 않게 다니거든. 그러자 여관 지배인이 곧바로 받아쳐요. 글쎄, 네가 보이지 않게 다니는 건 고사리 씨앗보다 밤 덕이 더 클 것 같은데.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"shakespeare.mit.edu\",\"sourceUrl\":\"https://shakespeare.mit.edu/1henryiv/1henryiv.2.1.html\"},{\"id\":\"bstory-fern-pteridomania-1855\",\"title\":\"1855년 영국을 덮친 고사리 열병\",\"hook\":\"킹즐리는 딸들이 걸린 유행에 '프테리도마니아'라는 병명을 붙였어요.\",\"body\":\"1855년 5월, 찰스 킹즐리는 글라우코스, 혹은 바닷가의 경이라는 책을 냅니다. 그 안에 이런 문장이 있어요. 당신의 딸들도 아마 요즘 유행하는 프테리도마니아에 걸려서, 고사리를 모으고 사들이고, 그것을 기를 워드 상자까지 장만하고, 발음도 안 되는 학명을 두고 다투고 있을 거라고요. 그 상자 값은 아버지가 치른다는 말도 괄호로 덧붙여요. 프테리도마니아는 킹즐리가 만든 말이에요. 양치식물을 뜻하는 그리스어 어근에 광기를 뜻하는 마니아를 붙였죠. 그러면서도 그는 이 유행이 소설이나 자수보다 딸들을 더 활기차고 밝게 만든다고 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"빅토리아 시대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Project Gutenberg\",\"sourceUrl\":\"https://www.gutenberg.org/cache/epub/695/pg695.txt\"}]},\"12-8\":{\"photo\":{\"src\":\"/birth/galdae.jpg\",\"thumbSrc\":\"/birth/thumbs/galdae.jpg\",\"author\":\"Le.Loup.Gris\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Phragmites_australis_(inflorescences).jpg\",\"familyLine\":\"겨울이 와도 이삭을 그대로 달고 서 있어요. 바람이 불면 통째로 눕지만 부러지지는 않아요.\"},\"stories\":[{\"id\":\"bstory-reed-syrinx\",\"title\":\"갈대가 된 님프 시링크스\",\"hook\":\"판이 붙잡은 것은 님프가 아니라 한 줌의 물가 갈대였어요.\",\"body\":\"오비디우스 변신 이야기 1권에는 헤르메스가 눈이 백 개 달린 아르고스를 재우려고 들려주는 이야기가 나와요. 아르카디아에 시링크스라는 물의 님프가 있었는데, 디아나를 본받아 처녀로 살기를 고집했어요. 판이 쫓아오자 시링크스는 라돈 강가로 달아나 자매 님프들에게 자기 모습을 바꿔 달라고 빌었어요. 판이 마침내 붙잡았을 때 그의 팔에 안긴 것은 님프의 몸이 아니라 물가의 갈대였어요. 그 갈대 사이로 바람이 지나며 구슬프고도 사람 목소리 같은 소리가 났어요. 판은 이 소리로 우리가 영원히 이어지겠다고 말하고, 길이가 다른 갈대들을 밀랍으로 붙여 악기를 만들었어요. 그 악기 이름이 시링크스예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스·로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"perseus.tufts.edu\",\"sourceUrl\":\"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.02.0028%3Abook%3D1%3Acard%3D689\"},{\"id\":\"bstory-reed-haplotype\",\"title\":\"표본실이 밝힌 갈대의 정체\",\"hook\":\"북미 갈대밭의 주인이 언제 바뀌었는지, 백 년 전 표본이 말해 줬어요.\",\"body\":\"2002년 한 연구가 북아메리카 갈대밭의 정체를 다시 썼어요. 전 세계 갈대에서 스물일곱 개의 하플로타입이 확인됐고 그중 열한 개가 북아메리카 토종이었어요. 그런데 지금 습지를 뒤덮은 것은 유럽에서 건너온 하플로타입 M이었어요. 연구진은 1910년 이전에 채집된 표본 예순두 점과 1960년 이후의 표본 195점을 비교했어요. 코네티컷과 매사추세츠에서는 1940년이 되자 모든 표본이 M으로 바뀌어 있었어요. 옛 뉴잉글랜드 표본에 있던 토종 하플로타입 셋은 같은 자리를 다시 뒤졌는데도 현대 표본에서 나오지 않았어요. M은 원래 갈대가 자라지 않던 남동부까지 번졌고, 지금은 서쪽 중서부로 퍼지는 중이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"북아메리카\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC122384/\"}]},\"12-9\":{\"stories\":[]},\"12-10\":{\"stories\":[]},\"12-11\":{\"stories\":[{\"id\":\"bstory-danyang-aster-lost-and-found\",\"title\":\"댐에 잠겼다가 다시 발견됐어요\",\"hook\":\"자생지가 물에 잠긴 뒤 20여 년 만에 다시 나타났어요.\",\"body\":\"단양쑥부쟁이는 한국에만 자라는 특산식물이에요. 남한강 가의 자갈과 모래가 섞인 척박한 강변이 삶터였는데, 1980년대 충주댐이 들어서면서 단양과 충주 일대의 자생지가 대부분 물에 잠겼어요. 사라진 줄 알았던 이 풀은 2005년 여주 남한강 일대에서 다시 발견됐어요. 지금은 멸종위기 야생생물 2급으로 지정돼 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"bravo.etoday.co.kr\",\"sourceUrl\":\"https://bravo.etoday.co.kr/view/atc_view/9957\"},{\"id\":\"bstory-danyang-aster-dredged-soil\",\"title\":\"준설토 더미에서 다시 싹텄어요\",\"hook\":\"파낸 흙더미 위에서 멸종위기 식물이 자라 있었어요.\",\"body\":\"4대강 사업으로 최대 자생지가 또 한 번 위기를 맞자 강천섬에 대체 서식지를 만들어 옮겨 심는 작업이 이어졌어요. 그런데 2017년에는 뜻밖의 일이 있었어요. 강바닥에서 퍼 올려 쌓아 둔 준설토 더미에서 단양쑥부쟁이가 무리 지어 자라고 있는 것이 확인된 거예요. 물에 잠겨 있던 씨앗이 흙과 함께 올라와 싹을 틔운 셈이에요. 강가의 자갈밭을 고르는 이 풀의 습성이 그대로 드러난 장면이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"khan.co.kr\",\"sourceUrl\":\"https://www.khan.co.kr/article/201709291416001\"},{\"id\":\"bstory-fig-marigold-1937-naming\",\"title\":\"1937년에 이름을 얻은 풀\",\"hook\":\"남한강 자갈밭에만 사는 이 한국 특산 풀은 경쟁이 두려워 척박한 땅을 골랐어요.\",\"body\":\"단양쑥부쟁이는 1937년 일본 식물학자 기타무라 시로가 한반도 특산으로 보고하면서 학명을 얻었어요. 오랫동안 아스테르 알타이쿠스의 변종으로 불렸고, 최근 연구로 아스테르 단양겐시스라는 독립 종명을 갖게 됐어요. 국화과 두해살이풀로 키는 30에서 100센티미터, 잎이 솔잎처럼 가늘어 솔잎국화라고도 불려요. 지름 4센티미터쯤 되는 자주색 두상화를 8월부터 10월에 피우고요. 이 풀이 하필 강변 모래땅과 자갈밭을 고르는 이유는 경쟁에 약하기 때문이에요. 다른 식물과 섞이면 밀리니까 아예 남들이 버티기 힘든 척박한 땅으로 들어간 셈이죠. 지금은 환경부 지정 멸종위기 야생생물 2급이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"newspenguin.com\",\"sourceUrl\":\"https://www.newspenguin.com/news/articleView.html?idxno=18134\"},{\"id\":\"bstory-fig-marigold-gangcheon-island\",\"title\":\"강천섬의 150만 포기\",\"hook\":\"2005년 여주 남한강변에서 최대 군락이 발견됐고 4대강 사업 때 3만 8천 포기가 옮겨졌어요.\",\"body\":\"2005년 경기 여주 남한강변에서 단양쑥부쟁이 최대 군락지가 발견됐어요. 여주 강천면 굴암리의 강천섬을 비롯한 남한강 일대에는 150만여 개체가 사는 것으로 파악됐고요. 이 풀은 두해살이라 두 해째에 어른 허리 높이까지 자라 가을에 꽃을 피우고 죽어요. 척박한 땅을 좋아해서 몇 년에 한 번씩 홍수가 강천섬을 덮쳐 쌓인 모래를 쓸어내고 자갈밭을 다시 만들어 줘야 살아갈 수 있어요. 4대강 사업이 이 서식지를 없앨 거라는 우려가 커지자 정부는 3만 8천여 개체를 대체서식지로 옮겨 심었어요. 그해 4월 9일부터 11일까지 삼합지구에서만 2만 2천 개체가 이식됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"korea.kr\",\"sourceUrl\":\"https://www.korea.kr/news/policyNewsView.do?newsId=148695287\"}]},\"12-12\":{\"photo\":{\"src\":\"/birth/mokhwa.jpg\",\"thumbSrc\":\"/birth/thumbs/mokhwa.jpg\",\"author\":\"Mason Brock (Masebrock)\",\"license\":\"Public domain\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Gossypium_hirsutum_Florida.jpg\",\"familyLine\":\"꽃은 하얗게 피었다가 하루 만에 분홍으로 바뀌어요. 솜은 그 꽃이 진 자리에서 씨앗을 감싸며 자라요.\"},\"stories\":[{\"id\":\"bstory-cotton-munikjeom\",\"title\":\"붓 뚜껑이 아니라 주머니\",\"hook\":\"사료에 적힌 건 붓 뚜껑이 아니라 주머니고, 씨는 정확히 '10여 개'였어요.\",\"body\":\"문익점이 붓 뚜껑에 목화씨를 숨겨 왔다는 이야기는 사료에 없어요. 국사편찬위원회가 정리한 원 기록은 길가의 목화나무를 보고 그 씨 열 개 남짓을 따서 주머니에 넣어 왔다는 문장이에요. 국사편찬위원회는 훗날 그가 붓 뚜껑에 목화씨를 몰래 가져왔다는 등의 허구 섞인 이야기가 만들어지기도 하였다고 못 박아요. 문익점이 원에서 돌아온 것은 1364년 무렵이고, 장인 정천익이 씨를 심었지만 처음에는 딱 한 알만 살아남았어요. 3년 만에 크게 불어나 1367년에는 마을 사람들에게 씨를 나눠 줬고, 정천익은 중국 승려 홍원의 도움으로 씨아와 물레를 만들었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"14세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"contents.history.go.kr\",\"sourceUrl\":\"https://contents.history.go.kr/front/hm/view.do?treeId=020204&tabId=01&levelId=hm_056_0030\"},{\"id\":\"bstory-cotton-herodotus\",\"title\":\"양털을 능가하는 나무 털\",\"hook\":\"헤로도토스는 목화를 설명할 말이 없어서 '양털보다 나은 나무 털'이라고 적었어요.\",\"body\":\"기원전 5세기에 헤로도토스가 쓴 역사 3권 106절은 인도의 산물을 늘어놓는 대목이에요. 거기 이런 문장이 있어요. 야생으로 자라는 나무들이 양의 것을 아름다움과 뛰어남에서 능가하는 털을 맺고, 인도 사람들은 그 나무에서 얻은 옷을 입는다. 목화를 두고 한 말이에요. 그리스 독자들에게 목화는 낯선 물건이었으니, 헤로도토스는 그들이 아는 재료인 양털을 끌어와 설명할 수밖에 없었어요. 정작 목화는 나무가 아니라 관목이거나 한해살이 풀이고, 털처럼 보이는 것은 씨앗을 감싼 섬유예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"lexundria.com\",\"sourceUrl\":\"https://lexundria.com/hdt/3.106/mcly\"},{\"id\":\"bstory-cotton-gin-1794\",\"title\":\"1794년 조면기 특허\",\"hook\":\"기계가 손을 덜어 줬는데 노예 수요는 오히려 늘었어요.\",\"body\":\"1794년 일라이 휘트니가 조면기 특허를 받았어요. 그는 아버지에게 보낸 편지에 사람 하나와 말 한 마리가 옛 기계를 쓰는 사람 쉰 명보다 많이 해낸다고 적었어요. 씨를 빼는 병목이 풀리자 원면 생산은 1800년 이후 10년마다 두 배씩 늘었고, 1850년에는 미국이 세계 목화의 4분의 3을 댔어요. 그런데 기계가 사람 손을 덜어 준 만큼 노예가 줄어든 게 아니라 오히려 늘었어요. 목화를 심고 따는 일에 사람이 더 필요해졌거든요. 1790년에 여섯 곳이던 노예주는 1860년에 열다섯 곳이 됐고, 1790년부터 아프리카 노예무역이 금지된 1808년까지 남부는 약 8만 명의 아프리카인을 들여왔어요. 1860년에는 남부 사람 셋 중 하나가 노예였어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"archives.gov\",\"sourceUrl\":\"https://www.archives.gov/education/lessons/cotton-gin-patent\"}]},\"12-13\":{\"stories\":[]},\"12-14\":{\"photo\":{\"src\":\"/birth/sonamu-1114.jpg\",\"thumbSrc\":\"/birth/thumbs/sonamu-1114.jpg\",\"author\":\"Shuvaev\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Pinus_densiflora,_Morris_Arboretum_04.jpg\",\"familyLine\":\"잎이 두 개씩 짝을 지어 나요. 그 한 쌍이 붙어 있는 모양 때문에 예부터 부부에 빗대어 이야기됐어요.\"},\"stories\":[{\"id\":\"bstory-pine-jeongipumsong\",\"title\":\"벼슬 받은 소나무 한 그루\",\"hook\":\"임금의 가마가 걸리자 스스로 가지를 들어 올렸다는 나무가 있어요.\",\"body\":\"충청북도 보은군 속리산 어귀에는 정이품송이라 불리는 소나무가 서 있어요. 1464년, 세조 10년에 임금이 법주사로 행차하다 이 나무 아래를 지나게 되는데, 처진 가지에 가마가 걸릴 참이었대요. 연이 걸린다는 말이 떨어지자 나무가 스스로 가지를 위로 들어 올려 임금을 지나가게 했다는 이야기가 전해져요. 세조는 그 공을 기려 정이품 벼슬을 내렸고, 그래서 이름이 정이품송이 됐어요. 실제 나무는 높이 약 15미터, 가슴높이 줄기둘레 약 4.7미터에 가지가 동서로 19.9미터, 남북으로 19미터 뻗어 있고, 수령은 500년에서 600년으로 추정돼요. 1962년 12월 7일 천연기념물로 지정됐지만 1970년대 이후 솔잎혹파리 피해를 입어 1982년에는 보호구역과 철책이 설치됐어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"조선\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0030407\"},{\"id\":\"bstory-pine-sehando\",\"title\":\"유배지에서 그린 송백\",\"hook\":\"벼슬을 잃은 사람 곁에 남은 제자에게, 김정희는 소나무 그림을 보내요.\",\"body\":\"1844년, 김정희는 제주도 유배지에 있었어요. 지위도 권력도 사라진 자리였죠. 그때 역관 이상적은 두 번이나 북경에서 귀한 책을 구해 스승에게 보냈어요. 김정희는 그 마음에 답해 종이에 먹만으로 그림 한 장을 그려 건넵니다. 세로 23센티미터, 가로 69.2센티미터의 작은 화면에 허름한 집 한 채가 놓이고, 그 좌우로 소나무와 잣나무가 두 그루씩 마주 서 있어요. 겨울에도 잎을 떨구지 않는 나무를 지조의 상징으로 세운 구도예요. 이 그림이 세한도예요. 1974년 국보로 지정됐고 지금은 서울 국립중앙박물관에 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"한국\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"encykorea.aks.ac.kr\",\"sourceUrl\":\"https://encykorea.aks.ac.kr/Article/E0038956\"},{\"id\":\"bstory-pine-prometheus\",\"title\":\"4862개의 나이테\",\"hook\":\"1964년, 세상에서 가장 오래 산 나무가 나이를 재려던 사람의 손에 잘려 나갔어요.\",\"body\":\"1964년 여름, 지리학자 도널드 커리는 네바다주 휠러피크에서 브리슬콘 소나무를 조사하고 있었어요. WPN-114라는 번호를 붙인 나무에서 온전한 시료를 얻지 못하자 그는 산림청 허가를 받아 나무를 베고 단면을 통째로 살폈죠. 세어 보니 나이테가 4,862개였어요. 혹독한 해에는 테가 아예 생기지 않는 점을 감안하면 실제 나이는 약 4,900살로 추정됐고요. 당시까지 확인된 가장 오래된 나무였고, 2위였던 캘리포니아의 브리슬콘 소나무는 4,847살이었어요. 2012년에는 같은 지역에서 5,065살 된 나무가 발견됐죠. 프로메테우스라 불린 그 나무의 단면 조각은 지금 그레이트베이슨 방문자센터에 전시돼 있고, 브리슬콘 소나무는 연방 토지에서 보호받고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"미국\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"nps.gov\",\"sourceUrl\":\"https://www.nps.gov/grba/learn/historyculture/the-prometheus-story.htm\"}]},\"12-15\":{\"photo\":{\"src\":\"/birth/seohyang-1215.jpg\",\"thumbSrc\":\"/birth/thumbs/seohyang-1215.jpg\",\"author\":\"Herby (talk thyme)\",\"license\":\"CC BY 2.5\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Daphne_Odora_flower.jpg\",\"familyLine\":\"천 리를 간다는 말이 붙을 만큼 향이 멀리 가요. 정작 꽃은 손톱만 해서 향을 먼저 맡고 나서 찾게 돼요.\"},\"stories\":[{\"id\":\"bstory-daphne-odora-not-a-laurel\",\"title\":\"월계수의 이름을 쓰는 월계수 아닌 나무\",\"hook\":\"학명은 다프네, 흔한 별명은 스퍼지 로렐. 그런데 이 나무는 월계수가 아닙니다.\",\"body\":\"서향의 학명은 다프네 오도라예요. 다프네는 그리스 말로 월계수를 뜻해요. 아폴론에게 쫓기다 월계수가 된 님프의 이름이기도 하고요. 영어권에서 이 나무에 붙은 별명 가운데는 스퍼지 로렐, 드워프 베이 같은 것도 있어요. 로렐도 베이도 월계수를 가리키는 말이에요. 그런데 서향은 월계수와 아무 관계가 없어요. 팥꽃나무과 나무거든요. 향기 하나만큼은 대단해서 겨울 끝자락에 담장 하나를 통째로 채워요. 대신 온몸에 독이 있어요. 자료는 이 나무의 독성을 최고 등급으로 매겨 놓았어요. 이름은 월계수, 집안은 팥꽃나무, 성질은 독초예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/daphne-odora/\"},{\"id\":\"bstory-daphne-sleeping-scent\",\"title\":\"여산에서 잠을 깬 향기\",\"hook\":\"벼랑 밑에서 낮잠을 자다 향기에 깬 승려가 이 나무에 이름을 붙였대요.\",\"body\":\"서향은 중국이 원산이고 송나라 때부터, 그러니까 천 년 넘게 길러 온 나무예요. 중국 본초 기록에는 이름의 유래로 이런 이야기가 전해요. 여산 벼랑 아래에서 낮잠을 자던 승려가 잊을 수 없는 향기에 잠을 깼고, 그 향의 근원을 찾아 벼랑을 올라가 꽃이 핀 이 나무를 발견하고는 잠결의 향이라 이름 붙였다는 거예요. 늦겨울에 밀랍처럼 도톰한 분홍 꽃이 뭉쳐 피고 향은 꽤 멀리까지 퍼져요. 유럽 정원사들이 이 나무를 만난 것은 1771년, 일본을 거쳐 영국에 들어오면서였어요. 잎이든 열매든 뿌리든 먹으면 중독되고 수액은 피부를 상하게 해요. 물이 고이는 흙에서는 뿌리가 썩어 그대로 죽어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"woodlanders.net\",\"sourceUrl\":\"https://woodlanders.net/products/daphne-odora\"},{\"id\":\"bstory-daphne-not-laurel\",\"title\":\"린네가 남긴 말장난\",\"hook\":\"그리스어 다프네는 월계수라는 뜻인데, 정작 서향은 월계수와 과부터 달라요.\",\"body\":\"서향속의 학명 다프네는 그리스어로 월계수라는 뜻이에요. 아폴론에게 쫓기던 물의 님프 다프네가 강의 신인 아버지에게 빌어 월계수로 변했다는 신화에서 온 말이죠. 그런데 정원의 서향은 월계수와 아무 관계가 없어요. 월계수는 녹나무과이고 서향은 팥꽃나무과라 과부터 다릅니다. 1750년대에 이명법을 세운 린네는 이 사실을 알면서도 유럽의 한 종에 다프네 라우레올라라는 이름을 붙였어요. 풀어 쓰면 월계수 월계수인 셈이라, 일종의 말장난이었어요. 서향은 중국 송나라 때부터 재배됐고 일본 기록에는 1309년에 나타나요. 중국에서는 목이 아플 때와 천연두에 씻는 약으로 썼어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"khkeeler.blogspot.com\",\"sourceUrl\":\"http://khkeeler.blogspot.com/2015/05/plant-story-daphne-attractive-and.html\"}]},\"12-16\":{\"photo\":{\"src\":\"/birth/orinamu.jpg\",\"thumbSrc\":\"/birth/thumbs/orinamu.jpg\",\"author\":\"Agnieszka Kwiecień, Nova\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Alnus_japonica_Olsza_japo%C5%84ska_2021-10-02_06.jpg\",\"familyLine\":\"뿌리에 공생균을 들여 척박한 땅에서도 자라요. 그 덕에 헐벗은 산에 가장 먼저 들어가는 나무가 됐어요.\"},\"stories\":[{\"id\":\"bstory-alder-venice-piles\",\"title\":\"물속에 잠긴 1500만 개 말뚝\",\"hook\":\"베네치아 석호 바닥에는 790만에서 1580만 개의 나무 말뚝이 박혀 있어요.\",\"body\":\"베네치아는 석호 바닥에 나무 말뚝을 박아 올린 도시예요. 추정치로 790만에서 1,580만 개의 말뚝이 갯벌에 박혔어요. 나무는 종류별로 역할이 갈렸어요. 오리나무는 물에 잠겼을 때 썩지 않는 성질이 뛰어나 기본 말뚝으로, 참나무는 단단해서 교회와 궁전처럼 무거운 건물 밑에, 소나무는 구하기 쉽고 가벼워 다루기 좋아서, 낙엽송은 썩음과 벌레에 강해서 골랐어요. 말뚝은 길이 2에서 8미터, 지름 10에서 30센티미터짜리를 1제곱미터에 다섯에서 열 개씩 촘촘히 박았어요. 산소가 거의 없는 진흙에 잠긴 나무에는 미생물이 붙지 못하고, 고운 흙과 광물이 나무의 세포 구멍을 채우면서 돌처럼 굳어 갔어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이탈리아\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pilebuck.com\",\"sourceUrl\":\"https://pilebuck.com/building-venice-timber-piles-infrastructure-lasting-lessons-foundation-engineering/\"},{\"id\":\"bstory-alder-bleeding\",\"title\":\"베면 피가 흐르는 나무\",\"hook\":\"창백하던 속살이 베는 순간 붉어져서, 사람들은 나무가 피를 흘린다고 여겼어요.\",\"body\":\"살아 있을 때 창백하던 오리나무 속살은 베는 순간 짙은 주황빛으로 변해요. 피가 흐르는 것처럼 보였고, 그래서 이 나무에는 온갖 불길한 미신이 붙었어요. 아일랜드에서는 길을 가다 오리나무를 지나치는 일을 불운으로 여겼어요. 그러면서도 먼 길을 떠날 때 신발에 오리나무 잎을 넣으면 발이 시원하고 붓지 않는다고 믿었고요. 아일랜드 신화에서 오리나무 숲은 숨는 곳이었어요. 슬픔의 데어드러 이야기에서 데어드러와 노이셰는 왕의 추격을 피해 글렌 에티브의 오리나무 숲에 몸을 감춰요. 꽃에서 얻는 초록 물감은 로빈 후드 같은 무법자의 옷과 요정의 옷을 물들이는 데 쓰였다고 하고, 켈트족은 오리나무 숯의 센 불로 최고의 무기를 벼렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"아일랜드\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"treesforlife.org.uk\",\"sourceUrl\":\"https://treesforlife.org.uk/into-the-forest/trees-plants-animals/trees/alder/alder-mythology-and-folklore/\"}]},\"12-17\":{\"photo\":{\"src\":\"/birth/beotkkotnan.jpg\",\"thumbSrc\":\"/birth/thumbs/beotkkotnan.jpg\",\"author\":\"Franz van Duns\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Hoya_carnosa_-_umbel_with_nectar_droplets.jpg\",\"familyLine\":\"별 모양 꽃이 공처럼 둥글게 모여 피어요. 밤이면 꿀이 방울져 맺힐 만큼 넉넉히 흘려요.\"},\"stories\":[{\"id\":\"bstory-hoya-not-cherry-not-orchid\",\"title\":\"벚꽃도 아니고 난초도 아닙니다\",\"hook\":\"이름에 벚꽃과 난이 다 들어 있는데, 둘 다 아닙니다.\",\"body\":\"벚꽃난의 학명은 호야 카르노사예요. 영어 별명은 왁스 플랜트, 포슬린 플라워, 허니 플랜트예요. 밀랍 식물, 도자기 꽃, 꿀 식물이라는 뜻이에요. 이름들이 하나같이 촉감과 질감을 가리켜요. 꽃잎이 정말 밀랍이나 도자기처럼 단단하고 반들거리거든요. 그런데 우리말 이름에는 벚꽃과 난이 들어 있어요. 둘 다 아니에요. 벚나무와도 난초과와도 무관한, 협죽도과의 상록 덩굴식물이에요. 나무나 바위에 붙어 사는 착생식물이고요. birth_flowers 표에 붙은 영문명 허니 플랜트는 정확한데, 우리말 이름은 두 겹으로 헷갈리게 돼 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"plants.ces.ncsu.edu\",\"sourceUrl\":\"https://plants.ces.ncsu.edu/plants/hoya-carnosa/\"},{\"id\":\"bstory-hoya-1782-naming\",\"title\":\"1782년의 첫 이름\",\"hook\":\"벚꽃난은 처음 학계에 등장할 때 호야가 아니라 아스클레피아스라는 이름이었어요.\",\"body\":\"지금 호야 카르노사라 부르는 이 덩굴은 처음부터 호야가 아니었어요. 1782년 린네의 아들 카를 폰 린네가 아버지 저작의 보유편인 수플레멘툼 플란타룸 170쪽에서 이 식물을 아스클레피아스 카르노사로 기재했어요. 종소명 카르노사는 살집이 있다는 뜻으로, 두툼하게 살이 오른 잎을 가리켜요. 그로부터 스물여덟 해 뒤인 1810년, 스코틀랜드 식물학자 로버트 브라운이 박주가리 무리를 정리한 논문에서 이 종을 새 속인 호야로 옮겼어요. 속명은 노섬벌랜드 공작의 시온하우스에서 40년을 일한 정원사 토머스 호이의 성에서 왔고요. 그래서 학명 뒤에는 두 사람의 흔적이 괄호 친 형태로 나란히 남아 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"ipni.org\",\"sourceUrl\":\"https://www.ipni.org/n/107308-3\"},{\"id\":\"bstory-hoya-peduncle\",\"title\":\"시든 꽃대를 자르지 마세요\",\"hook\":\"꽃이 진 자리를 잘라내면 다음 해에 필 꽃까지 함께 잘려 나가요.\",\"body\":\"벚꽃난은 꽃이 지고 남은 짧은 꽃대를 그대로 두어야 해요. 이 꽃대는 페덩클, 흔히 스퍼라고 부르는 여러 해 남는 구조인데, 많은 종이 해마다 같은 꽃대에서 다시 꽃을 피워요. 아이오와주립대 확장교육 자료는 시든 꽃은 저절로 떨어지게 두고 절대 잘라내지 말라고 못 박아요. 잘라 버리면 앞으로 꽃이 달릴 자리를 없애는 셈이라 개화가 오래 늦어지거든요. 꽃은 밀랍을 입힌 듯한 별 모양으로 무리 지어 피고 대개 여름에 나오며, 저녁이나 밤에 향이 특히 진해져요. 이 속에는 아시아와 오스트레일리아, 그 주변 섬의 열대·아열대에 자생하는 수백 종이 들어 있고 대개 나뭇가지에 붙어 사는 착생식물이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"여러 나라\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"yardandgarden.extension.iastate.edu\",\"sourceUrl\":\"https://yardandgarden.extension.iastate.edu/how-to/all-about-hoyas\"}]},\"12-18\":{\"photo\":{\"src\":\"/birth/seiji.jpg\",\"thumbSrc\":\"/birth/thumbs/seiji.jpg\",\"author\":\"Flocci Nivis\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20260614_Salvia_officinalis_05.jpg\",\"familyLine\":\"이름에 구한다는 뜻이 들어 있어요. 이 풀을 심어 둔 집에는 병이 들지 않는다는 말이 오래 따라다녔어요.\"},\"stories\":[{\"id\":\"bstory-sage-may-proverb\",\"title\":\"5월에 세이지를 먹으라\",\"hook\":\"오래 살고 싶으면 5월에 세이지를 먹어야 한다는 속담이 영국에 있었어요.\",\"body\":\"세이지는 오래 살게 해 준다는 믿음을 길게 달고 다녔어요. 영국에는 길이 살고자 하는 이는 5월에 세이지를 먹어야 한다는 속담이 있었고, 아예 구원하는 세이지라는 뜻의 살비아 살바트릭스라는 별명으로도 불렸어요. 살레르노 의학교가 남긴 라틴 격언은 한술 더 떠요. 정원에 세이지가 자라는데 사람이 어찌 죽겠느냐고 물은 다음, 곧바로 죽음의 힘 앞에서는 정원에 아무 약도 없다고 스스로 답하거든요. 1597년 제라드는 세이지를 영국 정원에 이미 자리 잡은 식물로 적었어요. 새뮤얼 피프스는 어느 교회 묘지에서 무덤 위에 세이지를 심는 풍습을 보고 일기에 남겼지요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"16세기\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"http://botanical.com/botanical/mgmh/s/sages-05.html\"},{\"id\":\"bstory-sage-tea-trade\",\"title\":\"세이지 1파운드에 차 3파운드\",\"hook\":\"네덜란드 상인은 중국에 세이지를 내밀고 그 세 배 무게의 차를 받아 왔다고 해요.\",\"body\":\"18세기 유럽에는 중국인이 자기네 차보다 세이지 차를 더 쳐준다는 이야기가 돌았어요. 네덜란드 동인도회사 배가 두 번째로 중국에 갔을 때, 네덜란드 쪽은 중국에 아직 알려지지 않은 귀한 약초라며 세이지를 내밀었고, 세이지 1파운드에 차 3파운드를 받는 조건으로 바꿨다고 해요. 이 대목은 1730년 런던에서 나온 토머스 쇼트의 차에 관한 논고에 실린 것을 후대의 차 역사서가 그대로 옮긴 것이에요. 차를 유럽으로 실어 나르고 싶었던 상인들이 중국 상인의 마음을 끌 물건을 찾다 벌인 일이었지요.\",\"notes\":[{\"key\":\"region\",\"text\":\"네덜란드·중국\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"henriettes-herb.com\",\"sourceUrl\":\"https://henriettes-herb.com/eclectic/tea/chapter-ii.html\"}]},\"12-19\":{\"photo\":{\"src\":\"/birth/seuno-peulreikeu.jpg\",\"thumbSrc\":\"/birth/thumbs/seuno-peulreikeu.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lenteklokje_(Leucojum_vernum),_05-03-2026._(d.j.b.).jpg\",\"familyLine\":\"흰 꽃잎 여섯 장 끝마다 연둣빛 점이 하나씩 찍혀 있어요. 눈송이처럼 보이지만 자세히 보면 그 점이 먼저 눈에 들어와요.\"},\"stories\":[{\"id\":\"bstory-snowflake-vs-snowdrop\",\"title\":\"스노드롭과 헷갈리는 이유\",\"hook\":\"꽃잎 여섯 장의 크기가 같으면 스노플레이크, 안쪽 세 장이 작으면 스노드롭이에요.\",\"body\":\"스노플레이크와 스노드롭은 봄을 먼저 알리는 흰 종 모양 꽃이라 자주 뒤바뀌어 불려요. 모리스 수목원 설명을 보면 구분법은 의외로 단순해요. 스노드롭인 갈란투스는 바깥쪽 화피 세 장이 크고 안쪽 세 장이 작아 길이가 확 달라지는데, 스노플레이크인 레우코윰은 여섯 장이 모두 같은 크기예요. 꽃대를 잘라 보면 레우코윰은 속이 비어 있고 갈란투스는 차 있어요. 이름도 대비돼요. 갈란투스는 고대 그리스어로 젖빛 꽃, 레우코윰은 흰 제비꽃이라는 뜻이에요. 이름은 제비꽃인데 정작 수선화과에 속해서 아마릴리스나 수선화와 한 집안이지요. 둘은 갈란테아이족에 함께 묶이는 자매 속이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"유럽\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"morrisarboretum.org\",\"sourceUrl\":\"https://www.morrisarboretum.org/blog/snowflakes-vs-snowdrops-pendulous-beauties-early-spring\"},{\"id\":\"bstory-snowflake-poznan-record\",\"title\":\"폴란드가 기다리는 봄 신호\",\"hook\":\"포즈난 근처에는 이 꽃 하나를 지키려고 만든 자연보호구역이 있어요.\",\"body\":\"폴란드에서 이 꽃은 시니에지차 비오센나라 불리며 겨울이 끝났다는 신호로 기다려지는 꽃이에요. 꽃이 피는 곳에 사람이 몰려서 생태관광 자원이 될 정도고, 포즈난 근처에는 이 종을 지키려고 지정한 자연보호구역까지 있어요. 스파크스 연구진은 약 20킬로미터 떨어진 두 곳, 포즈난 식물원과 이 보호구역에서 1994년부터 2009년까지 16년 동안 개화 기록을 모았어요. 그리고 두 장소의 개화 시기가 얼마나 함께 움직이는지 분석해 2011년 국제생물기상학회지에 실었어요. 논문은 이 꽃의 위상을 일본의 벚꽃에 견주어 설명해요.\",\"notes\":[{\"key\":\"region\",\"text\":\"폴란드\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC3278609/\"}]},\"12-20\":{\"photo\":{\"src\":\"/birth/painaepeul.jpg\",\"thumbSrc\":\"/birth/thumbs/painaepeul.jpg\",\"author\":\"Flocci Nivis\",\"license\":\"CC BY 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:20260317_Ananas_comosus.jpg\",\"familyLine\":\"열매 하나가 사실은 꽃 백여 송이가 붙어 만들어진 덩어리예요. 겉의 육각 무늬 하나하나가 꽃 한 송이의 자리예요.\"},\"stories\":[{\"id\":\"bstory-pineapple-dunmore-folly\",\"title\":\"37피트짜리 돌 파인애플\",\"hook\":\"던모어 백작은 1761년 무렵 온실 건물 꼭대기에 높이 37피트 돌 파인애플을 얹었어요.\",\"body\":\"파인애플이 신분의 상징이던 시절, 영국의 파인애플 온실에는 파이너리라는 이름이 붙었어요. 1688년 윌리엄 3세와 메리 여왕이 들어온 뒤 햄프턴 코트에서도 파인애플을 길렀고, 스코틀랜드에서는 1732년부터 재배가 시작됐어요. 그 자랑이 건물로 굳은 것이 던모어의 파인애플이에요. 4대 던모어 백작 존 머리는 1761년 무렵 자기 정원 건물 꼭대기에 높이 37피트, 약 11미터짜리 돌 파인애플을 깎아 올렸어요. 온실 벽을 데워 열대 과일을 익히던 정원 위에 그 과일을 통째로 석조로 세워 둔 셈이지요. 파인애플 무늬는 1730년대부터 아메리카 식민지의 건축 장식에도 나타나요.\",\"notes\":[{\"key\":\"region\",\"text\":\"스코틀랜드\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"blog.library.si.edu\",\"sourceUrl\":\"https://blog.library.si.edu/blog/2021/01/28/the-prickly-meanings-of-the-pineapple/\"},{\"id\":\"bstory-pineapple-rental\",\"title\":\"하룻밤 빌리는 파인애플\",\"hook\":\"살 수 없는 사람은 만찬 저녁 동안만 파인애플을 빌려 식탁에 올렸어요.\",\"body\":\"18세기 영국에서 파인애플 한 개 값은 한 가정의 연 수입을 훌쩍 넘겼어요. 대부분의 가정이 한 해 50파운드도 벌지 못하던 시절에 파인애플은 수천 파운드까지 나갔거든요. 그래서 살 형편이 안 되는 중산층은 만찬 저녁 동안만 파인애플을 빌려 식탁에 올려놓고, 손님이 돌아가면 돌려줬어요. 업자들은 같은 열매를 상하기 직전까지 여러 번 빌려주다가 마지막에는 귀족에게 먹을 것으로 팔아넘겼고요. 왕실은 아예 길렀어요. 1733년 루이 15세는 베르사유 정원에서 난 파인애플을 받고 기뻐하며 귀족들에게 조각을 나눠 줬고, 1738년 베르사유 온실에는 800그루가 넘게 자라고 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국·프랑스\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"justhistoryposts.com\",\"sourceUrl\":\"https://justhistoryposts.com/2019/03/15/when-pineapples-were-the-height-of-luxury/\"}]},\"12-21\":{\"photo\":{\"src\":\"/birth/bakha-1221.jpg\",\"thumbSrc\":\"/birth/thumbs/bakha-1221.jpg\",\"author\":\"Ivar Leidus\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Mentha_arvensis_-_p%C3%B5ldm%C3%BCnt_Keila.jpg\",\"familyLine\":\"시원한 느낌은 온도가 아니라 착각이에요. 잎의 멘톨이 차가움을 느끼는 감각을 그냥 켜 버리는 거예요.\"},\"stories\":[{\"id\":\"bstory-mint-minthe-trampled\",\"title\":\"밟혀서 향이 된 님프\",\"hook\":\"저승의 왕이 사랑한 님프는 여왕의 발에 짓밟혔습니다. 그 자리에서 박하가 돋았습니다.\",\"body\":\"민테는 엘리스 지방의 물의 님프였어요. 하데스가 그를 사랑했고요. 그런데 민테가 자기가 페르세포네보다 아름답다고, 하데스가 곧 자기에게 돌아올 거라고 떠벌렸어요. 그 말이 화를 불렀어요. 스트라본의 지리지는 민테가 페르세포네의 발에 짓밟혀 정원의 박하로 변했다고 적어요. 오피아노스는 데메테르가 노해서 짓밟았다고 하고, 오비디우스는 페르세포네가 직접 변신시켰다고 해요. 누가 밟았는지는 갈리는데 결말은 같아요. 짓밟힌 자리에서 향기로운 풀이 돋았다는 것. 필로스 근처에는 지금도 민테의 이름을 딴 산이 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"theoi.com\",\"sourceUrl\":\"https://www.theoi.com/Nymphe/NympheMinthe.html\"},{\"id\":\"bstory-mint-peppermint-hybrid\",\"title\":\"페퍼민트는 야생에서 우연히 생긴 잡종이에요\",\"hook\":\"페퍼민트에는 조상이 둘 있어요.\",\"body\":\"페퍼민트는 워터민트와 스피어민트가 자연에서 교배해 생긴 잡종이에요. 1696년 영국 박물학자 존 레이가 들판에서 후추 맛이 나는 민트를 발견해 처음 기록했고, 1721년에는 런던 약전에 올랐어요. 상업 재배는 18세기 중반 서리주 미첨 일대에서 시작됐는데, 그곳 이름을 딴 미첨 민트는 지금도 가장 널리 퍼진 계통이에요. 향은 오래됐지만 종 자체는 꽤 젊은 셈이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"영국\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"Wikipedia\",\"sourceUrl\":\"https://en.wikipedia.org/wiki/Peppermint\"},{\"id\":\"bstory-mint-mitcham-500acres\",\"title\":\"미첨의 박하밭 500에이커\",\"hook\":\"1750년 무렵 시작된 미첨의 페퍼민트 재배는 1850년에 약 500에이커에 이르렀어요.\",\"body\":\"페퍼민트는 오랫동안 박하의 한 갈래로만 취급되다가 1696년 식물학자 존 레이가 별개의 종으로 갈라냈어요. 1721년에는 런던 약전에 정식으로 올랐지요. 상업 재배는 1750년 무렵 런던 남쪽 미첨에서 시작됐고, 1850년에는 재배 면적이 약 500에이커에 이르렀어요. 박하 자체는 훨씬 오래되어서 중세 유럽의 식물 목록에는 빠짐없이 올랐고 9세기 수녀원 정원에서도 길렀으며, 페퍼민트는 13세기 아이슬란드 약전에도 이름이 보여요. 초서는 민트가 가득하고 회향이 푸른 작은 길을 노래했고, 1568년 터너의 약초서는 정원 박하를 스피어민트로 적었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"http://botanical.com/botanical/mgmh/m/mints-39.html\"}]},\"12-22\":{\"stories\":[]},\"12-23\":{\"photo\":{\"src\":\"/birth/peulrataneoseu.jpg\",\"thumbSrc\":\"/birth/thumbs/peulrataneoseu.jpg\",\"author\":\"Emőke Dénes\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Proteales_-_Platanus_orientalis_-_8.jpg\",\"familyLine\":\"껍질이 조각조각 벗겨져 얼룩덜룩해져요. 매연을 뒤집어쓴 껍질을 아예 버리는 방식이라 길가에 많이 심어요.\"},\"stories\":[{\"id\":\"bstory-plane-tree-hippocrates-kos\",\"title\":\"코스 섬의 히포크라테스 나무\",\"hook\":\"줄기 둘레 18야드인 코스 섬의 플라타너스는 2400살이 아니라 500살쯤이에요.\",\"body\":\"에게해의 코스 섬에는 히포크라테스가 그 그늘에 앉아 환자를 보고 제자를 가르쳤다는 플라타너스가 서 있어요. 그가 기원전 5세기 사람이니 나무가 2400년이 넘었다는 말도 돌지만, 지금 서 있는 나무는 500년쯤 된 것으로 보고 원래 나무의 후손일 가능성이 있다고 해요. 줄기 둘레는 18야드에 이르러요. 이 나무의 씨앗과 꺾꽂이, 가지는 미국과 유럽의 의과대학과 도서관으로 퍼져 나갔어요. 1969년 디미트리오스 오레오풀로스는 벨파스트를 떠나며 존 미고에게 씨앗을 건넸고, 미고 부부가 다섯 그루를 길러 벨파스트 시립병원 곳곳에 심었어요. 1985년까지 세 그루가 확인돼 명판이 붙었지요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC3992091/\"},{\"id\":\"bstory-plane-tree-london-hybrid\",\"title\":\"껍질을 벗어 매연을 턴다\",\"hook\":\"런던플라타너스는 묘목장에서 우연히 생긴 잡종이 도시를 뒤덮은 경우예요.\",\"body\":\"런던 거리를 채운 런던플라타너스는 사람이 계획해서 만든 나무가 아니에요. 오리엔탈 플라타너스와 아메리칸 시커모어가 둘 다 영국에 들어와 식물학자 존 트레이드스캔트 2세의 런던 묘목장에 함께 심겼는데, 거기서 우연히 꽃가루가 섞여 잡종이 태어났어요. 트레이드스캔트가 17세기 중엽에 이 새 나무를 알아보고 태어난 도시의 이름을 붙였고요. 이 나무가 매연 속에서 잘 버티는 이유는 껍질에 있어요. 껍질이 큰 조각으로 떨어져 나가면서 오염 물질을 함께 떨궈 내거든요. 얼룩덜룩한 위장무늬 같은 줄기도 그래서 생겨요. 런던 트리 리포트에 따르면 이너런던 수종 가운데 잎 면적 총합이 가장 큰 나무가 런던플라타너스예요. 키는 35미터까지 자라고 수백 년을 살아요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"17세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"woodlandtrust.org.uk\",\"sourceUrl\":\"https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/british-trees/a-z-of-british-trees/london-plane/\"}]},\"12-24\":{\"photo\":{\"src\":\"/birth/gyeousali.jpg\",\"thumbSrc\":\"/birth/thumbs/gyeousali.jpg\",\"author\":\"H. Zell\",\"license\":\"CC BY-SA 3.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Viscum_album_004.jpg\",\"familyLine\":\"다른 나무 가지에 얹혀 살아요. 잎을 다 떨군 겨울에야 초록 덩어리로 남아 눈에 띄어요.\"},\"stories\":[{\"id\":\"bstory-mistletoe-druid-golden-knife\",\"title\":\"황금 칼로 벤 가지\",\"hook\":\"흰옷 사제가 참나무에 올라 황금 칼로 겨우살이를 베고 흰 망토로 받았어요.\",\"body\":\"드루이드는 겨우살이를 신성하게 여겼다고 전해져요. 그들은 흰옷을 입고 나가 참나무에 붙은 겨우살이를 찾았고, 황금으로 만든 칼로 잘라 냈다고 해요. 자르는 때도 아무 날이나가 아니어서 해가 바뀌는 무렵 달의 특정한 나이에 맞춰 채집했지요. 겨우살이가 땅에 떨어지거나 한동안 찾지 못하면 나라에 불행이 닥칠 조짐으로 여겼고, 지닌 사람을 모든 악에서 지켜 준다고 믿었어요. 오비디우스는 드루이드가 겨우살이를 향해 노래하곤 했다고 적었고, 셰익스피어는 이 풀을 해로운 겨우살이라 불렀어요. 1720년에는 존 콜바치 경이 겨우살이로 간질을 치료한다는 소책자를 냈어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"갈리아\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"http://botanical.com/botanical/mgmh/m/mistle40.html\"},{\"id\":\"bstory-mistletoe-kissing-1820\",\"title\":\"입맞춤 관습은 1820년에야\",\"hook\":\"겨우살이 아래 입맞춤이 글로 처음 남은 건 1820년 워싱턴 어빙의 이야기예요.\",\"body\":\"겨우살이 아래에서 입을 맞추는 관습은 생각보다 늦게 기록에 나타나요. 크리스마스 장식으로서의 겨우살이가 글에 또렷하게 보이는 첫 사례는 1820년 워싱턴 어빙의 크리스마스 이야기로, 흰 열매가 달린 겨우살이가 걸려 있어 예쁜 하녀들이 모두 위태롭다고 적었어요. 관습을 자세히 묘사한 초기 기록은 1836년 찰스 디킨스의 픽윅 클럽 여행기예요. 예법도 있어서 입을 맞출 때마다 열매를 하나씩 떼어 내고 열매가 다 없어지면 그만두어야 했지요. 드루이드의 겨우살이 신앙을 1세기에 적어 둔 대플리니우스와는 1700년 넘게 떨어진 이야기예요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"slate.com\",\"sourceUrl\":\"https://slate.com/news-and-politics/2011/12/how-did-mistletoe-come-to-be-associated-with-christmas-kissing.html\"}]},\"12-25\":{\"photo\":{\"src\":\"/birth/seoyanghoranggasinamu.jpg\",\"thumbSrc\":\"/birth/thumbs/seoyanghoranggasinamu.jpg\",\"author\":\"Dominicus Johannes Bergsma\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Fruits_of_holly_(Ilex_aquifolium)._Locatie,_Jonkersvallei.jpg\",\"familyLine\":\"가시 돋친 잎은 아래쪽 가지에만 나요. 짐승이 닿지 않는 높이에서는 잎 가장자리가 매끈해져요.\"},\"stories\":[{\"id\":\"bstory-holly-carol-1911-sharp\",\"title\":\"호랑가시와 담쟁이의 캐럴\",\"hook\":\"1911년 세실 샤프는 치핑캠던의 메리 클레이턴에게서 이 캐럴 가락을 받아 적었어요.\",\"body\":\"호랑가시와 담쟁이는 영국에서 오래 불린 캐럴이에요. 가장 이른 자취는 1710년 무렵의 낱장 인쇄물로 거슬러 올라가고, 버밍엄에서 찍힌 브로드사이드가 1812년에서 1830년 사이 것으로 남아 있어요. 활자로 이 캐럴을 처음 묶어 낸 사람은 조슈아 실베스터라는 필명의 편자로, 1861년 런던에서 낸 고금의 크리스마스 캐럴에 실었어요. 지금 널리 불리는 가락은 1911년 세실 샤프가 채집한 것인데, 치핑캠던의 메리 클레이턴 부인에게서 곡조를 받고 서머싯 이스트하프트리의 와이엇 부인에게서 얻은 가사를 보태 잉글리시 포크 캐럴스에 실었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"잉글랜드\"},{\"key\":\"era\",\"text\":\"19세기~20세기\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"hymnsandcarolsofchristmas.com\",\"sourceUrl\":\"http://www.hymnsandcarolsofchristmas.com/Hymns_and_Carols/holly_and_the_ivy.htm\"},{\"id\":\"bstory-holly-saturnalia-birdlime\",\"title\":\"사투르날리아의 호랑가시 가지\",\"hook\":\"로마인은 축제 때 선물과 함께 호랑가시 가지를 친구에게 보냈다고 해요.\",\"body\":\"호랑가시로 집을 꾸미는 풍습은 로마의 사투르날리아 축제에서 왔다는 이야기가 전해져요. 로마인은 축제 때 친구에게 선물과 함께 호랑가시 가지를 보냈고 초기 교회가 이를 받아들였다고 해요. 다만 이교의 축제와 같은 시기에 푸른 가지로 집을 꾸미지 말라는 교회의 금령이 나온 적도 있었어요. 플리니우스는 호랑가시를 집이나 농장 가까이 심으면 독을 물리치고 벼락과 마법을 막아 준다고 적었지요. 잉글랜드에서는 호랑가시 껍질을 삭혀 새 잡는 끈끈이를 만들었는데, 레이크 디스트릭트에서 만든 물량이 동인도까지 실려 갈 정도였어요. 노퍽에서는 헐버, 데번에서는 홈이라 불렀고요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"시대마다 조금씩 다르게 전해져요\"}],\"sourceLabel\":\"botanical.com\",\"sourceUrl\":\"http://botanical.com/botanical/mgmh/h/holly-28.html\"}]},\"12-26\":{\"stories\":[]},\"12-27\":{\"photo\":{\"src\":\"/birth/maehwa.jpg\",\"thumbSrc\":\"/birth/thumbs/maehwa.jpg\",\"author\":\"Laitche\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Flowers_of_Prunus_mume_(Armenaca_mume_%E2%80%98Bumpi%E2%80%99)_at_Nagai_Botanical_Garden,_February_2024_-_5452.jpg\",\"familyLine\":\"눈이 채 녹기 전에 피어요. 잎도 나기 전에 꽃부터 여는 성질이라 향이 유난히 멀리 가요.\"},\"stories\":[{\"id\":\"bstory-mume-lin-bu-plum-wife\",\"title\":\"매화를 아내로, 학을 자식으로\",\"hook\":\"북송의 임포는 서호 고산에 숨어 매화를 아내로, 학을 자식으로 삼았어요.\",\"body\":\"북송의 시인 임포는 벼슬길을 마다하고 항저우 서호 고산에 초막을 짓고 살았어요. 그 둘레에 매화를 심고 학을 길렀는데 평생 장가를 들지 않아, 사람들은 매화를 아내로 삼고 학을 자식으로 삼았다고 말했어요. 매처학자라는 말이 여기서 나왔고 이후 은거하는 선비의 상징처럼 굳어졌어요. 명나라 화가 두근은 15세기 후반에 달빛 아래 거니는 시인 임포라는 족자를 그렸어요. 지팡이를 짚은 사람이 매화나무를 바라보며 느리게 걷는 그림인데, 임포가 남긴 매화 시의 한 장면이에요. 굽은 매화 줄기와 바위를 짙고 옅은 먹으로 나눠 찍어낸 붓질이 특히 생생하고, 지금은 클리블랜드 미술관이 소장하고 있어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"clevelandart.org\",\"sourceUrl\":\"https://www.clevelandart.org/art/1954.582\"},{\"id\":\"bstory-mume-tobiume-dazaifu\",\"title\":\"교토에서 하룻밤에 날아온 매화\",\"hook\":\"좌천된 스가와라노 미치자네를 따라 매화나무가 규슈까지 날아왔다고 해요.\",\"body\":\"매화는 나라 시대에 당나라에서 들어온 새롭고 우아한 나무였어요. 헤이안 시대의 학자 스가와라노 미치자네가 이 꽃을 몹시 아꼈고, 그가 다자이후로 좌천되던 날 매화나무를 두고 와카 한 수를 지었다고 전해져요. 전설은 여기서 한 걸음 더 나가요. 교토에 남겨진 매화 한 그루가 주인을 그리워한 나머지 하룻밤 사이에 규슈까지 날아와 다시 그의 곁에 섰다는 거예요. 이 나무가 도비우메, 곧 날아온 매화이고, 다자이후 덴만구 본전 옆에 선 매화가 바로 그 나무로 여겨져요. 근처 에노키샤 신사 옆에는 도비우메가 처음 내려앉았다는 자리에서 150미터쯤 떨어진 곳에 또 다른 도비우메가 서 있고, 미치자네의 아이 구마마로의 무덤 곁에는 꽃잎이 여섯 장인 특이한 매화가 자라요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"dazaifu-japan-heritage.jp\",\"sourceUrl\":\"https://www.dazaifu-japan-heritage.jp/en/bunkazai/detail.php?cId=336\"}]},\"12-28\":{\"photo\":{\"src\":\"/birth/seokryu-1228.jpg\",\"thumbSrc\":\"/birth/thumbs/seokryu-1228.jpg\",\"author\":\"Jules Verne Times Two\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Pomegranate_flowers_(Punica_granatum),_Ponte_de_Sor,_Portugal_(approx._GPS_location)_julesvernex2.jpg\",\"familyLine\":\"꽃받침이 두껍고 붉어서 꽃일 때부터 열매 모양이 보여요. 그 왕관 같은 끝이 익은 뒤에도 그대로 남아요.\"},\"stories\":[{\"id\":\"bstory-pomegranate-grenade\",\"title\":\"수류탄의 어원이 이 열매예요\",\"hook\":\"석류와 수류탄은 같은 말에서 갈라져 나왔어요.\",\"body\":\"로마의 플리니우스는 석류를 말루스 푸니카, 곧 '카르타고의 사과'라 불렀어요. 로마가 카르타고를 거쳐 이 열매를 들여왔기 때문이에요. 학명 Punica granatum의 앞 절반이 여기서 왔고, granatum은 '씨앗이 많다'는 뜻이에요. 영어 pomegranate도 '씨 많은 사과'라는 같은 뜻이고요. 훗날 프랑스군은 손에 쥐는 크기에 알갱이가 가득 든 무기를 보고 같은 이름을 붙였어요. 그것이 지금의 grenade, 곧 수류탄이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"로마\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"khkeeler.blogspot.com\",\"sourceUrl\":\"http://khkeeler.blogspot.com/2015/03/plant-story-pomegranates-punica_22.html\"},{\"id\":\"bstory-pomegranate-persephone-one-seed\",\"title\":\"호메로스 원전에는 한 알\",\"hook\":\"하데스가 페르세포네에게 몰래 먹인 석류는 여섯 알이 아니라 한 알이에요.\",\"body\":\"페르세포네가 석류 몇 알을 먹었느냐고 물으면 흔히 여섯 알이라는 답이 돌아오지만, 가장 오래된 문헌은 그렇게 말하지 않아요. 데메테르에게 바치는 호메로스 찬가 370행에서 375행 부근에서 하데스는 페르세포네에게 달콤한 석류 씨를 몰래 먹여요. 검은 옷을 입은 데메테르 곁에 딸이 영영 머물지 않게 하려는 계산이었어요. 410행에서 413행 부근에서는 페르세포네가 직접 말해요. 그가 몰래 내 입에 달콤한 것을, 석류 씨 하나를 넣고 내 뜻과 상관없이 맛보게 했다고요. 두 대목 모두 단수로 씨라고만 적고 개수를 밝히지 않아요. 여러 알이라는 설정은 훨씬 나중 판본에서 붙은 살이에요.\",\"notes\":[{\"key\":\"region\",\"text\":\"그리스\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"perseus.tufts.edu\",\"sourceUrl\":\"https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.01.0138%3Ahymn%3D2\"},{\"id\":\"bstory-pomegranate-613-seeds\",\"title\":\"석류 206개를 센 사람\",\"hook\":\"613알 전승을 확인하려고 대학원생이 석류 206개의 알을 손으로 셌어요.\",\"body\":\"유대 전통에는 석류 한 개에 씨가 613개 들어 있고 이것이 토라의 계명 613개와 맞아떨어진다는 말이 돌아요. 다만 이 숫자는 탈무드에 없어요. 베라코트는 석류가 씨로 가득하듯 이스라엘의 빈 사람들도 계명으로 가득하다고, 아가의 구절을 빌려 풍성함을 말할 뿐이에요. 613이라는 수를 언급한 것은 19세기의 하탐 소페르와 말빔 같은 후대 학자예요. 실제로 세어 본 사람도 있어요. 컬럼비아대 대학원생 알렉산더 하우볼트가 세계 각지에서 온 석류 206개의 알을 셌는데, 평균이 정확히 613개로 나왔어요. 하지만 낱개로 보면 165개부터 1,370개까지 흩어져 있었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"이스라엘\"},{\"key\":\"era\",\"text\":\"오늘날\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"드물게 전해지는 이야기예요\"}],\"sourceLabel\":\"jewishaction.com\",\"sourceUrl\":\"https://jewishaction.com/religion/jewish-law/whats_the_truth_about_pomegranate_seeds/\"}]},\"12-29\":{\"photo\":{\"src\":\"/birth/kkwari.jpg\",\"thumbSrc\":\"/birth/thumbs/kkwari.jpg\",\"author\":\"Reinhold Möller (Ermell)\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Lampionblume_(Physalis_alkekengi)-20260208-RM-121159.jpg\",\"familyLine\":\"주황 주머니는 꽃받침이 부풀어 만든 등이에요. 얇아지다 못해 그물만 남으면 안의 붉은 열매가 비쳐 보여요.\"},\"stories\":[{\"id\":\"bstory-physalis-shimanrokusennichi\",\"title\":\"하루가 사만 육천 일\",\"hook\":\"7월 10일 센소지에 참배하면 사만 육천 일치 공덕을 받는다고 믿었어요.\",\"body\":\"도쿄 아사쿠사 센소지에서는 해마다 7월 9일과 10일에 꽈리 시장, 호오즈키이치가 열려요. 이날 하루 참배하면 4만 6천 일, 그러니까 약 126년치 공덕을 얻는다고 여겼어요. 왜 하필 4만 6천인지는 확실하지 않은데, 쌀 한 되에 알이 약 4만 6천 개 들어 있어 한 되와 한 평생의 발음을 겹쳤다는 설이 전해져요. 꽈리를 파는 장은 메이와 연간, 곧 1764년에서 1772년 사이에 시작된 것으로 봐요. 본래는 시바의 아타고 신사에서 서던 꽈리 장이 센소지로 옮겨 온 것이고, 꽈리 열매를 통째로 먹으면 어른의 지병이 낫고 아이의 뱃속 벌레가 떨어진다고 믿었지요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"에도 시대\"},{\"key\":\"type\",\"text\":\"오래 전해 온 설화\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"senso-ji.jp\",\"sourceUrl\":\"https://www.senso-ji.jp/annual_event/13.html\"},{\"id\":\"bstory-physalis-golden-lantern\",\"title\":\"금등롱이라 불린 열매\",\"hook\":\"중국에서 꽈리는 금등롱, 곧 황금 초롱이라는 이름의 약재였어요.\",\"body\":\"중국에서 꽈리는 금등롱, 곧 황금 초롱이라는 이름으로 불려요. 열매가 익으면 그것을 감싼 꽃받침이 노랑이나 주황, 빨강으로 물들면서 속이 비치는 초롱처럼 부풀기 때문이에요. 전통 의학에서는 열을 내리고 독을 풀며 목이 붓고 아픈 것을 가라앉히고 가래를 삭이는 약재로 썼고, 오줌이 잘 나오게 하는 데도 썼어요. 과육은 달고 살짝 시며 성질이 차다고 보았고 폐 경락에 든다고 분류했지요. 붉은 버섯 아가씨라는 뜻의 별명으로도 불렸어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"전통 시대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"pmc.ncbi.nlm.nih.gov\",\"sourceUrl\":\"https://pmc.ncbi.nlm.nih.gov/articles/PMC11858199/\"}]},\"12-30\":{\"photo\":{\"src\":\"/birth/napmae.jpg\",\"thumbSrc\":\"/birth/thumbs/napmae.jpg\",\"author\":\"Laitche\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Chimonanthus_praecox_f._concolor,_Nagai_Botanical_Garden,_January_2026_-1841.jpg\",\"familyLine\":\"섣달 추위 속에서 잎도 없이 노란 꽃을 열어요. 반쯤 비치는 꽃잎이 밀랍을 얇게 편 것처럼 보여요.\"},\"stories\":[{\"id\":\"bstory-wintersweet-wax-name\",\"title\":\"밀랍으로 빚은 듯한 꽃\",\"hook\":\"소식은 이 꽃을 두고 여공이 밀랍을 비벼 만든 것 같다고 적었어요.\",\"body\":\"납매의 한자 이름은 밀랍 랍 자를 쓴 납매예요. 소식은 이 꽃을 두고 향기가 매화를 닮았고 여공이 밀랍을 비벼 빚어낸 것 같아서 납매라 부른다고 적었어요. 섣달을 뜻하는 다른 글자를 써서 적는 사람도 많지만, 식물학 문헌은 꽃잎의 밀랍 같은 질감을 가리키는 쪽을 정식 이름으로 삼아요. 이름에 매화가 들어 있어도 매화는 아니에요. 납매는 납매과, 매화는 장미과라 계통이 아예 달라요. 매보나 본초강목 같은 옛 문헌도 이것이 매화 종류가 아니라고 이미 밝혀 두었어요. 대접은 오히려 납매 쪽이 좋았어요. 오대 남당의 장익이 쓴 화경에서 납매는 난초, 모란과 같은 일품구명에 올랐는데 정작 매화는 사품육명이었어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국\"},{\"key\":\"era\",\"text\":\"중세\"},{\"key\":\"type\",\"text\":\"문학에서 온 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"forestry.gov.cn\",\"sourceUrl\":\"https://www.forestry.gov.cn/c/www/dzw/542157.jhtml\"},{\"id\":\"bstory-wintersweet-1766-britain\",\"title\":\"1766년 영국에 닿은 향\",\"hook\":\"크룸코트 정원사가 남긴 편지 한 통이 납매의 영국 도착 연도를 알려 줘요.\",\"body\":\"납매는 중국에서 라메이화라 부르고 천 년 넘게 길러 온 나무예요. 자생지는 후베이와 쓰촨 동부에서 저장에 이르는 지역이에요. 17세기에 일본으로 건너갔고, 영국에는 1766년에 중국에서 들어왔어요. 이 연도는 우스터셔 크룸코트에서 코번트리 경의 정원사로 일하던 윌리엄 딘이 남긴 편지로 확인돼요. 꽃은 12월 말에 피기 시작해 늦으면 3월까지 이어져요. 다른 꽃이 거의 없는 시기에 달콤한 향을 뿜어서 영어로는 윈터스위트, 곧 겨울의 달콤함이라 불러요. 요즘은 재패니즈 올스파이스라는 이름으로도 팔리는데, 향신료로 쓰는 자메이카 올스파이스와는 아무 관계가 없어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"중국·영국\"},{\"key\":\"era\",\"text\":\"18세기\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"기록으로 남아 있는 이야기예요\"}],\"sourceLabel\":\"botanicgardens.uw.edu\",\"sourceUrl\":\"https://botanicgardens.uw.edu/about/blog/2017/01/05/january-2017-plant-profile-chimonanthus-praecox/\"}]},\"12-31\":{\"photo\":{\"src\":\"/birth/nosongnamu.jpg\",\"thumbSrc\":\"/birth/thumbs/nosongnamu.jpg\",\"author\":\"Shuvaev\",\"license\":\"CC BY-SA 4.0\",\"pageUrl\":\"https://commons.wikimedia.org/wiki/File:Chamaecyparis_obtusa,_Morris_Arboretum_05.jpg\",\"familyLine\":\"잎 뒷면에 하얀 Y자 무늬가 그려져 있어요. 숨구멍이 모인 자리라 뒤집어 보면 바로 알아볼 수 있어요.\"},\"stories\":[{\"id\":\"bstory-chamaecyparis-sengu-690\",\"title\":\"스무 해마다 새로 짓는 궁\",\"hook\":\"690년에 시작된 이 관습은 2013년으로 예순두 번째를 채웠어요.\",\"body\":\"일본 이세 신궁은 스무 해마다 지금 신전과 똑같은 크기의 새 신전을 옆자리에 지어요. 식년천궁이라 부르는 이 관습은 690년, 41대 지토 천황 때 처음 치러졌고 천삼백 년 넘게 이어져 왔어요. 2013년에 치른 것이 예순두 번째예요. 새로 짓는 것은 건물만이 아니에요. 신에게 올리는 옷과 세간, 신보까지 함께 새로 만들고 마지막에 신경을 새 신전으로 옮겨요. 여기에 딸린 제사와 행사가 서른 가지쯤 되고, 전부 치르는 데 여덟 해가 걸려요. 내궁만이 아니라 외궁과 신궁에 딸린 다른 신사들에서도 함께 진행돼요. 이세 신궁은 정식으로는 신궁이라 부르고 모두 125개 신사를 아울러요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"isejingu.or.jp\",\"sourceUrl\":\"https://www.isejingu.or.jp/en/ritual/index.html\"},{\"id\":\"bstory-chamaecyparis-fire-tree-kiso\",\"title\":\"불의 나무, 기소의 신목\",\"hook\":\"히노키는 불의 나무라는 뜻으로, 신사에서는 지금도 이 나무를 비벼 불을 냅니다.\",\"body\":\"히노키라는 이름은 불의 나무라는 뜻으로 풀이돼요. 이 나무를 비벼 마찰로 불을 냈기 때문인데, 신사에서는 지금도 그 방식으로 불을 지피는 의식이 남아 있어요. 편백은 기소 지방의 다섯 신목 가운데 하나로 꼽혀요. 나라 시대, 그러니까 8세기 유적을 발굴하면 나오는 구조재 목재의 대부분이 편백과 또 다른 신성한 침엽수였어요. 에도 시대에 들어서면서 쓰임의 비중은 달라졌지만, 지금 남아 있는 목조 건물에도 편백이 많이 들어가 있어요. 1910년에는 교토 니시혼간지 가라몬을 5분의 4 크기로 줄여 편백으로 다시 지었고, 그 복제 건물은 1994년에 한 번 더 세워졌어요.\",\"notes\":[{\"key\":\"region\",\"text\":\"일본\"},{\"key\":\"era\",\"text\":\"고대\"},{\"key\":\"type\",\"text\":\"기록으로 남은 이야기\",\"accent\":false},{\"key\":\"confidence\",\"text\":\"오래, 두루 전해지는 이야기\"}],\"sourceLabel\":\"conifers.org\",\"sourceUrl\":\"https://www.conifers.org/cu/Chamaecyparis_obtusa.php\"}]}}";
